import { useState } from "react";
import PremiumSectionCard from "../../components/PremiumSectionCard";
import { useLanguage } from "../../context/LanguageContext";
import { fetchConsultationSummary } from "../services/aiService";
import { getApiErrorMessage } from "../../utils/apiError";
import { translateDisplayText } from "../../utils/i18n";

function buildSummaryText(summary) {
  if (!summary) {
    return "";
  }
  return [
    `Subjective: ${summary.subjective}`,
    `Objective: ${summary.objective}`,
    `Assessment: ${summary.assessment}`,
    `Plan: ${summary.plan}`
  ].join("\n");
}

export default function AiConsultationSummaryCard({ consultationId, onApplySummary }) {
  const { t, language, translateUiText = (value) => translateDisplayText(language, value) } = useLanguage();
  const [summary, setSummary] = useState(null);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");

  const loadSummary = async () => {
    if (!consultationId) {
      setError(translateUiText("Save a consultation note first."));
      return;
    }
    setLoading(true);
    setError("");
    try {
      const data = await fetchConsultationSummary(consultationId);
      setSummary(data);
      setMessage("");
    } catch (err) {
      setError(getApiErrorMessage(err, translateUiText("Unable to generate summary.")));
    } finally {
      setLoading(false);
    }
  };

  const applySummary = () => {
    if (!summary || !onApplySummary) {
      return;
    }
    const text = buildSummaryText(summary);
    onApplySummary(text);
    setMessage(translateUiText("Summary copied into consultation notes."));
  };

  return (
    <PremiumSectionCard
      title={translateUiText("Consultation auto-summary")}
      action={(
        <button
          className="px-3 py-1.5 bg-primary/10 text-primary font-semibold text-xs rounded-lg hover:bg-primary/20 transition-colors disabled:opacity-50"
          type="button"
          disabled={loading}
          onClick={loadSummary}
        >
          {loading ? translateUiText("Loading...") : translateUiText("Generate summary")}
        </button>
      )}
    >
      {error ? <p className="text-sm text-alert mb-3">{error}</p> : null}
      {summary ? (
        <div className="space-y-4 text-sm text-ink/90">
          <div className="bg-white/5 border border-white/10 rounded-xl p-4 space-y-3">
            <p><span className="font-semibold text-primary uppercase text-xs tracking-wider">S:</span> {summary.subjective}</p>
            <p><span className="font-semibold text-primary uppercase text-xs tracking-wider">O:</span> {summary.objective}</p>
            <p><span className="font-semibold text-primary uppercase text-xs tracking-wider">A:</span> {summary.assessment}</p>
            <p><span className="font-semibold text-primary uppercase text-xs tracking-wider">P:</span> {summary.plan}</p>
          </div>
          {summary.suggestedCodes?.length ? (
            <p className="text-xs text-ink-muted bg-white/5 px-3 py-2 rounded-lg border border-white/10">
              <span className="font-semibold text-ink/80">{translateUiText("Suggested codes")}:</span> {summary.suggestedCodes.join(", ")}
            </p>
          ) : null}
          {summary.rationale?.length ? (
            <ul className="list-disc pl-5 text-xs text-ink-muted/80 space-y-1">
              {summary.rationale.map((item) => <li key={item}>{item}</li>)}
            </ul>
          ) : null}
          <p className="text-[10px] text-ink-muted/50 italic">{summary.disclaimer}</p>
          {onApplySummary ? (
            <button className="w-full btn-primary" type="button" onClick={applySummary}>
              {translateUiText("Add to notes")}
            </button>
          ) : null}
        </div>
      ) : (
        <p className="text-sm text-ink-muted py-4 text-center border border-dashed border-white/10 rounded-xl bg-white/5">{translateUiText("Generate a structured summary from the consultation notes.")}</p>
      )}
      {message ? <p className="mt-3 text-sm font-semibold text-primary bg-primary/10 border border-primary/20 px-3 py-2 rounded-lg" role="status" aria-live="polite">{message}</p> : null}
    </PremiumSectionCard>
  );
}

import { useEffect, useState } from "react";
import PremiumSectionCard from "../../components/PremiumSectionCard";
import { useLanguage } from "../../context/LanguageContext";
import { fetchDifferentialSuggestions, fetchDoctorRiskQueue, fetchDrugInteractions } from "../services/aiService";
import { getApiErrorMessage } from "../../utils/apiError";
import { translateDisplayText } from "../../utils/i18n";
import { Activity, Beaker, Pill, AlertTriangle } from "lucide-react";

export default function AiDoctorInsightsPanel({ doctorId }) {
  const { t, language, translateUiText = (value) => translateDisplayText(language, value) } = useLanguage();
  const [riskQueue, setRiskQueue] = useState(null);
  const [diffInput, setDiffInput] = useState("");
  const [diffSuggestions, setDiffSuggestions] = useState(null);
  const [diffLoading, setDiffLoading] = useState(false);
  const [medInput, setMedInput] = useState("");
  const [interactionWarnings, setInteractionWarnings] = useState(null);
  const [interactionLoading, setInteractionLoading] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    if (!doctorId) return;
    fetchDoctorRiskQueue(doctorId)
      .then((data) => setRiskQueue(data))
      .catch((err) => setError(getApiErrorMessage(err, t("unableLoadDoctorQueue"))));
  }, [doctorId, t]);

  const runDifferential = async () => {
    if (!diffInput.trim()) return;
    setError("");
    setDiffLoading(true);
    try {
      const response = await fetchDifferentialSuggestions({ symptoms: diffInput.trim(), notes: "" });
      setDiffSuggestions(response);
    } catch (err) {
      setError(getApiErrorMessage(err, t("unableLoadDoctorQueue")));
    } finally {
      setDiffLoading(false);
    }
  };

  const runInteractions = async () => {
    const meds = medInput.split(",").map((item) => item.trim()).filter(Boolean);
    if (!meds.length) return;
    setError("");
    setInteractionLoading(true);
    try {
      const response = await fetchDrugInteractions({ medicines: meds });
      setInteractionWarnings(response);
    } catch (err) {
      setError(getApiErrorMessage(err, t("unableLoadDoctorQueue")));
    } finally {
      setInteractionLoading(false);
    }
  };

  const getRiskColor = (score) => {
    if (score >= 80) return "bg-alert shadow-[0_0_10px_rgba(239,68,68,0.5)]";
    if (score >= 50) return "bg-amber-400 shadow-[0_0_10px_rgba(251,191,36,0.5)]";
    return "bg-primary shadow-[0_0_10px_rgba(20,184,166,0.5)]";
  };

  return (
    <div className="grid gap-6 xl:grid-cols-3 mt-6">
      <div className="xl:col-span-1">
        <PremiumSectionCard title={(
          <span className="flex items-center gap-2">
            <Activity className="h-4 w-4 text-primary" />
            {translateUiText("Patient risk heatmap")}
          </span>
        )} className="h-full border-t-[3px] border-t-primary/50">
          {error ? <p className="text-sm text-alert mb-4">{error}</p> : null}
          {riskQueue ? (
            <div className="space-y-4">
              {(Array.isArray(riskQueue.patients) ? riskQueue.patients : []).map((patient) => (
                <div key={patient.patientId} className="group rounded-xl border border-white/5 bg-white/5 p-4 transition-colors hover:bg-white/10 cursor-pointer">
                  <div className="flex items-center justify-between mb-2">
                    <p className="font-semibold text-ink">{patient.patientName}</p>
                    <span className="text-xs font-bold text-ink bg-white/10 px-2 py-0.5 rounded-full">{patient.score}/100</span>
                  </div>
                  
                  {/* Radial/Bar Gauge Representation */}
                  <div className="h-1.5 w-full bg-white/5 rounded-full overflow-hidden mb-3">
                    <div className={`h-full rounded-full transition-all duration-1000 ${getRiskColor(patient.score)}`} style={{ width: `${Math.max(5, patient.score)}%` }} />
                  </div>
                  
                  <div className="flex flex-wrap gap-1 mb-2">
                    <span className="text-[10px] uppercase tracking-wider font-semibold text-ink-muted bg-white/5 px-1.5 py-0.5 rounded">
                      {patient.riskCategory}
                    </span>
                  </div>
                  
                  <p className="text-xs text-ink-muted/80 leading-relaxed">
                    {(Array.isArray(patient.reasons) ? patient.reasons : []).join(" ΓÇó ")}
                  </p>
                </div>
              ))}
              <div className="flex items-start gap-2 mt-4 text-ink-muted bg-white/5 border border-white/10 p-3 rounded-lg">
                <AlertTriangle className="h-4 w-4 shrink-0 mt-0.5" />
                <p className="text-xs leading-relaxed opacity-80">{riskQueue.disclaimer}</p>
              </div>
            </div>
          ) : (
            <div className="space-y-4 animate-pulse">
              {[1, 2].map(i => (
                <div key={i} className="rounded-xl border border-white/5 bg-white/5 p-4">
                  <div className="h-5 w-1/2 mb-3 bg-white/10 rounded" />
                  <div className="h-1.5 w-full mb-3 bg-white/5 rounded-full" />
                  <div className="h-4 w-3/4 bg-white/10 rounded" />
                </div>
              ))}
            </div>
          )}
        </PremiumSectionCard>
      </div>

      <div className="xl:col-span-2 grid gap-6 md:grid-cols-2">
        <PremiumSectionCard title={(
          <span className="flex items-center gap-2">
            <Beaker className="h-4 w-4 text-sky-400" />
            {translateUiText("AI differential suggestions")}
          </span>
        )} className="border-t-[3px] border-t-sky-400/50 bg-sky-400/5">
          <div className="flex flex-col h-full">
            <textarea
              className="w-full min-h-[100px] resize-y mb-4 bg-white/5 border border-white/10 rounded-xl p-3 text-sm text-ink outline-none focus:border-sky-400/50 transition-colors placeholder:text-ink-muted/50"
              placeholder={translateUiText("Enter symptoms or clinical notes (e.g. '34yo M, acute RLQ pain, nausea')")}
              value={diffInput}
              onChange={(event) => setDiffInput(event.target.value)}
            />
            <button 
              className="bg-sky-500 hover:bg-sky-400 text-canvas px-4 py-2.5 rounded-xl font-semibold text-sm transition-colors disabled:opacity-50" 
              type="button" 
              onClick={runDifferential} 
              disabled={diffLoading}
            >
              {diffLoading ? "Analyzing..." : translateUiText("Generate differential")}
            </button>
            
            {diffSuggestions && !diffLoading && (
              <div className="mt-6 space-y-4 animate-fadeSlideUp">
                <div className="rounded-xl bg-sky-400/10 border border-sky-400/20 p-4">
                  <h4 className="text-sm font-semibold text-sky-400 mb-2 uppercase tracking-wider">Top Differentials</h4>
                  <ul className="space-y-1.5">
                    {(Array.isArray(diffSuggestions.suggestions) ? diffSuggestions.suggestions : []).map((item, i) => (
                      <li key={i} className="flex items-start gap-2 text-sm text-ink/90">
                        <span className="text-sky-400 opacity-50 block mt-0.5">ΓÇó</span>
                        {item}
                      </li>
                    ))}
                  </ul>
                </div>
                
                {Array.isArray(diffSuggestions.rationale) && diffSuggestions.rationale.length > 0 && (
                  <div className="rounded-xl bg-white/5 border border-white/5 p-4">
                    <h4 className="text-xs font-semibold text-ink-muted mb-2 uppercase tracking-wider">Clinical Rationale</h4>
                    <ul className="space-y-1.5">
                      {diffSuggestions.rationale.map((item, i) => (
                        <li key={i} className="text-xs text-ink-muted/80 leading-relaxed">{item}</li>
                      ))}
                    </ul>
                  </div>
                )}
                <p className="text-[10px] text-ink-muted/50 italic px-1">{diffSuggestions.disclaimer}</p>
              </div>
            )}
          </div>
        </PremiumSectionCard>

        <PremiumSectionCard title={(
          <span className="flex items-center gap-2">
            <Pill className="h-4 w-4 text-amber-400" />
            {translateUiText("Drug interaction alerts")}
          </span>
        )} className="border-t-[3px] border-t-amber-400/50 bg-amber-400/5">
          <div className="flex flex-col h-full">
            <input
              className="w-full mb-4 bg-white/5 border border-white/10 rounded-xl p-3 text-sm text-ink outline-none focus:border-amber-400/50 transition-colors placeholder:text-ink-muted/50"
              placeholder={translateUiText("Enter medicines (e.g. 'warfarin, amiodarone')")}
              value={medInput}
              onChange={(event) => setMedInput(event.target.value)}
            />
            <button 
              className="bg-amber-500 hover:bg-amber-400 text-canvas px-4 py-2.5 rounded-xl font-semibold text-sm transition-colors disabled:opacity-50" 
              type="button" 
              onClick={runInteractions} 
              disabled={interactionLoading}
            >
              {interactionLoading ? "Checking..." : translateUiText("Check interactions")}
            </button>
            
            {interactionWarnings && !interactionLoading && (
              <div className="mt-6 space-y-4 animate-fadeSlideUp">
                {(Array.isArray(interactionWarnings.warnings) ? interactionWarnings.warnings : []).map((w, idx) => {
                  const isNotEvaluated = typeof w === "string" && w.startsWith("Not evaluated");
                  const isInteractionFound = typeof w === "string" && w.startsWith("Interaction found");
                  const isNoInteraction = typeof w === "string" && w.startsWith("No interaction");
                  
                  if (isNoInteraction) {
                    return (
                      <div key={idx} className="rounded-xl bg-primary/10 border border-primary/20 p-4 text-center">
                        <p className="text-sm font-medium text-primary">No interaction found (verified)</p>
                      </div>
                    );
                  }

                  if (isNotEvaluated) {
                    return (
                      <div key={idx} className="rounded-xl bg-amber-500/10 border border-amber-500/20 p-4">
                        <div className="flex items-start gap-2">
                          <AlertTriangle className="h-4 w-4 text-amber-500 shrink-0 mt-0.5" />
                          <div>
                            <p className="text-sm font-semibold text-amber-400">Not Evaluated</p>
                            <p className="text-sm text-ink/90 mt-1">{w}</p>
                          </div>
                        </div>
                      </div>
                    );
                  }

                  return (
                    <div key={idx} className="rounded-xl bg-alert/10 border border-alert/20 p-4">
                      <div className="flex items-start gap-2">
                        <AlertTriangle className="h-4 w-4 text-alert shrink-0 mt-0.5" />
                        <div>
                          <p className="text-sm font-semibold text-alert">Interaction Found</p>
                          <p className="text-sm text-ink/90 mt-1">{typeof w === "string" ? w.replace("Interaction found: ", "") : w.description || w}</p>
                        </div>
                      </div>
                    </div>
                  );
                })}
                
                {(!interactionWarnings.warnings || interactionWarnings.warnings.length === 0) && (
                  <div className="rounded-xl bg-primary/10 border border-primary/20 p-4 text-center">
                    <p className="text-sm font-medium text-primary">No interactions provided</p>
                  </div>
                )}
                
                <p className="text-[10px] text-ink-muted/50 italic px-1">Disclaimer: {interactionWarnings.disclaimer}</p>
              </div>
            )}
          </div>
        </PremiumSectionCard>
      </div>
    </div>
  );
}

import { useState, useRef, useEffect } from "react";
import PremiumSectionCard from "../../components/PremiumSectionCard";
import { ScanFace, Upload, Loader2, AlertCircle, Eye, EyeOff, ZoomIn, ZoomOut, History, XCircle, CheckCircle2 } from "lucide-react";
import { analyzeMedicalImage, fetchImageHistory, cancelImageAnalysis } from "../services/aiService";
import { useWebSocket } from "../../hooks/useWebSocket";
import { formatDisplayValue } from "../../utils/formatDisplayValue";

export default function AiImagingAnalyzer({ patientId }) {
  const [imageSrc, setImageSrc] = useState(null);
  const [activeJobId, setActiveJobId] = useState(null);

  // Job State
  const [jobStatus, setJobStatus] = useState("idle"); // idle | uploading | processing | completed | failed | canceled
  const [progress, setProgress] = useState(0);
  const [jobMessage, setJobMessage] = useState("");
  const [analysisResult, setAnalysisResult] = useState(null);
  const [severity, setSeverity] = useState(null);

  // History
  const [history, setHistory] = useState([]);
  const [showHistory, setShowHistory] = useState(false);

  // Canvas Interactions
  const canvasRef = useRef(null);
  const [showAnnotations, setShowAnnotations] = useState(true);
  const [scale, setScale] = useState(1);
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

  useEffect(() => {
    if (patientId) {
      loadHistory();
    }
  }, [patientId]);

  const loadHistory = async () => {
    try {
      const data = await fetchImageHistory(patientId);
      setHistory(data);
    } catch (error) {
      console.error("Failed to fetch image history", error);
    }
  };

  // WebSocket Subscription
  const wsTopic = activeJobId ? `/topic/imaging/${activeJobId}` : null;
  useWebSocket(wsTopic, (message) => {
    setJobStatus(message.status.toLowerCase());
    setProgress(message.progress || 0);
    setJobMessage(message.message || "");

    if (message.status === "COMPLETED") {
      setAnalysisResult(message.findings);
      setSeverity(message.severity);
      setActiveJobId(null);
      loadHistory(); // refresh history
    } else if (message.status === "FAILED" || message.status === "CANCELED") {
      setActiveJobId(null);
    }
  });

  const handleImageUpload = async (e) => {
    const file = e.target.files[0];
    if (file) {
      if (file.size > 10 * 1024 * 1024) {
        alert("File size exceeds 10MB limit.");
        return;
      }
      const url = URL.createObjectURL(file);
      setImageSrc(url);
      setAnalysisResult(null);
      setSeverity(null);
      setJobStatus("uploading");
      setProgress(5);
      setJobMessage("Uploading image securely...");

      try {
        const formData = new FormData();
        formData.append("file", file);

        const result = await analyzeMedicalImage(formData, patientId);
        setActiveJobId(result.jobId);
      } catch (error) {
        console.error("Image upload failed:", error);
        setJobStatus("failed");
        setJobMessage("Upload failed.");
      }
    }
  };

  const handleCancel = async () => {
    if (activeJobId) {
      try {
        await cancelImageAnalysis(activeJobId);
        setJobStatus("canceled");
        setJobMessage("Job canceled by user.");
        setActiveJobId(null);
      } catch (error) {
        console.error("Failed to cancel job", error);
      }
    }
  };

  const loadFromHistory = (record) => {
    if (record.status !== "COMPLETED") return;

    // In a real app we'd fetch the actual image bytes via an authorized URL. 
    // Here we'll use a placeholder or clear the image for demo purposes since we don't have a static file server configured to serve absolute paths from C:\.
    // For demo continuity, we'll just reset the canvas.
    setImageSrc(null); 
    setAnalysisResult(record.findingsJson ? JSON.parse(record.findingsJson) : null);
    setSeverity(record.severity);
    setJobStatus("completed");
    setJobMessage(`Loaded historical record: ${record.fileName}`);
    setScale(1);
    setPan({ x: 0, y: 0 });
    setShowHistory(false);
  };

  // Canvas Drawing
  useEffect(() => {
    if (!imageSrc || !canvasRef.current) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    const img = new Image();
    img.src = imageSrc;
    img.onload = () => {
      // Base canvas size to match container
      const parentWidth = canvas.parentElement.clientWidth;
      const baseScale = parentWidth / img.width;
      canvas.width = parentWidth;
      canvas.height = img.height * baseScale;

      // Clear
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Apply transforms (Pan + Zoom)
      ctx.save();
      ctx.translate(pan.x, pan.y);
      ctx.scale(scale, scale);

      // Draw image
      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

      // Draw annotations if permitted
      if (showAnnotations && analysisResult) {
        analysisResult.forEach(res => {
          const rx = res.x * canvas.width;
          const ry = res.y * canvas.height;
          const rw = res.w * canvas.width;
          const rh = res.h * canvas.height;

          const isAnomaly = res.type === "ANOMALY";
          const color = isAnomaly ? "#f43f5e" : "#10b981"; // rose-500 or emerald-500

          // Draw Box
          ctx.strokeStyle = color;
          ctx.lineWidth = 2 / scale;
          ctx.strokeRect(rx, ry, rw, rh);

          // Draw Background for Text
          ctx.fillStyle = color;
          ctx.globalAlpha = 0.8;
          ctx.fillRect(rx, ry - (20 / scale), rw, 20 / scale);

          // Draw Text
          ctx.globalAlpha = 1.0;
          ctx.fillStyle = "#ffffff";
          ctx.font = `bold ${10 / scale}px sans-serif`;
          ctx.fillText(`${res.label} (${res.confidence}%)`, rx + (4 / scale), ry - (6 / scale));
        });
      }
      ctx.restore();
    };
  }, [imageSrc, analysisResult, showAnnotations, scale, pan]);

  // Canvas Event Handlers
  const handleWheel = (e) => {
    e.preventDefault();
    const zoomSensitivity = 0.05;
    const delta = e.deltaY > 0 ? -zoomSensitivity : zoomSensitivity;
    setScale(s => Math.max(1, Math.min(s + delta, 5)));
  };

  const handleMouseDown = (e) => {
    setIsDragging(true);
    setDragStart({ x: e.clientX - pan.x, y: e.clientY - pan.y });
  };

  const handleMouseMove = (e) => {
    if (!isDragging) return;
    setPan({
      x: e.clientX - dragStart.x,
      y: e.clientY - dragStart.y
    });
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  return (
    <PremiumSectionCard
      title={(
        <div className="flex items-center justify-between w-full">
          <div className="flex items-center gap-2">
            <ScanFace className="w-5 h-5 text-indigo-400" />
            <span>AI Diagnostic Imaging</span>
          </div>
          <button 
            onClick={() => setShowHistory(!showHistory)}
            className="flex items-center gap-2 text-xs font-medium text-slate-300 hover:text-white bg-white/5 hover:bg-white/10 px-3 py-1.5 rounded-lg transition-colors border border-white/10"
          >
            <History className="w-4 h-4" /> {showHistory ? "Hide History" : "View History"}
          </button>
        </div>
      )}
    >
      {showHistory ? (
        <div className="mt-4 bg-slate-900/50 rounded-xl border border-white/10 p-4 max-h-[400px] overflow-y-auto">
          <h4 className="text-white font-semibold mb-4">Patient Imaging History</h4>
          {history.length === 0 ? (
            <p className="text-slate-400 text-sm">No previous scans found.</p>
          ) : (
            <div className="space-y-3">
              {history.map(record => (
                <div key={record.id} className="bg-black/40 border border-white/10 rounded-lg p-3 flex items-center justify-between hover:bg-white/5 transition-colors cursor-pointer" onClick={() => loadFromHistory(record)}>
                  <div>
                    <p className="text-sm font-medium text-white">{record.fileName}</p>
                    <p className="text-xs text-slate-400">{formatDisplayValue(record.uploadedAt, "datetime")} &bull; {record.status}</p>
                  </div>
                  {record.severity === "HIGH" && <span className="bg-rose-500/20 text-rose-400 text-xs px-2 py-1 rounded-full border border-rose-500/30">High Severity</span>}
                  {record.status === "COMPLETED" && !record.severity && <span className="bg-emerald-500/20 text-emerald-400 text-xs px-2 py-1 rounded-full border border-emerald-500/30">Analyzed</span>}
                </div>
              ))}
            </div>
          )}
        </div>
      ) : (
        <>
          {!imageSrc && jobStatus === "idle" ? (
            <div className="border-2 border-dashed border-slate-700 hover:border-indigo-500/50 bg-slate-900/30 rounded-xl p-8 transition-colors flex flex-col items-center justify-center text-center cursor-pointer relative mt-4 h-64">
              <input 
                type="file" 
                accept="image/*"
                aria-label="Upload Medical Image"
                title="Upload Medical Image"
                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                onChange={handleImageUpload}
              />
              <div className="w-12 h-12 bg-indigo-500/10 rounded-full flex items-center justify-center mb-3">
                <Upload className="w-6 h-6 text-indigo-400" />
              </div>
