                  <div className="flex items-center justify-between mb-4">
                    <h4 className="font-semibold text-white flex items-center gap-2">
                      <ScanFace className="w-4 h-4 text-indigo-400" /> AI Findings
                    </h4>
                    {severity === "HIGH" ? (
                      <span className="bg-rose-500/20 text-rose-400 text-xs px-2 py-1 rounded-full border border-rose-500/30 font-bold">High Severity</span>
                    ) : (
                      <span className="bg-emerald-500/20 text-emerald-400 text-xs px-2 py-1 rounded-full border border-emerald-500/30 font-bold">Low Risk</span>
                    )}
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                    {analysisResult.map((res, i) => (
                      <div key={i} className={`p-3 rounded-lg border flex items-start gap-3 ${res.type === 'ANOMALY' ? 'bg-rose-500/10 border-rose-500/20' : 'bg-emerald-500/10 border-emerald-500/20'}`}>
                        <AlertCircle className={`w-5 h-5 shrink-0 ${res.type === 'ANOMALY' ? 'text-rose-400' : 'text-emerald-400'}`} />
                        <div>
                          <div className="flex items-center justify-between mb-1">
