import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { queryKeys } from "../../utils/queryKeys";
import PharmacistPremiumCard from "../../components/PharmacistPremiumCard";
import { useLanguage } from "../../context/LanguageContext";
import { fetchInventoryRisk, fetchRefillPrediction, fetchSubstitutionSuggestions } from "../services/aiService";
import { getApiErrorMessage } from "../../utils/apiError";
import { translateDisplayText } from "../../utils/i18n";

export default function AiPharmacistInsightsPanel({ pharmacistId }) {
  const { t, language, translateUiText = (value) => translateDisplayText(language, value) } = useLanguage();
  const [medicineName, setMedicineName] = useState("");
  const [substitution, setSubstitution] = useState(null);
  const [substitutionError, setSubstitutionError] = useState("");
  const { data: refill, error: refillError, isLoading: loadingRefill } = useQuery({
    queryKey: queryKeys.pharmacist.refillPrediction(pharmacistId),
    queryFn: () => fetchRefillPrediction(pharmacistId),
    enabled: !!pharmacistId
  });

  const { data: inventory, error: inventoryError, isLoading: loadingInventory } = useQuery({
    queryKey: queryKeys.pharmacist.inventoryRisk(pharmacistId),
    queryFn: () => fetchInventoryRisk(pharmacistId),
    enabled: !!pharmacistId
  });

  const error = (refillError || inventoryError) ? getApiErrorMessage(refillError || inventoryError, t("unableLoadPharmacistDashboard")) : "";

  const runSubstitution = async () => {
    if (!medicineName.trim()) {
      return;
    }
    setSubstitutionError("");
    try {
      const response = await fetchSubstitutionSuggestions({ medicineName: medicineName.trim() });
      setSubstitution(response);
    } catch (err) {
      setSubstitutionError(getApiErrorMessage(err, t("unableLoadPharmacistDashboard")));
    }
  };

  return (
    <div className="grid gap-6 xl:grid-cols-2">
      <PharmacistPremiumCard title={translateUiText("Refill prediction")}>
        {error ? <p className="text-sm text-red-400">{error}</p> : null}
        {refill ? (
          <div className="space-y-3 text-sm text-slate-300">
            {(Array.isArray(refill.items) ? refill.items : []).map((item) => (
              <div key={`${item.medicineName}-${item.estimatedRefillDate}`} className="rounded-xl bg-white/5 p-4 border border-white/10 hover:bg-white/10 transition-colors">
                <p className="font-semibold text-white text-base">{item.medicineName}</p>
                <p className="text-xs text-slate-400 mt-1">
                  {translateUiText("Estimated refill")}: <span className="text-emerald-400 font-medium">{item.estimatedRefillDate}</span>
                </p>
                <p className="text-xs text-slate-400 mt-1">{item.status}</p>
              </div>
            ))}
            <p className="text-xs text-slate-500 pt-2">{refill.disclaimer}</p>
          </div>
        ) : <p className="text-sm text-slate-400">{t("loadingPharmacistDashboard")}</p>}
      </PharmacistPremiumCard>

      <PharmacistPremiumCard title={translateUiText("Inventory risk alerts")}>
        {inventory ? (
          <div className="space-y-3 text-sm text-slate-300">
            {(inventory.alerts || []).map((item) => (
              <p key={item} className="rounded-xl bg-red-500/10 p-4 border border-red-500/20 text-red-200">
                {item}
              </p>
            ))}
            <p className="text-xs text-slate-500 pt-2">{inventory.disclaimer}</p>
          </div>
        ) : <p className="text-sm text-slate-400">{t("loadingPharmacistDashboard")}</p>}
      </PharmacistPremiumCard>

      <PharmacistPremiumCard title={translateUiText("Medication substitution suggestions")}>
        <input
          className="ph-input"
          placeholder={translateUiText("Enter medicine name")}
          value={medicineName}
          onChange={(event) => setMedicineName(event.target.value)}
        />
        <button className="ph-btn ph-btn-secondary mt-4 w-full sm:w-auto" type="button" onClick={runSubstitution}>
          {translateUiText("Get suggestions")}
        </button>
        {substitutionError ? <p className="text-sm text-red-400 mt-2">{substitutionError}</p> : null}
        {substitution ? (
          <div className="mt-4 space-y-2 text-sm text-slate-300 bg-white/5 p-4 rounded-xl border border-white/10">
            <ul className="list-disc pl-5 space-y-1">
              {(Array.isArray(substitution.suggestions) ? substitution.suggestions : []).map((item) => <li key={item}>{item}</li>)}
            </ul>
            <p className="text-xs text-slate-500 mt-3 pt-3 border-t border-white/10">{substitution.disclaimer}</p>
          </div>
        ) : null}
      </PharmacistPremiumCard>
    </div>
  );
}

import { useEffect, useState } from "react";
import PremiumSectionCard from "../../components/PremiumSectionCard";
import LocalizedText from "../../components/LocalizedText";
import { useLanguage } from "../../context/LanguageContext";
import { fetchAiRiskPrediction } from "../services/aiService";
import { getApiErrorMessage } from "../../utils/apiError";

export default function AiRiskCard({ patientId, titleKey = "aiRiskInsights" }) {
  const { language, t } = useLanguage();
  const [insight, setInsight] = useState(null);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (!patientId) {
      setInsight(null);
      setError("");
      return;
    }

    let active = true;
    setLoading(true);
    fetchAiRiskPrediction(patientId)
      .then((data) => {
        if (active) {
          setInsight(data);
          setError("");
        }
      })
      .catch((err) => {
        if (active) {
          setError(getApiErrorMessage(err, t("unableLoadAiRisk")));
        }
      })
      .finally(() => {
        if (active) {
          setLoading(false);
        }
      });

    return () => {
      active = false;
    };
  }, [patientId, language]);

  return (
    <PremiumSectionCard title={<LocalizedText value={t(titleKey)} forceTranslate minLength={1} sourceLanguage="auto" />}>
      {!patientId ? <p className="text-sm text-ink-muted/80">{t("selectAppointment")}</p> : null}
      {loading ? (
        <div className="space-y-3 animate-pulse">
          <div className="h-16 bg-white/10 rounded-xl w-full"></div>
          <div className="h-4 bg-white/10 rounded w-3/4"></div>
          <div className="h-4 bg-white/10 rounded w-5/6"></div>
        </div>
      ) : null}
      {error ? <p className="text-sm text-alert">{error}</p> : null}
      {!loading && !error && insight ? (
        <div className="space-y-4">
          <div className="flex items-center justify-between rounded-xl bg-white/5 border border-white/10 px-4 py-3">
            <div>
              <p className="text-xs font-semibold text-ink-muted uppercase tracking-widest">{t("aiRiskCategory")}</p>
              <p className="text-lg font-bold text-primary mt-1">
                <LocalizedText value={insight.category} forceTranslate minLength={1} sourceLanguage="auto" />
              </p>
            </div>
            <div className="text-right">
              <p className="text-xs font-semibold text-ink-muted uppercase tracking-widest">{t("aiRiskScore")}</p>
              <p className="text-lg font-bold text-ink mt-1">{insight.score}<span className="text-sm text-ink-muted">/100</span></p>
            </div>
          </div>
          <div className="space-y-2 bg-white/5 border border-white/10 p-4 rounded-xl">
            {Array.isArray(insight.insights) ? insight.insights.map((item, index) => (
              <LocalizedText
                key={`${item}-${index}`}
                as="p"
                className="text-sm text-ink/90 flex gap-2"
                value={`ΓÇó ${item}`}
                forceTranslate
                minLength={1}
                sourceLanguage="auto"
              />
            )) : null}
          </div>
          <LocalizedText as="p" className="text-[10px] text-slate-400 italic px-1" value={insight.disclaimer} forceTranslate minLength={1} sourceLanguage="auto" />
        </div>
      ) : null}
    </PremiumSectionCard>
  );
}

