    }
  };

  const runVideoAnalysis = async () => {
    if (!videoObservations.trim()) return;
    setVideoError("");
    try {
      setVideoResult(await analyzeVideoObservations({ observations: videoObservations.trim() }));
    } catch (err) {
      setVideoError(getApiErrorMessage(err, translateUiText("Unable to analyze consultation observations.")));
    }
  };

  const loadAnomalyReport = async () => {
    if (!patientId) return;
    setAnomalyError("");
    try {
      setAnomalyReport(await fetchAnomalyReport(patientId));
    } catch (err) {
      setAnomalyError(getApiErrorMessage(err, translateUiText("Unable to load anomaly detection report.")));
    }
  };

  const loadRecommendations = async () => {
    if (!patientId) return;
    setRecommendationError("");
    try {
      setRecommendations(await fetchRecommendations(patientId));
    } catch (err) {
      setRecommendationError(getApiErrorMessage(err, translateUiText("Unable to load recommendations.")));
    }
  };

  const triggerAutomation = async () => {
    setN8nError("");
    try {
      setN8nResult(await triggerN8nWorkflow({
        workflowName: "telecare-followup-demo",
        patientId: patientId ? Number(patientId) : null,
        payload: { role, source: "ai-hub" }
      }));
    } catch (err) {
      setN8nError(getApiErrorMessage(err, translateUiText("Unable to trigger automation workflow.")));
    }
  };

  return (
    <div className="space-y-8">
      <SectionCard title={roleLabel}>
        <p className="text-sm text-slate-600">
          <LocalizedText value={translateUiText("Premium AI feature lab for TeleCare+. Use this space to explore advanced, explainable AI insights by role.")} />
        </p>
      </SectionCard>

      <SectionCard title={translateUiText("Identity context")}>
        <div className="grid gap-4 md:grid-cols-4">
          <label className="text-sm text-slate-600">
            {translateUiText("Patient ID")}
            <input className="field mt-2" value={patientId} onChange={(e) => setPatientId(e.target.value)} />
          </label>
          <label className="text-sm text-slate-600">
            {translateUiText("Doctor ID")}
            <input className="field mt-2" value={doctorId} onChange={(e) => setDoctorId(e.target.value)} />
          </label>
          <label className="text-sm text-slate-600">
            {translateUiText("Caregiver ID")}
            <input className="field mt-2" value={caregiverId} onChange={(e) => setCaregiverId(e.target.value)} />
          </label>
          <label className="text-sm text-slate-600">
            {translateUiText("Pharmacist ID")}
            <input className="field mt-2" value={pharmacistId} onChange={(e) => setPharmacistId(e.target.value)} />
          </label>
        </div>
        <p className="mt-3 text-xs text-slate-500">
          {translateUiText("Role detected")}: {role}
        </p>
      </SectionCard>

      <div className="grid gap-6 xl:grid-cols-2">
        <SectionCard title={translateUiText("AI Symptom Navigator")}>
          <textarea
            className="field min-h-24 resize-y"
            placeholder={translateUiText("Describe symptoms in your own words")}
            value={symptomInput}
            onChange={(e) => setSymptomInput(e.target.value)}
          />
          <button className="btn-primary mt-3" type="button" onClick={submitSymptomChat}>
            {translateUiText("Analyze symptoms")}
          </button>
          {symptomError ? <p className="mt-2 text-sm text-red-600">{symptomError}</p> : null}
          {symptomResponse ? (
            <div className="mt-4 space-y-3 text-sm text-slate-700">
              <p className="font-semibold">{symptomResponse.reply}</p>
              <AiInsightBlock
                  title={translateUiText("Triage level")}
                subtitle={`${symptomResponse.triageLevel} ΓÇó ${translateUiText("Confidence")}: ${symptomResponse.confidence}`}
                items={symptomResponse.keyFindings}
                rationale={symptomResponse.rationale}
                disclaimer={symptomResponse.disclaimer}
              />
              <AiInsightBlock title={translateUiText("Next questions")} items={symptomResponse.nextQuestions} />
              <AiInsightBlock title={translateUiText("Safety checklist")} items={symptomResponse.safetyChecklist} />
            </div>
          ) : null}
        </SectionCard>

        <SectionCard title={translateUiText("Risk snapshot")}>
          <button className="btn-secondary" type="button" onClick={loadRiskSnapshot}>
            {translateUiText("Load snapshot")}
          </button>
          {riskError ? <p className="mt-2 text-sm text-red-600">{riskError}</p> : null}
          {riskSnapshot ? (
            <AiInsightBlock
              title={`${riskSnapshot.category} (${riskSnapshot.score}/100)`}
              subtitle={`${translateUiText("Confidence")}: ${riskSnapshot.confidence}`}
              items={riskSnapshot.drivers}
              disclaimer={riskSnapshot.disclaimer}
            />
          ) : null}
        </SectionCard>

        <SectionCard title={translateUiText("Appointment prep checklist")}>
          <button className="btn-secondary" type="button" onClick={loadPrepChecklist}>
            {translateUiText("Generate prep checklist")}
          </button>
          {prepError ? <p className="mt-2 text-sm text-red-600">{prepError}</p> : null}
          {prepData ? (
            <AiInsightBlock
              title={translateUiText("Checklist")}
              items={prepData.checklist}
              rationale={prepData.rationale}
              disclaimer={prepData.disclaimer}
            />
          ) : null}
        </SectionCard>

        <SectionCard title={translateUiText("Smart follow-up plan")}>
          <button className="btn-secondary" type="button" onClick={loadFollowPlan}>
            {translateUiText("Generate follow-up plan")}
          </button>
          {followError ? <p className="mt-2 text-sm text-red-600">{followError}</p> : null}
          {followPlan ? (
            <AiInsightBlock
              title={`${translateUiText("Recommended date")}: ${followPlan.recommendedDate}`}
              items={followPlan.planItems}
              rationale={followPlan.rationale}
              disclaimer={followPlan.disclaimer}
            />
          ) : null}
        </SectionCard>

        <SectionCard title={translateUiText("Multilingual translation for notes/chat")}>
          <textarea
            className="field min-h-24 resize-y"
            placeholder={translateUiText("Paste a note to translate")}
            value={translationText}
            onChange={(e) => setTranslationText(e.target.value)}
          />
          <div className="mt-3 flex flex-wrap items-center gap-3">
            <select className="field" value={translationTarget} onChange={(e) => setTranslationTarget(e.target.value)}>
              {languageOptions.map((opt) => <option key={opt.value} value={opt.value}>{opt.label}</option>)}
            </select>
            <button className="btn-primary" type="button" onClick={runTranslation}>
              {translateUiText("Translate")}
            </button>
          </div>
          {translationError ? <p className="mt-2 text-sm text-red-600">{translationError}</p> : null}
          {translationResult ? (
            <div className="mt-4 space-y-2 text-sm text-slate-700">
              <p className="font-semibold">{translateUiText("Translated output")}</p>
              <div className="rounded-2xl bg-mist p-4">{translationResult.text}</div>
              <p className="text-xs text-slate-500">{translateUiText("Provider")}: {translationResult.provider}</p>
            </div>
          ) : null}
        </SectionCard>
      </div>

      <SectionCard title={translateUiText("Patient AI panels (live data)")}>
        <AiPatientInsightsPanel patientId={patientId || defaultId} />
      </SectionCard>

      <SectionCard title={translateUiText("Mental health check-in")}>
        <AiMoodInsightsPanel patientId={patientId || defaultId} />
      </SectionCard>

      <SectionCard title={translateUiText("Doctor AI panels (live data)")}>
        <AiDoctorInsightsPanel doctorId={doctorId || defaultId} />
      </SectionCard>

      <SectionCard title={translateUiText("ICD coding suggestions")}>
        <textarea
          className="field min-h-24 resize-y"
          placeholder={translateUiText("Paste consultation notes")}
          value={icdNotes}
          onChange={(e) => setIcdNotes(e.target.value)}
        />
        <button className="btn-primary mt-3" type="button" onClick={runIcdSuggestions}>
          {translateUiText("Generate ICD suggestions")}
        </button>
        {icdError ? <p className="mt-2 text-sm text-red-600">{icdError}</p> : null}
        {icdResult ? (
          <AiInsightBlock
            title={translateUiText("Suggested codes")}
            items={icdResult.codes}
            rationale={icdResult.rationale}
            disclaimer={icdResult.disclaimer}
          />
        ) : null}
      </SectionCard>

      <SectionCard title={translateUiText("Caregiver AI panels (live data)")}>
        <AiCaregiverInsightsPanel caregiverId={caregiverId || defaultId} />
      </SectionCard>

      <SectionCard title={translateUiText("Care plan adherence summary")}>
        <button className="btn-secondary" type="button" onClick={loadCarePlan}>
          {translateUiText("Generate adherence summary")}
        </button>
        {carePlanError ? <p className="mt-2 text-sm text-red-600">{carePlanError}</p> : null}
        {carePlan ? (
          <AiInsightBlock
            title={`${translateUiText("Adherence rate")}: ${carePlan.adherenceRate}%`}
            items={carePlan.gaps}
            rationale={carePlan.rationale}
            disclaimer={carePlan.disclaimer}
          />
        ) : null}
      </SectionCard>

      <SectionCard title={translateUiText("Pharmacist AI panels (live data)")}>
        <AiPharmacistInsightsPanel pharmacistId={pharmacistId || defaultId} />
      </SectionCard>

      <SectionCard title={translateUiText("Dispense anomaly detection")}>
        <button className="btn-secondary" type="button" onClick={loadDispenseAnomaly}>
          {translateUiText("Analyze dispensing activity")}
        </button>
        {dispenseError ? <p className="mt-2 text-sm text-red-600">{dispenseError}</p> : null}
        {dispenseAnomaly ? (
          <AiInsightBlock
            title={translateUiText("Dispense monitoring")}
            items={dispenseAnomaly.alerts}
            rationale={dispenseAnomaly.rationale}
            disclaimer={dispenseAnomaly.disclaimer}
          />
        ) : null}
      </SectionCard>

      <SectionCard title={translateUiText("AI medical report generator")}>
        <button className="btn-secondary" type="button" onClick={loadReportOutline}>
          {translateUiText("Build report outline")}
        </button>
        {reportOutline ? (
          <div className="mt-4 space-y-3 text-sm text-slate-700">
            <p className="font-semibold">{reportOutline.title}</p>
            {reportOutline.sections.map((section) => (
              <AiInsightBlock
                key={section.title}
                title={section.title}
                items={section.content}
                disclaimer={reportOutline.disclaimer}
              />
            ))}
            {reportOutline.exportAvailable ? (
              <button className="btn-primary" type="button" onClick={downloadReport}>
                {translateUiText("Download report file")}
              </button>
            ) : null}
          </div>
        ) : null}
        {reportError ? <p className="mt-2 text-sm text-red-600">{reportError}</p> : null}
      </SectionCard>

      <SectionCard title={translateUiText("Predictive disease risk model")}>
        <button className="btn-secondary" type="button" onClick={loadPredictiveRisk}>
          {translateUiText("Generate predictive risk")}
        </button>
        {predictiveError ? <p className="mt-2 text-sm text-red-600">{predictiveError}</p> : null}
        {predictiveRisk ? (
          <div className="mt-4 space-y-3 text-sm text-slate-700">
            {predictiveRisk.forecasts.map((item) => (
              <AiInsightBlock
                key={item.condition}
                title={`${item.condition} ΓÇó ${item.probability}%`}
                subtitle={`${translateUiText("Horizon")}: ${item.horizonDays} ${translateUiText("days")}`}
                items={[item.rationale]}
                disclaimer={predictiveRisk.disclaimer}
              />
            ))}
          </div>
        ) : null}
      </SectionCard>

      <SectionCard title={translateUiText("Health anomaly detection")}>
        <button className="btn-secondary" type="button" onClick={loadAnomalyReport}>
          {translateUiText("Analyze anomalies")}
        </button>
        {anomalyError ? <p className="mt-2 text-sm text-red-600">{anomalyError}</p> : null}
        {anomalyReport ? (
          <AiInsightBlock
            title={`${translateUiText("Severity")}: ${anomalyReport.severity}`}
            items={anomalyReport.anomalies}
            rationale={anomalyReport.rationale}
            disclaimer={anomalyReport.disclaimer}
          />
        ) : null}
      </SectionCard>

      <SectionCard title={translateUiText("Personalized recommendations")}>
        <button className="btn-secondary" type="button" onClick={loadRecommendations}>
          {translateUiText("Generate recommendations")}
        </button>
        {recommendationError ? <p className="mt-2 text-sm text-red-600">{recommendationError}</p> : null}
        {recommendations ? (
          <AiInsightBlock
            title={translateUiText("Recommendations")}
            items={recommendations.recommendations}
            rationale={recommendations.rationale}
            disclaimer={recommendations.disclaimer}
          />
        ) : null}
      </SectionCard>

      <SectionCard title={translateUiText("Video consultation analysis (notes-based)")}>
        <textarea
          className="field min-h-24 resize-y"
          placeholder={translateUiText("Enter observations from the video consultation")}
          value={videoObservations}
          onChange={(e) => setVideoObservations(e.target.value)}
        />
        <button className="btn-primary mt-3" type="button" onClick={runVideoAnalysis}>
          {translateUiText("Analyze observations")}
        </button>
        {videoError ? <p className="mt-2 text-sm text-red-600">{videoError}</p> : null}
        {videoResult ? (
          <AiInsightBlock
            title={`${translateUiText("Risk level")}: ${videoResult.riskLevel}`}
            items={[videoResult.summary, ...videoResult.signals]}
            rationale={videoResult.rationale}
            disclaimer={videoResult.disclaimer}
          />
        ) : null}
      </SectionCard>

      <SectionCard title={translateUiText("n8n workflow integration (optional)")}>
        <button className="btn-secondary" type="button" onClick={triggerAutomation}>
          {translateUiText("Trigger follow-up workflow")}
        </button>
        {n8nError ? <p className="mt-2 text-sm text-red-600">{n8nError}</p> : null}
        {n8nResult ? (
          <AiInsightBlock
            title={`${translateUiText("Status")}: ${n8nResult.status}`}
            items={[n8nResult.message]}
            rationale={n8nResult.rationale}
          />
        ) : null}
      </SectionCard>

      <SectionCard title={translateUiText("Automation & escalation workflow engine")}>
        <div className="flex flex-wrap gap-3">
          <button className="btn-secondary" type="button" onClick={loadAutomationPlans}>
            {translateUiText("Load automation plans")}
          </button>
          <button className="btn-secondary" type="button" onClick={loadEscalationRules}>
            {translateUiText("Load escalation rules")}
          </button>
        </div>
        {automationError ? <p className="mt-2 text-sm text-red-600">{automationError}</p> : null}
        {automationPlans ? (
          <div className="mt-4 grid gap-3">
            {automationPlans.flows.map((flow) => (
              <AiInsightBlock
                key={flow.name}
                title={flow.name}
                subtitle={`${translateUiText("Owner")}: ${flow.ownerRole}`}
                items={[`${translateUiText("Trigger")}: ${flow.trigger}`, ...flow.actions]}
                disclaimer={automationPlans.disclaimer}
              />
            ))}
          </div>
        ) : null}
        {escalationError ? <p className="mt-2 text-sm text-red-600">{escalationError}</p> : null}
        {escalationRules ? (
          <div className="mt-4 grid gap-3">
            {escalationRules.rules.map((rule) => (
              <AiInsightBlock
                key={rule.condition}
                title={`${rule.condition} (${rule.severity})`}
                items={[rule.action]}
                rationale={[rule.rationale]}
                disclaimer={escalationRules.disclaimer}
              />
            ))}
          </div>
        ) : null}
      </SectionCard>

      <SectionCard title={translateUiText("AI audit & compliance dashboard")}>
        <button className="btn-secondary" type="button" onClick={loadCompliance}>
          {translateUiText("Load compliance view")}
        </button>
        {complianceError ? <p className="mt-2 text-sm text-red-600">{complianceError}</p> : null}
        {compliance ? (
          <div className="mt-4 space-y-3 text-sm text-slate-700">
            {compliance.metrics.map((metric) => (
              <AiInsightBlock
                key={metric.name}
                title={metric.name}
                subtitle={metric.status}
                items={[metric.detail]}
              />
            ))}
            <AiInsightBlock items={compliance.highlights} disclaimer={compliance.disclaimer} />
          </div>
        ) : null}
      </SectionCard>
    </div>
  );
}

import { useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { ArrowLeft, ArrowRight, Brain, User, LogOut } from "lucide-react";
import { MentalHealthIllustration } from "../../components/illustrations/CareIllustrations";
import { useLanguage } from "../../context/LanguageContext";
import { useAuth } from "../../context/AuthContext";
import { runMentalHealthAssessment, sendMentalHealthChat } from "../services/aiService";
import { getApiErrorMessage } from "../../utils/apiError";
import PatientSidebar from "../../components/PatientSidebar";
import "../../pages/patient-booking-override.css";
import { buildLoginRedirect } from "../../utils/authSession";
import LanguageSwitcher from "../../components/LanguageSwitcher";

const moodOptions = [
  { label: "Very low", emoji: "Low", value: "very-low", tone: "danger" },
  { label: "Low", emoji: "Soft", value: "low", tone: "warning" },
  { label: "Okay", emoji: "Steady", value: "okay", tone: "info" },
  { label: "Good", emoji: "Bright", value: "good", tone: "success" },
  { label: "Great", emoji: "Calm", value: "great", tone: "success" }
];

const initialForm = {
  mood: "",
  stress: 4,
  anxiety: 4,
  notes: ""
};

export default function MentalHealthCheckinPage() {
  const { auth, logout } = useAuth();
  const navigate = useNavigate();
  const { t } = useLanguage();
  
  const [step, setStep] = useState(0);
  const [form, setForm] = useState(initialForm);
  const [messages, setMessages] = useState([]);
  const [status, setStatus] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const steps = useMemo(() => ([
    {
      key: "mood",
      title: "How are you feeling today?",
      description: "Choose the option that matches your overall mood."
    },
    {
      key: "stress",
      title: "How stressed do you feel right now?",
      description: "0 means calm, 10 means overwhelming."
    },
    {
      key: "anxiety",
      title: "How anxious do you feel right now?",
      description: "0 means relaxed, 10 means intense worry."
    },
    {
      key: "notes",
      title: "Anything you want to share?",
      description: "A few words are enough. This is optional but useful."
    }
  ]), []);

  const currentStep = steps[step];
  const progress = Math.round(((step + 1) / steps.length) * 100);

  const goNext = () => {
    if (currentStep.key === "mood" && !form.mood) {
      setError("Choose a mood to continue.");
      return;
    }
    setError("");
    setStep((current) => Math.min(current + 1, steps.length - 1));
  };

  const goBack = () => {
    setError("");
    setStep((current) => Math.max(current - 1, 0));
  };

  const submitCheckin = async () => {
    const summary = `Mood: ${form.mood || "not selected"}, Stress: ${form.stress}/10, Anxiety: ${form.anxiety}/10. Notes: ${form.notes || "No additional notes."}`;
    setLoading(true);
    setError("");

    try {
      const [chat, assessment] = await Promise.all([
        sendMentalHealthChat({ message: summary, sessionId: "" }),
        runMentalHealthAssessment({ text: summary })
      ]);

      setMessages([
        { role: "assistant", text: chat.response },
        ...(Array.isArray(chat.suggestions) ? chat.suggestions.map((item) => ({ role: "assistant", text: item })) : []),
        { role: "assistant", text: assessment.guidance }
      ]);
      setStatus(`Risk level: ${assessment.riskLevel}`);
    } catch (err) {
      setError(getApiErrorMessage(err, "Unable to load mental health guidance."));
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    logout();
    navigate(buildLoginRedirect(""), { replace: true });
  };

  return (
    <div id="tct-root">
      <div className="app">
        <PatientSidebar />
        
        <main id="page-main" role="main">
          <div className="topbar">
            <div>
              <h1 className="serif">Mental Health Check-in</h1>
              <p>Track your well-being with daily structured reflections.</p>
              <div className="eyebrow-pill" style={{ marginTop: '12px' }}>
                <Brain />Support
              </div>
              <div className="signed-in" style={{ marginTop: '12px', marginLeft: '8px' }}>
                <User />
                Signed in as {auth?.fullName || "Anita Patient"}
              </div>
            </div>
            <div className="topbar-right">
              <LanguageSwitcher customClass="lang" hideLabel />
              <button className="btn-ghost" onClick={handleLogout} aria-label="Log out">
                <LogOut />Logout
              </button>
            </div>
          </div>

          <div className="booking-layout">
            <div style={{ flex: 1, padding: '32px', maxWidth: '1000px', margin: '0 auto', width: '100%' }}>
              
              <div className="tct-animate-in">
                
                {/* Guided Flow */}
                <div className="doctor-card" style={{ cursor: 'default', padding: '0', overflow: 'hidden' }}>
                  
                  {/* Header / Graphic */}
                  <div style={{ background: 'var(--tct-panel)', borderBottom: '1px solid var(--tct-panel-line-strong)', padding: '32px' }}>
                    <div className="doctors-grid" style={{ gridTemplateColumns: 'minmax(0,1fr) 180px', gap: '32px', alignItems: 'center' }}>
                      <div>
                        <p style={{ fontSize: '12px', fontWeight: '600', textTransform: 'uppercase', letterSpacing: '0.1em', color: 'var(--tct-teal)' }}>
                          Step {step + 1} of {steps.length}
                        </p>
                        <h2 style={{ fontSize: '24px', fontWeight: '600', color: '#FFFFFF', marginTop: '8px', marginBottom: '8px' }}>{currentStep.title}</h2>
                        <p style={{ fontSize: '15px', color: 'var(--tct-text-secondary)', lineHeight: '1.5', maxWidth: '600px' }}>{currentStep.description}</p>
                        
                        <div style={{ display: 'flex', gap: '8px', marginTop: '16px' }}>
                          <span style={{ fontSize: '11px', padding: '4px 10px', background: 'rgba(255,255,255,0.05)', color: 'var(--tct-text-muted)', borderRadius: '100px', fontWeight: '600' }}>{progress}% Complete</span>
                          <span style={{ fontSize: '11px', padding: '4px 10px', background: 'var(--tct-teal-dim)', color: 'var(--tct-teal)', borderRadius: '100px', fontWeight: '600' }}>Private & Secure</span>
                        </div>
                      </div>
                      <div style={{ margin: '0 auto', opacity: 0.8 }}>
                        <MentalHealthIllustration />
                      </div>
                    </div>

                    <div style={{ height: '4px', background: 'rgba(255,255,255,0.05)', borderRadius: '100px', overflow: 'hidden', marginTop: '32px' }}>
                      <div style={{ height: '100%', width: `${progress}%`, background: 'var(--tct-teal)', transition: 'width 0.3s ease' }}></div>
                    </div>
                  </div>

                  {/* Body */}
                  <div style={{ padding: '32px' }}>
                    
                    {currentStep.key === "mood" ? (
                      <div className="doctors-grid" style={{ gridTemplateColumns: 'repeat(auto-fit, minmax(140px, 1fr))', gap: '16px' }}>
                        {moodOptions.map(option => (
                          <button
                            key={option.value}
                            onClick={() => setForm(c => ({...c, mood: option.value}))}
                            style={{
                              padding: '24px 16px',
                              background: form.mood === option.value ? 'var(--tct-teal-dim)' : 'rgba(255,255,255,0.02)',
                              border: form.mood === option.value ? '1px solid var(--tct-teal)' : '1px solid var(--tct-panel-line-strong)',
                              borderRadius: '16px',
                              textAlign: 'center',
                              cursor: 'pointer',
                              transition: 'all 0.2s ease',
                              outline: 'none',
                              color: form.mood === option.value ? 'var(--tct-teal)' : '#FFFFFF'
                            }}
                          >
                            <div style={{ 
                              display: 'inline-flex', padding: '4px 12px', borderRadius: '100px', fontSize: '13px', fontWeight: '600', marginBottom: '16px',
                              background: option.tone === 'danger' ? 'rgba(239, 68, 68, 0.1)' : option.tone === 'warning' ? 'rgba(245, 158, 11, 0.1)' : 'rgba(255,255,255,0.05)',
                              color: option.tone === 'danger' ? 'var(--tct-coral)' : option.tone === 'warning' ? '#C9A24B' : 'var(--tct-text-secondary)'
                            }}>
                              {option.emoji}
                            </div>
                            <p style={{ fontSize: '16px', fontWeight: '600' }}>{option.label}</p>
                          </button>
                        ))}
                      </div>
                    ) : null}

                    {currentStep.key === "stress" || currentStep.key === "anxiety" ? (
                      <div style={{ padding: '32px', background: 'rgba(255,255,255,0.02)', border: '1px solid var(--tct-panel-line-strong)', borderRadius: '16px' }}>
                        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', color: 'var(--tct-text-muted)', fontSize: '14px', fontWeight: '500', marginBottom: '24px' }}>
                          <span>0 - Calm</span>
                          <span style={{ fontSize: '24px', fontWeight: '700', color: '#FFFFFF' }}>{form[currentStep.key]}/10</span>
                          <span>10 - Intense</span>
                        </div>
                        <input
                          type="range"
                          min="0"
                          max="10"
                          value={form[currentStep.key]}
                          onChange={(e) => setForm(c => ({...c, [currentStep.key]: Number(e.target.value)}))}
                          style={{ width: '100%', cursor: 'pointer', accentColor: 'var(--tct-teal)' }}
                        />
                      </div>
                    ) : null}

                    {currentStep.key === "notes" ? (
                      <div>
                        <textarea
                          placeholder="Share anything that may help your care team understand today better."
                          value={form.notes}
                          onChange={(e) => setForm(c => ({...c, notes: e.target.value}))}
                          style={{
                            width: '100%', minHeight: '160px', padding: '16px', background: 'rgba(255,255,255,0.03)',
                            border: '1px solid var(--tct-panel-line-strong)', borderRadius: '12px', color: '#FFFFFF', fontSize: '15px', resize: 'vertical', outline: 'none', lineHeight: '1.5'
                          }}
                        />
                      </div>
                    ) : null}

                    {error && <p style={{ fontSize: '14px', color: 'var(--tct-coral)', marginTop: '16px', fontWeight: '500' }}>{error}</p>}

                    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginTop: '32px' }}>
                      <button className="btn-secondary" disabled={step === 0 || loading} onClick={goBack} style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                        <ArrowLeft size={16} /> Back
                      </button>
                      
                      {step < steps.length - 1 ? (
                        <button className="btn-primary" onClick={goNext} disabled={loading} style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                          Continue <ArrowRight size={16} />
                        </button>
                      ) : (
                        <button className="btn-primary" onClick={submitCheckin} disabled={loading} style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                          {loading ? "Saving..." : "Save check-in"}
                        </button>
                      )}
                    </div>
                  </div>
                </div>

                {/* History & AI Guidance */}
                <div className="doctors-grid" style={{ gridTemplateColumns: '1fr 1fr', gap: '24px', marginTop: '24px', alignItems: 'start' }}>
                  
                  {/* Mood Pattern */}
                  <div>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '16px', marginBottom: '16px' }}>
                       <h3 style={{ fontSize: '18px', fontWeight: '600', color: '#FFFFFF' }}>Mood History Snapshot</h3>
                       <div style={{ flex: 1, height: '1px', background: 'var(--tct-panel-line)' }}></div>
                    </div>
                    
                    <div className="doctor-card" style={{ cursor: 'default', padding: '24px' }}>
                      
                      <div style={{ display: 'flex', height: '140px', alignItems: 'flex-end', gap: '12px', marginBottom: '24px' }}>
                        {[42, 54, 46, 68, 58, 72, 64].map((value, idx) => (
                          <div key={idx} style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '8px' }}>
                            <div style={{ width: '100%', height: `${value}%`, background: idx === 6 ? 'var(--tct-teal)' : 'rgba(255,255,255,0.1)', borderRadius: '4px 4px 0 0', transition: 'height 0.3s ease' }}></div>
                            <span style={{ fontSize: '11px', fontWeight: '600', color: idx === 6 ? 'var(--tct-teal)' : 'var(--tct-text-muted)' }}>
                              {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'][idx]}
                            </span>
                          </div>
                        ))}
                      </div>

                      <div style={{ background: 'rgba(255,255,255,0.02)', borderLeft: '3px solid var(--tct-teal)', padding: '16px', borderRadius: '8px', marginBottom: '16px' }}>
                        <p style={{ fontSize: '12px', fontWeight: '600', textTransform: 'uppercase', color: 'var(--tct-teal)', marginBottom: '8px' }}>Pattern Insight</p>
                        <p style={{ fontSize: '14px', lineHeight: '1.5', color: '#E2E8F0' }}>Stress tends to rise mid-week. Completing a short check-in earlier in the day can help us spot patterns faster.</p>
                      </div>

                      <div style={{ background: 'rgba(239, 68, 68, 0.1)', borderLeft: '3px solid var(--tct-coral)', padding: '16px', borderRadius: '8px' }}>
                        <p style={{ fontSize: '12px', fontWeight: '600', textTransform: 'uppercase', color: 'var(--tct-coral)', marginBottom: '8px' }}>Support Prompt</p>
                        <p style={{ fontSize: '14px', lineHeight: '1.5', color: '#E2E8F0' }}>If you are feeling overwhelmed or unsafe, contact your doctor or trusted caregiver immediately.</p>
                      </div>

                    </div>
                  </div>

                  {/* AI Output */}
                  {(status || messages.length > 0) && (
                    <div>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '16px', marginBottom: '16px' }}>
                         <h3 style={{ fontSize: '18px', fontWeight: '600', color: '#FFFFFF' }}>AI Guidance</h3>
                         <div style={{ flex: 1, height: '1px', background: 'var(--tct-panel-line)' }}></div>
                      </div>

                      <div className="doctor-card" style={{ cursor: 'default', padding: '24px' }}>
                        {status && (
                          <div style={{ display: 'inline-flex', alignItems: 'center', gap: '8px', marginBottom: '16px', padding: '12px 16px', background: 'rgba(255,255,255,0.05)', borderRadius: '100px' }}>
                            <span style={{ fontSize: '12px', fontWeight: '600', color: 'var(--tct-teal)' }}>{status}</span>
                          </div>
                        )}
                        
                        <div className="space-y-4">
                          {messages.map((msg, idx) => (
                            <div key={idx} style={{ padding: '16px', background: 'rgba(255,255,255,0.02)', border: '1px solid var(--tct-panel-line-strong)', borderRadius: '12px' }}>
                              <p style={{ fontSize: '14px', lineHeight: '1.6', color: '#E2E8F0' }}>{msg.text}</p>
                            </div>
                          ))}
                        </div>
                      </div>
                    </div>
                  )}

                </div>

              </div>

            </div>
          </div>
        </main>
      </div>
    </div>
  );
}

