      <div className="min-h-screen bg-canvas px-4 py-6 md:px-8">
        <div className="mx-auto max-w-3xl">
          <LoadingSkeleton lines={5} />
        </div>
      </div>
    );
  }

  const routes = Array.isArray(roleRoutes[normalizedRole]) ? roleRoutes[normalizedRole] : [];
  
  const renderIcon = (key) => {
    const base = "w-5 h-5";
    switch (key) {
      case "dashboard": return <Home className={base} />;
      case "profile": return <ShieldCheck className={base} />;
      case "appointments":
      case "consultation": return <CalendarDays className={base} />;
      case "book":
      case "booking": return <ClipboardPlus className={base} />;
      case "carePlans": return <ClipboardList className={base} />;
      case "prescriptions":
      case "dispensing": return <Pill className={base} />;
      case "reminders":
      case "alerts":
      case "notifications": return <Bell className={base} />;
      case "triage":
      case "health":
      case "observations": return <HeartPulse className={base} />;
      case "messages":
      case "aiChatbot": return <MessageSquareText className={base} />;
      case "ivrBooking":
      case "voiceAssist": return <Mic className={base} />;
      case "futureCare": return <Hospital className={base} />;
      case "familyNetwork": return <Users className={base} />;
      case "timeline":
      case "intelligence":
      case "populationInsights":
      case "monitoring":
      case "careGaps": return <Activity className={base} />;
      case "education":
      case "mentalHealthCheckin": return <NotebookPen className={base} />;
      case "referrals": return <Stethoscope className={base} />;
      case "inventory": return <Package className={base} />;
      case "records": return <FileText className={base} />;
