    }
  };

  const languageSearch = (() => {
    try {
      const params = new URLSearchParams(location.search || "");
      const lang = params.get("lang") || language;
      return lang && lang !== "en" ? `?lang=${lang}` : "";
    } catch {
      return language && language !== "en" ? `?lang=${language}` : "";
    }
  })();

  const resolvedRole = normalizedRole ?? "";
  const roleLabelKey = resolvedRole === "PATIENT" ? "patientCredential" : resolvedRole === "DOCTOR" ? "doctorCredential" : resolvedRole === "CAREGIVER" ? "caregiverCredential" : resolvedRole === "ADMIN" ? "admin" : "pharmacistCredential";

  const sectionLabels = {
    Care: localizedChromeCopy[language]?.Care ?? translateUiText("Care"),
    Medications: localizedChromeCopy[language]?.Medications ?? translateUiText("Medications"),
    Health: localizedChromeCopy[language]?.Health ?? translateUiText("Health"),
    Support: localizedChromeCopy[language]?.Support ?? translateUiText("Support"),
    "Family & Community": localizedChromeCopy[language]?.["Family & Community"] ?? translateUiText("Family & Community"),
    Insights: localizedChromeCopy[language]?.Insights ?? translateUiText("Insights"),
    Profile: localizedChromeCopy[language]?.Profile ?? translateUiText("Profile"),
    General: localizedChromeCopy[language]?.General ?? translateUiText("General")
  };

  const groupedRoutes = routes.reduce((acc, item) => {
    const section = item.section || "General";
    if (!acc[section]) acc[section] = [];
    acc[section].push(item);
    return acc;
  }, {});

  const sectionOrder = [
    "Workspace", "Patient Management", "Clinical Intelligence", "Care", "Medications", "Health", 
    "Actions", "Operations", "Communication", "Support", "Family & Community", "Insights", 
    "Profile", "Account", "General"
  ];
  const activeRoute = routes.find((item) => item.path === location.pathname);
  const activeTitle = activeRoute ? translateUiText(t(activeRoute.labelKey)) : translateUiText(t("continuityWorkspace"));
  const activeSection = activeRoute?.section ? (sectionLabels[activeRoute.section] ?? translateUiText(activeRoute.section)) : "";

  useEffect(() => {
    if (typeof document === "undefined") return;
    const pageTitle = activeRoute ? translateUiText(t(activeRoute.labelKey)) : translateUiText(t("appName"));
    document.title = `TeleCare+ - ${pageTitle}`;
  }, [location.pathname, routes, t, translateUiText]);

  const handleLogout = () => {
    logout();
    navigate(buildLoginRedirect(languageSearch), { replace: true });
  };

  return (
    <div className="min-h-screen bg-canvas text-ink font-sans flex flex-col lg:flex-row overflow-hidden relative">
      
      {/* Mobile Header (replaces standard Sidebar on small screens) */}
      <div className="lg:hidden flex items-center justify-between p-4 bg-surface border-b border-white/10 shrink-0 z-50 relative">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 rounded-full bg-primary/20 flex items-center justify-center">
            <span className="text-white font-bold text-sm">T+</span>
          </div>
          <span className="font-display font-semibold text-lg tracking-wide text-white">TeleCare<span className="text-primary">+</span></span>
        </div>
        <button onClick={() => setMobileMenuOpen(!mobileMenuOpen)} className="p-2 text-ink-muted hover:text-ink hover:bg-white/5 rounded-md">
          {mobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </div>

      {/* Sidebar Navigation */}
      <aside className={`fixed inset-y-0 left-0 z-40 flex-shrink-0 w-full lg:w-[280px] bg-surface/30 lg:border-r border-white/10 transform transition-transform duration-300 ease-in-out lg:translate-x-0 lg:static lg:flex flex-col h-full ${mobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="flex items-center p-6 pb-4 shrink-0 border-b lg:border-b-0 border-white/10">
          <div className="font-display font-semibold text-xl tracking-tight text-ink flex items-center gap-1">
            TELECARE<span className="text-primary">+</span>
          </div>
        </div>
        
        <div className="flex-1 overflow-y-auto overflow-x-hidden custom-scrollbar px-3 py-4">
          <nav className="space-y-6">
            {sectionOrder
              .filter((section) => groupedRoutes[section]?.length)
              .map((section, index) => (
                <div key={section}>
                  {index > 0 && <div className="h-px w-full bg-white/5 mb-6"></div>}
                  <p className="px-3 mb-2 text-xs font-semibold tracking-wider text-ink-muted uppercase">
                    {sectionLabels[section] ?? translateUiText(section)}
                  </p>
                  <ul className="space-y-1">
                    {groupedRoutes[section].map((item) => {
                      const active = location.pathname === item.path;
                      
                      const hasBadge = item.labelKey === "messages" || item.labelKey === "alerts" || item.labelKey === "notifications";
                      const isNumberBadge = item.labelKey === "messages";

                      return (
                        <li key={item.path}>
                          <Link
                            to={`${item.path}${languageSearch}`}
                            onClick={() => setMobileMenuOpen(false)}
                            className={`flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm transition-all duration-200 group relative ${
                              active 
                                ? 'bg-gradient-to-r from-blue-600 to-indigo-600 text-white shadow-md shadow-blue-500/20 font-medium' 
                                : 'text-ink-muted hover:bg-white/5 hover:text-ink'
                            }`}
                          >
                            <span className={`transition-transform group-hover:translate-x-1 shrink-0 ${active ? "text-white" : "text-ink-muted group-hover:text-ink"}`}>
                              {renderIcon(item.labelKey)}
                            </span>
                            <span className="text-[14px]">{translateUiText(t(item.labelKey))}</span>
                            
                            {hasBadge && (
                              isNumberBadge ? (
                                <span className="ml-auto bg-rose-500 text-white text-[10px] font-bold px-2 py-0.5 rounded-full">3</span>
                              ) : (
                                <span className="ml-auto w-2 h-2 rounded-full bg-rose-500"></span>
                              )
                            )}
                          </Link>
                        </li>
                      );
                    })}
                  </ul>
                </div>
              ))}
          </nav>
        </div>

        <div className="p-4 shrink-0">
          <button onClick={handleLogout} className="flex items-center justify-center gap-2 w-full px-4 py-2.5 bg-white/5 hover:bg-white/10 border border-white/10 hover:border-white/20 text-ink rounded-xl transition-all font-semibold text-sm">
            <LogOut size={16} className="text-ink-muted" />
            {translateUiText(t("logout"))}
