      </aside>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col min-w-0 h-full overflow-hidden z-0" role="main">
        {/* Topbar for Desktop (Since sidebar covers navigation, topbar can be simpler or contain context info) */}
