            <div className="w-12 h-12 rounded-full bg-emerald-500/20 flex items-center justify-center mb-4">
              <CheckCircle2 className="w-6 h-6 text-emerald-400" />
            </div>
            <h4 className="font-bold text-lg text-white mb-1">Prior Auth Approved</h4>
            <p className="text-sm text-emerald-300 mb-4">Medication is now fully covered for the patient.</p>
            <button 
              onClick={() => setStatus("idle")}
              className="text-sm text-white bg-white/10 hover:bg-white/20 px-4 py-2 rounded-lg"
            >
              Submit Another
            </button>
          </div>
        )}

        {status === "denied" && (
          <div className="bg-rose-500/10 rounded-xl p-6 border border-rose-500/30 flex flex-col items-center justify-center text-center">
            <div className="w-12 h-12 rounded-full bg-rose-500/20 flex items-center justify-center mb-4">
              <ShieldAlert className="w-6 h-6 text-rose-400" />
            </div>
            <h4 className="font-bold text-lg text-white mb-1">Prior Auth Denied</h4>
            <p className="text-sm text-rose-300 mb-4">Does not meet step-therapy requirements. An alternative is recommended.</p>
