  ]
};

function readStoredSettings() {
  if (typeof window === "undefined" || typeof window.localStorage === "undefined") {
    return {
      largeText: false,
      highContrast: false,
      screenReaderMode: false
    };
  }

  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) {
      return {
        largeText: false,
        highContrast: false,
        screenReaderMode: false
      };
    }

    const stored = safeJsonParse(raw, {});
    if (!stored || typeof stored !== "object") {
      window.localStorage.removeItem(STORAGE_KEY);
      return {
        largeText: false,
        highContrast: false,
        screenReaderMode: false
      };
    }
    return {
      largeText: Boolean(stored.largeText),
      highContrast: Boolean(stored.highContrast),
      screenReaderMode: Boolean(stored.screenReaderMode)
    };
  } catch {
    try {
      window.localStorage.removeItem(STORAGE_KEY);
    } catch {
      // Ignore storage cleanup failures.
    }
    return {
      largeText: false,
      highContrast: false,
      screenReaderMode: false
    };
  }
}

function escapeRegExp(value) {
  return String(value).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function normalizeWhitespace(value) {
  return String(value || "")
    .replace(/_/g, " ")
    .replace(/\|/g, ", ")
    .replace(/\s+/g, " ")
    .trim();
}

function normalizeTextForSpeech(text, preferredLanguage = "en") {
  const localized = normalizeWhitespace(text);
  const tokens = SPEECH_FRIENDLY_TOKENS[preferredLanguage] || SPEECH_FRIENDLY_TOKENS.en;

  return tokens.reduce((current, [from, to]) => {
    const pattern = new RegExp(escapeRegExp(from), "gi");
    return current.replace(pattern, to);
  }, localized);
}

function detectContentLanguage(text, preferredLanguage = "en") {
  const value = String(text || "");

  if (/[\u0B80-\u0BFF]/.test(value)) return "ta";
  if (/[\u0C00-\u0C7F]/.test(value)) return "te";
  if (/[\u0D00-\u0D7F]/.test(value)) return "ml";
  if (/[\u0A00-\u0A7F]/.test(value)) return "pa";
  if (/[\u0900-\u097F]/.test(value)) return "hi";
  if (/[A-Za-z]/.test(value)) return "en";

  return preferredLanguage;
}

function buildSpeechSegments(text, preferredLanguage = "en") {
  const cleaned = normalizeWhitespace(text);
  if (!cleaned) {
    return [];
  }

  const parts = cleaned.match(
