import { useState, useEffect } from "react";
import { useLanguage } from "../context/LanguageContext";
import AdminLayout from "../components/AdminLayout";
import api from "../services/api";
import { getApiErrorMessage } from "../utils/apiError";
import { Users, Filter, CheckCircle2, XCircle, AlertTriangle } from "lucide-react";
import { toast } from "react-hot-toast";

export default function AdminUsersPage() {
  const { t } = useLanguage();
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [roleFilter, setRoleFilter] = useState("");
  const [statusFilter, setStatusFilter] = useState("");
  const [showModal, setShowModal] = useState(false);
  const [modalAction, setModalAction] = useState(null); 

  const fetchUsers = async () => {
    setLoading(true);
    try {
      const res = await api.get("/admin/users", {
        params: {
          role: roleFilter || undefined,
          active: statusFilter ? statusFilter === "true" : undefined
        }
      });
      setUsers(res.data);
      setError("");
    } catch (err) {
      setError(getApiErrorMessage(err, "Failed to load users"));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchUsers();
  }, [roleFilter, statusFilter]);

  const confirmAction = async () => {
    if (!modalAction) return;
    const { type, user } = modalAction;
    try {
      if (type === 'suspend') {
        await api.put(`/admin/users/${user.id}/suspend`);
        toast.success(`User ${user.fullName} suspended.`);
      } else if (type === 'reactivate') {
        await api.put(`/admin/users/${user.id}/reactivate`);
        toast.success(`User ${user.fullName} reactivated.`);
      } else if (type === 'reset') {
        const res = await api.put(`/admin/users/${user.id}/reset-password`);
        toast.success(res.data.message || `Password reset link sent to ${user.email}`);
      }
      fetchUsers();
    } catch (err) {
      toast.error(getApiErrorMessage(err, "Action failed"));
    } finally {
      setShowModal(false);
    }
  };

  const openModal = (type, user) => {
    setModalAction({ type, user });
    setShowModal(true);
  };

  return (
    <AdminLayout>
      <div className="mx-auto max-w-7xl space-y-8">
        <header className="flex flex-col gap-2 md:flex-row md:items-end justify-between">
          <div>
            <h1 className="text-2xl font-bold text-white flex items-center gap-2">
              <Users className="w-6 h-6 text-teal-400" />
              User Management
            </h1>
            <p className="text-sm text-slate-400 mt-1">Manage system access, roles, and security.</p>
          </div>
          <div className="flex gap-4">
            <div className="relative">
              <Filter className="w-4 h-4 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" />
              <select
                className="pl-9 py-2 pr-8 text-sm appearance-none min-w-[140px] bg-slate-900/50 border border-white/10 rounded-lg text-white outline-none focus:border-teal-500"
                value={roleFilter}
                onChange={(e) => setRoleFilter(e.target.value)}
              >
                <option value="">All Roles</option>
                <option value="ADMIN">Admin</option>
                <option value="DOCTOR">Doctor</option>
                <option value="PATIENT">Patient</option>
                <option value="CAREGIVER">Caregiver</option>
                <option value="PHARMACIST">Pharmacist</option>
              </select>
            </div>
            <select
              className="py-2 px-4 pr-8 text-sm appearance-none min-w-[140px] bg-slate-900/50 border border-white/10 rounded-lg text-white outline-none focus:border-teal-500"
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
            >
              <option value="">All Statuses</option>
              <option value="true">Active Only</option>
              <option value="false">Suspended Only</option>
            </select>
          </div>
        </header>

        {loading ? (
          <div className="flex justify-center p-12 text-slate-400">Loading users...</div>
        ) : error ? (
          <p className="text-rose-400 p-4 bg-rose-500/10 rounded-lg border border-rose-500/20">{error}</p>
        ) : (
          <div className="bg-slate-900/80 rounded-2xl border border-white/10 overflow-hidden shadow-2xl">
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse min-w-[800px]">
                <thead>
                  <tr className="bg-slate-900 border-b border-white/10">
                    <th className="px-6 py-4 text-xs font-semibold text-slate-300 uppercase tracking-wider">User</th>
                    <th className="px-6 py-4 text-xs font-semibold text-slate-300 uppercase tracking-wider">Role</th>
                    <th className="px-6 py-4 text-xs font-semibold text-slate-300 uppercase tracking-wider">Status</th>
                    <th className="px-6 py-4 text-xs font-semibold text-slate-300 uppercase tracking-wider text-right">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-white/5">
                  {users.map((user) => (
                    <tr key={user.id} className="hover:bg-white/5 transition-colors">
                      <td className="px-6 py-4">
                        <p className="font-semibold text-white">{user.fullName}</p>
                        <p className="text-sm text-slate-400">{user.email}</p>
                        <p className="text-xs text-slate-500">{user.phone}</p>
                      </td>
                      <td className="px-6 py-4">
                        <span className="inline-flex px-2 py-1 rounded-md bg-slate-800 text-xs font-medium text-slate-300 border border-white/10">
                          {user.role}
                        </span>
                      </td>
                      <td className="px-6 py-4">
                        {user.active ? (
                          <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-teal-500/10 text-xs font-semibold text-teal-400 border border-teal-500/20">
                            <CheckCircle2 className="w-3.5 h-3.5" /> Active
                          </span>
                        ) : (
                          <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-rose-500/10 text-xs font-semibold text-rose-400 border border-rose-500/20">
                            <XCircle className="w-3.5 h-3.5" /> Suspended
                          </span>
                        )}
                      </td>
                      <td className="px-6 py-4 text-right">
                        <div className="flex items-center justify-end gap-3">
                          <button
                            onClick={() => openModal('reset', user)}
                            className="text-xs font-medium text-indigo-400 hover:text-indigo-300 transition-colors"
                          >
                            Reset Password
                          </button>
                          {user.active ? (
                            <button
                              onClick={() => openModal('suspend', user)}
                              className="text-xs font-medium text-rose-400 hover:text-rose-300 transition-colors"
                            >
                              Suspend
                            </button>
                          ) : (
                            <button
                              onClick={() => openModal('reactivate', user)}
                              className="text-xs font-medium text-emerald-400 hover:text-emerald-300 transition-colors"
                            >
                              Reactivate
                            </button>
                          )}
                        </div>
                      </td>
                    </tr>
                  ))}
                  {users.length === 0 && (
                    <tr>
                      <td colSpan="4" className="px-6 py-12 text-center text-slate-400">
                        No users found matching the selected filters.
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>

      {showModal && modalAction && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/80 backdrop-blur-sm p-4">
          <div className="bg-slate-900 border border-white/10 rounded-2xl p-6 max-w-sm w-full shadow-2xl">
            <div className="flex items-start gap-4 mb-4">
              <div className={`p-3 rounded-full shrink-0 ${modalAction.type === 'suspend' ? 'bg-rose-500/10 text-rose-400' : 'bg-teal-500/10 text-teal-400'}`}>
                <AlertTriangle className="w-6 h-6" />
              </div>
              <div>
                <h3 className="text-lg font-bold text-white">
                  {modalAction.type === 'suspend' && 'Suspend User'}
                  {modalAction.type === 'reactivate' && 'Reactivate User'}
                  {modalAction.type === 'reset' && 'Reset Password'}
                </h3>
                <p className="text-sm text-slate-400 mt-1">
                  {modalAction.type === 'suspend' && `Are you sure you want to suspend ${modalAction.user.fullName}? They will immediately lose access to the system.`}
                  {modalAction.type === 'reactivate' && `Are you sure you want to reactivate ${modalAction.user.fullName}? They will regain access.`}
                  {modalAction.type === 'reset' && `Are you sure you want to trigger a password reset for ${modalAction.user.fullName}? A link will be emailed to ${modalAction.user.email}.`}
                </p>
              </div>
            </div>
            <div className="flex gap-3 justify-end mt-6">
              <button className="px-4 py-2 rounded-lg text-sm font-medium text-slate-300 hover:bg-white/5 transition" onClick={() => setShowModal(false)}>Cancel</button>
              <button 
                className={`px-4 py-2 rounded-lg text-sm font-medium text-white shadow transition ${
                  modalAction.type === 'suspend' ? 'bg-rose-500 hover:bg-rose-600' : 'bg-teal-600 hover:bg-teal-700'
                }`} 
                onClick={confirmAction}
              >
                Confirm
              </button>
            </div>
          </div>
        </div>
      )}
    </AdminLayout>
  );
}

import { useEffect, useState } from "react";
import { useAuth } from "../context/AuthContext";
import { useLanguage } from "../context/LanguageContext";
import AiCaregiverInsightsPanel from "../ai/components/AiCaregiverInsightsPanel";
import { fetchDashboard } from "../services/telecareService";
import api from "../services/api";
import { getApiErrorMessage } from "../utils/apiError";
import { logAsyncFailure, runWithRequestTimeout } from "../utils/requestLifecycle";
import { useWebSocket } from "../hooks/useWebSocket";
import { toast } from "react-hot-toast";
import { 
  Activity, Bell, CalendarDays, ShieldAlert, Users, TrendingUp, FlaskConical, 
  Stethoscope, PhoneCall, AlertTriangle, CheckCircle2, Clock, Heart, Wind, Thermometer
} from "lucide-react";
import "./caregiver-premium-override.css";

export default function CaregiverDashboardPage() {
  const { auth } = useAuth();
  const { language, t } = useLanguage();
  const caregiverId = auth.profileId ?? auth.userId;
  const [dashboard, setDashboard] = useState(null);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);
  const [reloadToken, setReloadToken] = useState(0);

  // Mock Care Tasks
  const [tasks, setTasks] = useState([
    { id: 1, text: "Verify morning medications for Anita", done: false, time: "09:00 AM" },
    { id: 2, text: "Check BP reading for Robert", done: true, time: "10:30 AM" },
    { id: 3, text: "Call Dr. Smith regarding Anita's dosage", done: false, time: "01:00 PM" },
    { id: 4, text: "Update care notes for weekly review", done: false, time: "04:00 PM" }
  ]);

  useWebSocket(`/topic/caregiver/${caregiverId}/alerts`, (message) => {
    toast.error(message.message || "Alert received!", {
      duration: 6000,
      position: 'top-right',
      className: "bg-red-500/20 border border-red-500/50 text-white backdrop-blur-md"
    });
  });

  const handleSimulateAlert = async () => {
    try {
      await api.post(`/caregivers/${caregiverId}/simulate-alert`, {
        patientName: dashboard?.recentHealthAlerts?.[0]?.patientName || "Anita Patient"
      });
      toast.success("Alert simulation triggered.");
    } catch (e) {
      toast.error("Failed to simulate alert");
    }
  };

  useEffect(() => {
    const controller = new AbortController();
    let active = true;

    if (!caregiverId || auth?.role !== "CAREGIVER") {
      if (active) {
        setDashboard(null);
        setError("");
        setLoading(false);
      }
      return () => { active = false; };
    }

    setLoading(true);
    runWithRequestTimeout(
      (signal) => fetchDashboard(auth.role, caregiverId, { signal }),
      { signal: controller.signal }
    )
      .then((data) => {
        if (!active) return;
        setDashboard(data);
        setError("");
      })
      .catch((err) => {
        if (!active) return;
        setDashboard(null);
        setError(getApiErrorMessage(err, t("unableLoadCaregiverDashboard")));
        logAsyncFailure("caregiver-dashboard", err, { caregiverId });
      })
      .finally(() => {
        if (active) setLoading(false);
      });

    return () => {
      active = false;
      controller.abort();
    };
  }, [auth.role, caregiverId, language, t, reloadToken]);

  if (loading) {
    return (
      <div className="cg-premium-workspace p-6 space-y-6 min-h-screen flex items-center justify-center">
        <div className="text-center space-y-4">
          <Activity className="w-12 h-12 text-indigo-400 animate-pulse mx-auto" />
          <p className="cg-subheading">Loading Dashboard Data...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="cg-premium-workspace p-6 min-h-screen">
        <div className="cg-card border-red-500/30 bg-red-500/10 p-8 text-center">
          <AlertTriangle className="w-12 h-12 text-red-400 mx-auto mb-4" />
          <h2 className="cg-heading text-red-400 mb-2">Unable to Load Dashboard</h2>
          <p className="text-slate-400 mb-6">{error}</p>
          <button className="cg-btn cg-btn-secondary" onClick={() => setReloadToken(c => c + 1)}>Retry</button>
        </div>
      </div>
    );
  }

  const alertsCount = Array.isArray(dashboard?.recentHealthAlerts) ? dashboard.recentHealthAlerts.length : 0;
  const pendingReminders = Number(dashboard?.pendingMedicationReminders || 0);
  const adherencePercentage = Number(dashboard?.adherencePercentage ?? 0);
  const totalAppointments = Number(dashboard?.totalAppointments || 0);
  const latestAlert = dashboard?.recentHealthAlerts?.[0];

  const toggleTask = (id) => {
    setTasks(tasks.map(t => t.id === id ? { ...t, done: !t.done } : t));
  };

  return (
    <div className="cg-premium-workspace space-y-6">

      {/* KPI Cards */}
      <div className="cg-grid-4">
        <div className="cg-card cg-card-interactive p-5 flex items-center gap-4">
          <div className="bg-indigo-500/20 p-3 rounded-xl text-indigo-400 border border-indigo-500/20">
            <Users className="h-6 w-6" />
          </div>
          <div>
            <p className="cg-subheading">Patients Monitored</p>
            <p className="text-2xl font-bold text-white mt-1">12 <span className="text-sm font-normal text-slate-400">Active</span></p>
          </div>
        </div>

        <div className="cg-card cg-card-interactive p-5 flex items-center gap-4">
          <div className="bg-amber-500/20 p-3 rounded-xl text-amber-400 border border-amber-500/20">
            <Activity className="h-6 w-6" />
          </div>
          <div>
            <p className="cg-subheading">Pending Tasks</p>
            <p className="text-2xl font-bold text-white mt-1">{pendingReminders} <span className="text-sm font-normal text-slate-400">Reminders</span></p>
          </div>
        </div>

        <div className="cg-card cg-card-interactive p-5 flex items-center gap-4">
          <div className="bg-emerald-500/20 p-3 rounded-xl text-emerald-400 border border-emerald-500/20">
            <TrendingUp className="h-6 w-6" />
          </div>
          <div>
            <p className="cg-subheading">Avg Adherence</p>
            <p className="text-2xl font-bold text-white mt-1">{adherencePercentage.toFixed(1)}%</p>
          </div>
        </div>

        <div className="cg-card cg-card-interactive p-5 flex items-center gap-4">
          <div className="bg-sky-500/20 p-3 rounded-xl text-sky-400 border border-sky-500/20">
            <CalendarDays className="h-6 w-6" />
          </div>
          <div>
            <p className="cg-subheading">Upcoming Visits</p>
            <p className="text-2xl font-bold text-white mt-1">{totalAppointments}</p>
          </div>
        </div>
