import "./caregiver-premium-override.css";
import { useEffect, useState } from "react";
import LocalizedText from "../components/LocalizedText";
import CaregiverPremiumCard from "../components/CaregiverPremiumCard";
import { useAuth } from "../context/AuthContext";
import { useLanguage } from "../context/LanguageContext";
import { fetchCaregiverFamilyNetwork } from "../services/telecareService";
import { getApiErrorMessage } from "../utils/apiError";
import { translateDisplayText } from "../utils/i18n";
import LoadingSkeleton from "../components/ui/LoadingSkeleton";
import EmptyStateCard from "../components/ui/EmptyStateCard";
import ErrorStateCard from "../components/ui/ErrorStateCard";
import { useToast } from "../components/ui/ToastProvider";
import { Users, Mail, Phone, HeartHandshake, UserPlus } from "lucide-react";

export default function CaregiverFamilyNetworkPage() {
  const { auth } = useAuth();
  const { language, t } = useLanguage();
  const caregiverId = auth.profileId ?? auth.userId;
  const [network, setNetwork] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const { pushToast } = useToast();
  
  // Form state
  const [inviteEmail, setInviteEmail] = useState("");
  const [invitePatientId, setInvitePatientId] = useState("");

  useEffect(() => {
    setLoading(true);
    fetchCaregiverFamilyNetwork(caregiverId)
      .then((data) => {
        setNetwork(data);
        setError("");
      })
      .catch((err) => setError(getApiErrorMessage(err, t("unableLoadCaregiverFamilyNetwork"))))
      .finally(() => setLoading(false));
  }, [caregiverId]);

  const handleInvite = async (e) => {
    e.preventDefault();
    if (!inviteEmail || !invitePatientId) {
      pushToast({ type: "error", title: "Missing Fields", message: "Please provide an email and select a patient." });
      return;
    }
    try {
      await import("../services/telecareService").then(m => m.inviteCaregiver({
        patientId: parseInt(invitePatientId, 10),
        email: inviteEmail,
        relationship: "Family Member"
      }));
      pushToast({ type: "success", title: "Invite Sent", message: `Secure invitation sent to ${inviteEmail}.` });
      setInviteEmail("");
    } catch (err) {
      pushToast({ type: "error", title: "Invite Failed", message: getApiErrorMessage(err, "Could not send invitation.") });
    }
  };

  return (
    <div className="tcd-animate-in space-y-6">
      <CaregiverPremiumCard
        title={
          <span className="inline-flex items-center gap-2">
            <UserPlus className="h-5 w-5 text-indigo-400" />
            <span>Expand Care Network</span>
          </span>
        }
      >
        <form onSubmit={handleInvite} className="flex flex-col sm:flex-row items-end gap-4 bg-white/5 p-5 rounded-xl border border-white/10">
          <label className="flex-1 w-full block space-y-2">
            <span className="text-sm font-medium text-slate-300">Invite Email</span>
            <input 
              type="email" 
              className="cg-input w-full" 
              placeholder="family.member@example.com" 
              value={inviteEmail} 
              onChange={(e) => setInviteEmail(e.target.value)} 
            />
          </label>
          <label className="flex-1 w-full block space-y-2">
            <span className="text-sm font-medium text-slate-300">For Patient</span>
            <select className="cg-input w-full" value={invitePatientId} onChange={(e) => setInvitePatientId(e.target.value)}>
              <option value="" disabled>Select patient...</option>
              {(network?.linkedPatients || []).map(p => (
                <option key={p.patientId} value={p.patientId}>{p.patientName}</option>
              ))}
            </select>
          </label>
          <button type="submit" className="cg-btn cg-btn-primary w-full sm:w-auto px-6 h-[46px]">
            Send Invite
          </button>
        </form>
      </CaregiverPremiumCard>

      <CaregiverPremiumCard
        title={
          <span className="inline-flex items-center gap-2">
            <HeartHandshake className="h-5 w-5 text-indigo-400" />
            <LocalizedText as="span" value={t("familyCareNetwork")} minLength={4} />
          </span>
        }
      >
        {loading ? <LoadingSkeleton lines={4} /> : null}
        {error ? (
          <ErrorStateCard
            title={t("unableLoadCaregiverFamilyNetwork")}
            body={error}
          />
        ) : null}
        {!loading && !error && !(network?.linkedPatients?.length) ? (
          <EmptyStateCard
            title={t("noLinkedFamilies")}
            body={translateDisplayText(language, "Linked families will appear here once patients share access.")}
          />
        ) : null}
        <div className="space-y-6">
          {(network?.linkedPatients || []).map((item) => (
            <div key={item.patientId} className="rounded-xl bg-white/5 border border-white/10 p-5 transition-colors hover:bg-white/10">
              <div className="flex flex-wrap items-center justify-between gap-3 mb-4 pb-4 border-b border-white/10">
                <div>
                  <h3 className="text-xl font-semibold text-white">{item.patientName}</h3>
                  <p className="text-sm text-slate-400 mt-1">{item.sharedSupport ? t("sharedSupport") : t("singleSupport")}</p>
                </div>
                <span className="rounded-full bg-indigo-500/20 text-indigo-400 border border-indigo-500/30 px-3 py-1 text-sm font-semibold flex items-center gap-2">
                  <Users className="w-4 h-4" />
                  {(Array.isArray(item.caregivers) ? item.caregivers.length : 0)} {t("caregiversLabel")}
                </span>
              </div>
              
              <LocalizedText as="p" className="mb-5 text-sm text-slate-300 bg-black/20 p-3 rounded-lg border border-white/5" value={item.coordinationNote} />
              
              <div className="grid gap-4 md:grid-cols-2">
                {(Array.isArray(item.caregivers) ? item.caregivers : []).map((caregiver) => (
                  <div key={caregiver.caregiverId} className="rounded-xl bg-white/5 border border-white/10 px-4 py-4 hover:border-indigo-500/30 transition-colors">
                    <p className="font-semibold text-white text-base">{caregiver.caregiverName}</p>
                    <p className="text-sm text-indigo-400 font-medium mb-3">{translateDisplayText(language, caregiver.relationshipLabel || t("caregiverCredential"))}</p>
                    
                    <div className="space-y-2 mt-auto">
                      <div className="flex items-center gap-2 text-sm text-slate-300">
                        <Phone className="w-4 h-4 text-slate-500" />
                        {caregiver.phone || "No phone provided"}
                      </div>
                      <div className="flex items-center gap-2 text-sm text-slate-300">
                        <Mail className="w-4 h-4 text-slate-500" />
                        {caregiver.email || "No email provided"}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      </CaregiverPremiumCard>
    </div>
  );
}

import { useEffect, useState } from "react";
import Badge from "../components/Badge";
import LocalizedText from "../components/LocalizedText";
import CaregiverPremiumCard from "../components/CaregiverPremiumCard";
import { useAuth } from "../context/AuthContext";
import { useLanguage } from "../context/LanguageContext";
import { createCaregiverIntervention, fetchCaregiverAlerts, fetchCaregiverInterventions, fetchLinkedPatients, updateCaregiverInterventionStatus } from "../services/telecareService";
import { getApiErrorMessage } from "../utils/apiError";
import { translateDisplayText } from "../utils/i18n";
import LoadingSkeleton from "../components/ui/LoadingSkeleton";
import EmptyStateCard from "../components/ui/EmptyStateCard";
import { ClipboardList, Users, Phone, Car, Stethoscope, Home, UserCheck, ShieldAlert, CheckCircle } from "lucide-react";
import SmartEMarScanner from "../components/caregiver/SmartEMarScanner";

export default function CaregiverInterventionsPage() {
  const { auth } = useAuth();
  const { language, t } = useLanguage();
  const caregiverId = auth.profileId ?? auth.userId;
  const [interventions, setInterventions] = useState([]);
  const [alerts, setAlerts] = useState([]);
  const [patients, setPatients] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [message, setMessage] = useState("");
  const [fieldErrors, setFieldErrors] = useState({ notes: "" });
  const [form, setForm] = useState({
    patientId: "",
    alertNotificationId: "",
    actionType: "CALLED_PATIENT",
    wellbeingStatus: "NEEDS_ATTENTION",
    notes: "",
    followUpNeeded: true
  });

  const actionOptions = [
    { value: "CALLED_PATIENT", label: translateDisplayText(language, "CALLED_PATIENT") },
    { value: "CONFIRMED_MEDICINE_TAKEN", label: translateDisplayText(language, "CONFIRMED_MEDICINE_TAKEN") },
    { value: "BOOKED_IN_PERSON_VISIT", label: translateDisplayText(language, "BOOKED_IN_PERSON_VISIT") },
    { value: "TOOK_PATIENT_TO_HOSPITAL", label: translateDisplayText(language, "TOOK_PATIENT_TO_HOSPITAL") },
    { value: "DOCTOR_INFORMED", label: translateDisplayText(language, "DOCTOR_INFORMED") },
    { value: "HOME_CHECK_COMPLETED", label: translateDisplayText(language, "HOME_CHECK_COMPLETED") }
  ];

  const wellbeingOptions = [
    { value: "STABLE", label: translateDisplayText(language, "STABLE") },
    { value: "NEEDS_ATTENTION", label: translateDisplayText(language, "NEEDS_ATTENTION") },
    { value: "URGENT", label: translateDisplayText(language, "URGENT") },
    { value: "UNREACHABLE", label: translateDisplayText(language, "UNREACHABLE") }
  ];

  const load = async () => {
    setLoading(true);
    try {
      const [linkedPatients, caregiverAlerts, actionLog] = await Promise.all([
        fetchLinkedPatients(caregiverId),
        fetchCaregiverAlerts(caregiverId),
        fetchCaregiverInterventions(caregiverId)
      ]);
      const safePatients = Array.isArray(linkedPatients) ? linkedPatients : [];
      const safeAlerts = Array.isArray(caregiverAlerts) ? caregiverAlerts : [];
      const safeInterventions = Array.isArray(actionLog) ? actionLog : [];
      setPatients(safePatients);
      setAlerts(safeAlerts);
      setInterventions(safeInterventions);
      setForm((current) => ({
        ...current,
        patientId: current.patientId || (safePatients[0]?.patientId ? String(safePatients[0].patientId) : ""),
        alertNotificationId: current.alertNotificationId || (safeAlerts[0]?.id ? String(safeAlerts[0].id) : "")
      }));
      setError("");
    } catch (err) {
      setError(getApiErrorMessage(err, t("unableLoadInterventionHub")));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, [caregiverId]);

  const priorityPatients = [...patients].sort((left, right) => {
    const leftScore = Number(left.pendingReminders || 0) + (Array.isArray(left.activeAlerts) ? left.activeAlerts.length * 2 : 0);
    const rightScore = Number(right.pendingReminders || 0) + (Array.isArray(right.activeAlerts) ? right.activeAlerts.length * 2 : 0);
    return rightScore - leftScore;
  });

  return (
    <div className="tcd-animate-in space-y-6">
      <div className="grid gap-6 xl:grid-cols-[0.9fr_1.1fr]">
        <CaregiverPremiumCard
          title={
            <span className="inline-flex items-center gap-2">
              <ClipboardList className="h-5 w-5 text-indigo-400" />
              <span>{t("interventionHub")}</span>
            </span>
          }
          action={
            <button
              className="cg-btn cg-btn-primary"
              type="button"
              aria-label={t("logIntervention")}
              data-voice-label={t("logIntervention")}
              onClick={async () => {
                const trimmedNotes = form.notes.trim();
                if (!trimmedNotes) {
                  setFieldErrors({ notes: t("caregiverNotesRequired") });
                  setMessage("");
                  setError("");
                  return;
                }
                try {
                  setFieldErrors({ notes: "" });
                  const created = await createCaregiverIntervention({
                    caregiverId,
                    patientId: Number(form.patientId),
                    alertNotificationId: form.alertNotificationId ? Number(form.alertNotificationId) : null,
                    actionType: form.actionType,
                    wellbeingStatus: form.wellbeingStatus,
                    notes: trimmedNotes,
                    followUpNeeded: form.followUpNeeded
                  });
                  setMessage(t("interventionLoggedFor").replace("{name}", created.patientName));
                  setError("");
                  setForm((current) => ({ ...current, notes: "" }));
                  await load();
                } catch (err) {
                  setError(getApiErrorMessage(err, t("unableLogIntervention")));
                }
              }}
            >
              {t("logIntervention")}
            </button>
          }
        >
          <div className="grid gap-5">
            <label className="block space-y-2">
              <span className="text-sm font-medium text-slate-300">{t("patient")}</span>
              <select className="cg-input" aria-label={t("patient")} data-voice-label={t("patient")} value={form.patientId} onChange={(e) => setForm({ ...form, patientId: e.target.value })}>
                {patients.map((patient) => (
                  <option key={patient.patientId} value={patient.patientId}>{patient.patientName}</option>
                ))}
              </select>
            </label>
            <label className="block space-y-2">
              <span className="text-sm font-medium text-slate-300">{t("linkedAlert")}</span>
              <select className="cg-input" aria-label={t("linkedAlert")} data-voice-label={t("linkedAlert")} value={form.alertNotificationId} onChange={(e) => setForm({ ...form, alertNotificationId: e.target.value })}>
                <option value="">{t("noLinkedAlert")}</option>
                {alerts.map((alert) => (
                  <option key={alert.id} value={alert.id}>{alert.patientName} - {translateDisplayText(language, alert.severity)}</option>
                ))}
              </select>
            </label>
            <div className="grid grid-cols-2 gap-4">
              <label className="block space-y-2">
                <span className="text-sm font-medium text-slate-300">{t("actionTaken")}</span>
                <select className="cg-input" aria-label={t("actionTaken")} data-voice-label={t("actionTaken")} value={form.actionType} onChange={(e) => setForm({ ...form, actionType: e.target.value })}>
                  {actionOptions.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}
                </select>
              </label>
              <label className="block space-y-2">
                <span className="text-sm font-medium text-slate-300">{t("patientWellbeing")}</span>
                <select className="cg-input" aria-label={t("patientWellbeing")} data-voice-label={t("patientWellbeing")} value={form.wellbeingStatus} onChange={(e) => setForm({ ...form, wellbeingStatus: e.target.value })}>
                  {wellbeingOptions.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}
                </select>
              </label>
            </div>
            <label className="block space-y-2">
              <span className="text-sm font-medium text-slate-300">{t("caregiverNotes")}</span>
              <textarea
                className="cg-input min-h-[120px] resize-y"
                aria-label={t("caregiverNotes")}
                data-voice-label={t("caregiverNotes")}
                aria-invalid={Boolean(fieldErrors.notes)}
                aria-describedby={fieldErrors.notes ? "caregiver-intervention-notes-error" : undefined}
                value={form.notes}
                onChange={(e) => {
                  setForm({ ...form, notes: e.target.value });
                  if (fieldErrors.notes) {
                    setFieldErrors({ notes: "" });
                  }
                }}
              />
              {fieldErrors.notes ? <p id="caregiver-intervention-notes-error" className="text-xs text-red-400" role="alert">{fieldErrors.notes}</p> : null}
            </label>
            <label className="flex items-center gap-3 text-sm text-slate-300 bg-white/5 p-3 rounded-xl border border-white/10 cursor-pointer hover:bg-white/10 transition-colors">
              <input type="checkbox" className="w-4 h-4 text-indigo-500 rounded bg-black/50 border-white/20 focus:ring-indigo-500 focus:ring-offset-slate-900" aria-label={t("followUpNeeded")} data-voice-label={t("followUpNeeded")} checked={form.followUpNeeded} onChange={(e) => setForm({ ...form, followUpNeeded: e.target.checked })} />
              {t("followUpNeeded")}
            </label>
          </div>
          {message ? <p className="mt-4 text-sm text-emerald-400 bg-emerald-500/10 p-3 rounded-lg flex items-center gap-2" role="status" aria-live="polite"><CheckCircle className="w-4 h-4"/>{message}</p> : null}
          {error ? <p className="mt-4 text-sm text-red-400 bg-red-500/10 p-3 rounded-lg flex items-center gap-2" role="alert"><ShieldAlert className="w-4 h-4"/>{error}</p> : null}
        </CaregiverPremiumCard>
        
        {/* Smart eMAR Scanner */}
        {form.patientId && (
          <SmartEMarScanner patientId={form.patientId} />
        )}

        <CaregiverPremiumCard 
          title={
            <span className="inline-flex items-center gap-2">
              <Users className="h-5 w-5 text-indigo-400" />
              <span>{t("priorityPatientQueue")}</span>
            </span>
          }
        >
          {loading ? <LoadingSkeleton lines={4} /> : null}
          {!loading && !priorityPatients.length ? (
            <EmptyStateCard
              title={t("noLinkedPatients")}
              body={translateDisplayText(language, "Link a patient to see priority monitoring here.")}
            />
          ) : null}
          <div className="space-y-4">
            {priorityPatients.map((patient) => {
              const needsReview = (Array.isArray(patient.activeAlerts) ? patient.activeAlerts.length : 0) > 0;
              return (
                <div key={patient.patientId} className={`rounded-xl p-5 border ${needsReview ? 'bg-indigo-500/10 border-indigo-500/20' : 'bg-white/5 border-white/10'} hover:border-white/20 transition-colors`}>
                  <div className="flex flex-wrap items-center justify-between gap-3 mb-3">
                    <div>
                      <p className="font-semibold text-white">{patient.patientName}</p>
                      <p className="text-sm text-slate-400 mt-1">{t("pendingRemindersLabel")}: <span className="text-amber-400">{patient.pendingReminders}</span> | {t("adherenceLabel")}: <span className="text-teal-400">{patient.adherencePercentage}%</span></p>
                    </div>
                    <span className={`rounded-full px-3 py-1 text-xs font-semibold ${needsReview ? 'bg-indigo-500 text-white shadow-[0_0_10px_rgba(99,102,241,0.5)]' : 'bg-white/10 text-slate-300'}`}>
                      {needsReview ? t("needsReview") : t("stableQueue")}
                    </span>
                  </div>
                  {Array.isArray(patient.activeAlerts) && patient.activeAlerts.length ? (
                    <div className="mt-3 space-y-2 border-t border-white/10 pt-3">
                      {(Array.isArray(patient.activeAlerts) ? patient.activeAlerts : []).slice(0, 2).map((item) => (
                        <LocalizedText key={item} as="div" className="text-sm text-slate-300 bg-black/20 p-2 rounded-lg" value={item} />
                      ))}
                    </div>
                  ) : null}
                </div>
              );
            })}
          </div>
        </CaregiverPremiumCard>
      </div>

      <CaregiverPremiumCard 
        title={
          <span className="inline-flex items-center gap-2">
            <ClipboardList className="h-5 w-5 text-indigo-400" />
            <span>{t("interventionTimeline")}</span>
          </span>
        }
      >
        {loading ? <LoadingSkeleton lines={4} /> : null}
        {!loading && !interventions.length ? (
          <EmptyStateCard
            title={t("noInterventionsRecorded")}
            body={translateDisplayText(language, "Interventions will appear here after you log an action.")}
          />
        ) : null}
        <div className="relative border-l-2 border-white/10 ml-4 space-y-8 py-4">
          {interventions.map((item) => {
            const isResolved = item.status === "RESOLVED";
            
            // Map action type to icon
            let ActionIcon = UserCheck;
            if (item.actionType === "CALLED_PATIENT") ActionIcon = Phone;
            if (item.actionType === "CONFIRMED_MEDICINE_TAKEN") ActionIcon = CheckCircle;
            if (item.actionType === "TOOK_PATIENT_TO_HOSPITAL") ActionIcon = Car;
            if (item.actionType === "DOCTOR_INFORMED") ActionIcon = Stethoscope;
            if (item.actionType === "HOME_CHECK_COMPLETED") ActionIcon = Home;
            
            return (
              <div key={item.id} className="relative pl-6">
                <div className={`absolute -left-[13px] top-1 h-6 w-6 rounded-full border-4 border-[var(--cg-panel)] flex items-center justify-center ${isResolved ? 'bg-teal-500' : 'bg-amber-500'}`}>
                  {isResolved ? <CheckCircle className="h-3 w-3 text-[var(--cg-panel)]" /> : <div className="h-2 w-2 rounded-full bg-[var(--cg-panel)]" />}
                </div>
                
                <div className="rounded-xl border border-white/10 bg-white/5 p-5">
                  <div className="flex flex-wrap items-start justify-between gap-3 mb-4 border-b border-white/10 pb-4">
                    <div>
                      <p className="font-semibold text-white">{item.patientName}</p>
                      <p className="text-xs text-slate-400 mt-1">{new Date(item.actionAt).toLocaleString()}</p>
                    </div>
                    <div className="flex items-center gap-3">
                      {item.alertSeverity ? <Badge value={item.alertSeverity} /> : null}
                      <span className={`rounded-full px-2 py-0.5 text-xs font-semibold ${isResolved ? 'bg-teal-500/10 text-teal-400 border border-teal-500/20' : 'bg-amber-500/10 text-amber-400 border border-amber-500/20'}`}>
                        {translateDisplayText(language, item.status)}
                      </span>
                    </div>
                  </div>
                  
                  <div className="flex items-center gap-2 mb-3">
                    <div className="p-1.5 rounded-md bg-white/10 text-indigo-400">
                      <ActionIcon className="w-4 h-4" />
                    </div>
                    <p className="font-medium text-white">{translateDisplayText(language, item.actionType)}</p>
                  </div>
                  
                  <div className="grid grid-cols-2 gap-4 mb-4">
                    <div className="bg-black/20 p-3 rounded-lg">
                      <p className="text-xs text-slate-400 mb-1">{t("wellbeingStatus")}</p>
                      <p className="text-sm font-medium text-slate-200">{translateDisplayText(language, item.wellbeingStatus)}</p>
                    </div>
                    {item.alertMessage ? (
                      <div className="bg-black/20 p-3 rounded-lg">
                        <p className="text-xs text-slate-400 mb-1">{t("linkedAlert")}</p>
                        <LocalizedText as="p" className="text-sm font-medium text-red-400 line-clamp-1" value={item.alertMessage} />
                      </div>
                    ) : null}
                  </div>
                  
                  {item.notes ? (
                    <div className="bg-white/5 p-3 rounded-lg border border-white/5 mb-4">
                      <LocalizedText as="p" className="text-sm text-slate-300" value={item.notes} />
                    </div>
                  ) : null}
                  
                  <div className="flex flex-wrap items-center justify-between gap-3 pt-2">
                    {item.followUpNeeded ? (
                      <span className="rounded-full bg-amber-500/10 border border-amber-500/20 px-3 py-1 text-xs font-semibold text-amber-400">
                        {t("followUpNeeded")}
                      </span>
                    ) : <span />}
                    {!isResolved ? (
                      <button
                        className="cg-btn cg-btn-ghost text-xs"
                        type="button"
                        aria-label={t("markResolved")}
                        data-voice-label={t("markResolved")}
                        onClick={async () => {
                          try {
                            await updateCaregiverInterventionStatus(item.id, { status: "RESOLVED" });
                            await load();
                          } catch (err) {
                            setError(getApiErrorMessage(err, t("unableUpdateIntervention")));
                          }
                        }}
                      >
                        <CheckCircle className="w-3.5 h-3.5" />
                        {t("markResolved")}
                      </button>
                    ) : null}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </CaregiverPremiumCard>
    </div>
  );
}

import { useEffect, useState } from "react";
import AlertStrip from "../components/AlertStrip";
import CaregiverPremiumCard from "../components/CaregiverPremiumCard";
import { useAuth } from "../context/AuthContext";
import { useLanguage } from "../context/LanguageContext";
import { fetchLinkedPatients, linkCaregiver } from "../services/telecareService";
import { getApiErrorMessage } from "../utils/apiError";
import LoadingSkeleton from "../components/ui/LoadingSkeleton";
import EmptyStateCard from "../components/ui/EmptyStateCard";
import ErrorStateCard from "../components/ui/ErrorStateCard";
import { useToast } from "../components/ui/ToastProvider";
import { Activity, Link as LinkIcon, UserCircle, ShieldAlert } from "lucide-react";
import GeofenceMap from "../components/caregiver/GeofenceMap";

export default function CaregiverMonitoringPage() {
  const { auth } = useAuth();
  const { language, t } = useLanguage();
  const caregiverId = auth.profileId ?? auth.userId;
  const [linkedPatients, setLinkedPatients] = useState([]);
  const [patientId, setPatientId] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);
  const { pushToast } = useToast();
  
  const lastUpdated = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

  const load = () => {
    setLoading(true);
    fetchLinkedPatients(caregiverId)
      .then((data) => {
        setLinkedPatients(Array.isArray(data) ? data : []);
        setError("");
      })
      .catch((err) => setError(getApiErrorMessage(err, t("unableLoadLinkedPatients"))))
      .finally(() => setLoading(false));
  };

  useEffect(() => {
    load();
  }, [caregiverId]);

  return (
    <div className="tcd-animate-in space-y-6">
      <CaregiverPremiumCard
        title={
          <span className="inline-flex items-center gap-2">
            <LinkIcon className="h-5 w-5 text-indigo-400" />
            <span>{t("linkPatient")}</span>
          </span>
        }
      >
        <div className="flex flex-col sm:flex-row items-start sm:items-end gap-4 max-w-xl">
          <label className="flex-1 w-full block space-y-2">
            <span className="text-sm font-medium text-slate-400">Patient ID or Invite Code</span>
            <input 
              className="cg-input w-full" 
              placeholder="e.g. 1 or P-98765"
              value={patientId} 
              onChange={(e) => setPatientId(e.target.value)} 
            />
          </label>
          <button
            className="cg-btn cg-btn-primary w-full sm:w-auto"
            onClick={async () => {
              if (!patientId.trim()) {
                setError("Please enter a valid Patient ID");
                return;
              }
              try {
                setError("");
                await linkCaregiver({ patientId: Number(patientId), caregiverId });
                pushToast({ type: "success", title: "Patient Linked", message: t("patientLinkedSuccessfully") });
                setPatientId("");
                await load();
              } catch (err) {
                const errMsg = getApiErrorMessage(err, t("unableLinkPatient"));
                setError(errMsg);
                pushToast({ type: "error", title: "Linking Failed", message: errMsg });
              }
            }}
          >
            {t("link")}
          </button>
        </div>
        {error ? <p className="mt-3 text-sm text-red-400 flex items-center gap-1"><ShieldAlert className="w-4 h-4" />{error}</p> : null}
      </CaregiverPremiumCard>
      
      <CaregiverPremiumCard
        title={
          <div className="flex items-center justify-between w-full">
            <span className="inline-flex items-center gap-2">
              <Activity className="h-5 w-5 text-indigo-400" />
              <span>{t("linkedPatientMonitoring")}</span>
            </span>
            <span className="text-xs font-medium text-slate-400">Updated {lastUpdated}</span>
          </div>
        }
      >
        {loading ? <LoadingSkeleton lines={4} /> : null}
        {error ? (
          <ErrorStateCard
            title={t("unableLoadLinkedPatients")}
            body={error}
            actionLabel={t("retry")}
            onAction={() => load()}
          />
        ) : null}
        {!loading && !error && !linkedPatients.length ? (
          <EmptyStateCard
            title={t("noLinkedPatients")}
            body={t("linkPatient")}
          />
        ) : null}
        
        <div className="grid gap-6 lg:grid-cols-2 mt-4">
          {(Array.isArray(linkedPatients) ? linkedPatients : []).map((patient) => (
            <div key={patient.patientId} className="rounded-xl border border-white/5 bg-white/5 p-5 hover:bg-white/10 transition-colors">
              <div className="flex items-center gap-4 mb-5 pb-5 border-b border-white/10">
                <div className="w-12 h-12 rounded-full bg-indigo-500/20 flex items-center justify-center text-indigo-400">
                  <UserCircle className="w-8 h-8" />
                </div>
                <div>
                  <h3 className="font-semibold text-lg text-white">{patient.patientName}</h3>
                  <p className="text-sm text-slate-400">ID: {patient.patientId}</p>
                </div>
              </div>
              
              <div className="grid grid-cols-2 gap-4 mb-5">
                <div className="bg-black/20 rounded-lg p-3 text-center">
                  <p className="text-xs text-slate-400 mb-1">{t("pendingReminders")}</p>
                  <p className="text-xl font-semibold text-amber-400">{patient.pendingReminders}</p>
                </div>
                <div className="bg-black/20 rounded-lg p-3 text-center">
                  <p className="text-xs text-slate-400 mb-1">{t("adherence")}</p>
                  <p className="text-xl font-semibold text-teal-400">{patient.adherencePercentage}%</p>
                </div>
              </div>

              {patient.activeAlerts && patient.activeAlerts.length > 0 ? (
                <div className="mb-5">
                  <p className="text-xs font-medium text-slate-400 uppercase tracking-wider mb-2">Active Alerts</p>
                  <AlertStrip items={patient.activeAlerts} />
                </div>
              ) : (
                <div className="bg-teal-500/10 text-teal-400 rounded-lg p-3 text-sm text-center mb-5">
                  No active alerts for this patient
                </div>
              )}

              <GeofenceMap patientId={patient.patientId} />
            </div>
          ))}
        </div>
      </CaregiverPremiumCard>
    </div>
  );
}

import "./doctor-premium-override.css";
import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import PremiumSectionCard from "../components/PremiumSectionCard";
import { useAuth } from "../context/AuthContext";
import { useLanguage } from "../context/LanguageContext";
import { fetchDoctorAppointments, updateAppointmentStatus } from "../services/telecareService";
import { getApiErrorMessage } from "../utils/apiError";
import { translateDisplayText } from "../utils/i18n";
import { useToast } from "../components/ui/ToastProvider";
import EmptyStateCard from "../components/ui/EmptyStateCard";
import ErrorStateCard from "../components/ui/ErrorStateCard";
import { CalendarDays, Clock, CheckCircle2, XCircle, FileText, User, AlertTriangle } from "lucide-react";

function AppointmentsSkeleton() {
  return (
    <div className="space-y-4">
      <div className="h-10 w-1/3 mb-6 bg-white/5 animate-pulse rounded-lg" />
      <div className="doc-grid-2">
        {Array.from({ length: 4 }).map((_, index) => (
          <div key={`doctor-appointment-skeleton-${index}`} className="h-48 w-full rounded-xl bg-white/5 animate-pulse" />
        ))}
      </div>
    </div>
  );
}

export default function DoctorAppointmentsPage() {
  const { auth } = useAuth();
  const { language, t, translateUiText = (value) => translateDisplayText(language, value) } = useLanguage();
  const { pushToast } = useToast();
  const navigate = useNavigate();
  const doctorId = auth.profileId ?? auth.userId;
  const [appointments, setAppointments] = useState([]);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);
  const [updatingAppointmentId, setUpdatingAppointmentId] = useState(null);
  const [reloadToken, setReloadToken] = useState(0);

  const load = async () => {
    setLoading(true);
    try {
      const data = await fetchDoctorAppointments(doctorId);
      setAppointments(Array.isArray(data) ? data : []);
      setError("");
    } catch (err) {
      setError(getApiErrorMessage(err, t("unableLoadDoctorAppointments")));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, [doctorId, t, reloadToken]);

  const updateStatus = async (appointmentId, status, fallbackMessage) => {
    setUpdatingAppointmentId(appointmentId);
    try {
      setError("");
      await updateAppointmentStatus(appointmentId, { status });
      pushToast({
        type: "success",
        title: t("appointments"),
        message: status === "CONFIRMED"
          ? translateUiText("Appointment confirmed.")
          : translateUiText("Appointment cancelled.")
      });
      await load();
    } catch (err) {
      const message = getApiErrorMessage(err, fallbackMessage);
      setError(message);
      pushToast({ type: "error", title: fallbackMessage, message });
    } finally {
      setUpdatingAppointmentId(null);
    }
  };

  const getStatusBadge = (status) => {
    switch (status) {
      case "CONFIRMED":
        return <span className="doc-badge doc-badge-success">{status}</span>;
      case "CANCELLED":
        return <span className="doc-badge doc-badge-neutral">{status}</span>;
      case "PENDING":
      default:
        return <span className="doc-badge doc-badge-warn">{status}</span>;
    }
  };

  return (
    <div className="space-y-6 doc-premium-workspace tcd-animate-in">
      <PremiumSectionCard
        title={(
          <span className="flex items-center gap-3">
            <div className="p-2 bg-primary/10 rounded-lg">
              <CalendarDays className="h-6 w-6 text-primary" />
            </div>
            <span className="doc-heading tracking-tight">{translateDisplayText(language, t("doctorAppointmentQueue"))}</span>
          </span>
        )}
      >
        {loading ? <AppointmentsSkeleton /> : null}
        {error ? (
          <ErrorStateCard
            title={t("unableLoadDoctorAppointments")}
            body={error}
            actionLabel={t("retry")}
            onAction={() => setReloadToken((current) => current + 1)}
          />
        ) : null}
        {!loading && !error && !appointments.length ? (
          <EmptyStateCard
            title={t("noAppointmentsAssigned")}
            body={translateUiText("New appointment requests will appear here when patients book a visit.")}
            actionLabel={t("retry")}
            onAction={() => setReloadToken((current) => current + 1)}
          />
        ) : null}
        <div className="doc-grid-2 mt-6">
          {appointments.map((item) => {
            const isUrgent = item.triageLevel === "EMERGENCY" || item.triageLevel === "URGENT";
            
            return (
              <div key={item.id} className={`doc-card doc-card-interactive flex flex-col justify-between p-6 ${isUrgent ? 'border-red-500/30 shadow-[0_0_15px_rgba(239,68,68,0.1)]' : ''}`}>
                <div>
                  <div className="flex items-start justify-between mb-5">
                    <div className="flex items-center gap-4">
                      <div className="flex h-12 w-12 items-center justify-center rounded-full bg-slate-800 border border-slate-700 text-primary">
                        <User className="h-6 w-6" />
                      </div>
                      <div>
                        <p className="font-semibold text-lg text-white tracking-tight">{item.patientName}</p>
                        <div className="flex items-center gap-2 text-sm text-slate-400 mt-1">
                          <Clock className="h-4 w-4" />
                          <span>{new Date(item.appointmentDateTime).toLocaleString(undefined, {
                            weekday: 'short', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit'
                          })}</span>
                        </div>
                      </div>
                    </div>
                  </div>
                  
                  <div className="flex flex-wrap gap-2 mb-5">
                    {getStatusBadge(item.status)}
                    {item.triageLevel && (
                      <span className={`doc-badge ${isUrgent ? 'doc-badge-alert' : 'doc-badge-neutral flex items-center gap-1'}`}>
                        {isUrgent && <AlertTriangle className="w-3 h-3 mr-1" />}
                        {item.triageLevel}
                      </span>
                    )}
                  </div>
                  
                  <div className="mb-6 rounded-xl bg-slate-900/50 border border-slate-800 p-4">
                    <p className="doc-subheading mb-2">Chief Concern</p>
                    <p className="text-sm text-slate-300 leading-relaxed line-clamp-2">{item.concernSummary || "No details provided"}</p>
                  </div>
                </div>

                <div className="flex gap-3 pt-5 border-t border-slate-800">
                  {item.status !== "CONFIRMED" && (
                    <button
                      className="doc-btn doc-btn-primary flex-1"
                      type="button"
                      disabled={updatingAppointmentId === item.id}
                      onClick={() => updateStatus(item.id, "CONFIRMED", t("unableConfirmAppointment"))}
                    >
                      <CheckCircle2 className="h-4 w-4" />
                      {updatingAppointmentId === item.id ? t("saving") : t("confirm")}
                    </button>
                  )}
                  {item.status !== "CANCELLED" && (
                    <button
                      className="doc-btn doc-btn-secondary flex-1"
                      type="button"
                      disabled={updatingAppointmentId === item.id}
                      onClick={() => updateStatus(item.id, "CANCELLED", t("unableCancelAppointment"))}
                    >
                      <XCircle className="h-4 w-4" />
                      {updatingAppointmentId === item.id ? t("saving") : t("cancel")}
                    </button>
                  )}
                  {item.status === "CONFIRMED" && (
                    <button
                      className="doc-btn doc-btn-primary flex-1"
                      type="button"
                      onClick={() => navigate(`/doctor/consultation?appointmentId=${item.id}`)}
                    >
                      <FileText className="h-4 w-4" />
                      {translateUiText("Consult")}
                    </button>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </PremiumSectionCard>
    </div>
  );
}

import "./doctor-premium-override.css";
import { useEffect, useState } from "react";
import FormField from "../components/FormField";
import PremiumSectionCard from "../components/PremiumSectionCard";
import { useAuth } from "../context/AuthContext";
import { useLanguage } from "../context/LanguageContext";
import { createCarePlan, fetchDoctorCarePlans } from "../services/telecareService";
import { getApiErrorMessage } from "../utils/apiError";
import LoadingSkeleton from "../components/ui/LoadingSkeleton";
import EmptyStateCard from "../components/ui/EmptyStateCard";

export default function DoctorCarePlansPage() {
  const { auth } = useAuth();
  const { t, language } = useLanguage();
  const doctorId = auth.profileId ?? auth.userId;
  const translateCarePlanValue = (value) => {
    const demoMap = {
      "Diabetes continuity care plan": t("demoDiabetesCarePlanTitle"),
      "Type 2 Diabetes": t("demoType2Diabetes"),
      "Keep fasting sugar under control, maintain medicine adherence above 90%, and avoid emergency fluctuations.": t("demoDiabetesGoals"),
      "Take diabetic medicines after meals as prescribed. Do not skip doses. Record missed doses in the reminders page.": t("demoDiabetesMedicationGuidance"),
      "Walk 30 minutes at least 5 days a week, reduce refined sugar intake, maintain hydration, and log weekly weight.": t("demoDiabetesLifestyleGuidance"),
      "Escalate if sugar remains above 250 mg/dL, if dizziness worsens, or if repeated missed medication events occur.": t("demoDiabetesWarningThresholds"),
      "Weekly review": t("weeklyReview")
