function serializeSoap(soap) {
  return `[SUBJECTIVE]\n${soap.subjective}\n\n[OBJECTIVE]\n${soap.objective}\n\n[ASSESSMENT]\n${soap.assessment}\n\n[PLAN]\n${soap.plan}\n\n[LABS]\n${soap.labs.join(", ")}`;
}

function deserializeSoap(text) {
  const soap = { subjective: "", objective: "", assessment: "", plan: "", labs: [] };
  if (!text) return soap;

  const extract = (tag, nextTag) => {
    const idx = text.indexOf(`[${tag}]`);
    if (idx === -1) return "";
    const start = idx + `[${tag}]`.length;
    let end = text.length;
    if (nextTag) {
      const nextIdx = text.indexOf(`[${nextTag}]`);
      if (nextIdx !== -1) end = nextIdx;
    }
    return text.substring(start, end).trim();
  };

  soap.subjective = extract("SUBJECTIVE", "OBJECTIVE");
  soap.objective = extract("OBJECTIVE", "ASSESSMENT");
  soap.assessment = extract("ASSESSMENT", "PLAN");

  const planRaw = extract("PLAN", "LABS");
  if (!planRaw && text.indexOf("[PLAN]") !== -1) {
      soap.plan = extract("PLAN", null); 
  } else {
      soap.plan = planRaw;
  }

  const labsRaw = extract("LABS", null);
  soap.labs = labsRaw ? labsRaw.split(",").map(l => l.trim()).filter(Boolean) : [];

  if (!soap.subjective && !soap.objective && !soap.assessment && !soap.plan) {
    soap.subjective = text;
  }

  return soap;
}

function buildConsultationDraft(appointmentId = "") {
  return {
    appointmentId,
    soap: { subjective: "", objective: "", assessment: "", plan: "", labs: [] },
    outcome: "ROUTINE",
    followUpDate: ""
  };
}

function buildPrescriptionDraft(patientDisplayName = "") {
  return {
    patientDisplayName,
    notes: "",
    followUpDate: "",
    medications: []
  };
}

export default function DoctorConsultationPage() {
  const { auth } = useAuth();
  const { language, t, translateUiText = (value) => translateDisplayText(language, value) } = useLanguage();
  const [searchParams, setSearchParams] = useSearchParams();
  const doctorId = auth.profileId ?? auth.userId;
  const [appointments, setAppointments] = useState([]);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const [loadingAppointments, setLoadingAppointments] = useState(true);
  const [appointmentsReloadToken, setAppointmentsReloadToken] = useState(0);
  const [consultationId, setConsultationId] = useState(null);
  const [existingPrescriptionLoaded, setExistingPrescriptionLoaded] = useState(false);
  const [webrtcStream, setWebrtcStream] = useState(null);

  const [consultation, setConsultation] = useState(buildConsultationDraft());
  const [prescription, setPrescription] = useState(buildPrescriptionDraft());
  const [activeSoapTab, setActiveSoapTab] = useState('subjective');
  const [newLabTest, setNewLabTest] = useState('');

  const lastAppointmentIdRef = useRef("");
  const lastFetchedAppointmentIdRef = useRef("");
  const prescriptionDirtyRef = useRef({ patientName: false, notes: false });
  const requestedAppointmentId = searchParams.get("appointmentId") || "";
  const initialAppointmentId = useMemo(() => requestedAppointmentId.trim(), [requestedAppointmentId]);

  useEffect(() => {
    if (!doctorId || auth?.role !== "DOCTOR") {
      setAppointments([]);
      setError("");
      setLoadingAppointments(false);
      return;
    }

    setLoadingAppointments(true);
    fetchDoctorAppointments(doctorId)
      .then((data) => {
        const availableAppointments = (Array.isArray(data) ? data : []).filter((item) => item.status !== "COMPLETED");
        setAppointments(availableAppointments);
        setConsultation((current) => ({
          ...current,
          appointmentId: current.appointmentId
            || (initialAppointmentId && availableAppointments.some((item) => String(item.id) === initialAppointmentId)
              ? initialAppointmentId
              : (availableAppointments[0] ? String(availableAppointments[0].id) : ""))
        }));
        setError("");
      })
      .catch((err) => setError(getApiErrorMessage(err, t("unableLoadConsultationAppointments"))))
      .finally(() => setLoadingAppointments(false));
  }, [auth?.role, doctorId, initialAppointmentId, language, appointmentsReloadToken]);

  useEffect(() => {
    if (!consultation.appointmentId) {
      lastAppointmentIdRef.current = "";
      lastFetchedAppointmentIdRef.current = "";
      prescriptionDirtyRef.current = { patientName: false, notes: false };
      setConsultationId(null);
      setExistingPrescriptionLoaded(false);
      setConsultation(buildConsultationDraft(""));
      setPrescription(buildPrescriptionDraft(""));
      setMessage("");
      setError("");
      return;
    }

    const selectedAppointment = appointments.find((item) => String(item.id) === String(consultation.appointmentId));
    const selectedPatientName = selectedAppointment?.patientName || "";
    const nextAppointmentId = String(consultation.appointmentId);
    const appointmentChanged = lastAppointmentIdRef.current !== nextAppointmentId;
    lastAppointmentIdRef.current = nextAppointmentId;

    if (appointmentChanged) {
      lastFetchedAppointmentIdRef.current = "";
      prescriptionDirtyRef.current = { patientName: false, notes: false };
      setConsultationId(null);
      setExistingPrescriptionLoaded(false);
      setConsultation((current) => buildConsultationDraft(current.appointmentId));
      setPrescription(buildPrescriptionDraft(selectedPatientName));
      setError("");
      setMessage("");
    } else if (selectedPatientName && !prescriptionDirtyRef.current.patientName) {
      setPrescription((current) => ({
        ...current,
        patientDisplayName: current.patientDisplayName || selectedPatientName
      }));
    }

    if (lastFetchedAppointmentIdRef.current === nextAppointmentId) {
      return;
    }
    lastFetchedAppointmentIdRef.current = nextAppointmentId;

    fetchConsultationByAppointment(Number(consultation.appointmentId))
      .then((data) => {
        if (!data || !data.id) {
          setConsultationId(null);
          setExistingPrescriptionLoaded(false);
          if (!appointmentChanged) {
            setError("");
            setMessage(translateUiText("No consultation note exists for this appointment yet. Save a consultation note to continue."));
          }
          return;
        }

        setConsultationId(data.id);
        setExistingPrescriptionLoaded(false);
        setConsultation((current) => ({
          ...current,
          soap: deserializeSoap(data.notes),
          outcome: data.outcome ?? current.outcome,
          followUpDate: data.followUpDate ?? current.followUpDate
        }));
        setError("");
        setMessage(t("existingConsultationLoaded"));
      })
      .catch((err) => {
        if (err?.response?.status === 404) {
          setConsultationId(null);
          setExistingPrescriptionLoaded(false);
          if (!appointmentChanged) {
            setError("");
            setMessage(translateUiText("No consultation note exists for this appointment yet. Save a consultation note to continue."));
          }
          return;
        }

        setConsultationId(null);
        setExistingPrescriptionLoaded(false);
        if (!appointmentChanged) {
          setMessage("");
          setError(getApiErrorMessage(err, translateUiText("Unable to load consultation details.")));
        }
      });
  }, [consultation.appointmentId, appointments, language]);

  useEffect(() => {
    if (!consultationId) {
      setExistingPrescriptionLoaded(false);
      return;
    }

    fetchPrescriptionByConsultation(consultationId)
      .then((data) => {
        setPrescription({
          patientDisplayName: data.patientName ?? "",
          notes: data.notes ?? "",
          followUpDate: data.followUpDate ?? "",
          medications: Array.isArray(data.medications) ? data.medications : []
        });
        setExistingPrescriptionLoaded(true);
        setMessage(t("existingPrescriptionLoaded"));
        setError("");
      })
      .catch((err) => {
        if (err?.response?.status === 404) {
          setExistingPrescriptionLoaded(false);
          setError("");
          return;
        }
        setExistingPrescriptionLoaded(false);
        setError(getApiErrorMessage(err, translateUiText("Unable to load existing prescription details.")));
      });
  }, [consultationId, language]);

  const selectedAppointment = appointments.find((item) => String(item.id) === String(consultation.appointmentId));
  const selectedPatientId = selectedAppointment?.patientId;

  return (
    <div className="space-y-6 doc-premium-workspace">
      <VideoConsultation
        doctorName={auth?.fullName || "Doctor"}
        patientName={selectedAppointment?.patientName || "Patient"}
        appointmentTime={selectedAppointment?.appointmentDateTime ? new Date(selectedAppointment.appointmentDateTime).toLocaleString() : "Awaiting appointment selection"}
        showTeleExam={true}
        currentUserId={auth?.userId}
        recipientId={selectedPatientId}
        onStreamMixed={setWebrtcStream}
      />

      {/* Patient Summary Header */}
      {selectedAppointment && (
        <div className="doc-card p-6 flex flex-wrap lg:flex-nowrap items-center justify-between gap-6 bg-gradient-to-r from-slate-900 to-slate-800">
          <div className="flex items-center gap-4">
            <div className="h-14 w-14 rounded-full bg-primary/20 flex items-center justify-center text-primary text-xl font-bold border border-primary/30">
              {selectedAppointment.patientName.charAt(0)}
            </div>
            <div>
              <h2 className="text-xl font-bold text-white">{selectedAppointment.patientName}</h2>
              <div className="flex gap-4 text-sm text-slate-400 mt-1">
                <span>Age: 42</span>
                <span>Gender: M</span>
                <span>ID: #{selectedPatientId}</span>
              </div>
            </div>
          </div>
          <div className="flex gap-6 divide-x divide-white/10">
            <div className="px-4">
              <p className="doc-subheading mb-1 text-alert">Allergies</p>
              <p className="font-semibold text-white">Penicillin, Peanuts</p>
            </div>
            <div className="px-4">
              <p className="doc-subheading mb-1 text-primary">Latest Vitals</p>
              <p className="font-semibold text-white">BP: 120/80, HR: 72 bpm</p>
            </div>
            <div className="px-4">
              <p className="doc-subheading mb-1 text-warn">Triage Level</p>
              <p className="font-semibold text-white">{selectedAppointment.triageLevel || 'Standard'}</p>
            </div>
          </div>
        </div>
      )}

      <div className="grid gap-8 xl:grid-cols-[2fr_1fr]">
        <div className="space-y-8">
          <PremiumSectionCard
            title={(
              <div className="flex items-center gap-2">
                <Stethoscope className="w-5 h-5 text-primary" />
                <span>Clinical Consultation</span>
              </div>
            )}
            action={
              <button
                className="doc-btn doc-btn-primary"
                type="button"
                disabled={!consultation.appointmentId || loadingAppointments}
                onClick={async () => {
                  if (!consultation.appointmentId) {
                    setMessage("");
                    setError(t("selectAppointmentBeforeSaving"));
                    return;
                  }
                  try {
                    setError("");
                    setMessage("");
                    const serializedNotes = serializeSoap(consultation.soap);
                    const isAiGenerated = serializedNotes.includes("AI GENERATED, PENDING REVIEW") || serializedNotes.includes("[SUBJECTIVE]");
                    const data = await createConsultation({
                      appointmentId: Number(consultation.appointmentId),
                      notes: serializedNotes.replace("--- AI GENERATED, PENDING REVIEW ---", "--- AI GENERATED & REVIEWED ---"),
                      outcome: consultation.outcome,
                      followUpDate: consultation.followUpDate || null,
                      aiGenerated: isAiGenerated,
                      reviewedAt: isAiGenerated ? new Date().toISOString() : null,
                      reviewedBy: isAiGenerated ? auth?.fullName : null
                    });
                    setConsultationId(data.id);
                    setMessage(t("consultationSavedFor").replace("{name}", data.patientName));
                  } catch (err) {
                    const messageText = getApiErrorMessage(err, t("unableSaveConsultation"));
                    if (messageText === "Consultation note already exists for appointment") {
                      try {
                        const existing = await fetchConsultationByAppointment(Number(consultation.appointmentId));
                        setConsultationId(existing.id);
                        setConsultation((current) => ({
                          ...current,
                          soap: deserializeSoap(existing.notes),
                          outcome: existing.outcome ?? current.outcome,
                          followUpDate: existing.followUpDate ?? current.followUpDate
                        }));
                        setError("");
                        setMessage(t("existingConsultationLoaded"));
                      } catch {
                        setError(messageText);
                      }
                    } else {
                      setError(messageText);
                    }
                  }
                }}
              >
                <Save className="w-4 h-4" /> {t("saveConsultation")}
              </button>
            }
          >
            <div className="mb-6">
              <label className="block space-y-2">
                <span className="doc-subheading">{t("appointment")}</span>
                <select
                  className="doc-input bg-slate-900/50"
                  value={consultation.appointmentId}
                  onChange={(e) => {
                    const nextAppointmentId = e.target.value;
                    setConsultation({ ...consultation, appointmentId: nextAppointmentId });
                    setSearchParams(nextAppointmentId ? { appointmentId: nextAppointmentId } : {}, { replace: true });
                  }}
                >
                  <option value="">{t("selectAppointment")}</option>
                  {(Array.isArray(appointments) ? appointments : []).map((item) => (
                    <option key={item.id} value={item.id}>
                      {item.patientName} - {new Date(item.appointmentDateTime).toLocaleString()}
                    </option>
                  ))}
                </select>
              </label>
            </div>

            {loadingAppointments ? <LoadingSkeleton lines={3} /> : null}
            {!loadingAppointments && error ? (
              <ErrorStateCard
                title={t("unableLoadConsultationAppointments")}
                body={error}
                actionLabel={t("retry")}
                onAction={() => setAppointmentsReloadToken((current) => current + 1)}
              />
            ) : null}

            <div className="mt-6 border border-slate-700/50 rounded-xl overflow-hidden bg-slate-900/30">
              <div className="flex border-b border-slate-700/50 bg-slate-800/50">
                {['subjective', 'objective', 'assessment', 'plan'].map(tab => (
                  <div 
                    key={tab} 
                    className={`doc-soap-tab flex-1 text-center capitalize ${activeSoapTab === tab ? 'active bg-slate-900/50' : ''}`}
                    onClick={() => setActiveSoapTab(tab)}
                  >
                    {tab}
                  </div>
                ))}
              </div>
              <div className="p-4">
                <textarea
                  className="doc-input min-h-[200px] resize-y bg-transparent border-none p-2 focus:box-shadow-none"
                  placeholder={`Enter ${activeSoapTab} notes...`}
                  value={consultation.soap[activeSoapTab]}
                  onChange={(e) => setConsultation({ 
                    ...consultation, 
                    soap: { ...consultation.soap, [activeSoapTab]: e.target.value } 
                  })}
                />
              </div>
            </div>

            {/* Lab Test Ordering */}
            <div className="mt-6 border border-slate-700/50 rounded-xl p-5 bg-slate-900/30">
              <div className="flex items-center justify-between mb-4">
                <span className="flex items-center gap-2 doc-subheading text-white">
                  <FlaskConical className="w-4 h-4 text-purple-400" /> Lab Test Orders
                </span>
              </div>
              <div className="flex gap-2 mb-4">
                <input 
                  type="text" 
                  placeholder="e.g. Complete Blood Count (CBC)" 
                  className="doc-input flex-1"
                  value={newLabTest}
                  onChange={e => setNewLabTest(e.target.value)}
                  onKeyDown={e => {
                    if (e.key === 'Enter' && newLabTest.trim()) {
                      e.preventDefault();
                      setConsultation({
                        ...consultation,
                        soap: { ...consultation.soap, labs: [...consultation.soap.labs, newLabTest.trim()] }
                      });
                      setNewLabTest('');
                    }
                  }}
                />
                <button 
                  type="button"
                  className="doc-btn doc-btn-secondary"
                  onClick={() => {
                    if (newLabTest.trim()) {
                      setConsultation({
                        ...consultation,
                        soap: { ...consultation.soap, labs: [...consultation.soap.labs, newLabTest.trim()] }
                      });
                      setNewLabTest('');
                    }
                  }}
                >
                  <Plus className="w-4 h-4" /> Add
                </button>
              </div>
              {consultation.soap.labs.length > 0 && (
                <div className="flex flex-wrap gap-2">
                  {consultation.soap.labs.map((lab, i) => (
                    <span key={i} className="inline-flex items-center gap-1.5 px-3 py-1.5 bg-purple-500/10 text-purple-300 border border-purple-500/20 rounded-lg text-sm">
                      <TestTube className="w-3 h-3" /> {lab}
                      <button 
                        type="button" 
                        onClick={() => {
                          const newLabs = [...consultation.soap.labs];
                          newLabs.splice(i, 1);
                          setConsultation({ ...consultation, soap: { ...consultation.soap, labs: newLabs } });
                        }}
                        className="ml-1 text-purple-400 hover:text-white"
                      >&times;</button>
                    </span>
                  ))}
                </div>
              )}
            </div>

            <div className="mt-6 grid grid-cols-2 gap-6">
              <label className="block space-y-2">
                <span className="doc-subheading">{t("outcome")}</span>
                <select
                  className="doc-input"
                  value={consultation.outcome}
                  onChange={(e) => setConsultation({ ...consultation, outcome: e.target.value })}
                >
                  <option value="ROUTINE">{t("routine")}</option>
                  <option value="PRIORITY">{t("priority")}</option>
                  <option value="IN_PERSON_REQUIRED">{t("inPersonRequired")}</option>
                  <option value="EMERGENCY_REFERRAL">{t("emergencyReferral")}</option>
                </select>
              </label>

              <label className="block space-y-2">
                <span className="doc-subheading">{t("followUpDate")}</span>
                <div className="flex items-center gap-2">
                  <input 
                    type="date" 
                    className="doc-input"
                    value={consultation.followUpDate} 
                    onChange={(e) => setConsultation({ ...consultation, followUpDate: e.target.value })} 
                  />
                  <button
                    type="button"
                    className="doc-btn doc-btn-secondary px-3"
                    onClick={() => {
                      const now = new Date();
                      if (consultation.outcome === "PRIORITY" || consultation.outcome === "IN_PERSON_REQUIRED") now.setDate(now.getDate() + 3);
                      else if (consultation.outcome === "EMERGENCY_REFERRAL") now.setDate(now.getDate() + 1);
                      else now.setDate(now.getDate() + 30);
                      setConsultation({ ...consultation, followUpDate: now.toISOString().split("T")[0] });
                    }}
                    title="Smart Schedule based on outcome"
                  >
                    Γ£¿ Auto
                  </button>
                </div>
              </label>
            </div>
            {message ? <p className="mt-4 text-sm font-semibold text-primary bg-primary/10 border border-primary/20 px-4 py-2 rounded-xl">{message}</p> : null}
          </PremiumSectionCard>

          <SmartPrescriptionPad
            prescription={prescription}
            setPrescription={setPrescription}
            patientId={selectedPatientId}
            loading={false}
            disabled={!consultationId || existingPrescriptionLoaded}
            message={message}
            error={error}
            onSave={async () => {
              if (!consultationId) {
                setError("");
                setMessage(t("saveConsultationFirst"));
                return;
              }
              try {
                setError("");
                setMessage("");
                const data = await createPrescription({
                  consultationNoteId: consultationId,
                  patientDisplayName: prescription.patientDisplayName,
                  notes: prescription.notes,
                  followUpDate: prescription.followUpDate || null,
                  medications: prescription.medications
                });
                setExistingPrescriptionLoaded(true);
                setMessage(t("prescriptionCreatedScheduled").replace("{count}", data.medications.length));
              } catch (err) {
                const messageText = getApiErrorMessage(err, t("unableCreatePrescription"));
                if (messageText === "Prescription already created for consultation") {
                  try {
                    const existing = await fetchPrescriptionByConsultation(consultationId);
                    setPrescription({
                      patientDisplayName: existing.patientName ?? "",
                      notes: existing.notes ?? "",
                      followUpDate: existing.followUpDate ?? "",
                      medications: Array.isArray(existing.medications) ? existing.medications : []
                    });
                    setExistingPrescriptionLoaded(true);
                    setError("");
                    setMessage(t("prescriptionAlreadyLoaded"));
                  } catch {
                    setError(messageText);
                  }
                } else {
                  setError(messageText);
                }
              }
            }}
          />

          {selectedPatientId && (
            <>
              <LongitudinalTimelineCard patientId={selectedPatientId} />
              <IotTelemetryDashboard patientId={selectedPatientId} />
              <AiImagingAnalyzer patientId={selectedPatientId} />
            </>
          )}
        </div>

        <div className="space-y-6">
          <div className="sticky top-6 space-y-6">
            <h3 className="doc-heading flex items-center gap-2 text-primary bg-slate-800/50 p-4 rounded-xl border border-primary/20 shadow-[0_0_15px_rgba(56,189,248,0.1)]">
              <Activity className="w-6 h-6 animate-pulse" /> AI Clinical Assistant
            </h3>

            <AiMedicalScribePanel
              webrtcStream={webrtcStream}
              onSoapNoteGenerated={(data) => setConsultation((current) => ({
                ...current,
                soap: {
                  ...current.soap,
                  subjective: data.subjective || current.soap.subjective,
                  objective: data.objective || current.soap.objective,
                  assessment: data.assessment || current.soap.assessment,
                  plan: data.plan || current.soap.plan
                }
              }))}
            />

            <AiConsultationSummaryCard
              consultationId={consultationId}
              patientId={selectedPatientId}
              onApplySummary={(summaryText) => setConsultation((current) => ({ 
                ...current, 
                soap: { ...current.soap, assessment: `${current.soap.assessment}\n${summaryText}`.trim() } 
              }))}
            />

            {selectedPatientId && (
              <PriorAuthorizationPanel patientId={selectedPatientId} consultationId={consultationId} />
            )}

            <AiTreatmentSuggestionsCard patientId={selectedPatientId} />
            <AiRiskCard patientId={selectedPatientId} titleKey="aiRiskInsightsDoctor" />
            <AiReportSummaryCard patientId={selectedPatientId} titleKey="aiReportSummaryDoctor" />
          </div>
        </div>
      </div>
    </div>
  );
}

import "./doctor-premium-override.css";
import { useEffect, useState } from "react";
import PremiumSectionCard from "../components/PremiumSectionCard";
import PremiumStatCard from "../components/PremiumStatCard";
import { useAuth } from "../context/AuthContext";
import { useLanguage } from "../context/LanguageContext";
import AiDoctorInsightsPanel from "../ai/components/AiDoctorInsightsPanel";
import { fetchDashboard } from "../services/telecareService";
import { getApiErrorMessage } from "../utils/apiError";
import { logAsyncFailure, runWithRequestTimeout } from "../utils/requestLifecycle";
import { translateDisplayText } from "../utils/i18n";
import EmptyStateCard from "../components/ui/EmptyStateCard";
import ErrorStateCard from "../components/ui/ErrorStateCard";
import PremiumPriorityActionsCard from "../components/PremiumPriorityActionsCard";
import { CalendarDays, ClipboardCheck, ShieldAlert, Stethoscope } from "lucide-react";

export default function DoctorDashboardPage() {
  const { auth } = useAuth();
  const { language, t } = useLanguage();
  const translateUiText = (value) => translateDisplayText(language, value);
  const doctorId = auth.profileId ?? auth.userId;
  const [dashboard, setDashboard] = useState(null);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);
  const [reloadToken, setReloadToken] = useState(0);

  useEffect(() => {
    const controller = new AbortController();
    let active = true;

    if (!doctorId || auth?.role !== "DOCTOR") {
      if (active) {
        setDashboard(null);
        setError("");
        setLoading(false);
      }
      return () => {
        active = false;
      };
    }

    setLoading(true);
    runWithRequestTimeout(
      (signal) => fetchDashboard(auth.role, doctorId, { signal }),
      { signal: controller.signal }
    )
      .then((data) => {
        if (!active) return;
        setDashboard(data);
        setError("");
      })
      .catch((err) => {
        if (!active) return;
        setDashboard(null);
        setError(getApiErrorMessage(err, t("unableLoadDoctorDashboard")));
        logAsyncFailure("doctor-dashboard", err, { doctorId });
      })
      .finally(() => {
        if (active) {
          setLoading(false);
        }
      });

    return () => {
      active = false;
      controller.abort();
    };
  }, [auth.role, doctorId, language, reloadToken, t]);

  if (error) {
    return (
      <ErrorStateCard
        title={t("unableLoadDoctorDashboard")}
        body={error}
        actionLabel={t("retry")}
        onAction={() => setReloadToken((current) => current + 1)}
      />
    );
  }
  if (loading) return (
    <div className="space-y-6 animate-pulse">
      <div className="card-premium h-64 w-full bg-white/5"></div>
      <div className="grid gap-6 md:grid-cols-3">
        <div className="card-premium h-32 w-full bg-white/5"></div>
        <div className="card-premium h-32 w-full bg-white/5"></div>
        <div className="card-premium h-32 w-full bg-white/5"></div>
      </div>
    </div>
  );
  
  if (!dashboard) {
    return (
      <EmptyStateCard
        title={t("noDashboardData")}
        body={t("noDashboardData")}
      />
    );
  }

  const alertsCount = Array.isArray(dashboard.recentHealthAlerts) ? dashboard.recentHealthAlerts.length : 0;
  const pendingAppointments = Number(dashboard.pendingAppointments || 0);
  const totalAppointments = Number(dashboard.totalAppointments || 0);
  const prescriptionsCompleted = Number(dashboard.prescriptionCount || 0);

  const priorityActions = [];

  if (alertsCount > 0) {
    priorityActions.push({
      id: "alerts",
      title: translateUiText("Triage alerts to review"),
      description: translateUiText("{count} patient alerts need review").replace("{count}", alertsCount),
      meta: translateUiText("Open the priority queue to respond."),
      priority: "urgent",
      status: translateUiText("Urgent"),
      statusTone: "danger",
      icon: <ShieldAlert className="h-5 w-5" />
    });
  }

  if (pendingAppointments > 0) {
    priorityActions.push({
      id: "pending-appointments",
      title: translateUiText("Appointments pending confirmation"),
      description: translateUiText("{count} appointments need review").replace("{count}", pendingAppointments),
      meta: translateUiText("Confirm or reschedule as needed."),
      priority: "review",
      status: translateUiText("Needs review"),
      statusTone: "warning",
      icon: <ClipboardCheck className="h-5 w-5" />
    });
  }

  if (totalAppointments > 0) {
    priorityActions.push({
      id: "upcoming-appointments",
      title: translateUiText("Upcoming appointments"),
      description: translateUiText("{count} appointments on your schedule").replace("{count}", totalAppointments),
      meta: translateUiText("Review the day's agenda."),
      priority: "upcoming",
      status: translateUiText("Upcoming"),
      statusTone: "info",
      icon: <CalendarDays className="h-5 w-5" />
    });
  }

  if (prescriptionsCompleted > 0) {
    priorityActions.push({
      id: "completed-consults",
      title: translateUiText("Consultations completed"),
      description: translateUiText("{count} consults closed recently").replace("{count}", prescriptionsCompleted),
      meta: translateUiText("Document any follow-up tasks."),
      priority: "recent",
      status: translateUiText("Completed"),
      statusTone: "success",
      icon: <Stethoscope className="h-5 w-5" />
    });
  }

  // Calculate some dummy adherence or progress metrics for visual flavor
  const adherenceTarget = 80; // 80%
  const todayProgress = totalAppointments > 0 ? (totalAppointments - pendingAppointments) / totalAppointments * 100 : 100;
  
  return (
    <div className="space-y-6 pb-12 animate-fadeSlideUp">
      <PremiumPriorityActionsCard
        title={translateUiText("Priority actions")}
        subtitle={translateUiText("Focus on the most urgent clinical work first.")}
        actions={priorityActions}
        emptyTitle={translateUiText("No urgent care actions right now")}
        emptyBody={translateUiText("You're caught up. Continue monitoring your queue.")}
      />
      <div className="grid gap-6 md:grid-cols-3">
        <PremiumStatCard 
          title={t("appointmentsLabel")} 
          value={dashboard.totalAppointments} 
          hint={t("allAssignedAppointments")} 
          icon={<CalendarDays className="h-5 w-5" />} 
          progress={todayProgress}
        />
        <PremiumStatCard 
          title={t("pendingToday")} 
          value={dashboard.pendingAppointments} 
          hint={t("awaitingConfirmation")} 
          icon={<ClipboardCheck className="h-5 w-5" />} 
          progress={pendingAppointments > 0 ? 30 : 100}
        />
        <PremiumStatCard 
          title={t("completedConsults")} 
          value={dashboard.prescriptionCount} 
          hint={t("consultationsClosed")} 
          icon={<Stethoscope className="h-5 w-5" />} 
          progress={100}
        />
      </div>
      <div className="grid gap-6 lg:grid-cols-2">
        <PremiumSectionCard
          title={(
            <span className="flex items-center gap-2">
              <Stethoscope className="h-4 w-4 text-teal-400" />
              {t("clinicalExtensionSnapshot")}
            </span>
          )}
        >
          <div className="space-y-4">
            <div className="rounded-xl bg-white/5 border border-white/10 p-4 flex items-center justify-between transition-colors hover:bg-white/10">
              <div>
                <p className="text-sm font-medium text-ink/90">{t("carePlanning")}</p>
                <p className="mt-1 text-xs text-ink-muted">{t("createStructuredCarePlans")}</p>
              </div>
              <span className="px-2 py-1 text-[10px] font-bold uppercase tracking-wider bg-primary/20 text-primary rounded-sm">{t("ready")}</span>
            </div>
            <div className="rounded-xl bg-white/5 border border-white/10 p-4 flex items-center justify-between transition-colors hover:bg-white/10">
              <div>
                <p className="text-sm font-medium text-ink/90">{t("prioritizedReview")}</p>
                <p className="mt-1 text-xs text-ink-muted">{t("patientsSurfacedByTriage")}</p>
              </div>
              <span className="px-3 py-1 text-xs font-bold uppercase tracking-wider bg-alert/20 text-alert rounded-sm">
                {(Array.isArray(dashboard.recentHealthAlerts) ? dashboard.recentHealthAlerts : []).length}
              </span>
            </div>
          </div>
        </PremiumSectionCard>
        
        <PremiumSectionCard
          title={(
            <span className="flex items-center gap-2">
              <ShieldAlert className="h-4 w-4 text-alert" />
              {t("priorityReviewQueue")}
            </span>
          )}
        >
          {(Array.isArray(dashboard.recentHealthAlerts) ? dashboard.recentHealthAlerts : []).length ? (
            <div className="space-y-3">
              {(Array.isArray(dashboard.recentHealthAlerts) ? dashboard.recentHealthAlerts : []).map((item, index) => (
                <div
                  key={`${item}-${index}`}
                  className="rounded-xl border border-alert/20 bg-alert/5 px-4 py-3 shadow-[0_0_15px_rgba(239,68,68,0.05)]"
                >
                  <p className="text-sm font-medium text-ink/90">{item}</p>
                </div>
              ))}
            </div>
          ) : (
            <div className="flex flex-col items-center justify-center py-8 text-center bg-white/5 border border-white/10 rounded-xl border-dashed">
              <div className="mb-3 text-ink-muted/30">
                <ShieldAlert className="h-10 w-10" />
              </div>
              <p className="text-sm font-medium text-ink/90">{t("noDoctorQueue")}</p>
              <p className="mt-1 text-xs text-ink-muted">All alerts have been reviewed</p>
            </div>
          )}
        </PremiumSectionCard>
      </div>
      
      {/* TODO: AiDoctorInsightsPanel requires a redesign as well to match the layout */}
      <AiDoctorInsightsPanel doctorId={doctorId} />
    </div>
  );
}

import "./doctor-premium-override.css";
import { useEffect, useState } from "react";
import PremiumSectionCard from "../components/PremiumSectionCard";
import { useAuth } from "../context/AuthContext";
import { useLanguage } from "../context/LanguageContext";
import { fetchDoctorPriorityQueue } from "../services/telecareService";
import { getApiErrorMessage } from "../utils/apiError";
import { translateDisplayText } from "../utils/i18n";
import EmptyStateCard from "../components/ui/EmptyStateCard";
import ErrorStateCard from "../components/ui/ErrorStateCard";
import { BrainCircuit, Activity, AlertTriangle, TrendingDown } from "lucide-react";

function IntelligenceSkeleton() {
  return (
    <div className="space-y-4">
      {Array.from({ length: 3 }).map((_, i) => (
        <div key={i} className="doc-skeleton h-40 w-full rounded-xl" />
      ))}
    </div>
  );
}

export default function DoctorIntelligencePage() {
  const { auth } = useAuth();
  const { language, t } = useLanguage();
  const doctorId = auth.profileId ?? auth.userId;
  const [queue, setQueue] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    setLoading(true);
    fetchDoctorPriorityQueue(doctorId)
      .then((data) => {
        setQueue(Array.isArray(data) ? data : []);
        setError("");
      })
      .catch((err) => setError(getApiErrorMessage(err, t("unableLoadDoctorQueue"))))
      .finally(() => setLoading(false));
  }, [doctorId, t]);

  const getRiskColor = (level) => {
    switch (level) {
      case "CRITICAL": return "bg-rose-500";
      case "HIGH": return "bg-amber-500";
      case "MODERATE": return "bg-yellow-500";
      default: return "bg-teal-500";
    }
  };

  const getRiskBadge = (level) => {
    switch (level) {
      case "CRITICAL": return "doc-badge-alert";
      case "HIGH": return "doc-badge-warn";
      default: return "doc-badge-neutral";
    }
  };

  return (
    <div className="space-y-6 tcd-animate-in">
      <PremiumSectionCard title={(
        <span className="flex items-center gap-2">
          <BrainCircuit className="h-5 w-5 text-teal-400" />
          {t("doctorIntelligenceQueue")}
        </span>
      )}>
        {loading ? <IntelligenceSkeleton /> : null}
        {error ? (
          <ErrorStateCard
            title={t("unableLoadDoctorQueue")}
            body={error}
          />
        ) : null}
        {!loading && !error && !queue.length ? (
          <EmptyStateCard
            title={t("noDoctorQueue")}
            body={translateDisplayText(language, "Priority patients will appear here when risk signals are detected.")}
          />
        ) : null}
        <div className="doc-grid-2">
          {queue.map((patient) => (
            <div key={patient.patientId} className="group rounded-xl border border-white/5 bg-white/5 p-5 transition-colors hover:bg-white/10 hover:border-white/10">
              <div className="flex items-start justify-between mb-4">
                <div>
                  <p className="font-semibold text-white text-lg tracking-tight">{patient.patientName}</p>
                  <div className="flex items-center gap-3 mt-1">
                    <span className={`doc-badge ${getRiskBadge(patient.riskLevel)} text-xs px-2.5 py-0.5`}>
                      {translateDisplayText(language, patient.riskLevel)}
                    </span>
                    {patient.latestAlert && patient.latestAlert !== t("noActiveAlert") && (
                      <span className="flex items-center gap-1 text-xs font-semibold text-rose-400">
                        <AlertTriangle className="h-3 w-3" /> Active Alert
                      </span>
                    )}
                  </div>
                </div>
                <div className="text-right">
                  <p className="text-sm font-semibold text-slate-300">{patient.riskScore}/100</p>
                  <p className="text-[10px] uppercase tracking-wider text-slate-500">{t("riskScore")}</p>
                </div>
              </div>
              
              <div className="grid grid-cols-2 gap-4 mb-5 border-y border-white/5 py-4">
                <div>
                  <div className="flex items-center justify-between mb-1">
                    <span className="text-xs text-slate-400 flex items-center gap-1"><Activity className="h-3 w-3" /> Risk Status</span>
                  </div>
                  <div className="h-1.5 w-full bg-white/5 rounded-full overflow-hidden">
                    <div className={`h-full rounded-full ${getRiskColor(patient.riskLevel)}`} style={{ width: `${Math.max(5, patient.riskScore)}%` }} />
                  </div>
                </div>
                <div>
                  <div className="flex items-center justify-between mb-1">
                    <span className="text-xs text-slate-400 flex items-center gap-1"><TrendingDown className="h-3 w-3" /> Adherence</span>
                    <span className="text-xs font-semibold text-white">{patient.adherencePercentage}%</span>
                  </div>
                  <div className="h-1.5 w-full bg-white/5 rounded-full overflow-hidden">
                    <div className="h-full rounded-full bg-teal-400" style={{ width: `${Math.max(5, patient.adherencePercentage)}%` }} />
                  </div>
                </div>
              </div>
              
              <div className="space-y-3">
                <div className="rounded-lg bg-black/20 p-3">
                  <p className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-1">Latest Signal</p>
                  <p className="text-sm text-slate-300 leading-relaxed">{translateDisplayText(language, patient.latestAlert)}</p>
                </div>
                
                <div className="rounded-lg bg-teal-400/5 border border-teal-400/10 p-3">
                  <p className="text-xs font-semibold text-teal-400/70 uppercase tracking-wider mb-1">AI Recommendation</p>
                  <p className="text-sm font-medium text-teal-400">{translateDisplayText(language, patient.recommendedAction)}</p>
                </div>
              </div>
            </div>
          ))}
        </div>
      </PremiumSectionCard>

      <PremiumSectionCard title={(
        <span className="flex items-center gap-2">
          <BrainCircuit className="h-5 w-5 text-indigo-400" />
          Clinical Copilot (RAG)
        </span>
      )}>
        <div className="rounded-xl border border-white/5 bg-slate-900/50 p-5 space-y-4">
          <p className="text-sm text-slate-400">Ask the AI Copilot questions about clinical guidelines and patient history.</p>
          <div className="flex gap-2">
            <input 
              id="copilot-query" 
              className="doc-input flex-1" 
              placeholder="e.g. What is the recommended treatment for hypertension?" 
              onKeyDown={async (e) => {
                if (e.key === 'Enter') {
                  const val = e.target.value;
                  if (!val) return;
                  e.target.disabled = true;
                  const resSpan = document.getElementById("copilot-response");
                  resSpan.innerText = "Thinking...";
                  try {
                    const { askCopilot } = await import("../ai/services/aiService");
                    const res = await askCopilot({ query: val, patientId: null });
                    resSpan.innerText = res.answer;
                  } catch (err) {
                    resSpan.innerText = "Error asking copilot.";
                  } finally {
                    e.target.disabled = false;
                  }
                }
              }}
            />
          </div>
          <div className="p-4 rounded-lg bg-slate-800 border border-slate-700 min-h-24 text-sm text-slate-300">
            <span id="copilot-response">Copilot response will appear here...</span>
          </div>
        </div>
      </PremiumSectionCard>
    </div>
  );
}

import "./doctor-premium-override.css";
import { useEffect, useState } from "react";
import LocalizedText from "../components/LocalizedText";
import PremiumSectionCard from "../components/PremiumSectionCard";
import { useAuth } from "../context/AuthContext";
import { useLanguage } from "../context/LanguageContext";
import { fetchDoctorProfile, updateDoctorProfile } from "../services/telecareService";
import { supportedLanguages, translateDisplayText } from "../utils/i18n";
import { useToast } from "../components/ui/ToastProvider";
import { getApiErrorMessage } from "../utils/apiError";
import LoadingSkeleton from "../components/ui/LoadingSkeleton";
import ErrorStateCard from "../components/ui/ErrorStateCard";

export default function DoctorProfilePage() {
  const { auth } = useAuth();
  const { language, t, translateUiText = (value) => translateDisplayText(language, value) } = useLanguage();
  const { pushToast } = useToast();
  const [form, setForm] = useState(null);
  const [error, setError] = useState("");

  useEffect(() => {
    fetchDoctorProfile(auth.profileId ?? auth.userId)
      .then((data) => {
        setForm({
          fullName: data?.user?.fullName || "",
          email: data?.user?.email || "",
          phone: data?.user?.phone || "",
          preferredLanguage: data?.user?.preferredLanguage || "en",
          specialization: data?.specialization || "",
          qualification: data?.qualification || "",
          availabilitySummary: data?.availabilitySummary || "",
          bio: data?.bio || ""
        });
        setError("");
      })
      .catch((err) => {
        setError(getApiErrorMessage(err, t("unableLoadProfile")));
      });
  }, [auth.profileId, auth.userId]);

  if (error) {
    return (
      <div className="tcd-animate-in">
        <PremiumSectionCard title={t("doctorProfile")}>
          <ErrorStateCard
            title={t("unableLoadProfile")}
            body={error}
          />
        </PremiumSectionCard>
      </div>
    );
  }
  if (!form) {
    return (
      <div className="tcd-animate-in">
        <PremiumSectionCard title={t("doctorProfile")}>
          <LoadingSkeleton lines={4} />
        </PremiumSectionCard>
      </div>
    );
  }

  const fieldLabels = {
    fullName: t("fullName"),
    email: t("email"),
    phone: t("phone"),
    preferredLanguage: t("preferredLanguage"),
    specialization: t("specialization"),
    qualification: t("qualification"),
    availabilitySummary: t("availabilitySummary"),
    bio: t("bio")
  };

  const languageOptions = supportedLanguages;
  const translatableValueFields = new Set([
    "specialization",
    "availabilitySummary",
    "bio"
  ]);

  return (
    <div className="tcd-animate-in space-y-6">
      <PremiumSectionCard
        title={t("doctorProfile")}
        action={
          <button
            className="doc-btn doc-btn-primary"
            onClick={async () => {
              try {
                const data = await updateDoctorProfile(auth.profileId ?? auth.userId, form);
                pushToast({
                  type: "success",
                  title: t("saveProfile"),
                  message: t("profileSavedFor").replace("{name}", data?.user?.fullName || form.fullName || t("doctor"))
                });
              } catch (err) {
                const message = getApiErrorMessage(err, t("unableSaveProfile"));
                pushToast({ type: "error", title: t("unableSaveProfile"), message });
              }
            }}
          >
            {t("saveProfile")}
          </button>
        }
      >
      <div className="doc-grid-2">
        {Object.entries(form).map(([key, value]) => {
          if (key === "preferredLanguage") {
            return (
              <label key={key} className="block space-y-2">
                <span className="text-sm font-medium text-slate-400">{fieldLabels[key]}</span>
                <select className="doc-input" value={value ?? "en"} onChange={(e) => setForm({ ...form, [key]: e.target.value })}>
                  {languageOptions.map((option) => (
                    <option key={option.code} value={option.code}>{translateDisplayText(language, option.code)}</option>
                  ))}
                </select>
              </label>
            );
          }

          const isTextArea = key === 'bio' || key === 'availabilitySummary' || key === 'specialization';

          return (
            <label key={key} className={`block space-y-2 ${isTextArea ? 'col-span-1 md:col-span-2' : ''}`}>
              <span className="text-sm font-medium text-slate-400">{fieldLabels[key] || key}</span>
              {isTextArea ? (
                <textarea
                  className="doc-input min-h-28 resize-y"
                  value={value ?? ""}
                  onChange={(e) => setForm({ ...form, [key]: e.target.value })}
                />
              ) : (
                <input
                  className="doc-input"
                  value={value ?? ""}
                  onChange={(e) => setForm({ ...form, [key]: e.target.value })}
                />
              )}
              {translatableValueFields.has(key) && value && language !== "en" && (
                <span className="text-xs text-slate-400 block mt-1">
                  {translateUiText("Preview")}: <LocalizedText as="span" className="text-teal-400" value={value} />
                </span>
              )}
            </label>
          );
        })}
      </div>
    </PremiumSectionCard>
    </div>
  );
}

import "./doctor-premium-override.css";
import { useEffect, useState } from "react";
import LocalizedText from "../components/LocalizedText";
import PremiumSectionCard from "../components/PremiumSectionCard";
import { useAuth } from "../context/AuthContext";
import { useLanguage } from "../context/LanguageContext";
import { createReferral, fetchDoctorReferrals, fetchReferralSuggestions } from "../services/telecareService";
import { getApiErrorMessage } from "../utils/apiError";
import { translateDisplayText } from "../utils/i18n";
import LoadingSkeleton from "../components/ui/LoadingSkeleton";
import EmptyStateCard from "../components/ui/EmptyStateCard";

export default function DoctorReferralsPage() {
  const { auth } = useAuth();
  const { language, t } = useLanguage();
  const doctorId = auth.profileId ?? auth.userId;
  const [suggestions, setSuggestions] = useState([]);
  const [referrals, setReferrals] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [message, setMessage] = useState("");
  const [form, setForm] = useState({
    doctorId,
    patientId: "",
    specialty: "",
    targetFacility: "",
    reason: "",
    recommendationNote: "",
    urgency: "ROUTINE",
    recommendedDate: ""
  });

  const load = async () => {
    setLoading(true);
    try {
      const [suggestionData, referralData] = await Promise.all([
        fetchReferralSuggestions(doctorId),
        fetchDoctorReferrals(doctorId)
      ]);
      const safeSuggestions = Array.isArray(suggestionData) ? suggestionData : [];
      const safeReferrals = Array.isArray(referralData) ? referralData : [];
      setSuggestions(safeSuggestions);
      setReferrals(safeReferrals);
      setForm((current) => ({
        ...current,
        doctorId,
        patientId: current.patientId || (safeSuggestions[0]?.patientId ? String(safeSuggestions[0].patientId) : ""),
        specialty: current.specialty || (safeSuggestions[0]?.specialty || ""),
        targetFacility: current.targetFacility || (safeSuggestions[0]?.recommendedFacility || ""),
        urgency: current.urgency || (safeSuggestions[0]?.urgency || "ROUTINE"),
        reason: current.reason || (safeSuggestions[0]?.rationale || "")
      }));
      setError("");
    } catch (err) {
      setError(getApiErrorMessage(err, t("unableLoadReferrals")));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, [doctorId]);

  return (
    <div className="grid gap-6 xl:grid-cols-[0.95fr_1.05fr] tcd-animate-in">
      <PremiumSectionCard
        title={t("referralIntelligence")}
        action={
          <button
            className="doc-btn doc-btn-primary"
            type="button"
            disabled={saving}
            aria-label={saving ? t("saving") : t("createReferral")}
            data-voice-label={saving ? t("saving") : t("createReferral")}
            onClick={async () => {
              try {
                setSaving(true);
                const created = await createReferral({
                  ...form,
                  doctorId,
                  patientId: Number(form.patientId),
                  recommendedDate: form.recommendedDate || null
                });
                setReferrals((current) => [created, ...current]);
                setMessage(t("referralCreated"));
                setError("");
              } catch (err) {
                setError(getApiErrorMessage(err, t("unableCreateReferral")));
              } finally {
                setSaving(false);
              }
            }}
          >
            {saving ? t("saving") : t("createReferral")}
          </button>
        }
      >
        <div className="space-y-4">
          <label className="block space-y-2">
            <span className="text-sm font-medium text-slate-400">{t("patientId")}</span>
            <select
              className="doc-input"
              aria-label={t("patientId")}
              data-voice-label={t("patientId")}
              value={form.patientId}
              onChange={(e) => setForm({ ...form, patientId: e.target.value })}
            >
              <option value="">{t("selectPatient")}</option>
              {suggestions.map((item) => (
                <option key={item.patientId} value={item.patientId}>{item.patientName}</option>
              ))}
            </select>
          </label>
          <div className="grid gap-4 md:grid-cols-2">
            <label className="block space-y-2">
              <span className="text-sm font-medium text-slate-400">{t("specialty")}</span>
              <input
                className="doc-input"
                aria-label={t("specialty")}
                data-voice-label={t("specialty")}
                value={form.specialty}
                onChange={(e) => setForm({ ...form, specialty: e.target.value })}
              />
            </label>
            <label className="block space-y-2">
              <span className="text-sm font-medium text-slate-400">{t("urgency")}</span>
              <select
                className="doc-input"
                aria-label={t("urgency")}
                data-voice-label={t("urgency")}
                value={form.urgency}
                onChange={(e) => setForm({ ...form, urgency: e.target.value })}
              >
                <option value="ROUTINE">{translateDisplayText(language, "ROUTINE")}</option>
                <option value="PRIORITY">{translateDisplayText(language, "PRIORITY")}</option>
                <option value="URGENT">{translateDisplayText(language, "URGENT")}</option>
              </select>
            </label>
          </div>
          <label className="block space-y-2">
            <span className="text-sm font-medium text-slate-400">{t("targetFacility")}</span>
            <input
              className="doc-input"
              aria-label={t("targetFacility")}
              data-voice-label={t("targetFacility")}
              value={form.targetFacility}
              onChange={(e) => setForm({ ...form, targetFacility: e.target.value })}
            />
          </label>
          <label className="block space-y-2">
            <span className="text-sm font-medium text-slate-400">{t("reason")}</span>
            <textarea
              className="doc-input min-h-24 resize-y"
              aria-label={t("reason")}
              data-voice-label={t("reason")}
              value={form.reason}
              onChange={(e) => setForm({ ...form, reason: e.target.value })}
            />
          </label>
          <label className="block space-y-2">
            <span className="text-sm font-medium text-slate-400">{t("recommendationNote")}</span>
            <textarea
              className="doc-input min-h-24 resize-y"
              aria-label={t("recommendationNote")}
              data-voice-label={t("recommendationNote")}
              value={form.recommendationNote}
              onChange={(e) => setForm({ ...form, recommendationNote: e.target.value })}
            />
          </label>
          <label className="block space-y-2">
            <span className="text-sm font-medium text-slate-400">{t("recommendedDate")}</span>
            <input
              className="doc-input"
              type="date"
              aria-label={t("recommendedDate")}
              data-voice-label={t("recommendedDate")}
              value={form.recommendedDate}
              onChange={(e) => setForm({ ...form, recommendedDate: e.target.value })}
            />
          </label>
        </div>
        {message ? <p className="mt-4 text-sm text-emerald-600" role="status" aria-live="polite">{message}</p> : null}
        {error ? <p className="mt-4 text-sm text-red-400" role="alert">{error}</p> : null}
      </PremiumSectionCard>

      <div className="space-y-6">
        <PremiumSectionCard title={t("suggestedReferrals")}>
          {loading ? <LoadingSkeleton lines={4} /> : null}
          {!loading && !suggestions.length ? (
            <EmptyStateCard
              title={t("noReferralSuggestions")}
              body={translateDisplayText(language, "Suggestions will appear when continuity signals indicate a referral.")}
            />
          ) : null}
          <div className="space-y-4">
            {suggestions.map((item) => (
              <div key={`${item.patientId}-${item.specialty}`} className="rounded-xl border border-white/5 bg-white/5 p-5">
                <div className="flex flex-wrap items-center justify-between gap-3 border-b border-white/5 pb-3">
                  <div>
                    <p className="font-semibold text-white tracking-tight">{item.patientName}</p>
                    <p className="text-sm text-slate-400 mt-1">{translateDisplayText(language, item.specialty)}</p>
                  </div>
                  <span className={`doc-badge ${item.urgency === 'URGENT' ? 'doc-badge-alert' : item.urgency === 'PRIORITY' ? 'doc-badge-warn' : 'doc-badge-neutral'} text-xs px-2.5 py-1`}>{item.urgency}</span>
                </div>
                <LocalizedText as="p" className="mt-4 text-sm text-slate-300 leading-relaxed" value={item.rationale} />
                <LocalizedText as="p" className="mt-2 text-sm font-semibold text-teal-400" value={item.recommendedFacility} />
                <button
                  className="doc-btn doc-btn-secondary mt-4 w-full"
                  type="button"
                  aria-label={t("useSuggestion")}
                  data-voice-label={t("useSuggestion")}
                  onClick={() => setForm({
                    ...form,
                    doctorId,
                    patientId: String(item.patientId),
                    specialty: item.specialty,
                    targetFacility: item.recommendedFacility,
                    urgency: item.urgency,
                    reason: item.rationale
                  })}
                >
                  {t("useSuggestion")}
                </button>
              </div>
            ))}
          </div>
        </PremiumSectionCard>

        <PremiumSectionCard title={t("existingReferrals")}>
          {!loading && !referrals.length ? (
            <EmptyStateCard
              title={t("noReferrals")}
              body={translateDisplayText(language, "Created referrals will appear here for tracking.")}
            />
          ) : null}
          <div className="space-y-4">
            {referrals.map((item) => (
              <div key={item.id} className="rounded-xl border border-white/5 bg-white/5 p-5">
                <div className="flex flex-wrap items-center justify-between gap-3 border-b border-white/5 pb-3">
                  <div>
                    <p className="font-semibold text-white tracking-tight">{item.patientName}</p>
                    <p className="text-sm text-slate-400 mt-1">{translateDisplayText(language, item.specialty)}</p>
                  </div>
                  <div className="flex items-center gap-3">
                    <span className={`doc-badge ${item.urgency === 'URGENT' ? 'doc-badge-alert' : item.urgency === 'PRIORITY' ? 'doc-badge-warn' : 'doc-badge-neutral'} text-[10px] px-2 py-0.5`}>{item.urgency}</span>
                    <span className="doc-badge doc-badge-success text-[10px] px-2 py-0.5">{translateDisplayText(language, item.status)}</span>
                  </div>
                </div>
                <LocalizedText as="p" className="mt-4 text-sm text-slate-300 leading-relaxed" value={item.reason} />
                {item.recommendationNote ? <LocalizedText as="p" className="mt-2 text-sm text-slate-400" value={item.recommendationNote} /> : null}
                <LocalizedText as="p" className="mt-2 text-sm font-semibold text-teal-400" value={item.targetFacility || "-"} />
              </div>
            ))}
          </div>
        </PremiumSectionCard>
      </div>
    </div>
  );
}

import { useEffect, useRef, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import "./landing-override.css";

export default function LandingPage() {
  const navigate = useNavigate();
  const [darkMode, setDarkMode] = useState(() => {
    if (typeof window === "undefined") return false;
    try {
      return localStorage.getItem("telecareplus-theme") === "light" ? false : true; // Default dark
    } catch {
      return true;
    }
  });

  // Toggles for accessibility
  const [screenReader, setScreenReader] = useState(false);
  const [readAloud, setReadAloud] = useState(false);
  const [largeText, setLargeText] = useState(false);
  const [highContrast, setHighContrast] = useState(false);
  const [voiceCommand, setVoiceCommand] = useState(false);
  const [langSwitch, setLangSwitch] = useState(false);

  useEffect(() => {
    if (typeof document !== "undefined") {
      document.title = `TeleCare+ ΓÇö Connected Care Platform`;
    }
  }, []);

  useEffect(() => {
    if (typeof document === "undefined") return;
    if (darkMode) {
      document.documentElement.removeAttribute("data-theme");
    } else {
      document.documentElement.setAttribute("data-theme", "light");
    }
    try {
      localStorage.setItem("telecareplus-theme", darkMode ? "dark" : "light");
    } catch {}
  }, [darkMode]);

  const toggleTheme = () => setDarkMode((d) => !d);

  // Animated ECG
  const ecgLineRef = useRef(null);
  useEffect(() => {
    const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    let req;
    if (!prefersReduced && ecgLineRef.current) {
      let offset = 0;
      const animateECG = () => {
        offset -= 1.4;
        if (offset <= -400) offset = 0;
        if (ecgLineRef.current) {
          ecgLineRef.current.setAttribute('transform', `translate(${offset},0)`);
        }
        req = requestAnimationFrame(animateECG);
      };
      req = requestAnimationFrame(animateECG);
    }
    return () => { if (req) cancelAnimationFrame(req); };
  }, []);

  // Symptom check-in bar animation
  const barRefs = useRef([]);
  useEffect(() => {
    const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (!prefersReduced) {
      barRefs.current.forEach(bar => {
        if (!bar) return;
        const target = bar.style.width;
        bar.style.width = '0%';
        requestAnimationFrame(() => {
          bar.style.transition = 'width 1.1s cubic-bezier(.2,.8,.2,1)';
          bar.style.width = target;
        });
      });
    }
  }, []);

  // Scroll reveals
  const revealRefs = useRef([]);
  useEffect(() => {
    const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (prefersReduced || !('IntersectionObserver' in window)) {
      revealRefs.current.forEach(el => el?.classList.add('is-visible'));
    } else {
      const io = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-visible');
            io.unobserve(entry.target);
          }
        });
      }, { threshold: 0.15, rootMargin: '0px 0px -40px 0px' });
      revealRefs.current.forEach(el => {
        if (el) io.observe(el);
      });
      return () => io.disconnect();
    }
  }, []);

  // Count up numbers
  const countRefs = useRef([]);
  useEffect(() => {
    const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const animateCount = (el) => {
      const target = parseFloat(el.dataset.count);
      const suffix = el.dataset.suffix || '';
      const duration = 1400;
      const start = performance.now();
      const tick = (now) => {
        const p = Math.min((now - start) / duration, 1);
        const eased = 1 - Math.pow(1 - p, 3);
        const val = Math.round(target * eased);
        el.textContent = val.toLocaleString() + suffix;
        if (p < 1) requestAnimationFrame(tick);
      };
      if (prefersReduced) {
        el.textContent = target.toLocaleString() + suffix;
      } else {
        requestAnimationFrame(tick);
      }
    };
    
    if ('IntersectionObserver' in window && !prefersReduced) {
      const countIo = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            animateCount(entry.target);
            countIo.unobserve(entry.target);
          }
        });
      }, { threshold: 0.4 });
      countRefs.current.forEach(el => {
        if (el) countIo.observe(el);
      });
      return () => countIo.disconnect();
    } else {
      countRefs.current.forEach(el => {
        if (el) animateCount(el);
      });
    }
  }, []);

  const addToRefs = (arr) => (el) => {
    if (el && !arr.current.includes(el)) {
      arr.current.push(el);
    }
  };

  return (
    <div className="landing-wrapper">
      <a className="skip-link" href="#main">Skip to content</a>

