import { useCallback, useEffect, useRef, useState } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import LanguageSwitcher from "../components/LanguageSwitcher";
import { useAuth } from "../context/AuthContext";
import { LANGUAGE_CONTEXT_FALLBACK, useLanguage } from "../context/LanguageContext";
import { API_BASE_URL } from "../services/api";
import { requestOtpLogin } from "../services/authService";
import { getDefaultRouteForRole, normalizeRole } from "../utils/roleUtils";
import { Loader2 } from "lucide-react";
import { useToast } from "../components/ui/ToastProvider";
import "./login-override.css";

export default function LoginPage() {
  const { language, t, translateUiText = (value) => value } = useLanguage() ?? LANGUAGE_CONTEXT_FALLBACK;
  const { login, verifyOtpLogin, logout, auth, isAuthenticated, isAuthReady } = useAuth();
  const { pushToast } = useToast();
  const navigate = useNavigate();
  const location = useLocation();

  const forceLogin = (() => {
    try {
      return new URLSearchParams(location.search || "").get("forceLogin") === "1";
    } catch {
      return false;
    }
  })();
  const languageSearch = (() => {
    try {
      const params = new URLSearchParams(location.search || "");
      params.delete("forceLogin");
      const lang = params.get("lang") || (language && language !== "en" ? language : "");
      return lang && lang !== "en" ? `?lang=${lang}` : "";
    } catch {
      return language && language !== "en" ? `?lang=${language}` : "";
    }
  })();

  const [form, setForm] = useState({ email: "", password: "" });
  const [otpForm, setOtpForm] = useState({ phone: "", otp: "" });
  const [mode, setMode] = useState("password");
  const [otpMessage, setOtpMessage] = useState("");
  const [otpErrors, setOtpErrors] = useState({ phone: "", otp: "" });
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const [backendStatus, setBackendStatus] = useState({ state: "checking" });
  const hasRedirectedRef = useRef(false);
  const hasForcedLogoutRef = useRef(false);

  useEffect(() => {
    try {
      const expired = sessionStorage.getItem("telecareplus-auth-expired");
      if (expired === "1") {
        sessionStorage.removeItem("telecareplus-auth-expired");
        pushToast({
          type: "error",
          title: "Session expired",
          message: "Please sign in again to continue."
        });
      }
    } catch {}
    setForm({ email: "", password: "" });
    setOtpForm({ phone: "", otp: "" });
  }, []);

  const checkBackend = useCallback(async () => {
    setBackendStatus({ state: "checking" });
    const controller = new AbortController();
    const timeoutId = window.setTimeout(() => controller.abort(), 4000);
    try {
      const statusUrl = import.meta.env.DEV ? "/api/system/status" : `${API_BASE_URL}/system/status`;
      const response = await fetch(statusUrl, {
        method: "GET",
        signal: controller.signal,
        headers: { "Accept": "application/json" }
      });
      if (!response.ok) throw new Error("Backend unavailable");
      const payload = await response.json();
      const ready = payload?.ready === true || payload?.status === "UP";
      setBackendStatus({ state: ready ? "ready" : "down" });
    } catch {
      setBackendStatus({ state: "down" });
    } finally {
      window.clearTimeout(timeoutId);
    }
  }, []);

  useEffect(() => {
    if (typeof window !== "undefined") {
      checkBackend();
    }
  }, [checkBackend]);

  useEffect(() => {
    if (typeof document !== "undefined") {
      document.title = `TeleCare+ ΓÇö Secure sign in`;
    }
  }, []);

  const redirectByRole = (authData, { allowForceLogin = false } = {}) => {
    if (hasRedirectedRef.current || (forceLogin && !allowForceLogin)) {
      return;
    }
    const normalizedRole = normalizeRole(authData?.role);
    const roleHome = getDefaultRouteForRole(normalizedRole, languageSearch);
    const requestedPath = typeof location.state?.from === "string" ? location.state.from : "";
    const destination = requestedPath && requestedPath.startsWith(roleHome.split("?")[0]) ? requestedPath : roleHome;
    hasRedirectedRef.current = true;
    navigate(destination, { replace: true });
  };

  useEffect(() => {
    if (forceLogin && isAuthenticated && !hasForcedLogoutRef.current) {
      hasForcedLogoutRef.current = true;
      logout();
      return;
    }
    if (isAuthReady && isAuthenticated && auth?.role) {
      redirectByRole(auth);
    }
  }, [auth, forceLogin, isAuthReady, isAuthenticated, location.pathname, location.search]);

  const backendUnavailable = backendStatus.state === "down";
  const backendMessage = "Backend service is starting. Please wait a moment and try again.";

  const onPasswordSubmit = async (event) => {
    event.preventDefault();
    if (backendUnavailable) {
      setError(backendMessage);
      return;
    }
    setLoading(true);
    setError("");
    try {
      const authData = await login(form);
      pushToast({
        type: "success",
        title: "Login successful",
        message: `Welcome back, ${authData?.fullName || "TeleCare+ user"}.`
      });
      redirectByRole(authData, { allowForceLogin: true });
    } catch (err) {
      setError(err.response?.data?.message || err.message || "Login failed");
    } finally {
      setLoading(false);
    }
  };

  const onRequestOtp = async () => {
    if (backendUnavailable) {
      setError(backendMessage);
      return;
    }
    const trimmedPhone = otpForm.phone.trim();
    const digitsOnly = trimmedPhone.replace(/\D/g, "");
    if (!trimmedPhone) {
      setOtpErrors((current) => ({ ...current, phone: "Mobile number is required" }));
      setError("");
      setOtpMessage("");
      return;
    }
    if (digitsOnly.length < 10 || digitsOnly.length > 15) {
      setOtpErrors((current) => ({ ...current, phone: "Invalid mobile number" }));
      setError("");
      setOtpMessage("");
      return;
    }

    setLoading(true);
    setError("");
    setOtpMessage("");
    try {
      const response = await requestOtpLogin({ phone: trimmedPhone });
      setOtpMessage(response.message);
      setOtpErrors({ phone: "", otp: "" });
      setOtpForm((current) => ({ ...current, phone: trimmedPhone }));
    } catch (err) {
      setError(err.response?.data?.message || "Unable to send OTP");
    } finally {
      setLoading(false);
    }
  };

  const onOtpSubmit = async (event) => {
    event.preventDefault();
    if (backendUnavailable) {
      setError(backendMessage);
      return;
    }
    const nextErrors = { phone: "", otp: "" };
    const trimmedPhone = otpForm.phone.trim();
    const digitsOnly = trimmedPhone.replace(/\D/g, "");
    const resolvedOtp = otpForm.otp.trim();

    if (!trimmedPhone) nextErrors.phone = "Mobile number is required";
    else if (digitsOnly.length < 10 || digitsOnly.length > 15) nextErrors.phone = "Invalid mobile number";

    if (!resolvedOtp) nextErrors.otp = "OTP is required";
    else if (resolvedOtp.length !== 6) nextErrors.otp = "OTP must be 6 digits";

    if (nextErrors.phone || nextErrors.otp) {
      setOtpErrors(nextErrors);
      setError("");
      return;
    }

    setLoading(true);
    setError("");
    try {
      const authData = await verifyOtpLogin({ phone: trimmedPhone, otp: resolvedOtp });
      pushToast({
        type: "success",
        title: "Login successful",
        message: `Welcome back, ${authData?.fullName || "TeleCare+ user"}.`
      });
      redirectByRole(authData, { allowForceLogin: true });
    } catch (err) {
      setError(err.response?.data?.message || err.response?.data?.error || err.message || "OTP login failed");
    } finally {
      setLoading(false);
    }
  };

  return (
    <main id="tcl-root" className="login-wrapper">
      <div className="stage">
        
        <div className="brand">
          <div className="eyebrow">Continuous care, beyond consultations</div>
          <h1 className="serif">TeleCare+ connected<br/><em>care</em> workspace</h1>
          <p className="lede">Monitor vitals, manage care plans, and stay connected with your care team ΓÇö all in one place.</p>

          <div className="overview-label">Today's overview</div>
          <div className="grid">
            <div className="card">
              <div className="label"><span className="dot"></span>Heart rate</div>
              <div className="value mono">78<span style={{fontSize: '14px', color: 'var(--text-muted)', fontWeight: 400}}> bpm</span></div>
              <div className="sub">Resting, within range</div>
            </div>
            <div className="card">
              <div className="label"><span className="dot brass"></span>Blood pressure</div>
              <div className="value mono">128<span style={{fontSize: '14px', color: 'var(--text-muted)'}}>/82</span></div>
              <div className="sub">Slightly elevated</div>
            </div>

            <div className="card appt wide">
              <div className="label">Next appointment</div>
              <div className="value serif">Dr. Sharma</div>
              <div className="sub mono">Today ┬╖ 4:30 PM</div>
            </div>

            <div className="card alert wide">
              <div className="label"><span className="dot coral"></span>Alert</div>
              <div className="value" style={{fontSize: '16px'}}>High blood pressure detected</div>
              <span className="badge">Critical</span>
            </div>

            <div className="card wide">
              <div className="label">Medication adherence</div>
              <div className="value mono">85<span style={{fontSize: '14px', color: 'var(--text-muted)'}}>%</span> <span style={{fontSize: '13px', color: 'var(--text-secondary)', fontWeight: 400}}>completed this week</span></div>
              <div className="bar-track"><div className="bar-fill"></div></div>
            </div>
          </div>

          <div className="pulse-strip">
            <svg width="150" height="28" viewBox="0 0 150 28">
              <polyline points="0,14 22,14 30,4 38,24 46,14 60,14 68,8 74,20 80,14 150,14"
                fill="none" stroke="#4FB3A0" strokeWidth="1.6" strokeLinejoin="round" strokeLinecap="round"
                strokeDasharray="220" strokeDashoffset="220">
                <animate attributeName="stroke-dashoffset" from="220" to="0" dur="1.8s" repeatCount="indefinite"/>
              </polyline>
            </svg>
            <div className="ptext">Live sync with <b>Apple Health</b> ┬╖ last updated 2 min ago</div>
          </div>
        </div>

        <div className="seam">
          <svg width="28" height="140" viewBox="0 0 28 140">
            <polyline points="0,70 6,70 9,50 12,90 15,70 19,70 22,58 25,80 28,70"
              fill="none" stroke="#C9A24B" strokeWidth="1.4" strokeLinejoin="round" strokeLinecap="round" opacity="0.55"/>
          </svg>
        </div>

        <div className="signin">
          <div className="signin-top">
            <div className="wordmark">TELECARE<span>+</span></div>
            <LanguageSwitcher customClass="lang" hideLabel />
          </div>

          <h2 className="serif">Secure sign in</h2>
          <p className="sub">Privacy-first, AI-assisted care ΓÇö built for how you actually manage your health.</p>

          <div className="trust-row">
            <span className="trust"><span className="dot"></span>Encrypted end to end</span>
            <span className="trust"><span className="dot"></span>HIPAA aligned</span>
            <span className="trust"><span className="dot"></span>Low-bandwidth optimized</span>
          </div>

          <div className="tabs">
            <button className={mode === "password" ? "active" : ""} onClick={() => { setMode("password"); setError(""); setOtpMessage(""); }}>Email login</button>
            <button className={mode === "otp" ? "active" : ""} onClick={() => { setMode("otp"); setError(""); }}>Mobile OTP</button>
          </div>

          {backendUnavailable && (
            <div className="error-banner" role="alert">
              <p>{backendMessage}</p>
              <button
                type="button"
                style={{ marginTop: '8px', textDecoration: 'underline' }}
                onClick={checkBackend}
                disabled={backendStatus.state === "checking"}
              >
                {backendStatus.state === "checking" ? "Checking..." : "Retry connection"}
              </button>
            </div>
          )}

          {error && <div className="error-banner" role="alert">{error}</div>}
          {otpMessage && <div className="otp-message">{otpMessage}</div>}

          {mode === "password" ? (
            <form onSubmit={onPasswordSubmit} style={{ display: 'contents' }}>
              <div className="field">
                <label className="field-label">Email</label>
                <input type="email" placeholder="Enter your email" required
                  value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} />
                <div className="hint">Use the email you registered with TeleCare+.</div>
              </div>

              <div className="field">
                <label className="field-label">Password</label>
                <input type="password" placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó" required
                  value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} />
                <div className="hint">Use the password created during registration.</div>
              </div>

              <button type="submit" className="signin-btn" disabled={loading}>
                {loading && <Loader2 className="animate-spin" size={16} />}
                {loading ? "Signing in..." : "Sign in"}
              </button>
            </form>
          ) : (
            <form onSubmit={onOtpSubmit} style={{ display: 'contents' }}>
              <div className="field">
                <label className="field-label">Mobile Number</label>
                <input type="tel" placeholder="+1 (555) 000-0000"
                  value={otpForm.phone} onChange={(e) => setOtpForm({ ...otpForm, phone: e.target.value })} />
                {otpErrors.phone ? <div className="hint" style={{ color: 'var(--coral)' }}>{otpErrors.phone}</div> : <div className="hint">Enter the phone number linked to your account.</div>}
              </div>

              {otpMessage && (
                <div className="field">
                  <label className="field-label">One-Time Password</label>
                  <input type="text" placeholder="123456" maxLength={6}
                    value={otpForm.otp} onChange={(e) => setOtpForm({ ...otpForm, otp: e.target.value })} />
                  {otpErrors.otp ? <div className="hint" style={{ color: 'var(--coral)' }}>{otpErrors.otp}</div> : <div className="hint">Enter the 6-digit code sent to your phone.</div>}
                </div>
              )}

              {otpMessage ? (
                <button type="submit" className="signin-btn" disabled={loading}>
                  {loading && <Loader2 className="animate-spin" size={16} />}
                  {loading ? "Verifying..." : "Sign in"}
                </button>
              ) : (
                <button type="button" className="signin-btn" onClick={onRequestOtp} disabled={loading}>
                  {loading && <Loader2 className="animate-spin" size={16} />}
                  {loading ? "Sending..." : "Send OTP"}
                </button>
              )}
            </form>
          )}

          <div className="foot-links">
            <span>Trouble signing in? <a href="#">Get help</a></span>
            <a href="#">Forgot password</a>
          </div>

          <div className="create-acct">
            New here? <Link to="/register">Create an account</Link>
          </div>
        </div>

      </div>
    </main>
  );
}

import { useEffect, useState, useMemo } from "react";
import { useNavigate } from "react-router-dom";
import Badge from "../components/Badge";
import { useAuth } from "../context/AuthContext";
import { useLanguage } from "../context/LanguageContext";
import { disableBackgroundAlerts, enableBackgroundAlerts, getPushStatus } from "../services/pushService";
import { fetchPatientAlerts, subscribeToPatientAlertStream } from "../services/telecareService";
import { getApiErrorMessage } from "../utils/apiError";
import { notifyBrowser, requestBrowserNotificationPermission } from "../utils/browserNotifications";
import { translateDisplayText } from "../utils/i18n";
import PatientSidebar from "../components/PatientSidebar";
import { User, LogOut, Bell, ShieldAlert, Check, RefreshCw, Layers } from "lucide-react";
import { buildLoginRedirect } from "../utils/authSession";
import LanguageSwitcher from "../components/LanguageSwitcher";

export default function PatientAlertsPage() {
  const { auth, logout } = useAuth();
  const navigate = useNavigate();
  const { language, t } = useLanguage();
  const patientId = auth?.profileId;
  
  const [alerts, setAlerts] = useState([]);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);
  const [pushState, setPushState] = useState({ loading: true, supported: true, subscribed: false, configured: true, message: "" });
  const [filter, setFilter] = useState("All"); // All or Unread
  const [readAlertIds, setReadAlertIds] = useState(() => {
    try { return JSON.parse(localStorage.getItem(`telecareplus-read-alerts-${patientId}`)) || []; } 
    catch { return []; }
  });

  const load = async () => {
    if (!patientId) {
      setAlerts([]);
      setError("Unable to load notifications.");
      setLoading(false);
      return;
    }
    setLoading(true);
    try {
      const data = await fetchPatientAlerts(patientId);
      setAlerts(Array.isArray(data) ? data : []);
      setError("");
    } catch (err) {
      setError(getApiErrorMessage(err, "Unable to load notifications."));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, [patientId]);

  useEffect(() => {
    requestBrowserNotificationPermission();
  }, []);

  useEffect(() => {
    getPushStatus()
      .then((status) => {
        setPushState({ loading: false, supported: status.supported, subscribed: status.subscribed, configured: status.configured, message: "" });
      })
      .catch(() => {
        setPushState({ loading: false, supported: false, subscribed: false, configured: false, message: "" });
      });
  }, []);

  useEffect(() => {
    if (!patientId) return () => {};
    const unsubscribe = subscribeToPatientAlertStream(
      patientId,
      (alert) => {
        setAlerts((current) => [alert, ...current.filter((item) => item.id !== alert.id)]);
        setError("");
        if (!pushState.subscribed) {
          notifyBrowser("Notification Center", translateDisplayText(language, alert.message));
        }
      },
      () => {}
    );
    return unsubscribe;
  }, [language, patientId, pushState.subscribed]);

  const handlePushToggle = async () => {
    setPushState((current) => ({ ...current, loading: true, message: "" }));
    try {
      if (pushState.subscribed) {
        await disableBackgroundAlerts();
        setPushState((current) => ({ ...current, loading: false, subscribed: false, message: "Background alerts disabled" }));
      } else {
        await enableBackgroundAlerts();
        setPushState((current) => ({ ...current, loading: false, subscribed: true, supported: true, configured: true, message: "Background alerts enabled" }));
      }
    } catch (err) {
      setPushState((current) => ({ ...current, loading: false, message: getApiErrorMessage(err, "Unable to update background alerts") }));
    }
  };

  const toggleReadStatus = (id) => {
    let nextReadIds;
    if (readAlertIds.includes(id)) {
      nextReadIds = readAlertIds.filter(x => x !== id);
    } else {
      nextReadIds = [...readAlertIds, id];
    }
    setReadAlertIds(nextReadIds);
    try { localStorage.setItem(`telecareplus-read-alerts-${patientId}`, JSON.stringify(nextReadIds)); } catch {}
  };

  const markAllAsRead = () => {
    const allIds = alerts.map(a => a.id);
    const nextReadIds = [...new Set([...readAlertIds, ...allIds])];
    setReadAlertIds(nextReadIds);
    try { localStorage.setItem(`telecareplus-read-alerts-${patientId}`, JSON.stringify(nextReadIds)); } catch {}
  };

  const filteredAlerts = useMemo(() => {
    if (filter === "Unread") return alerts.filter(a => !readAlertIds.includes(a.id));
    return alerts;
  }, [alerts, filter, readAlertIds]);

  const unreadCount = alerts.filter(a => !readAlertIds.includes(a.id)).length;

  const handleLogout = () => {
    logout();
    navigate(buildLoginRedirect(""), { replace: true });
  };

  return (
    <div className="min-h-screen bg-canvas text-ink font-sans flex flex-col lg:flex-row">
      <PatientSidebar />
      
      <main className="flex-1 p-6 lg:p-10 min-w-0" role="main">
        {/* Topbar */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4 animate-fadeSlideUp">
          <div>
            <h1 className="font-display text-3xl font-medium mb-2">Notification Center</h1>
            <p className="text-ink-muted text-sm mb-3">Review and manage your critical health alerts.</p>
            <div className="flex gap-2 items-center mt-3">
              <span className="inline-flex items-center gap-1.5 text-xs px-2.5 py-1 rounded-full bg-white/5 border border-white/10 text-ink-muted">
                <Bell size={12} className="text-primary" />Alerts
              </span>
              <div className="inline-flex items-center gap-2 text-xs text-ink-muted bg-white/5 border border-white/10 px-3 py-1.5 rounded-full">
                <User size={14} />
                Signed in as {auth?.fullName || "Anita Patient"}
              </div>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <LanguageSwitcher hideLabel />
            <button 
              onClick={handleLogout} 
              aria-label="Log out"
              className="inline-flex items-center gap-2 px-4 py-2 bg-transparent text-ink-muted border border-white/10 rounded-element text-sm font-medium hover:bg-white/5 hover:text-ink transition-colors"
            >
              <LogOut size={16} />Logout
            </button>
          </div>
        </div>

        <div className="max-w-4xl animate-fadeSlideUp" style={{animationDelay: '0.1s'}}>
          
          {/* Preferences */}
          <div className="mb-12">
            <div className="flex items-center gap-4 mb-6">
               <h3 className="font-display text-xl font-medium">Preferences</h3>
               <div className="flex-1 h-px bg-white/10"></div>
            </div>
            
            <div className="card-premium !bg-surface flex flex-col sm:flex-row sm:items-center justify-between gap-6">
              <div>
                <h4 className="text-base font-semibold text-ink mb-1">Background Notifications</h4>
                <p className="text-sm text-ink-muted leading-relaxed">Receive OS-level notifications even when the app is closed.</p>
                
                {!pushState.supported && <p className="text-sm font-medium text-alert mt-3 bg-alert/5 border border-alert/20 px-3 py-1.5 rounded inline-block">Your browser does not support background push notifications.</p>}
                {pushState.supported && !pushState.configured && <p className="text-sm font-medium text-alert mt-3 bg-alert/5 border border-alert/20 px-3 py-1.5 rounded inline-block">Push notifications are currently unavailable in your region.</p>}
                {pushState.message && <p className="text-sm font-medium text-primary mt-3 bg-primary/10 border border-primary/20 px-3 py-1.5 rounded inline-block animate-fadeIn">{pushState.message}</p>}
              </div>
              
              <button 
                onClick={handlePushToggle}
                disabled={pushState.loading || !pushState.supported || !pushState.configured}
                className={`px-5 py-2.5 rounded-full text-sm font-semibold transition-all shrink-0 ${pushState.subscribed ? 'bg-primary text-canvas shadow-[0_0_15px_rgba(20,184,166,0.3)]' : 'bg-white/5 border border-white/10 text-ink hover:bg-white/10'} disabled:opacity-50 disabled:cursor-not-allowed`}
              >
                {pushState.loading ? "Checking..." : pushState.subscribed ? "Enabled" : "Enable"}
              </button>
            </div>
          </div>

          {/* Inbox */}
          <div>
            <div className="flex flex-col sm:flex-row sm:items-center justify-between mb-8 gap-4">
               <div className="flex items-center gap-4">
                 <h3 className="font-display text-xl font-medium">Inbox</h3>
                 {unreadCount > 0 && <span className="text-xs font-bold bg-alert text-white px-2.5 py-1 rounded-full animate-pulse-soft shadow-[0_0_10px_rgba(239,68,68,0.4)]">{unreadCount} Unread</span>}
               </div>
               
               <div className="flex flex-col sm:flex-row sm:items-center gap-4">
                 <div className="flex gap-2 overflow-x-auto pb-1 scrollbar-hide">
                   <button className={`px-4 py-1.5 rounded-full text-xs font-medium transition-colors border whitespace-nowrap ${filter === 'All' ? 'bg-primary text-canvas border-primary' : 'bg-transparent text-ink-muted border-white/10 hover:text-ink hover:bg-white/5'}`} onClick={() => setFilter("All")}>All</button>
                   <button className={`px-4 py-1.5 rounded-full text-xs font-medium transition-colors border whitespace-nowrap ${filter === 'Unread' ? 'bg-primary text-canvas border-primary' : 'bg-transparent text-ink-muted border-white/10 hover:text-ink hover:bg-white/5'}`} onClick={() => setFilter("Unread")}>Unread</button>
                 </div>
                 {unreadCount > 0 && (
                   <button onClick={markAllAsRead} className="text-sm text-primary hover:text-primary-light font-medium transition-colors whitespace-nowrap">Mark all as read</button>
                 )}
               </div>
            </div>

            {loading ? (
              <div className="flex flex-col gap-4">
                {[1,2,3].map(i => <div key={i} className="card-premium h-24 animate-pulse bg-white/5"></div>)}
              </div>
            ) : error ? (
              <div className="flex flex-col items-center justify-center p-12 text-center bg-alert/5 border border-alert/20 rounded-xl">
                <ShieldAlert size={32} className="text-alert mb-4" />
                <h3 className="font-display text-lg mb-2">Unable to load alerts</h3>
                <p className="text-sm text-ink-muted mb-6">{error}</p>
                <button className="px-4 py-2 border border-white/20 rounded-element text-sm font-medium hover:bg-white/5 transition-colors flex items-center gap-2" onClick={load}><RefreshCw size={16} /> Retry</button>
              </div>
            ) : alerts.length === 0 ? (
              <div className="flex flex-col items-center justify-center p-16 text-center border border-white/5 rounded-xl border-dashed min-h-[300px]">
                <Bell size={48} className="text-ink-muted/30 mb-4" />
                <h3 className="font-display text-lg mb-2">No Active Alerts</h3>
                <p className="text-sm text-ink-muted max-w-[280px]">You're all caught up. Active clinical alerts will appear here when detected.</p>
              </div>
            ) : filteredAlerts.length === 0 ? (
              <div className="flex flex-col items-center justify-center p-16 text-center border border-white/5 rounded-xl border-dashed min-h-[250px]">
                <Layers size={48} className="text-ink-muted/30 mb-4" />
                <h3 className="font-display text-lg mb-2">No matching alerts</h3>
                <p className="text-sm text-ink-muted">There are no alerts matching the '{filter}' filter.</p>
              </div>
            ) : (
              <div className="flex flex-col gap-4">
                {filteredAlerts.map(alert => {
                  const isRead = readAlertIds.includes(alert.id);
                  return (
                    <div key={alert.id} className={`card-premium !bg-surface transition-all ${isRead ? 'opacity-60 grayscale-[0.2]' : 'hover:border-white/20'} ${!isRead && alert.severity === 'CRITICAL' ? 'border-alert/50 shadow-[0_0_15px_rgba(239,68,68,0.15)]' : ''}`}>
                      <div className="flex flex-col sm:flex-row sm:items-start justify-between gap-4">
                        <div className="flex-1">
                          <div className="flex items-center gap-3 mb-3">
                            <Badge value={alert.severity} />
                            {!isRead && <span className="w-2 h-2 rounded-full bg-alert shadow-[0_0_8px_rgba(239,68,68,0.8)]"></span>}
                          </div>
                          <p className="text-[15px] text-ink/90 leading-relaxed mb-3">{translateDisplayText(language, alert.message)}</p>
                          <p className="text-xs font-medium text-ink-muted">{new Date(alert.createdAt).toLocaleString(undefined, { weekday: 'short', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' })}</p>
                        </div>
                        
                        <button 
                          onClick={() => toggleReadStatus(alert.id)}
                          className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-xs font-semibold transition-colors border shrink-0 ${isRead ? 'bg-white/5 text-ink-muted border-transparent hover:bg-white/10 hover:text-ink' : 'bg-primary/10 text-primary border-primary/20 hover:bg-primary/20'}`}
                        >
                          <Check size={14} /> {isRead ? "Mark Unread" : "Mark Read"}
                        </button>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>

        </div>
      </main>
    </div>
  );
}

import { useState, useEffect, useMemo } from "react";
import { useAuth } from "../context/AuthContext";
import { useNavigate, Link } from "react-router-dom";
import { buildLoginRedirect } from "../utils/authSession";
import { useLanguage } from "../context/LanguageContext";
import {
  Stethoscope, User, LogOut, Clock, Calendar, CheckCircle2, AlertTriangle, Plus, CalendarDays
} from "lucide-react";
import PatientSidebar from "../components/PatientSidebar";
import LanguageSwitcher from "../components/LanguageSwitcher";
import ConsultationPrepPanel from "../components/patient/ConsultationPrepPanel";
import { fetchPatientAppointments } from "../services/telecareService";

function toTitleCase(str) {
  if (!str) return "";
  return str.toLowerCase().replace(/\b\w/g, s => s.toUpperCase());
}

export default function PatientAppointmentsPage() {
  const { auth, logout } = useAuth();
  const navigate = useNavigate();
  const { language } = useLanguage() || { language: "en" };

  const [isLoading, setIsLoading] = useState(true);
  const [filter, setFilter] = useState("upcoming"); // upcoming, requested, past
  const [appointments, setAppointments] = useState([]);

  useEffect(() => {
    let active = true;
    setIsLoading(true);
    fetchPatientAppointments(auth.profileId)
      .then(data => {
        if (!active) return;
        const formatted = (Array.isArray(data) ? data : []).map(appt => {
          let filterSet = "upcoming";
          const statusLower = (appt.status || "").toLowerCase();
          if (statusLower === 'completed' || statusLower === 'cancelled') {
             filterSet = 'past';
          } else if (statusLower === 'requested' || statusLower === 'pending') {
             filterSet = 'requested';
          }
          
          const dt = new Date(appt.appointmentDateTime);
          
          return {
            ...appt,
            filterSet,
            doctor: appt.doctorName || "Doctor",
            avatar: (appt.doctorName ? appt.doctorName.replace("Dr. ", "") : "Dr").substring(0, 2).toUpperCase(),
            date: dt.toLocaleDateString([], { month: "short", day: "numeric", year: "numeric" }),
            time: dt.toLocaleTimeString([], { hour: '2-digit', minute:'2-digit' }),
            reason: appt.concernSummary || "No concern summary provided.",
            actions: filterSet === 'past' ? [{ label: "View details", style: "outline" }] : [{ label: "Reschedule", style: "outline" }, { label: "Join visit", style: "primary" }],
            isEmergency: appt.triageLevel === "EMERGENCY_AMBULANCE",
            badges: [{ label: toTitleCase(appt.status || "Unknown"), type: statusLower }]
          };
        });
        setAppointments(formatted);
      })
      .catch(err => console.error(err))
      .finally(() => {
        if (active) setIsLoading(false);
      });

    return () => { active = false; };
  }, [auth.profileId]);

  const handleLogout = () => {
    logout();
    navigate(buildLoginRedirect(""), { replace: true });
  };

  const filteredAppointments = useMemo(() => {
    return appointments.filter(appt => appt.filterSet === filter);
  }, [filter, appointments]);

  const renderBadgeIcon = (type) => {
    switch (type) {
      case "confirmed": return <CheckCircle2 size={12} />;
      case "requested": return <Clock size={12} />;
      case "booked": return <Calendar size={12} />;
      case "priority": return <AlertTriangle size={12} />;
      case "emergency": return <AlertTriangle size={12} />;
      default: return null;
    }
  };

  return (
    <div className="min-h-screen bg-canvas text-ink font-sans flex flex-col lg:flex-row">
      <PatientSidebar />

      <main className="flex-1 p-6 lg:p-10 min-w-0" role="main">
        {/* Topbar */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4 animate-fadeSlideUp">
          <div>
            <h1 className="font-display text-3xl font-medium mb-2">Appointments</h1>
            <p className="text-ink-muted text-sm mb-3">Review, manage, and book your upcoming and past visits.</p>
            <div className="flex gap-2 items-center mt-3">
              <span className="inline-flex items-center gap-1.5 text-xs px-2.5 py-1 rounded-full bg-white/5 border border-white/10 text-ink-muted">
                <Stethoscope size={12} className="text-primary" />Care
              </span>
              <div className="inline-flex items-center gap-2 text-xs text-ink-muted bg-white/5 border border-white/10 px-3 py-1.5 rounded-full">
                <User size={14} />
                Signed in as {auth?.fullName || "Anita Patient"}
              </div>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <LanguageSwitcher hideLabel />
            <button 
              onClick={handleLogout} 
              aria-label="Log out"
              className="inline-flex items-center gap-2 px-4 py-2 bg-transparent text-ink-muted border border-white/10 rounded-element text-sm font-medium hover:bg-white/5 hover:text-ink transition-colors"
            >
              <LogOut size={16} />Logout
            </button>
          </div>
        </div>

        <div className="flex justify-between items-center mb-6 animate-fadeSlideUp" style={{animationDelay: '0.1s'}}>
          <h2 className="font-display text-xl font-medium flex items-center gap-2"><CalendarDays size={20}/>Appointment history</h2>
          <Link to="/patient/booking" className="btn-primary inline-flex items-center gap-2 text-sm px-4 py-2"><Plus size={16}/>Book appointment</Link>
        </div>

        {/* CONSULTATION PREP SECTION */}
        {auth?.profileId && (
          <ConsultationPrepPanel patientId={auth.profileId} />
        )}

        {/* FILTER TABS */}
        <div className="flex gap-2 mb-6 border-b border-white/10 pb-4 overflow-x-auto animate-fadeSlideUp" style={{animationDelay: '0.1s'}} role="tablist" aria-label="Filter appointments">
          {['upcoming', 'requested', 'past'].map(f => (
            <button 
              key={f}
              className={`px-4 py-2 rounded-full text-sm font-medium transition-all shrink-0 capitalize ${filter === f ? 'bg-white/10 text-ink shadow-sm ring-1 ring-white/20' : 'text-ink-muted hover:text-ink hover:bg-white/5'}`}
              onClick={() => { setFilter(f); if(f==='upcoming') setIsLoading(true); }} // just dummy trigger to show loader for upcoming for now
              role="tab"
              aria-selected={filter === f}
            >
              {f} ({appointments.filter(a => a.filterSet === f).length})
            </button>
          ))}
        </div>

        <div className="flex flex-col gap-4 animate-fadeSlideUp" style={{animationDelay: '0.2s'}} role="region" aria-live="polite">
          
          {isLoading ? (
            // LOADING STATE
            <div className="flex flex-col gap-4">
              {[1, 2, 3].map(i => (
                <div key={i} className="flex gap-4 p-5 bg-white/5 border border-white/10 rounded-xl animate-pulse">
                  <div className="w-12 h-12 rounded-full bg-white/10 shrink-0"></div>
                  <div className="flex-1 space-y-3">
                    <div className="h-5 w-1/4 bg-white/10 rounded"></div>
                    <div className="h-4 w-1/5 bg-white/10 rounded"></div>
                    <div className="h-4 w-full bg-white/10 rounded mt-4"></div>
                    <div className="h-4 w-3/4 bg-white/10 rounded"></div>
                    <div className="flex gap-2 mt-4">
                      <div className="w-24 h-8 bg-white/10 rounded-element"></div>
                      <div className="w-24 h-8 bg-white/10 rounded-element"></div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          ) : filteredAppointments.length === 0 ? (
            // EMPTY STATE
            <div className="flex flex-col items-center justify-center p-16 text-center border border-white/5 rounded-xl border-dashed">
              <CalendarDays size={48} className="text-ink-muted/30 mb-4" />
              <h3 className="font-display text-lg mb-2">No appointments found</h3>
              <p className="text-sm text-ink-muted max-w-md mb-6">You don't have any {filter} appointments right now. Book a new visit to connect with your care team.</p>
              <Link to="/patient/booking" className="px-4 py-2 border border-white/20 rounded-element text-sm font-medium hover:bg-white/5 transition-colors inline-flex items-center gap-2"><Plus size={16}/>Book visit</Link>
            </div>
          ) : (
            // LOADED STATE
            filteredAppointments.map(appt => (
              <div key={appt.id} className={`flex flex-col sm:flex-row gap-5 p-5 rounded-xl border transition-colors ${appt.isEmergency ? 'bg-alert/5 border-alert/30' : 'bg-surface border-white/10 hover:border-white/20 hover:bg-white/5'}`}>
                <div className={`w-12 h-12 rounded-full flex items-center justify-center text-lg font-medium shrink-0 ${appt.isEmergency ? 'bg-alert text-canvas' : 'bg-white/10 text-ink'}`}>
                  {appt.isEmergency ? <AlertTriangle size={20} /> : appt.avatar}
                </div>
                <div className="flex-1 min-w-0 flex flex-col">
                  <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-3">
                    <div>
                      <h3 className="text-base font-medium">{appt.doctor}</h3>
                      <div className="text-sm text-ink-muted font-mono">{appt.date} ┬╖ {appt.time}</div>
                    </div>
                    <div className="flex flex-wrap gap-2">
                      {appt.badges.map((b, idx) => {
                        let badgeStyle = "bg-white/10 text-ink border-white/20";
                        if (b.type === 'confirmed' || b.type === 'booked') badgeStyle = "bg-primary/10 text-primary border-primary/20";
                        if (b.type === 'priority' || b.type === 'emergency') badgeStyle = "bg-alert/10 text-alert border-alert/20";
                        
                        return (
                          <span key={idx} className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-semibold border uppercase tracking-wider ${badgeStyle}`}>
                            {renderBadgeIcon(b.type)}
                            {b.label}
                          </span>
                        );
                      })}
                    </div>
                  </div>
                  <p className="text-sm text-ink-muted leading-relaxed mb-4 flex-1">
                    {appt.reason}
                  </p>
                  <div className="flex flex-wrap gap-2">
                    {appt.actions.map((act, idx) => (
                      <button key={idx} className={act.style === 'primary' ? 'btn-primary text-sm py-2 px-4' : 'px-4 py-2 border border-white/20 rounded-element text-sm font-medium hover:bg-white/5 transition-colors'}>
                        {act.label}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            ))
          )}

        </div>
      </main>
    </div>
  );
}

import { useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { createAppointment, fetchTriageHistory, fetchDoctors } from "../services/telecareService";
import { getApiErrorMessage } from "../utils/apiError";
import { runWithRequestTimeout } from "../utils/requestLifecycle";
import { buildLoginRedirect } from "../utils/authSession";
import { getDoctorPortrait } from "../assets/doctorPortraits";
import {
  Stethoscope, User, LogOut, CheckCircle2, AlertTriangle,
  Clock3, Star, User2, RefreshCw, Search, FileText, IndianRupee,
  CalendarDays
} from "lucide-react";
import PatientSidebar from "../components/PatientSidebar";
import LanguageSwitcher from "../components/LanguageSwitcher";
import { DatePicker } from "../components/ui/DatePicker";
import { isSameDay } from "date-fns";

function buildSlotsForDate(date) {
  if (!date) return [];
  const hours = [9, 10, 11, 14, 15, 16];
  const now = new Date();
  
  const daySlots = [];
  hours.forEach((hour) => {
    const d = new Date(date);
    d.setHours(hour, 0, 0, 0);
    if (d > now || !isSameDay(d, now)) {
      daySlots.push({
        value: d.toISOString().slice(0, 19),
        label: d.toLocaleString([], { hour: "numeric", minute: "2-digit" }).toLowerCase()
      });
      const dHalf = new Date(date);
      dHalf.setHours(hour, 30, 0, 0);
      if (dHalf > now || !isSameDay(dHalf, now)) {
        daySlots.push({
          value: dHalf.toISOString().slice(0, 19),
          label: dHalf.toLocaleString([], { hour: "numeric", minute: "2-digit" }).toLowerCase()
        });
      }
    }
  });
  return daySlots;
}

export default function PatientBookingPage() {
  const { auth, logout } = useAuth();
  const navigate = useNavigate();
  const patientId = auth?.profileId;

  const [doctors, setDoctors] = useState([]);
  const [triageHistory, setTriageHistory] = useState([]);
  const [loadingDoctors, setLoadingDoctors] = useState(true);
  const [loadingTriage, setLoadingTriage] = useState(true);
  const [doctorError, setDoctorError] = useState("");
  
  const [query, setQuery] = useState("");
  const [filter, setFilter] = useState("All");
  
  const [selectedDoctor, setSelectedDoctor] = useState(null);
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [selectedSlot, setSelectedSlot] = useState(null);
  const [mode, setMode] = useState("TELECONSULTATION");
  const [concernSummary, setConcernSummary] = useState("");
  
  const [booking, setBooking] = useState(false);
  const [bookingSuccess, setBookingSuccess] = useState(false);
  const [bookingError, setBookingError] = useState("");

  const availableSlots = useMemo(() => buildSlotsForDate(selectedDate), [selectedDate]);
  const latestTriage = triageHistory[0] || null;

  useEffect(() => {
    let active = true;
    setLoadingDoctors(true);
    setDoctorError("");

    fetchDoctors()
      .then(data => {
        if (!active) return;
        setDoctors(data);
        setSelectedDoctor(data[0]);
      })
      .catch(err => {
        if (!active) return;
        setDoctorError("Failed to load doctors.");
      })
      .finally(() => {
        if (active) setLoadingDoctors(false);
      });

    return () => { active = false; };
  }, []);

  useEffect(() => {
    if (!patientId) {
      setLoadingTriage(false);
      return;
    }
    const controller = new AbortController();
    let active = true;
    setLoadingTriage(true);

    runWithRequestTimeout((signal) => fetchTriageHistory(patientId, { signal }), { signal: controller.signal })
      .then((data) => {
        if (!active) return;
        const items = Array.isArray(data) ? [...data] : [];
        items.sort((a, b) => new Date(b.assessedAt || 0) - new Date(a.assessedAt || 0));
        setTriageHistory(items);
      })
      .catch((err) => {
        if (active) setTriageHistory([]);
      })
      .finally(() => {
        if (active) setLoadingTriage(false);
      });

    return () => {
      active = false;
      controller.abort();
    };
  }, [patientId]);

  const handleLogout = () => {
    logout();
    navigate(buildLoginRedirect(""), { replace: true });
  };

  const filteredDoctors = useMemo(() => {
    let filtered = doctors;
    const q = query.trim().toLowerCase();
    
    if (q) {
      filtered = filtered.filter(d => 
        [d.fullName, d.specialization].filter(Boolean).some(val => String(val).toLowerCase().includes(q))
      );
    }
    
    if (filter === "Available Today") {
      filtered = filtered.filter(d => String(d.availabilitySummary).toLowerCase().includes("today"));
    } else if (filter === "Price: Low to High") {
      filtered = [...filtered].sort((a, b) => (a.consultationFee || 0) - (b.consultationFee || 0));
    } else if (filter === "Top Rated") {
      filtered = [...filtered].sort((a, b) => b.id - a.id);
    }
    
    return filtered;
  }, [doctors, query, filter]);

  const confirmBooking = async () => {
    if (!selectedDoctor || !selectedSlot) return;
    
    setBooking(true);
    setBookingError("");

    try {
      await createAppointment({
        patientId,
        doctorId: Number(selectedDoctor.id),
        triageAssessmentId: latestTriage ? Number(latestTriage.id) : null,
        appointmentDateTime: selectedSlot.value,
        mode,
        concernSummary
      });

      setBookingSuccess(true);
      setTimeout(() => {
        navigate("/patient/appointments");
      }, 1500);

    } catch (err) {
      setBookingError(getApiErrorMessage(err, "Unable to confirm appointment."));
      setBooking(false);
    }
  };

  return (
    <div className="min-h-screen bg-canvas text-ink font-sans flex flex-col lg:flex-row">
