          <div>
            <h1 className="font-display text-3xl font-medium mb-2">Book your next consultation</h1>
            <p className="text-ink-muted text-sm mb-3">Choose a trusted specialist and pick the earliest suitable slot.</p>
            <div className="flex gap-2 items-center mt-3">
              <span className="inline-flex items-center gap-1.5 text-xs px-2.5 py-1 rounded-full bg-white/5 border border-white/10 text-ink-muted">
