                        </button>
                      );
                    }) : (
                      <div className="col-span-full text-sm text-ink-muted/50 py-4 text-center italic">No slots available on this date.</div>
                    )}
                  </div>
                </div>
              )}

              <div className="mb-6">
                <label className="block text-sm font-medium text-ink-muted mb-2" htmlFor="mode">Consultation mode</label>
                <select id="mode" className="w-full bg-white/5 border border-white/10 rounded-element p-3 text-ink focus:outline-none focus:ring-2 focus:ring-primary/50" value={mode} onChange={(e) => setMode(e.target.value)}>
                  <option value="TELECONSULTATION" className="bg-surface">Teleconsultation</option>
                  <option value="IN_PERSON" className="bg-surface">In-person</option>
                  <option value="FOLLOW_UP" className="bg-surface">Follow-up</option>
