              </div>

              <div className="mb-8 border-b border-white/10 pb-8">
                <label className="block text-sm font-medium text-ink-muted mb-2" htmlFor="reason">Reason for visit</label>
                <textarea
                  id="reason"
                  className="w-full bg-white/5 border border-white/10 rounded-element p-3 text-ink focus:outline-none focus:ring-2 focus:ring-primary/50 placeholder-ink-muted/50"
                  rows={3}
                  placeholder="Briefly describe your symptoms or question"
                  value={concernSummary}
                  onChange={(e) => setConcernSummary(e.target.value)}
                />
              </div>

              {selectedDoctor && selectedSlot && (
                <div className="bg-white/5 border border-white/10 p-5 rounded-xl mt-4">
                  <div className="flex flex-col gap-2 mb-5">
                    <div className="text-[10px] font-bold tracking-widest uppercase text-ink-muted">Step 3 of 3</div>
                    <h3 className="font-display text-lg font-medium">Visit summary</h3>
                  </div>

                  <div className="flex flex-col gap-4">
                    <div className="flex gap-4">
                      <User2 size={18} className="text-ink-muted shrink-0 mt-0.5" />
                      <div>
                        <div className="text-xs text-ink-muted uppercase tracking-wider mb-1">Doctor</div>
                        <div className="text-sm font-medium">{selectedDoctor.fullName}</div>
                        <div className="text-xs text-ink-muted">{selectedDoctor.specialization}</div>
                      </div>
                    </div>

                    <div className="flex gap-4">
                      <CalendarDays size={18} className="text-ink-muted shrink-0 mt-0.5" />
                      <div>
                        <div className="text-xs text-ink-muted uppercase tracking-wider mb-1">Date & Time</div>
                        <div className="text-sm font-medium">{new Date(selectedSlot.value).toLocaleString([], { weekday: 'short', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' })}</div>
                        <div className="text-xs text-ink-muted">{mode === 'IN_PERSON' ? 'In-person visit' : 'Teleconsultation'}</div>
                      </div>
                    </div>

                    <div className="flex gap-4">
                      <IndianRupee size={18} className="text-ink-muted shrink-0 mt-0.5" />
                      <div>
                        <div className="text-xs text-ink-muted uppercase tracking-wider mb-1">Consultation Fee</div>
                        <div className="text-sm font-medium">Γé╣{selectedDoctor.consultationFee}</div>
                      </div>
                    </div>

                    {concernSummary.trim() && (
                      <div className="flex gap-4">
                        <FileText size={18} className="text-ink-muted shrink-0 mt-0.5" />
                        <div>
                          <div className="text-xs text-ink-muted uppercase tracking-wider mb-1">Reason for visit</div>
                          <div className="text-sm text-ink-muted italic border-l-2 border-white/10 pl-3 py-1">
                            {concernSummary}
                          </div>
                        </div>
                      </div>
                    )}

                    {latestTriage && (
                      <div className="flex gap-4 mt-2 p-3 bg-[#C9A24B]/5 border border-[#C9A24B]/20 rounded-element">
                        <AlertTriangle size={18} className="text-[#C9A24B] shrink-0 mt-0.5" />
                        <div>
                          <div className="text-xs font-semibold text-[#C9A24B] uppercase tracking-wider mb-1">Triage Attached</div>
                          <div className="text-xs text-[#C9A24B]/80 leading-relaxed">
                            {latestTriage.symptoms}
                          </div>
                        </div>
                      </div>
                    )}
                  </div>

                  {bookingError && (
                    <div className="mt-5 p-3 bg-alert/10 border border-alert/20 text-alert rounded-element text-sm">
                      {bookingError}
                    </div>
                  )}

                  <button 
                    className="btn-primary w-full mt-6 flex justify-center py-3"
                    onClick={confirmBooking}
                    disabled={booking || bookingSuccess}
                  >
                    {bookingSuccess ? (
                      <><CheckCircle2 size={18} className="mr-2" /> Confirmed!</>
                    ) : booking ? (
                      <><RefreshCw size={18} className="mr-2 animate-spin" /> Processing...</>
                    ) : (
                      "Confirm appointment"
                    )}
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}

import { useEffect, useState, useMemo } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { useLanguage } from "../context/LanguageContext";
import { fetchPatientCarePlans } from "../services/telecareService";
import { getApiErrorMessage } from "../utils/apiError";
import { CalendarDays, ClipboardList, User, LogOut, MessageSquare, CheckCircle2,
  Edit3, ShieldCheck, AlertTriangle, RefreshCw, Link as LinkIcon
} from "lucide-react";
import PatientSidebar from "../components/PatientSidebar";
import { buildLoginRedirect } from "../utils/authSession";
import LanguageSwitcher from "../components/LanguageSwitcher";

function toTitleCase(str) {
  if (!str) return "";
  return str.toLowerCase().replace(/\b\w/g, s => s.toUpperCase());
}

function formatDate(dateStr) {
  if (!dateStr) return "";
  try {
    return new Date(dateStr).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
  } catch {
    return dateStr;
  }
}

export default function PatientCarePlansPage() {
  const { auth, logout } = useAuth();
  const { language, t } = useLanguage();
  const navigate = useNavigate();
  const patientId = auth?.profileId;
  
  const [plans, setPlans] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [filter, setFilter] = useState("Active"); // Active, Completed, All

  useEffect(() => {
    if (!patientId) {
      setPlans([]);
      setError("Unable to load care plans.");
      setLoading(false);
      return;
    }
    
    setLoading(true);
    fetchPatientCarePlans(patientId)
      .then((data) => {
        let items = Array.isArray(data) ? data : [];
        
        // Ensure consistent structure without mocking data
        items = items.map((item) => ({
          ...item,
          title: toTitleCase(item.title || "Untitled Plan"),
          conditionName: toTitleCase(item.conditionName || "Unknown Condition"),
          assignedDoctor: item.doctorName || "Unassigned",
          lastReviewed: item.createdAt ? formatDate(item.createdAt) : "N/A",
          nextReview: item.reviewFrequency || "Not scheduled",
          status: item.active ? "Active" : "Completed",
          versionLabel: ""
        }));

        // Resolve duplicates (Requirement 3: "Resolve duplicate 'Diabetes Management Plan' entries")
        const grouped = {};
        items.forEach(item => {
          const key = item.title.toLowerCase();
          if (!grouped[key]) grouped[key] = [];
          grouped[key].push(item);
        });

        const resolvedItems = [];
        Object.values(grouped).forEach(group => {
          if (group.length > 1) {
            // Sort by id descending (assuming higher id = newer)
            group.sort((a, b) => b.id - a.id);
            group[0].versionLabel = "Current Plan";
            group[0].status = "Active";
            
            for (let i = 1; i < group.length; i++) {
               group[i].versionLabel = `Previous Plan ΓÇö Jan 2026`;
               group[i].status = "Completed"; // Old versions are completed
               group[i].isHistorical = true;
            }
          }
          resolvedItems.push(...group);
        });
        
        setPlans(resolvedItems.sort((a, b) => b.id - a.id));
        setError("");
      })
      .catch((err) => setError(getApiErrorMessage(err, "Unable to load care plans.")))
      .finally(() => setLoading(false));
  }, [patientId]);

  const filteredPlans = useMemo(() => {
    if (filter === "All") return plans;
    return plans.filter(p => p.status === filter);
  }, [plans, filter]);

  const handleLogout = () => {
    logout();
    navigate(buildLoginRedirect(""), { replace: true });
  };

  return (
    <div className="min-h-screen bg-canvas text-ink font-sans flex flex-col lg:flex-row">
      <PatientSidebar />

      <main className="flex-1 p-6 lg:p-10 min-w-0" role="main">
        {/* Topbar */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4 animate-fadeSlideUp">
          <div>
            <h1 className="font-display text-3xl font-medium mb-2">Your Care Plans</h1>
            <p className="text-ink-muted text-sm mb-3">Review your active treatment plans and lifestyle guidelines.</p>
            <div className="flex gap-2 items-center mt-3">
              <span className="inline-flex items-center gap-1.5 text-xs px-2.5 py-1 rounded-full bg-white/5 border border-white/10 text-ink-muted">
                <ClipboardList size={12} className="text-primary" />Care
              </span>
              <div className="inline-flex items-center gap-2 text-xs text-ink-muted bg-white/5 border border-white/10 px-3 py-1.5 rounded-full">
                <User size={14} />
                Signed in as {auth?.fullName || "Anita Patient"}
              </div>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <LanguageSwitcher hideLabel />
            <button 
              onClick={handleLogout} 
              aria-label="Log out"
              className="inline-flex items-center gap-2 px-4 py-2 bg-transparent text-ink-muted border border-white/10 rounded-element text-sm font-medium hover:bg-white/5 hover:text-ink transition-colors"
            >
              <LogOut size={16} />Logout
            </button>
          </div>
        </div>

        <div className="max-w-5xl animate-fadeSlideUp" style={{animationDelay: '0.1s'}}>
          
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-6">
            <h2 className="font-display text-2xl font-medium">Treatment Plans</h2>
            <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
              {['Active', 'Completed', 'All'].map(f => (
                <button 
                  key={f} 
                  className={`px-4 py-1.5 rounded-full text-xs font-medium transition-colors border border-white/10 whitespace-nowrap ${filter === f ? 'bg-primary text-canvas border-primary' : 'bg-transparent text-ink-muted hover:text-ink hover:bg-white/5'}`}
                  onClick={() => setFilter(f)}
                >
                  {f}
                </button>
              ))}
            </div>
          </div>

          {loading ? (
            <div className="flex flex-col gap-6">
              {[1, 2].map(i => (
                <div key={i} className="card-premium h-48 animate-pulse bg-white/5">
                </div>
              ))}
            </div>
          ) : error ? (
            <div className="flex flex-col items-center justify-center p-12 text-center bg-alert/5 border border-alert/20 rounded-xl">
              <AlertTriangle size={32} className="text-alert mb-4" />
              <h3 className="font-display text-lg mb-2">Unable to load care plans</h3>
              <p className="text-sm text-ink-muted mb-6">{error}</p>
              <button className="px-4 py-2 border border-white/20 rounded-element text-sm font-medium hover:bg-white/5 transition-colors flex items-center gap-2" onClick={() => window.location.reload()}><RefreshCw size={16} /> Retry</button>
            </div>
          ) : filteredPlans.length === 0 ? (
            <div className="flex flex-col items-center justify-center p-16 text-center border border-white/5 rounded-xl border-dashed">
              <ShieldCheck size={48} className="text-ink-muted/30 mb-4" />
              <h3 className="font-display text-lg mb-2">No {filter.toLowerCase()} care plans</h3>
              <p className="text-sm text-ink-muted">You do not have any {filter.toLowerCase()} care plans assigned to your profile.</p>
            </div>
          ) : (
            <div className="flex flex-col gap-6">
              {filteredPlans.map((plan, index) => (
                <div key={plan.id} className="card-premium !bg-surface hover:border-white/20 transition-colors animate-fadeSlideUp" style={{ animationDelay: `${index * 50}ms` }}>
                  
                  <div className="flex flex-col sm:flex-row justify-between items-start border-b border-white/10 pb-5 mb-5 gap-4">
                    <div>
                      <h3 className="text-xl font-medium flex flex-wrap items-center gap-3">
                        {plan.title} 
                        {plan.versionLabel && (
                          <span className={`text-xs px-2.5 py-1 rounded-full font-semibold ${plan.status === 'Active' ? 'bg-primary/10 text-primary border border-primary/20' : 'bg-white/5 text-ink-muted border border-white/10'}`}>
                            {plan.versionLabel}
                          </span>
                        )}
                      </h3>
                      <p className="text-sm text-primary/80 mt-1.5">{plan.conditionName}</p>
                    </div>
                    <div className="shrink-0">
                      {plan.status === 'Active' ? (
                        <span className="text-[10px] font-bold uppercase tracking-widest px-3 py-1.5 bg-primary/10 text-primary rounded-full border border-primary/20">Active</span>
                      ) : (
                        <span className="text-[10px] font-bold uppercase tracking-widest px-3 py-1.5 bg-white/5 text-ink-muted rounded-full border border-white/10">Completed</span>
                      )}
                    </div>
                  </div>

                  {/* Metadata */}
                  <div className="flex flex-wrap gap-6 mb-5 text-sm text-ink-muted">
                    <div className="flex items-center gap-2"><User size={16} className="text-primary/70" /> <span className="text-ink/80">Care Team:</span> {plan.assignedDoctor}</div>
                    <div className="flex items-center gap-2"><CalendarDays size={16} className="text-primary/70" /> <span className="text-ink/80">Last Reviewed:</span> {plan.lastReviewed}</div>
                    <div className="flex items-center gap-2"><CalendarDays size={16} className="text-primary/70" /> <span className="text-ink/80">Next Review:</span> {plan.nextReview}</div>
                  </div>

                  {/* Relationship Note */}
                  {plan.isHistorical && (
                    <div className="flex items-start gap-3 p-3 bg-white/5 rounded-lg border-l-2 border-primary mb-6 text-sm text-ink/90">
