                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {/* Goal */}
                    <div className="bg-white/5 border border-white/10 rounded-xl p-5">
                      <h4 className="text-sm font-semibold uppercase tracking-widest text-ink-muted mb-3 flex items-center gap-2">Goal</h4>
                      {plan.goals ? (
