                  <div className="flex items-center flex-wrap gap-3 mt-6 pt-5 border-t border-white/10">
                    {plan.status === 'Active' ? (
                      <>
                        <button className="px-4 py-2 bg-white/5 hover:bg-white/10 text-ink border border-white/10 rounded-element text-sm font-medium transition-colors flex items-center gap-2"><MessageSquare size={16}/> Message care team</button>
                        <button className="px-4 py-2 bg-white/5 hover:bg-white/10 text-ink border border-white/10 rounded-element text-sm font-medium transition-colors flex items-center gap-2"><CheckCircle2 size={16}/> Mark as reviewed</button>
