import { useEffect, useState, useMemo } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { useLanguage } from "../context/LanguageContext";
import { fetchPatientFamilyNetwork } from "../services/telecareService";
import { getApiErrorMessage } from "../utils/apiError";
import { translateDisplayText } from "../utils/i18n";
import PatientSidebar from "../components/PatientSidebar";
import { User, LogOut, Users, ShieldAlert, RefreshCw, Network, ClipboardList } from "lucide-react";
import { buildLoginRedirect } from "../utils/authSession";
import LanguageSwitcher from "../components/LanguageSwitcher";

export default function PatientFamilyNetworkPage() {
  const { auth, logout } = useAuth();
  const { language, t } = useLanguage();
  const navigate = useNavigate();
  const patientId = auth?.profileId;
  
  const [network, setNetwork] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const load = async () => {
    if (!patientId) {
      setNetwork(null);
      setError("Unable to load family network.");
      setLoading(false);
      return;
    }
    setLoading(true);
    try {
      const data = await fetchPatientFamilyNetwork(patientId);
      setNetwork(data);
      setError("");
    } catch (err) {
      setError(getApiErrorMessage(err, "Unable to load family network."));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, [patientId]);

  const filteredCaregivers = useMemo(() => {
    return network?.caregivers || [];
  }, [network?.caregivers]);

  const handleLogout = () => {
    logout();
    navigate(buildLoginRedirect(""), { replace: true });
  };

  return (
    <div className="min-h-screen bg-canvas text-ink font-sans flex flex-col lg:flex-row">
      <PatientSidebar />
      
      <main className="flex-1 p-6 lg:p-10 min-w-0" role="main">
        {/* Topbar */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4 animate-fadeSlideUp">
          <div>
            <h1 className="font-display text-3xl font-medium mb-2">Family Network</h1>
            <p className="text-ink-muted text-sm mb-3">Manage shared caregivers and coordination summaries.</p>
            <div className="flex gap-2 items-center mt-3">
              <span className="inline-flex items-center gap-1.5 text-xs px-2.5 py-1 rounded-full bg-white/5 border border-white/10 text-ink-muted">
                <Users size={12} className="text-primary" />Community
              </span>
              <div className="inline-flex items-center gap-2 text-xs text-ink-muted bg-white/5 border border-white/10 px-3 py-1.5 rounded-full">
                <User size={14} />
                Signed in as {auth?.fullName || "Anita Patient"}
              </div>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <LanguageSwitcher hideLabel />
            <button 
              onClick={handleLogout} 
              aria-label="Log out"
              className="inline-flex items-center gap-2 px-4 py-2 bg-transparent text-ink-muted border border-white/10 rounded-element text-sm font-medium hover:bg-white/5 hover:text-ink transition-colors"
            >
              <LogOut size={16} />Logout
            </button>
          </div>
        </div>

        <div className="max-w-5xl animate-fadeSlideUp" style={{animationDelay: '0.1s'}}>
          
          {loading ? (
            <div className="flex flex-col gap-6 mt-8">
              {[1, 2, 3].map(i => (
                <div key={i} className="card-premium h-32 animate-pulse bg-white/5"></div>
              ))}
            </div>
          ) : error ? (
            <div className="flex flex-col items-center justify-center p-12 text-center bg-alert/5 border border-alert/20 rounded-xl mt-8">
              <ShieldAlert size={32} className="text-alert mb-4" />
              <h3 className="font-display text-lg mb-2">Unable to load family network</h3>
              <p className="text-sm text-ink-muted mb-6">{error}</p>
              <button className="px-4 py-2 border border-white/20 rounded-element text-sm font-medium hover:bg-white/5 transition-colors flex items-center gap-2" onClick={load}><RefreshCw size={16} /> Retry</button>
            </div>
          ) : network && (
            <div className="space-y-10 mt-8">
              {/* Stats Row */}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="card-premium !bg-surface flex flex-col justify-center">
                  <p className="text-[10px] font-bold text-ink-muted uppercase tracking-widest mb-2">Patient</p>
                  <p className="text-2xl font-display font-medium text-ink truncate">{network.patientName}</p>
                </div>
                <div className="card-premium !bg-surface flex flex-col justify-center">
                  <p className="text-[10px] font-bold text-ink-muted uppercase tracking-widest mb-2">Shared Caregivers</p>
                  <p className="text-3xl font-display font-medium text-ink">{filteredCaregivers.length}</p>
                </div>
                <div className="card-premium !bg-surface flex flex-col justify-center">
                  <p className="text-[10px] font-bold text-ink-muted uppercase tracking-widest mb-2">Network Status</p>
                  <p className="text-2xl font-display font-medium text-ink">{network.multiCaregiverSupport ? "Shared Support" : "Single Support"}</p>
                </div>
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 items-start">
                
                {/* Shared Caregivers Column */}
                <div className="flex flex-col">
                  <div className="flex items-center gap-4 mb-6">
                     <h3 className="font-display text-xl font-medium">Shared Caregivers</h3>
                     <div className="flex-1 h-px bg-white/10"></div>
                  </div>
                  
                  {filteredCaregivers.length === 0 ? (
                    <div className="flex flex-col items-center justify-center p-16 text-center border border-white/5 rounded-xl border-dashed min-h-[250px]">
                      <Network size={48} className="text-ink-muted/30 mb-4" />
                      <h3 className="font-display text-lg mb-2">No Caregiver Network</h3>
                      <p className="text-sm text-ink-muted max-w-[250px] leading-relaxed">Caregivers will appear here once they are linked to your profile.</p>
                    </div>
                  ) : (
                    <div className="flex flex-col gap-4">
                      {filteredCaregivers.map(caregiver => (
                        <div key={caregiver.caregiverId} className="card-premium !bg-surface hover:border-white/20 transition-colors">
                          <div className="flex items-center gap-5">
                            <div className="w-14 h-14 rounded-full bg-primary/10 text-primary flex items-center justify-center text-xl font-medium shrink-0 border border-primary/20">
                              {caregiver.caregiverName?.charAt(0) || "C"}
                            </div>
                            <div className="min-w-0 flex-1">
                              <h4 className="text-lg font-medium text-ink truncate mb-1">{caregiver.caregiverName}</h4>
                              <p className="text-sm font-medium text-primary bg-primary/10 px-2.5 py-0.5 rounded w-fit mb-2">
                                {translateDisplayText(language, caregiver.relationshipLabel || "Caregiver")}
                              </p>
                              <p className="text-sm text-ink-muted font-mono">{caregiver.phone}</p>
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>

                {/* Coordination Summary Column */}
                <div className="flex flex-col">
                  <div className="flex items-center gap-4 mb-6">
                     <h3 className="font-display text-xl font-medium">Coordination Summary</h3>
                     <div className="flex-1 h-px bg-white/10"></div>
                  </div>
                  
                  {(!network.coordinationNote && !network.escalationAdvice) || (network.coordinationNote?.toLowerCase().includes("test") && network.escalationAdvice?.toLowerCase().includes("test")) ? (
                     <div className="flex flex-col items-center justify-center p-16 text-center border border-white/5 rounded-xl border-dashed min-h-[250px]">
                       <ClipboardList size={48} className="text-ink-muted/30 mb-4" />
                       <h3 className="font-display text-lg mb-2">No Active Coordination</h3>
                       <p className="text-sm text-ink-muted max-w-[280px] leading-relaxed mb-6">No coordination summaries or escalation advice have been set for your network yet.</p>
                       <button className="btn-primary py-2 px-4 text-sm flex items-center gap-2"><RefreshCw size={16}/> Request Update</button>
                     </div>
                  ) : (
                    <div className="flex flex-col gap-4">
                      {network.coordinationNote && !network.coordinationNote.toLowerCase().includes("test") && (
                        <div className="card-premium !bg-surface border-l-4 border-l-primary hover:border-white/20 transition-colors">
                          <h4 className="text-[10px] font-bold text-ink-muted uppercase tracking-widest mb-3">Care Note</h4>
                          <p className="text-sm leading-relaxed text-ink/90">{translateDisplayText(language, network.coordinationNote)}</p>
                        </div>
                      )}
                      {network.escalationAdvice && !network.escalationAdvice.toLowerCase().includes("test") && (
                        <div className="card-premium !bg-surface border-l-4 border-l-alert hover:border-white/20 transition-colors">
                          <h4 className="text-[10px] font-bold text-alert uppercase tracking-widest mb-3">Escalation Advice</h4>
                          <p className="text-sm leading-relaxed text-ink/90">{translateDisplayText(language, network.escalationAdvice)}</p>
                        </div>
                      )}
                    </div>
                  )}
                </div>

              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
}

import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import Badge from "../components/Badge";
import { useAuth } from "../context/AuthContext";
import { useLanguage } from "../context/LanguageContext";
import {
  fetchAdaptiveTriage,
  fetchCopilotRecommendations,
  fetchDeteriorationInsight,
  fetchFollowUpAutopilot
} from "../services/telecareService";
import { getApiErrorMessage } from "../utils/apiError";
import { translateDisplayText } from "../utils/i18n";
import PatientSidebar from "../components/PatientSidebar";
import { User, LogOut, Compass, TrendingDown, ClipboardList, AlertTriangle, RefreshCw, Layers, Zap, Bot, CalendarClock } from "lucide-react";
import { buildLoginRedirect } from "../utils/authSession";
import LanguageSwitcher from "../components/LanguageSwitcher";

export default function PatientFutureCarePage() {
  const { auth, logout } = useAuth();
  const navigate = useNavigate();
  const { language, t, translateUiText = (value) => translateDisplayText(language, value) } = useLanguage();
  const patientId = auth?.profileId;
  
  const [deterioration, setDeterioration] = useState(null);
  const [copilot, setCopilot] = useState(null);
  const [adaptive, setAdaptive] = useState(null);
  const [autopilot, setAutopilot] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const load = async () => {
    if (!patientId) {
      setDeterioration(null);
      setCopilot(null);
      setAdaptive(null);
      setAutopilot(null);
      setError("Unable to load Future Care guidance.");
      setLoading(false);
      return;
    }

    setLoading(true);
    try {
      const [deteriorationRes, copilotRes, adaptiveRes, autopilotRes] = await Promise.allSettled([
        fetchDeteriorationInsight(patientId),
        fetchCopilotRecommendations(patientId),
        fetchAdaptiveTriage(patientId),
        fetchFollowUpAutopilot(patientId)
      ]);

      const nextDeterioration = deteriorationRes.status === "fulfilled" ? deteriorationRes.value : null;
      const nextCopilot = copilotRes.status === "fulfilled" ? copilotRes.value : null;
      const nextAdaptive = adaptiveRes.status === "fulfilled" ? adaptiveRes.value : null;
      const nextAutopilot = autopilotRes.status === "fulfilled" ? autopilotRes.value : null;

      setDeterioration(nextDeterioration);
      setCopilot(nextCopilot);
      setAdaptive(nextAdaptive);
      setAutopilot(nextAutopilot);

      if (!nextDeterioration && !nextCopilot && !nextAdaptive && !nextAutopilot) {
        setError(getApiErrorMessage(deteriorationRes.reason || copilotRes.reason || adaptiveRes.reason || autopilotRes.reason, "Unable to load Future Care guidance."));
      } else {
        setError("");
      }
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, [patientId]);

  const handleLogout = () => {
    logout();
    navigate(buildLoginRedirect(""), { replace: true });
  };

  return (
    <div className="min-h-screen bg-canvas text-ink font-sans flex flex-col lg:flex-row">
      <PatientSidebar />
      
      <main className="flex-1 p-6 lg:p-10 min-w-0" role="main">
        {/* Topbar */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4 animate-fadeSlideUp">
          <div>
            <h1 className="font-display text-3xl font-medium mb-2">Future Care</h1>
            <p className="text-ink-muted text-sm mb-3">Predictive health insights and proactive follow-up plans.</p>
            <div className="flex gap-2 items-center mt-3">
              <span className="inline-flex items-center gap-1.5 text-xs px-2.5 py-1 rounded-full bg-white/5 border border-white/10 text-ink-muted">
                <Compass size={12} className="text-primary" />Care Planning
              </span>
              <div className="inline-flex items-center gap-2 text-xs text-ink-muted bg-white/5 border border-white/10 px-3 py-1.5 rounded-full">
                <User size={14} />
                Signed in as {auth?.fullName || "Anita Patient"}
              </div>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <LanguageSwitcher hideLabel />
            <button 
              onClick={handleLogout} 
              aria-label="Log out"
              className="inline-flex items-center gap-2 px-4 py-2 bg-transparent text-ink-muted border border-white/10 rounded-element text-sm font-medium hover:bg-white/5 hover:text-ink transition-colors"
            >
              <LogOut size={16} />Logout
            </button>
          </div>
        </div>

        <div className="max-w-5xl animate-fadeSlideUp" style={{animationDelay: '0.1s'}}>
          
          {loading ? (
            <div className="flex flex-col gap-8 mt-8">
              {[1,2,3].map(i => <div key={i} className="card-premium h-40 animate-pulse bg-white/5"></div>)}
            </div>
          ) : error ? (
            <div className="flex flex-col items-center justify-center p-12 text-center bg-alert/5 border border-alert/20 rounded-xl mt-8">
              <AlertTriangle size={32} className="text-alert mb-4" />
              <h3 className="font-display text-lg mb-2">Unable to load insights</h3>
              <p className="text-sm text-ink-muted mb-6">{error}</p>
              <button className="px-4 py-2 border border-white/20 rounded-element text-sm font-medium hover:bg-white/5 transition-colors flex items-center gap-2" onClick={load}><RefreshCw size={16} /> Retry</button>
            </div>
          ) : (
            <div className="space-y-10 mt-8">
              
              {/* Deterioration Overview */}
              <div className="flex flex-col">
                <div className="flex items-center gap-4 mb-6">
                   <h3 className="font-display text-xl font-medium">Deterioration Insights</h3>
                   <div className="flex-1 h-px bg-white/10"></div>
                </div>

                {deterioration ? (
                  <div className="flex flex-col gap-6">
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                      <div className="card-premium !bg-surface flex flex-col justify-center">
                        <p className="text-[10px] font-bold text-ink-muted uppercase tracking-widest mb-2">Risk Score</p>
                        <div className="flex items-baseline gap-1.5">
                          <p className="text-3xl font-display font-medium text-ink">{deterioration.predictedScore}</p>
                          <p className="text-sm font-medium text-ink-muted/50">/100</p>
                        </div>
                      </div>
                      <div className="card-premium !bg-surface flex flex-col justify-center">
                        <p className="text-[10px] font-bold text-ink-muted uppercase tracking-widest mb-3">Risk Profile</p>
                        <div><Badge value={deterioration.predictedRiskLevel} /></div>
                      </div>
                      <div className="card-premium !bg-surface flex flex-col justify-center">
                        <p className="text-[10px] font-bold text-ink-muted uppercase tracking-widest mb-2">Shared Caregivers</p>
                        <p className="text-3xl font-display font-medium text-ink">{deterioration.activeCaregiverCount}</p>
                      </div>
                      <div className="card-premium !bg-surface flex flex-col justify-center">
                        <p className="text-[10px] font-bold text-ink-muted uppercase tracking-widest mb-2">Abnormal Obs.</p>
                        <p className="text-3xl font-display font-medium text-ink">{deterioration.abnormalObservationCount}</p>
                      </div>
                    </div>
                    
                    {deterioration.summary && (
                      <div className="card-premium !bg-white/5 border-l-4 border-l-primary hover:border-white/20 transition-colors">
                        <p className="text-[15px] leading-relaxed text-ink/90">{deterioration.summary}</p>
                      </div>
                    )}

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      <div className="card-premium !bg-surface flex flex-col">
                        <h4 className="text-sm font-semibold uppercase tracking-widest text-ink-muted mb-4 flex items-center gap-2">
                          <TrendingDown size={18} className="text-primary" /> Contributing Factors
                        </h4>
                        {(deterioration.contributingFactors || []).length ? (
                          <div className="flex flex-col gap-2">
                            {(deterioration.contributingFactors || []).map((factor, idx) => (
                              <p key={idx} className="text-sm leading-relaxed text-ink/90 p-3 bg-white/5 rounded-lg border border-white/10">{translateDisplayText(language, factor)}</p>
                            ))}
                          </div>
                        ) : <p className="text-sm text-ink-muted italic">No contributing risk factors are available yet.</p>}
                      </div>
                      <div className="card-premium !bg-surface flex flex-col">
                        <h4 className="text-sm font-semibold uppercase tracking-widest text-ink-muted mb-4 flex items-center gap-2">
                          <ClipboardList size={18} className="text-primary" /> Recommended Actions
                        </h4>
                        {(deterioration.recommendedActions || []).length ? (
                          <div className="flex flex-col gap-2">
                            {(deterioration.recommendedActions || []).map((action, idx) => (
                              <p key={idx} className="text-sm leading-relaxed text-ink/90 p-3 bg-white/5 rounded-lg border border-white/10">{translateDisplayText(language, action)}</p>
                            ))}
                          </div>
                        ) : <p className="text-sm text-ink-muted italic">No recommended actions are available yet.</p>}
                      </div>
                    </div>
                  </div>
                ) : (
                  <div className="flex flex-col items-center justify-center p-16 text-center border border-white/5 rounded-xl border-dashed min-h-[200px]">
                    <Layers size={48} className="text-ink-muted/30 mb-4" />
                    <h3 className="font-display text-lg mb-2">No Deterioration Data</h3>
                    <p className="text-sm text-ink-muted max-w-[280px]">We need more health observations to predict deterioration risks.</p>
                  </div>
                )}
              </div>

              {/* Copilot Guidance */}
              <div className="flex flex-col">
                <div className="flex items-center gap-4 mb-6">
                   <h3 className="font-display text-xl font-medium">AI Copilot Guidance</h3>
                   <div className="flex-1 h-px bg-white/10"></div>
                </div>

                {copilot ? (
                  <div className="card-premium">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                      <div>
                        <h4 className="text-[10px] font-bold text-ink-muted uppercase tracking-widest mb-4">Patient Actions</h4>
                        {(copilot.patientActions || []).length ? (
                          <div className="flex flex-col gap-3">
                            {(copilot.patientActions || []).map((item, idx) => (
                              <p key={idx} className="text-sm leading-relaxed text-ink/90 flex gap-2">
                                <span className="text-primary mt-0.5">ΓÇó</span> {translateDisplayText(language, item)}
                              </p>
                            ))}
                          </div>
                        ) : <p className="text-sm text-ink-muted italic">No actions required.</p>}
                      </div>
                      <div>
                        <h4 className="text-[10px] font-bold text-ink-muted uppercase tracking-widest mb-4">Caregiver Actions</h4>
                        {(copilot.caregiverActions || []).length ? (
                          <div className="flex flex-col gap-3">
                            {(copilot.caregiverActions || []).map((item, idx) => (
                              <p key={idx} className="text-sm leading-relaxed text-ink/90 flex gap-2">
                                <span className="text-primary mt-0.5">ΓÇó</span> {translateDisplayText(language, item)}
                              </p>
                            ))}
                          </div>
                        ) : <p className="text-sm text-ink-muted italic">No actions required.</p>}
                      </div>
                      <div>
                        <h4 className="text-[10px] font-bold text-ink-muted uppercase tracking-widest mb-4">Doctor Actions</h4>
                        {(copilot.doctorActions || []).length ? (
                          <div className="flex flex-col gap-3">
                            {(copilot.doctorActions || []).map((item, idx) => (
                              <p key={idx} className="text-sm leading-relaxed text-ink/90 flex gap-2">
                                <span className="text-primary mt-0.5">ΓÇó</span> {translateDisplayText(language, item)}
                              </p>
                            ))}
                          </div>
                        ) : <p className="text-sm text-ink-muted italic">No actions required.</p>}
                      </div>
                    </div>
                    
                    {copilot.escalationDecision && (
                      <div className="mt-8 p-4 bg-alert/10 border-l-4 border-l-alert rounded-r-lg border border-y-alert/20 border-r-alert/20">
                        <p className="text-sm font-semibold text-alert">{copilot.escalationDecision}</p>
                      </div>
                    )}
                  </div>
                ) : (
                  <div className="flex flex-col items-center justify-center p-16 text-center border border-white/5 rounded-xl border-dashed min-h-[200px]">
                    <Bot size={48} className="text-ink-muted/30 mb-4" />
                    <h3 className="font-display text-lg mb-2">No Copilot Guidance</h3>
                    <p className="text-sm text-ink-muted max-w-[280px]">AI Copilot has no specific recommendations at this time.</p>
                  </div>
                )}
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 items-start">
                
                {/* Adaptive Triage */}
                <div className="flex flex-col">
                  <div className="flex items-center gap-4 mb-6">
                     <h3 className="font-display text-xl font-medium">Adaptive Triage</h3>
                     <div className="flex-1 h-px bg-white/10"></div>
                  </div>

                  {adaptive ? (
                    <div className="card-premium !bg-surface h-full">
                      {adaptive.rationale && <p className="text-sm text-primary font-medium mb-5 bg-primary/10 p-3 rounded-lg border border-primary/20">{adaptive.rationale}</p>}
                      {(adaptive.questions || []).length ? (
                        <div className="flex flex-col gap-3">
                          {(adaptive.questions || []).map((q, idx) => (
                            <div key={idx} className="p-4 bg-white/5 rounded-xl border border-white/10">
                              <p className="text-sm leading-relaxed text-ink/90">{translateDisplayText(language, q)}</p>
                            </div>
                          ))}
                        </div>
                      ) : <p className="text-sm text-ink-muted italic">No triage questions generated.</p>}
                    </div>
                  ) : (
                    <div className="flex flex-col items-center justify-center p-16 text-center border border-white/5 rounded-xl border-dashed min-h-[250px] h-full">
                      <Zap size={48} className="text-ink-muted/30 mb-4" />
                      <h3 className="font-display text-lg mb-2">No Triage Data</h3>
                      <p className="text-sm text-ink-muted max-w-[250px] leading-relaxed">Adaptive triage will appear here if health anomalies are detected.</p>
                    </div>
                  )}
                </div>

                {/* Follow-up Autopilot */}
                <div className="flex flex-col">
                  <div className="flex items-center gap-4 mb-6">
                     <h3 className="font-display text-xl font-medium">Follow-up Autopilot</h3>
                     <div className="flex-1 h-px bg-white/10"></div>
                  </div>

                  {autopilot ? (
                    <div className="card-premium !bg-surface h-full flex flex-col">
                      <div className="flex items-center justify-between gap-4 mb-6 pb-6 border-b border-white/10">
                        <div>
                          <p className="text-[10px] font-bold text-ink-muted uppercase tracking-widest mb-2">Next Follow-up</p>
                          <p className="text-2xl font-display font-medium text-ink">{autopilot.nextFollowUpDate}</p>
                        </div>
                        <div className="text-right">
                          <p className="text-[10px] font-bold text-ink-muted uppercase tracking-widest mb-2">Urgency</p>
                          <p className={`text-sm font-semibold px-3 py-1.5 rounded-lg w-fit ml-auto ${autopilot.urgencyLabel === 'HIGH' ? 'bg-alert/10 text-alert border border-alert/20' : 'bg-primary/10 text-primary border border-primary/20'}`}>{translateDisplayText(language, autopilot.urgencyLabel)}</p>
                        </div>
                      </div>

                      <h4 className="text-[10px] font-bold text-ink-muted uppercase tracking-widest mb-3">Autopilot Tasks</h4>
                      <div className="flex flex-col gap-2 mb-6">
                        {(autopilot.tasks || []).map((task, idx) => (
                          <p key={idx} className="text-sm leading-relaxed text-ink/90 flex gap-2.5 items-start">
                            <span className="text-primary mt-1">ΓÇó</span> <span>{translateDisplayText(language, task)}</span>
                          </p>
                        ))}
                      </div>

                      <h4 className="text-[10px] font-bold text-ink-muted uppercase tracking-widest mb-3 mt-auto">Reasons</h4>
                      <div className="flex flex-col gap-2 bg-white/5 p-4 rounded-xl border border-white/10">
                        {(autopilot.reasons || []).map((reason, idx) => (
                          <p key={idx} className="text-sm leading-relaxed text-ink-muted flex gap-2.5 items-start">
                            <span className="text-ink-muted/50 mt-0.5">-</span> <span>{translateDisplayText(language, reason)}</span>
                          </p>
                        ))}
                      </div>
                    </div>
                  ) : (
                    <div className="flex flex-col items-center justify-center p-16 text-center border border-white/5 rounded-xl border-dashed min-h-[250px] h-full">
                      <CalendarClock size={48} className="text-ink-muted/30 mb-4" />
                      <h3 className="font-display text-lg mb-2">No Follow-up Plan</h3>
                      <p className="text-sm text-ink-muted max-w-[250px] leading-relaxed">Automated follow-up scheduling is not active right now.</p>
                    </div>
                  )}
                </div>

              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
}

import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { useLanguage } from "../context/LanguageContext";
import { createHealthRecord, fetchHealthRecords, fetchHealthSummary } from "../services/telecareService";
import { getApiErrorMessage } from "../utils/apiError";
import { useToast } from "../components/ui/ToastProvider";
import PatientSidebar from "../components/PatientSidebar";
import { User, LogOut, Heart, AlertTriangle, CalendarDays, Stethoscope, Save, Bluetooth } from "lucide-react";
import { buildLoginRedirect } from "../utils/authSession";
import LanguageSwitcher from "../components/LanguageSwitcher";
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

export default function PatientHealthPage() {
  const { auth, logout } = useAuth();
  const { language, t } = useLanguage();
  const { pushToast } = useToast();
  const navigate = useNavigate();
  const patientId = auth?.profileId;
  
  const [records, setRecords] = useState([]);
  const [form, setForm] = useState({
    patientId,
    bloodPressure: "",
    sugar: "",
    weight: "",
    spo2: "",
    pulse: "",
    temperature: ""
  });
  const [isPairing, setIsPairing] = useState(false);

  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [summary, setSummary] = useState(null);

  const fieldUnits = {
    bloodPressure: "mmHg",
    sugar: "mg/dL",
    weight: "kg",
    spo2: "%",
    pulse: "bpm",
    temperature: "┬░F"
  };

  const fieldLabels = {
    bloodPressure: "Blood Pressure",
    sugar: "Blood Sugar",
    weight: "Weight",
    spo2: "SpO2 (Oxygen)",
    pulse: "Pulse Rate",
    temperature: "Temperature"
  };

  useEffect(() => {
    if (patientId) setForm((current) => ({ ...current, patientId }));
  }, [patientId]);

  const load = async ({ suppressError = false } = {}) => {
    if (!patientId) {
      if (!suppressError) setError("Unable to load health records.");
      setRecords([]);
      setSummary(null);
      setLoading(false);
      return;
    }
    setLoading(true);
    try {
      const data = await fetchHealthRecords(patientId);
      const trendSummary = await fetchHealthSummary(patientId);
      setRecords(data);
      setSummary(trendSummary);
      if (!suppressError) setError("");
    } catch (err) {
      if (!suppressError) setError(getApiErrorMessage(err, "Unable to load health records."));
    } finally {
      setLoading(false);
    }
  };
  
  useEffect(() => {
    load();
  }, [patientId]);

  const handleLogout = () => {
    logout();
    navigate(buildLoginRedirect(""), { replace: true });
  };

  return (
    <div className="min-h-screen bg-canvas text-ink font-sans flex flex-col lg:flex-row">
      <PatientSidebar />
      
      <main className="flex-1 p-6 lg:p-10 min-w-0" role="main">
        {/* Topbar */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4 animate-fadeSlideUp">
          <div>
            <h1 className="font-display text-3xl font-medium mb-2">Health Vitals</h1>
            <p className="text-ink-muted text-sm mb-3">Log your daily readings and monitor your health trends.</p>
            <div className="flex gap-2 items-center mt-3">
              <span className="inline-flex items-center gap-1.5 text-xs px-2.5 py-1 rounded-full bg-white/5 border border-white/10 text-ink-muted">
                <Heart size={12} className="text-primary" />Health
              </span>
              <div className="inline-flex items-center gap-2 text-xs text-ink-muted bg-white/5 border border-white/10 px-3 py-1.5 rounded-full">
                <User size={14} />
                Signed in as {auth?.fullName || "Anita Patient"}
              </div>
            </div>
          </div>
          <div className="flex items-center gap-3">
            <LanguageSwitcher hideLabel />
            
            <button 
              className="inline-flex items-center gap-2 px-4 py-2 bg-transparent text-ink border border-white/20 rounded-element text-sm font-medium hover:bg-white/5 transition-colors disabled:opacity-50"
              onClick={async () => {
                if (!navigator.bluetooth) {
                  alert("Web Bluetooth API is not available in this browser.");
                  return;
                }
                setIsPairing(true);
                try {
                  const device = await navigator.bluetooth.requestDevice({
                    acceptAllDevices: true,
                    optionalServices: ['heart_rate']
                  });
                  console.log("Paired with", device.name);
                  alert("Successfully paired with wearable device: " + device.name);
                } catch (err) {
                  console.error("Bluetooth pairing failed", err);
                } finally {
                  setIsPairing(false);
                }
              }}
              disabled={isPairing}
            >
              <Bluetooth size={16} className={isPairing ? "animate-pulse text-[#60A5FA]" : ""} />
              {isPairing ? "Pairing..." : "Sync Wearable"}
            </button>
            
            <button 
              onClick={handleLogout} 
              aria-label="Log out"
              className="inline-flex items-center gap-2 px-4 py-2 bg-transparent text-ink-muted border border-white/10 rounded-element text-sm font-medium hover:bg-white/5 hover:text-ink transition-colors"
            >
              <LogOut size={16} />Logout
            </button>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-[400px_1fr] gap-8 animate-fadeSlideUp" style={{animationDelay: '0.1s'}}>
          
          {/* Left Panel: Log New Reading */}
          <div className="flex flex-col">
            <h2 className="font-display text-xl font-medium mb-6">Log New Reading</h2>
            
            <div className="card-premium h-fit">
              <div className="grid grid-cols-2 gap-5">
                {Object.keys(form).filter(k => k !== "patientId").map((key) => (
                  <div key={key}>
                    <label className="block text-sm font-medium text-ink-muted mb-2">
                      {fieldLabels[key]}
                    </label>
                    <div className="relative">
                      <input
                        type="text"
                        value={form[key]}
                        onChange={(e) => setForm({ ...form, [key]: e.target.value })}
                        placeholder={`0.0`}
                        className="w-full bg-white/5 border border-white/10 rounded-element py-3 pl-4 pr-14 text-ink focus:outline-none focus:ring-2 focus:ring-primary/50 placeholder-ink-muted/50 font-mono text-sm"
                      />
                      <span className="absolute right-4 top-1/2 -translate-y-1/2 text-ink-muted text-xs font-medium uppercase tracking-wider">
                        {fieldUnits[key]}
                      </span>
                    </div>
                  </div>
                ))}
              </div>

              {error && <p className="text-alert text-sm mt-4 p-3 bg-alert/10 border border-alert/20 rounded-element">{error}</p>}
              
              <button
                className="btn-primary w-full mt-6 flex justify-center py-3"
                disabled={saving || !patientId}
                onClick={async () => {
                  if (!patientId) {
                    setError("Unable to save health reading.");
                    return;
                  }
                  setError("");
                  setSaving(true);
                  try {
                    const response = await createHealthRecord({
                      ...form,
                      sugar: form.sugar ? Number(form.sugar) : null,
                      weight: form.weight ? Number(form.weight) : null,
                      spo2: form.spo2 ? Number(form.spo2) : null,
                      pulse: form.pulse ? Number(form.pulse) : null,
                      temperature: form.temperature ? Number(form.temperature) : null
                    });
                    pushToast({
                      type: "success",
                      title: "Saved",
                      message: "Reading saved successfully."
                    });
                    setRecords((current) => [response, ...current.filter((item) => item.id !== response.id)]);
                    setForm({ ...form, bloodPressure: "", sugar: "", weight: "", spo2: "", pulse: "", temperature: "" });
                    await load({ suppressError: true });
                  } catch (err) {
                    setError(getApiErrorMessage(err, "Unable to save health reading."));
                  } finally {
                    setSaving(false);
                  }
                }}
              >
                <Save size={18} className="mr-2" /> {saving ? "Saving..." : "Save Reading"}
              </button>
            </div>
          </div>

          {/* Right Panel: History */}
          <div className="flex flex-col">
            <h2 className="font-display text-xl font-medium mb-6">Interactive Trends</h2>
            
            {(() => {
              if (!records || records.length === 0) return null;
              const chartData = [...records].reverse().map(record => {
                let systolic = null;
                let diastolic = null;
                if (record.bloodPressure && record.bloodPressure.includes('/')) {
                  const parts = record.bloodPressure.split('/');
                  systolic = Number(parts[0]);
                  diastolic = Number(parts[1]);
                }
                return {
                  ...record,
                  timeLabel: new Date(record.recordedAt).toLocaleDateString(undefined, { month: 'short', day: 'numeric' }),
                  systolic,
                  diastolic,
                };
              });

              return (
                <div className="flex flex-col gap-6 mb-8">
                  {/* Blood Pressure Chart */}
                  <div className="card-premium !bg-surface">
                    <h3 className="text-sm font-semibold text-ink mb-4">Blood Pressure (mmHg)</h3>
                    <div className="w-full h-[250px]">
                      <ResponsiveContainer>
                        <LineChart data={chartData} margin={{ top: 5, right: 5, left: -20, bottom: 5 }}>
                          <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.05)" />
                          <XAxis dataKey="timeLabel" stroke="var(--color-ink-muted)" fontSize={12} tickLine={false} axisLine={false} />
                          <YAxis stroke="var(--color-ink-muted)" fontSize={12} tickLine={false} axisLine={false} />
                          <Tooltip contentStyle={{ backgroundColor: '#0D1826', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '8px', color: '#fff' }} />
                          <Legend wrapperStyle={{ fontSize: '12px' }} />
                          <Line type="monotone" dataKey="systolic" name="Systolic" stroke="#E2604F" strokeWidth={2} dot={{ r: 3 }} activeDot={{ r: 5 }} connectNulls />
                          <Line type="monotone" dataKey="diastolic" name="Diastolic" stroke="#60A5FA" strokeWidth={2} dot={{ r: 3 }} activeDot={{ r: 5 }} connectNulls />
                        </LineChart>
                      </ResponsiveContainer>
                    </div>
                  </div>

                  {/* Sugar & Pulse Chart */}
                  <div className="card-premium !bg-surface">
                    <h3 className="text-sm font-semibold text-ink mb-4">Sugar (mg/dL) & Pulse (bpm)</h3>
                    <div className="w-full h-[250px]">
                      <ResponsiveContainer>
                        <LineChart data={chartData} margin={{ top: 5, right: 5, left: -20, bottom: 5 }}>
                          <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.05)" />
                          <XAxis dataKey="timeLabel" stroke="var(--color-ink-muted)" fontSize={12} tickLine={false} axisLine={false} />
                          <YAxis stroke="var(--color-ink-muted)" fontSize={12} tickLine={false} axisLine={false} />
                          <Tooltip contentStyle={{ backgroundColor: '#0D1826', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '8px', color: '#fff' }} />
                          <Legend wrapperStyle={{ fontSize: '12px' }} />
                          <Line type="monotone" dataKey="sugar" name="Blood Sugar" stroke="#4FB3A0" strokeWidth={2} dot={{ r: 3 }} activeDot={{ r: 5 }} connectNulls />
                          <Line type="monotone" dataKey="pulse" name="Pulse Rate" stroke="#A78BFA" strokeWidth={2} dot={{ r: 3 }} activeDot={{ r: 5 }} connectNulls />
                        </LineChart>
                      </ResponsiveContainer>
                    </div>
                  </div>

                  {/* SpO2 Chart */}
                  <div className="card-premium !bg-surface">
                    <h3 className="text-sm font-semibold text-ink mb-4">Oxygen Saturation (SpO2 %)</h3>
                    <div className="w-full h-[250px]">
                      <ResponsiveContainer>
                        <LineChart data={chartData} margin={{ top: 5, right: 5, left: -20, bottom: 5 }}>
                          <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.05)" />
                          <XAxis dataKey="timeLabel" stroke="var(--color-ink-muted)" fontSize={12} tickLine={false} axisLine={false} />
                          <YAxis domain={[90, 100]} stroke="var(--color-ink-muted)" fontSize={12} tickLine={false} axisLine={false} />
                          <Tooltip contentStyle={{ backgroundColor: '#0D1826', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '8px', color: '#fff' }} />
                          <Legend wrapperStyle={{ fontSize: '12px' }} />
                          <Line type="monotone" dataKey="spo2" name="SpO2" stroke="#4FB3A0" strokeWidth={2} dot={{ r: 3 }} activeDot={{ r: 5 }} connectNulls />
                        </LineChart>
                      </ResponsiveContainer>
                    </div>
                  </div>
                </div>
              );
            })()}

            {loading ? (
              <div className="flex flex-col gap-4">
                {[1, 2].map(i => (
                  <div key={i} className="card-premium animate-pulse h-32 flex flex-col justify-center">
                    <div className="h-6 w-1/3 bg-white/10 rounded mb-4"></div>
                    <div className="h-4 w-full bg-white/10 rounded"></div>
                  </div>
                ))}
              </div>
            ) : !loading && (!Array.isArray(records) || !records.length) ? (
              <div className="flex flex-col items-center justify-center min-h-[300px] border border-white/5 border-dashed rounded-xl p-8 text-center text-ink-muted">
                <Stethoscope size={48} className="opacity-30 mb-4" />
                <h3 className="font-display text-lg mb-2 text-ink">No health readings yet</h3>
                <p className="text-sm max-w-sm">Add your first reading using the form to start tracking your health trends over time.</p>
              </div>
            ) : (
              <div className="flex flex-col gap-4">
                <h3 className="text-sm font-semibold text-ink-muted tracking-widest uppercase mb-2">Recent Readings</h3>
                {records.map((record) => (
                  <div key={record.id} className="card-premium !bg-white/5 hover:!bg-white/10 transition-colors">
                    <div className="flex justify-between items-center mb-4">
                      <span className={`text-xs px-3 py-1 rounded-full font-bold uppercase tracking-wider ${record.alertSeverity === 'NORMAL' ? 'bg-primary/10 text-primary border border-primary/20' : 'bg-alert/10 text-alert border border-alert/20'}`}>
                        {record.alertSeverity || "NORMAL"}
                      </span>
                      <span className="text-xs text-ink-muted flex items-center gap-1.5 font-mono">
                        <CalendarDays size={14} /> {new Date(record.recordedAt).toLocaleString(undefined, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })}
                      </span>
                    </div>
                    
                    <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mb-4 bg-black/20 p-3 rounded-element border border-white/5">
                      <div className="text-xs text-ink-muted">BP: <span className="font-mono text-ink text-sm block mt-1">{record.bloodPressure || "-"}</span></div>
                      <div className="text-xs text-ink-muted">Sugar: <span className="font-mono text-ink text-sm block mt-1">{record.sugar || "-"}</span></div>
                      <div className="text-xs text-ink-muted">SpO2: <span className="font-mono text-ink text-sm block mt-1">{record.spo2 || "-"}</span></div>
                      <div className="text-xs text-ink-muted">Pulse: <span className="font-mono text-ink text-sm block mt-1">{record.pulse || "-"}</span></div>
                    </div>

                    {record.alertMessage && (
                      <div className="flex gap-2 text-xs text-ink-muted italic border-l-2 border-alert/50 pl-3 py-1">
                        <AlertTriangle size={14} className="text-alert shrink-0" />
                        {record.alertMessage}
                      </div>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>

        </div>
      </main>
    </div>
  );
}

import { useEffect, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { useLanguage } from "../context/LanguageContext";
import { fetchIvrSessions, startIvrSession } from "../services/telecareService";
import { getApiErrorMessage } from "../utils/apiError";
import { formatDisplayValue } from "../utils/formatDisplayValue";
import { translateDisplayText } from "../utils/i18n";
import PatientSidebar from "../components/PatientSidebar";
import { User, LogOut, PhoneCall, Calendar, CheckCircle, Clock, AlertTriangle, RefreshCw, Smartphone, ListCollapse } from "lucide-react";
import { buildLoginRedirect } from "../utils/authSession";
import LanguageSwitcher from "../components/LanguageSwitcher";

export default function PatientIvrPage() {
  const { auth, logout } = useAuth();
  const navigate = useNavigate();
  const { language, t, translateUiText = (value) => translateDisplayText(language, value) } = useLanguage();
  const patientId = auth?.profileId;
  
  const [sessions, setSessions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [starting, setStarting] = useState(false);
  const [error, setError] = useState("");
  const [sessionsError, setSessionsError] = useState("");
  const [message, setMessage] = useState("");
  
  const [fieldErrors, setFieldErrors] = useState({ appointmentDateTime: "", concernSummary: "" });
  const [form, setForm] = useState({
    patientId,
    phoneNumber: auth?.phone || "",
    languageCode: language,
    serviceType: "APPOINTMENT",
    appointmentDateTime: "",
    mode: "TELECONSULTATION",
    concernSummary: ""
  });

  const lastAutoPhoneRef = useRef(auth?.phone || "");
  const lastAutoLanguageRef = useRef(language);

  const normalizeDateTimeInput = (value) => (value && value.length === 16 ? `${value}:00` : value);

  const load = async () => {
    if (!patientId) {
      setSessions([]);
      setSessionsError("Unable to load IVR sessions.");
      setLoading(false);
      return;
    }
    setLoading(true);
    try {
      const data = await fetchIvrSessions(patientId);
      setSessions(Array.isArray(data) ? data : []);
      setSessionsError("");
    } catch (err) {
      setSessionsError(getApiErrorMessage(err, "Unable to load IVR sessions."));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    setForm((current) => {
      const next = { ...current, patientId };
      if (!current.phoneNumber || current.phoneNumber === lastAutoPhoneRef.current) {
        next.phoneNumber = auth?.phone || current.phoneNumber;
        lastAutoPhoneRef.current = next.phoneNumber || "";
      }
      if (!current.languageCode || current.languageCode === lastAutoLanguageRef.current) {
        next.languageCode = language;
        lastAutoLanguageRef.current = language;
      }
      return next;
    });
    load();
  }, [auth?.phone, language, patientId]);

  const validateForm = () => {
    if (form.serviceType !== "APPOINTMENT") {
      setFieldErrors({ appointmentDateTime: "", concernSummary: "" });
      return false;
    }
    const nextErrors = {
      appointmentDateTime: form.appointmentDateTime ? "" : "Requested appointment time is required",
      concernSummary: form.concernSummary.trim() ? "" : "Concern summary is required"
    };
    setFieldErrors(nextErrors);
    return Boolean(nextErrors.appointmentDateTime || nextErrors.concernSummary);
  };

  const handleStart = async () => {
    if (!patientId) { setError("Unable to start IVR session."); return; }
    if (validateForm()) { setMessage(""); setError(""); return; }
    try {
      setStarting(true);
      const created = await startIvrSession({
        ...form,
        patientId,
        appointmentDateTime: form.appointmentDateTime ? normalizeDateTimeInput(form.appointmentDateTime) : null,
        concernSummary: form.concernSummary.trim()
      });
      setSessions((current) => [created, ...current]);
      setMessage(created.appointmentId ? `IVR session created with appointment #${created.appointmentId}` : "IVR session completed.");
      setError("");
    } catch (err) {
      setError(getApiErrorMessage(err, "Unable to start IVR session."));
    } finally {
      setStarting(false);
    }
  };

  const handleLogout = () => {
    logout();
    navigate(buildLoginRedirect(""), { replace: true });
  };

  return (
    <div className="min-h-screen bg-canvas text-ink font-sans flex flex-col lg:flex-row">
      <PatientSidebar />
      
      <main className="flex-1 p-6 lg:p-10 min-w-0" role="main">
        {/* Topbar */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4 animate-fadeSlideUp">
          <div>
            <h1 className="font-display text-3xl font-medium mb-2">IVR Booking</h1>
            <p className="text-ink-muted text-sm mb-3">Schedule an automated call to book your next appointment.</p>
            <div className="flex gap-2 items-center mt-3">
              <span className="inline-flex items-center gap-1.5 text-xs px-2.5 py-1 rounded-full bg-white/5 border border-white/10 text-ink-muted">
                <PhoneCall size={12} className="text-primary" />Support
              </span>
              <div className="inline-flex items-center gap-2 text-xs text-ink-muted bg-white/5 border border-white/10 px-3 py-1.5 rounded-full">
                <User size={14} />
                Signed in as {auth?.fullName || "Anita Patient"}
              </div>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <LanguageSwitcher hideLabel />
            <button 
              onClick={handleLogout} 
              aria-label="Log out"
              className="inline-flex items-center gap-2 px-4 py-2 bg-transparent text-ink-muted border border-white/10 rounded-element text-sm font-medium hover:bg-white/5 hover:text-ink transition-colors"
            >
              <LogOut size={16} />Logout
            </button>
          </div>
        </div>

        <div className="grid grid-cols-1 xl:grid-cols-[400px_1fr] gap-8 animate-fadeSlideUp" style={{animationDelay: '0.1s'}}>
          
          {/* New Booking Form */}
          <div className="flex flex-col">
            <div className="flex items-center gap-4 mb-6">
               <h3 className="font-display text-xl font-medium">Request Automated Call</h3>
               <div className="flex-1 h-px bg-white/10"></div>
            </div>
            
            <div className="card-premium">
              <p className="text-sm text-ink-muted mb-6 leading-relaxed">
                {translateUiText("IVR requests are tracked inside TeleCare+. Live telephony delivery depends on configured voice providers and current connectivity.")}
              </p>

              <div className="flex flex-col gap-4">
                <div className="flex flex-col sm:flex-row gap-4">
                  <div className="flex-1">
                    <label className="block text-sm font-medium text-ink-muted mb-2">Phone</label>
                    <input 
                      type="text" 
                      value={form.phoneNumber} 
                      onChange={e => setForm({...form, phoneNumber: e.target.value})}
                      className="w-full bg-white/5 border border-white/10 rounded-element p-3 text-ink focus:outline-none focus:ring-2 focus:ring-primary/50 text-sm" 
                    />
                  </div>
                  <div className="flex-1">
                    <label className="block text-sm font-medium text-ink-muted mb-2">Language</label>
                    <input 
                      type="text" 
                      value={form.languageCode} 
                      onChange={e => setForm({...form, languageCode: e.target.value})}
                      className="w-full bg-white/5 border border-white/10 rounded-element p-3 text-ink focus:outline-none focus:ring-2 focus:ring-primary/50 text-sm" 
                    />
                  </div>
                </div>

                <div className="flex flex-col sm:flex-row gap-4">
                  <div className="flex-1">
                    <label className="block text-sm font-medium text-ink-muted mb-2">Service Type</label>
                    <select 
                      value={form.serviceType} 
                      onChange={e => setForm({...form, serviceType: e.target.value})}
                      className="w-full bg-white/5 border border-white/10 rounded-element p-3 text-ink focus:outline-none focus:ring-2 focus:ring-primary/50 text-sm"
                    >
                      <option value="APPOINTMENT" className="bg-surface">Appointment</option>
                      <option value="PRESCRIPTION_STATUS" className="bg-surface">Prescription</option>
                      <option value="MEDICATION_REMINDER" className="bg-surface">Medication</option>
                      <option value="EMERGENCY_SUPPORT" className="bg-surface">Emergency</option>
                    </select>
                  </div>
                  <div className="flex-1">
                    <label className="block text-sm font-medium text-ink-muted mb-2">Mode</label>
                    <select 
                      value={form.mode} 
                      onChange={e => setForm({...form, mode: e.target.value})}
                      className="w-full bg-white/5 border border-white/10 rounded-element p-3 text-ink focus:outline-none focus:ring-2 focus:ring-primary/50 text-sm"
                    >
                      <option value="TELECONSULTATION" className="bg-surface">Teleconsultation</option>
                      <option value="FOLLOW_UP" className="bg-surface">Follow Up</option>
                      <option value="IN_PERSON" className="bg-surface">In Person</option>
                    </select>
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-ink-muted mb-2">Requested Time</label>
                  <input 
                    type="datetime-local" 
                    value={form.appointmentDateTime} 
                    onChange={e => {
                      setForm({...form, appointmentDateTime: e.target.value});
                      if (fieldErrors.appointmentDateTime) setFieldErrors(c => ({...c, appointmentDateTime: ""}));
                    }}
                    className={`w-full bg-white/5 border rounded-element p-3 text-ink focus:outline-none focus:ring-2 focus:ring-primary/50 text-sm ${fieldErrors.appointmentDateTime ? 'border-alert' : 'border-white/10'}`} 
                  />
                  {fieldErrors.appointmentDateTime && <p className="text-xs text-alert mt-1.5">{fieldErrors.appointmentDateTime}</p>}
                </div>

                <div>
                  <label className="block text-sm font-medium text-ink-muted mb-2">Concern Summary</label>
                  <textarea 
                    value={form.concernSummary} 
                    onChange={e => {
                      setForm({...form, concernSummary: e.target.value});
                      if (fieldErrors.concernSummary) setFieldErrors(c => ({...c, concernSummary: ""}));
                    }}
                    className={`w-full min-h-[80px] p-3 bg-white/5 border rounded-element text-ink focus:outline-none focus:ring-2 focus:ring-primary/50 text-sm resize-y ${fieldErrors.concernSummary ? 'border-alert' : 'border-white/10'}`} 
                  />
                  {fieldErrors.concernSummary && <p className="text-xs text-alert mt-1.5">{fieldErrors.concernSummary}</p>}
                </div>
                
                {error && (
                  <div className="p-3 bg-alert/10 text-alert border border-alert/20 rounded-element text-sm mt-2">
                    {error}
                  </div>
                )}
                {message && (
                  <div className="p-3 bg-primary/10 text-primary border border-primary/20 rounded-element text-sm flex items-center gap-2 mt-2 font-medium">
                    <CheckCircle size={16} /> {message}
                  </div>
                )}

                <button 
                  className="btn-primary w-full mt-2 py-3 flex justify-center" 
                  disabled={starting || !patientId} 
                  onClick={handleStart}
                >
                  {starting ? "Starting..." : "Start IVR Session"}
                </button>

              </div>
            </div>
          </div>

          {/* History List */}
          <div className="flex flex-col">
            <div className="flex items-center gap-4 mb-6">
               <h3 className="font-display text-xl font-medium">Recent Sessions</h3>
               <div className="flex-1 h-px bg-white/10"></div>
            </div>
            
            {loading ? (
              <div className="flex flex-col gap-4">
                {[1,2].map(i => <div key={i} className="card-premium h-32 animate-pulse bg-white/5"></div>)}
              </div>
            ) : sessionsError ? (
              <div className="flex flex-col items-center justify-center p-12 text-center bg-alert/5 border border-alert/20 rounded-xl">
                <AlertTriangle size={32} className="text-alert mb-4" />
                <h3 className="font-display text-lg mb-2">Unable to load IVR history</h3>
                <p className="text-sm text-ink-muted mb-6">{sessionsError}</p>
                <button className="px-4 py-2 border border-white/20 rounded-element text-sm font-medium hover:bg-white/5 transition-colors flex items-center gap-2" onClick={load}>
                  <RefreshCw size={16} /> Retry
                </button>
              </div>
            ) : sessions.length === 0 ? (
              <div className="flex flex-col items-center justify-center p-16 text-center border border-white/5 rounded-xl border-dashed">
                <Smartphone size={48} className="text-ink-muted/30 mb-4" />
                <h3 className="font-display text-lg mb-2">No IVR Sessions</h3>
                <p className="text-sm text-ink-muted max-w-sm">IVR booking activity will appear here once automated calls are requested.</p>
              </div>
            ) : (
              <div className="flex flex-col gap-5">
                {sessions.map(session => (
                  <div key={session.id} className="card-premium !bg-surface hover:border-white/20 transition-colors">
                    <div className="flex flex-col sm:flex-row sm:items-start justify-between gap-4 mb-5 pb-5 border-b border-white/10">
                      <div>
                        {/* Show "Dr. [Name]" if available in transcript, else just use the service type as the primary header */}
                        <h4 className="text-base font-medium flex items-center gap-2 mb-1.5">
                          {session.doctorName ? session.doctorName : (translateDisplayText(language, session.serviceType) || formatDisplayValue(session.serviceType))}
                        </h4>
                        <p className="text-sm text-ink-muted flex flex-wrap items-center gap-2 font-mono">
                          <span className="flex items-center gap-1"><Calendar size={14} /> {new Date(session.createdAt).toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' })}</span>
                          <span className="opacity-50">ΓÇó</span>
                          <span className="flex items-center gap-1"><Clock size={14} /> {new Date(session.createdAt).toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' })}</span>
                        </p>
                      </div>
                      <span className={`text-xs px-3 py-1 rounded-full font-semibold tracking-wider uppercase border ${session.status === 'COMPLETED' ? 'bg-primary/10 text-primary border-primary/20' : 'bg-white/5 text-ink-muted border-white/10'}`}>
                        {translateDisplayText(language, session.status) || formatDisplayValue(session.status)}
                      </span>
                    </div>
                    
                    <div className="bg-white/5 p-4 rounded-xl border-l-4 border-primary">
                      <p className="text-sm leading-relaxed text-ink-muted italic">"{session.transcriptSummary}"</p>
                      {session.appointmentId && (
                        <p className="mt-3 text-sm font-semibold text-primary font-mono bg-primary/10 inline-block px-2 py-1 rounded">
                          Appointment ID: {session.appointmentId}
                        </p>
                      )}
                    </div>
                    
                    {!!session.prompts?.length && (
                      <details className="mt-5 text-sm text-ink-muted">
                        <summary className="cursor-pointer outline-none select-none inline-flex items-center gap-2 hover:text-ink transition-colors font-medium">
                          <ListCollapse size={16} /> View raw call script ({session.prompts.length} prompts)
                        </summary>
                        <div className="mt-4 flex flex-col gap-2 pl-3 border-l-2 border-white/10">
                          {session.prompts.map((prompt, idx) => (
                            <p key={idx} className="text-xs text-ink-muted/80 leading-relaxed font-mono">"{prompt}"</p>
                          ))}
                        </div>
                      </details>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>

        </div>
      </main>
    </div>
  );
}

import { useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { useLanguage } from "../context/LanguageContext";
import { acknowledgeCareMessage, fetchPatientMessages, sendCareMessage } from "../services/telecareService";
import { getApiErrorMessage } from "../utils/apiError";
import { useToast } from "../components/ui/ToastProvider";
import PatientSidebar from "../components/PatientSidebar";
import { User, LogOut, MessageSquare, Send, CheckCircle2, ShieldCheck, Search } from "lucide-react";
import { buildLoginRedirect } from "../utils/authSession";
import LanguageSwitcher from "../components/LanguageSwitcher";
import { useWebSocket } from "../hooks/useWebSocket";
export default function PatientMessagesPage() {
  const { auth, logout } = useAuth();
  const { language, t } = useLanguage();
  const { pushToast } = useToast();
  const navigate = useNavigate();
  const profileId = auth?.profileId ?? auth?.userId;
  
  const [contacts, setContacts] = useState([]);
  const [messages, setMessages] = useState([]);
  const [selectedUserId, setSelectedUserId] = useState(null);
  const [subject, setSubject] = useState("");
  const [body, setBody] = useState("");
  const [loading, setLoading] = useState(true);
  const [sending, setSending] = useState(false);
  const [error, setError] = useState("");
  const [search, setSearch] = useState("");

  const loadInbox = async () => {
    setLoading(true);
    try {
      const data = await fetchPatientMessages(profileId);
      const safeContacts = Array.isArray(data?.contacts) ? data.contacts : [];
      const safeMessages = Array.isArray(data?.messages) ? data.messages : [];
      
      const isTestEntity = (str) => {
        if (!str) return false;
        const s = str.toLowerCase();
        return s.includes("test") || s.includes("qa ") || s.includes("ui send");
      };

      const filteredContacts = safeContacts.filter(c => !isTestEntity(c.displayName));
      const filteredMessages = safeMessages.filter(m => 
        !isTestEntity(m.subject) && !isTestEntity(m.body) && 
        !isTestEntity(m.senderName) && !isTestEntity(m.recipientName)
      );

      const dedupedContacts = filteredContacts.filter((contact, index, list) =>
        list.findIndex((item) => item.userId === contact.userId) === index
      );
      
      setContacts(dedupedContacts);
      setMessages(filteredMessages);
      setSelectedUserId((current) => current ?? dedupedContacts[0]?.userId ?? null);
      setError("");
    } catch (err) {
      setError(getApiErrorMessage(err, "Unable to load messages."));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadInbox();
  }, [profileId]);

  const handleNewMessage = (newMsg) => {
    setMessages((current) => {
      if (current.find(m => m.id === newMsg.id)) return current;
      return [newMsg, ...current];
    });
  };

  useWebSocket('/user/queue/messages', handleNewMessage);

  const filteredContacts = useMemo(() => {
    if (!search.trim()) return contacts;
    const query = search.trim().toLowerCase();
    return contacts.filter(c => c.displayName?.toLowerCase().includes(query) || c.role?.toLowerCase().includes(query));
  }, [contacts, search]);

  const selectedContact = useMemo(
    () => contacts.find((contact) => contact.userId === selectedUserId) ?? null,
    [contacts, selectedUserId]
  );

  const visibleMessages = useMemo(() => {
    if (!selectedContact) return [];
    return messages
      .filter((item) => item.senderUserId === selectedContact.userId || item.recipientUserId === selectedContact.userId)
      .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()); // newest first
  }, [messages, selectedContact]);

  const sendMessage = async (e) => {
    if (e && e.preventDefault) e.preventDefault();
    window.alert("Button was clicked! Body: " + body);
    
    if (!selectedContact || !body.trim()) {
      window.alert("Please select a contact and enter a message.");
      return;
    }
    setSending(true);
    try {
      if (!profileId || !auth?.userId || !selectedContact?.userId) {
         window.alert("Error: Missing IDs");
         throw new Error("Missing required IDs for sending message");
      }
      const created = await sendCareMessage({
        patientId: profileId,
        senderUserId: auth.userId,
        recipientUserId: selectedContact.userId,
        subject: subject.trim() || "Care coordination message",
        body: body.trim()
      });
      setMessages((current) => [created, ...current]);
      setSubject("");
      setBody("");
      window.alert("Message sent successfully!");
    } catch (err) {
      console.error(err);
      window.alert("Failed to send: " + err.message);
    } finally {
      setSending(false);
    }
  };

  const handleLogout = () => {
    logout();
    navigate(buildLoginRedirect(""), { replace: true });
  };

  return (
    <div className="min-h-screen bg-canvas text-ink font-sans flex flex-col lg:flex-row h-screen overflow-hidden">
      <PatientSidebar />
      
      <main className="flex-1 flex flex-col min-w-0 h-full" role="main">
        {/* Topbar */}
        <div className="p-6 lg:p-10 pb-6 shrink-0 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 animate-fadeSlideUp z-10 bg-canvas">
          <div>
            <h1 className="font-display text-3xl font-medium mb-2">Messages</h1>
            <p className="text-ink-muted text-sm mb-3">Communicate directly with your care team and specialists.</p>
            <div className="flex gap-2 items-center mt-3">
              <span className="inline-flex items-center gap-1.5 text-xs px-2.5 py-1 rounded-full bg-white/5 border border-white/10 text-ink-muted">
                <MessageSquare size={12} className="text-primary" />Support
              </span>
              <div className="inline-flex items-center gap-2 text-xs text-ink-muted bg-white/5 border border-white/10 px-3 py-1.5 rounded-full">
                <User size={14} />
                Signed in as {auth?.fullName || "Anita Patient"}
              </div>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <LanguageSwitcher hideLabel />
            <button 
              onClick={handleLogout} 
              aria-label="Log out"
              className="inline-flex items-center gap-2 px-4 py-2 bg-transparent text-ink-muted border border-white/10 rounded-element text-sm font-medium hover:bg-white/5 hover:text-ink transition-colors"
            >
              <LogOut size={16} />Logout
            </button>
          </div>
        </div>

        <div className="flex-1 flex overflow-hidden animate-fadeSlideUp" style={{animationDelay: '0.1s'}}>
          
          {/* Contacts Sidebar */}
          <div className="w-full md:w-80 flex-shrink-0 flex flex-col bg-surface border-r border-white/10">
            <div className="p-6 border-b border-white/10">
              <div className="relative">
                <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-ink-muted" />
                <input
                  type="text"
                  placeholder="Search contacts..."
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  className="w-full pl-10 pr-4 py-2.5 bg-white/5 border border-white/10 rounded-full text-ink text-sm outline-none focus:border-primary/50 transition-colors placeholder:text-ink-muted/50"
                />
              </div>
            </div>
            
            <div className="flex-1 overflow-y-auto p-4 scrollbar-hide">
              {loading ? (
                <div className="flex flex-col gap-3">
                  {[1,2,3].map(i => <div key={i} className="card-premium h-16 animate-pulse bg-white/5"></div>)}
                </div>
              ) : filteredContacts.length === 0 ? (
                <p className="text-sm text-ink-muted text-center mt-6">No contacts available.</p>
              ) : (
                <div className="flex flex-col gap-2">
                  {filteredContacts.map(contact => (
                    <button
                      key={contact.userId}
                      onClick={() => setSelectedUserId(contact.userId)}
                      className={`w-full text-left p-4 rounded-xl flex items-center gap-4 transition-all border ${selectedUserId === contact.userId ? 'bg-primary/5 border-primary/20 shadow-[0_0_15px_rgba(20,184,166,0.05)]' : 'bg-transparent border-transparent hover:bg-white/5'}`}
                    >
                      <div className="w-10 h-10 rounded-full bg-primary/10 text-primary flex items-center justify-center font-bold shrink-0">
                        {contact.displayName?.charAt(0) || "U"}
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className={`text-[15px] font-semibold truncate ${selectedUserId === contact.userId ? 'text-primary' : 'text-ink'}`}>{contact.displayName}</p>
                        <p className="text-xs text-ink-muted mt-0.5 truncate">{contact.role}</p>
                      </div>
                    </button>
                  ))}
                </div>
              )}
            </div>
          </div>

          {/* Chat Area */}
          <div className="flex-1 flex flex-col bg-canvas min-w-0">
            {selectedContact ? (
              <>
                <div className="p-6 border-b border-white/10 bg-surface/50 backdrop-blur-sm flex items-center justify-between z-10 shadow-sm">
                  <div>
                    <h2 className="text-lg font-semibold text-ink">{selectedContact.displayName}</h2>
                    <p className="text-sm text-ink-muted mt-1">{selectedContact.role}</p>
                  </div>
                </div>
                
                <div className="flex-1 overflow-y-auto p-6 flex flex-col-reverse gap-4 scrollbar-hide relative z-0">
                  {visibleMessages.length === 0 ? (
                    <div className="flex flex-col items-center justify-center text-center my-auto">
                      <MessageSquare size={48} className="text-ink-muted/30 mb-4" />
                      <h3 className="font-display text-lg mb-2">No messages yet</h3>
                      <p className="text-sm text-ink-muted">Start a conversation with {selectedContact.displayName}.</p>
                    </div>
                  ) : (
                    visibleMessages.map(msg => {
                      const isMine = msg.senderUserId === auth.userId;
                      return (
                        <div key={msg.id} className={`flex flex-col max-w-[85%] sm:max-w-[75%] ${isMine ? 'items-end self-end' : 'items-start self-start'}`}>
                          <div className={`p-4 rounded-2xl ${isMine ? 'bg-primary text-canvas rounded-br-sm' : 'bg-surface border border-white/10 text-ink rounded-bl-sm'}`}>
                            {msg.subject && <h4 className="text-sm font-bold mb-2 opacity-90">{msg.subject}</h4>}
                            <p className="text-[15px] leading-relaxed whitespace-pre-wrap">{msg.body}</p>
                          </div>
                          <div className="flex items-center gap-2 mt-2 text-[11px] font-medium text-ink-muted">
                            <span>{new Date(msg.createdAt).toLocaleString(undefined, { hour: 'numeric', minute: '2-digit', month: 'short', day: 'numeric' })}</span>
                            {!isMine && !msg.acknowledged && (
                              <button 
                                onClick={async () => {
                                  try {
                                    const updated = await acknowledgeCareMessage(msg.id);
                                    setMessages(curr => curr.map(m => m.id === updated.id ? updated : m));
                                  } catch (e) { /* ignore */ }
                                }}
                                className="text-primary hover:text-primary-light transition-colors ml-2"
                              >
                                Mark as read
                              </button>
                            )}
                            {msg.acknowledged && <span className="flex items-center gap-1 text-primary ml-2"><CheckCircle2 size={12}/> Read</span>}
                          </div>
                        </div>
                      );
                    })
                  )}
                </div>

                <div className="relative z-50 p-6 bg-surface/50 border-t border-white/10 shadow-[0_-4px_20px_rgba(0,0,0,0.1)] backdrop-blur-md">
                  <div className="flex flex-col gap-3 max-w-4xl mx-auto">
                    <input
                      type="text"
                      placeholder="Subject (Optional)"
                      value={subject}
                      onChange={(e) => setSubject(e.target.value)}
                      className="w-full px-4 py-3 bg-white/5 border border-white/10 rounded-xl text-ink text-sm outline-none focus:border-primary/50 transition-colors placeholder:text-ink-muted/50"
                    />
                    <div className="flex flex-col sm:flex-row gap-3">
                      <textarea
                        placeholder="Type your message..."
                        value={body}
                        onChange={(e) => setBody(e.target.value)}
                        className="flex-1 min-h-[80px] sm:h-auto px-4 py-3 bg-white/5 border border-white/10 rounded-xl text-ink text-sm outline-none focus:border-primary/50 transition-colors resize-y placeholder:text-ink-muted/50"
                      />
                      <button
                        type="button"
                        className={`btn-primary sm:self-end px-6 py-3 flex items-center justify-center gap-2 rounded-xl h-[46px] ${(sending) ? 'opacity-50 cursor-not-allowed' : ''}`}
                        onClick={sendMessage}
                        onMouseDown={sendMessage}
                        onTouchStart={sendMessage}
                      >
                        <Send size={16} /> Send
                      </button>
                    </div>
                  </div>
                </div>
              </>
            ) : (
              <div className="flex-1 flex flex-col items-center justify-center p-12 text-center bg-canvas">
                <ShieldCheck size={48} className="text-ink-muted/30 mb-4" />
                <h3 className="font-display text-lg mb-2">Secure Messaging</h3>
                <p className="text-sm text-ink-muted max-w-[300px]">Select a contact from the sidebar to view your conversation history or send a new message.</p>
              </div>
            )}
          </div>

        </div>
      </main>
    </div>
  );
}

import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import LocalizedText from "../components/LocalizedText";
import { useAuth } from "../context/AuthContext";
import { useLanguage } from "../context/LanguageContext";
import { createPatientObservation, fetchPatientObservations } from "../services/telecareService";
import { getApiErrorMessage } from "../utils/apiError";
import { translateDisplayText } from "../utils/i18n";
import PatientSidebar from "../components/PatientSidebar";
import { User, LogOut, Activity, Upload, Database } from "lucide-react";
import { buildLoginRedirect } from "../utils/authSession";
import LanguageSwitcher from "../components/LanguageSwitcher";

export default function PatientObservationsPage() {
  const { auth, logout } = useAuth();
  const navigate = useNavigate();
  const { language, t, translateUiText = (value) => translateDisplayText(language, value) } = useLanguage();
  const patientId = auth?.profileId;
  
  const [observations, setObservations] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [message, setMessage] = useState("");
  const [form, setForm] = useState({
    source: "LAB_REPORT",
    observationType: "",
    metricName: "",
    metricValue: "",
    unit: "",
    abnormalFlag: false,
    notes: "",
    measuredAt: ""
  });

  const normalizeDateTimeInput = (value) => {
    if (!value) return value;
    return value.length === 16 ? `${value}:00` : value;
  };

  const sourceOptions = [
    { value: "LAB_REPORT", label: translateDisplayText(language, "LAB_REPORT") },
    { value: "WEARABLE_DEVICE", label: translateDisplayText(language, "WEARABLE_DEVICE") },
    { value: "MANUAL_UPLOAD", label: translateDisplayText(language, "MANUAL_UPLOAD") }
  ];

  const load = async () => {
    if (!patientId) {
      setObservations([]);
      setError("Unable to load observations.");
      setLoading(false);
      return;
    }
    setLoading(true);
    try {
      const data = await fetchPatientObservations(patientId);
      setObservations(Array.isArray(data) ? data : []);
      setError("");
    } catch (err) {
      setError(getApiErrorMessage(err, "Unable to load observations."));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, [patientId]);

  const handleSave = async () => {
    if (!patientId) return;
    try {
      setSaving(true);
      setError("");
      setMessage("");
      
      const created = await createPatientObservation({
        ...form,
        patientId,
        measuredAt: form.measuredAt ? normalizeDateTimeInput(form.measuredAt) : null
      });
      
      setObservations((current) => [created, ...current]);
      setMessage("Observation saved successfully.");
      setForm(c => ({
        ...c,
        observationType: "",
        metricName: "",
        metricValue: "",
        unit: "",
        abnormalFlag: false,
        notes: "",
        measuredAt: ""
      }));
      
      setTimeout(() => setMessage(""), 3000);
    } catch (err) {
      setError(getApiErrorMessage(err, "Unable to save observation."));
    } finally {
      setSaving(false);
    }
  };

  const handleLogout = () => {
    logout();
    navigate(buildLoginRedirect(""), { replace: true });
  };

  return (
    <div className="min-h-screen bg-canvas text-ink font-sans flex flex-col lg:flex-row">
      <PatientSidebar />
      
      <main className="flex-1 p-6 lg:p-10 min-w-0" role="main">
        {/* Topbar */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4 animate-fadeSlideUp">
          <div>
            <h1 className="font-display text-3xl font-medium mb-2">Smart Observations</h1>
            <p className="text-ink-muted text-sm mb-3">Manual and device-synced vitals and health metrics.</p>
            <div className="flex gap-2 items-center mt-3">
              <span className="inline-flex items-center gap-1.5 text-xs px-2.5 py-1 rounded-full bg-white/5 border border-white/10 text-ink-muted">
                <Activity size={12} className="text-primary" />Health
              </span>
              <div className="inline-flex items-center gap-2 text-xs text-ink-muted bg-white/5 border border-white/10 px-3 py-1.5 rounded-full">
                <User size={14} />
                Signed in as {auth?.fullName || "Anita Patient"}
              </div>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <LanguageSwitcher hideLabel />
            <button 
              onClick={handleLogout} 
              aria-label="Log out"
              className="inline-flex items-center gap-2 px-4 py-2 bg-transparent text-ink-muted border border-white/10 rounded-element text-sm font-medium hover:bg-white/5 hover:text-ink transition-colors"
            >
              <LogOut size={16} />Logout
            </button>
          </div>
        </div>

        <div className="max-w-5xl animate-fadeSlideUp" style={{animationDelay: '0.1s'}}>
          
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 items-start mt-8">
            
            {/* Upload Form */}
            <div className="flex flex-col">
              <div className="flex items-center gap-4 mb-6">
                 <h3 className="font-display text-xl font-medium">Upload Observation</h3>
                 <div className="flex-1 h-px bg-white/10"></div>
              </div>

              <div className="card-premium !bg-surface h-full flex flex-col">
                <p className="text-sm text-ink-muted leading-relaxed mb-6">
                  Lab and wearable entries are captured manually here unless a live vendor integration is connected.
                </p>

                <div className="flex flex-col gap-5">
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <div>
                      <label className="block text-xs font-semibold text-ink-muted uppercase tracking-widest mb-2">Source</label>
                      <select 
                        value={form.source} 
                        onChange={e => setForm({...form, source: e.target.value})}
                        className="w-full p-3 bg-white/5 border border-white/10 rounded-xl text-ink outline-none focus:border-primary/50 transition-colors"
                      >
                        {sourceOptions.map(opt => <option key={opt.value} value={opt.value} className="bg-canvas">{opt.label}</option>)}
                      </select>
                    </div>
                    <div>
                      <label className="block text-xs font-semibold text-ink-muted uppercase tracking-widest mb-2">Measured At</label>
                      <input 
                        type="datetime-local" 
                        value={form.measuredAt} 
                        onChange={e => setForm({...form, measuredAt: e.target.value})}
                        className="w-full p-3 bg-white/5 border border-white/10 rounded-xl text-ink outline-none focus:border-primary/50 transition-colors [color-scheme:dark]" 
                      />
                    </div>
                  </div>

                  <div>
                    <label className="block text-xs font-semibold text-ink-muted uppercase tracking-widest mb-2">Observation Type</label>
                    <input 
                      type="text" 
                      placeholder="e.g. Vitals, Blood Test"
                      value={form.observationType} 
                      onChange={e => setForm({...form, observationType: e.target.value})}
                      className="w-full p-3 bg-white/5 border border-white/10 rounded-xl text-ink outline-none focus:border-primary/50 transition-colors placeholder:text-ink-muted/30" 
                    />
                  </div>

                  <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
                    <div className="col-span-2 sm:col-span-1">
                      <label className="block text-xs font-semibold text-ink-muted uppercase tracking-widest mb-2">Metric</label>
                      <input 
                        type="text" 
                        placeholder="e.g. Heart Rate"
                        value={form.metricName} 
                        onChange={e => setForm({...form, metricName: e.target.value})}
                        className="w-full p-3 bg-white/5 border border-white/10 rounded-xl text-ink outline-none focus:border-primary/50 transition-colors placeholder:text-ink-muted/30" 
                      />
                    </div>
                    <div>
                      <label className="block text-xs font-semibold text-ink-muted uppercase tracking-widest mb-2">Value</label>
                      <input 
                        type="text" 
                        placeholder="e.g. 72"
                        value={form.metricValue} 
                        onChange={e => setForm({...form, metricValue: e.target.value})}
                        className="w-full p-3 bg-white/5 border border-white/10 rounded-xl text-ink outline-none focus:border-primary/50 transition-colors placeholder:text-ink-muted/30" 
                      />
                    </div>
                    <div>
                      <label className="block text-xs font-semibold text-ink-muted uppercase tracking-widest mb-2">Unit</label>
                      <input 
                        type="text" 
                        placeholder="bpm"
                        value={form.unit} 
                        onChange={e => setForm({...form, unit: e.target.value})}
                        className="w-full p-3 bg-white/5 border border-white/10 rounded-xl text-ink outline-none focus:border-primary/50 transition-colors placeholder:text-ink-muted/30" 
                      />
                    </div>
                  </div>

                  <div>
                    <label className="block text-xs font-semibold text-ink-muted uppercase tracking-widest mb-2">Notes</label>
                    <textarea 
                      value={form.notes} 
                      placeholder="Any context or conditions?"
                      onChange={e => setForm({...form, notes: e.target.value})}
                      className="w-full min-h-[100px] p-3 bg-white/5 border border-white/10 rounded-xl text-ink outline-none focus:border-primary/50 transition-colors resize-y placeholder:text-ink-muted/30" 
                    />
                  </div>

                  <label className={`flex items-center gap-3 cursor-pointer p-4 rounded-xl border transition-colors ${form.abnormalFlag ? 'bg-alert/10 border-alert/30' : 'bg-alert/5 border-transparent hover:bg-alert/10'}`}>
                    <input 
                      type="checkbox" 
                      checked={form.abnormalFlag} 
                      onChange={e => setForm({...form, abnormalFlag: e.target.checked})}
                      className="w-5 h-5 accent-alert cursor-pointer rounded border-alert/50 bg-white/5"
                    />
                    <span className={`text-sm font-medium ${form.abnormalFlag ? 'text-alert' : 'text-ink-muted'}`}>Flag as Abnormal</span>
                  </label>
                  
                  <div className="mt-auto pt-6 border-t border-white/10 flex items-center justify-between">
                    <div className="flex-1 pr-4">
                      {message && <p className="text-sm font-medium text-primary animate-fadeIn">{message}</p>}
                      {error && <p className="text-sm font-medium text-alert animate-fadeIn">{error}</p>}
                    </div>
                    <button 
                      className="btn-primary py-2.5 px-5 flex items-center gap-2 shrink-0 disabled:opacity-50 disabled:cursor-not-allowed" 
                      disabled={saving || !patientId}
                      onClick={handleSave}
                    >
                      <Upload size={18} className={saving ? "animate-bounce" : ""} /> {saving ? "Uploading..." : "Upload Observation"}
                    </button>
                  </div>
                </div>
              </div>
            </div>

            {/* History */}
            <div className="flex flex-col">
              <div className="flex items-center gap-4 mb-6">
                 <h3 className="font-display text-xl font-medium">History</h3>
                 <div className="flex-1 h-px bg-white/10"></div>
              </div>

              {loading ? (
                <div className="flex flex-col gap-4">
                  {[1,2,3,4].map(i => <div key={i} className="card-premium h-32 animate-pulse bg-white/5"></div>)}
                </div>
              ) : observations.length === 0 ? (
                <div className="flex flex-col items-center justify-center p-16 text-center border border-white/5 rounded-xl border-dashed min-h-[300px]">
                  <Database size={48} className="text-ink-muted/30 mb-4" />
                  <h3 className="font-display text-lg mb-2">No Observations</h3>
                  <p className="text-sm text-ink-muted max-w-[250px]">Upload an observation to start building this history.</p>
                </div>
              ) : (
                <div className="flex flex-col gap-4 max-h-[calc(100vh-200px)] overflow-y-auto pr-2 scrollbar-hide">
                  {observations.map(item => (
                    <div key={item.id} className={`card-premium !bg-surface border-l-4 hover:border-white/20 transition-colors ${item.abnormalFlag ? 'border-l-alert' : 'border-l-primary'}`}>
                      <div className="flex flex-col sm:flex-row items-start justify-between gap-4">
                        
                        <div className="flex-1">
                          <div className="flex flex-wrap items-center gap-3 mb-2">
                            <h4 className="text-lg font-medium text-ink">{translateDisplayText(language, item.metricName)}</h4>
                            <div className="flex items-baseline gap-1.5">
                              <span className={`text-2xl font-display font-medium ${item.abnormalFlag ? 'text-alert' : 'text-ink'}`}>{item.metricValue}</span>
                              {item.unit && <span className="text-sm text-ink-muted">{item.unit}</span>}
                            </div>
                          </div>
                          
                          <div className="flex flex-wrap items-center gap-3 text-sm text-ink-muted/80">
                            <span>{translateDisplayText(language, item.observationType)}</span>
                            <span className="w-1 h-1 rounded-full bg-ink-muted/30"></span>
                            <span>{new Date(item.measuredAt).toLocaleString(undefined, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })}</span>
                          </div>
                          
                          {item.notes && (
                            <div className="mt-4 p-3 bg-white/5 rounded-lg border border-white/10">
                              <LocalizedText as="p" className="text-sm text-ink/90 leading-relaxed" value={item.notes} />
                            </div>
                          )}
                        </div>
                        
                        <div className="flex flex-row sm:flex-col items-center sm:items-end gap-2 shrink-0">
                          <span className="text-[10px] font-bold uppercase tracking-widest bg-white/5 border border-white/10 px-2.5 py-1 rounded-md text-ink-muted whitespace-nowrap">
                            {translateDisplayText(language, item.source)}
                          </span>
                          {item.abnormalFlag && (
                            <span className="text-[10px] font-bold uppercase tracking-widest bg-alert/10 border border-alert/20 text-alert px-2.5 py-1 rounded-md">
                              ABNORMAL
                            </span>
                          )}
                        </div>
                        
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>

          </div>

        </div>
      </main>
    </div>
  );
}

import { Link, useNavigate } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import { useAuth } from "../context/AuthContext";
import { useLanguage } from "../context/LanguageContext";
import { fetchPatientPrescriptions } from "../services/telecareService";
import { getApiErrorMessage } from "../utils/apiError";
import PatientSidebar from "../components/PatientSidebar";
import { User, LogOut, Pill, AlertTriangle, RefreshCw, FileText, CalendarDays, ShieldCheck, Truck } from "lucide-react";
import { buildLoginRedirect } from "../utils/authSession";
import LanguageSwitcher from "../components/LanguageSwitcher";
import { useState, useEffect } from "react";
import { Client } from "@stomp/stompjs";
import SockJS from "sockjs-client";
import { MapContainer, TileLayer, Marker, Popup } from 'react-leaflet';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';

// Fix Leaflet's default icon path issues with Webpack/Vite
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon-2x.png',
  iconUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon.png',
  shadowUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-shadow.png',
});

export default function PatientPrescriptionsPage() {
  const { auth, logout } = useAuth();
  const { language, t } = useLanguage();
  const navigate = useNavigate();
  const patientId = auth?.profileId;
  
  const [activeDelivery, setActiveDelivery] = useState(null);

  const {
    data: prescriptionsData,
    isLoading: loading,
    error: queryError,
    refetch: load
  } = useQuery({
    queryKey: ["prescriptions", patientId],
    queryFn: () => fetchPatientPrescriptions(patientId),
    enabled: !!patientId,
  });

  const prescriptions = Array.isArray(prescriptionsData) ? prescriptionsData : [];

  useEffect(() => {
    if (!prescriptions.length) return;

    const client = new Client({
      webSocketFactory: () => new SockJS("http://localhost:8080/ws-telecare"),
      onConnect: () => {
        prescriptions.forEach(p => {
          client.subscribe(`/topic/delivery/${p.id}`, (message) => {
            const body = JSON.parse(message.body);
            setActiveDelivery(prev => ({
              ...prev,
              orderId: body.orderId,
              prescriptionId: p.id,
              lat: body.lat,
              lng: body.lng,
              status: body.status
            }));
          });
        });
      },
    });

    client.activate();
    return () => client.deactivate();
  }, [prescriptions]);
  const error = queryError ? getApiErrorMessage(queryError, "Unable to load prescriptions.") : "";

  const handleLogout = () => {
    logout();
    navigate(buildLoginRedirect(""), { replace: true });
  };

  return (
    <div className="min-h-screen bg-canvas text-ink font-sans flex flex-col lg:flex-row">
      <PatientSidebar />
      
      <main className="flex-1 p-6 lg:p-10 min-w-0" role="main">
        {/* Topbar */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4 animate-fadeSlideUp">
          <div>
            <h1 className="font-display text-3xl font-medium mb-2">Prescriptions</h1>
            <p className="text-ink-muted text-sm mb-3">View your medical prescriptions and doctor's notes.</p>
            <div className="flex gap-2 items-center mt-3">
              <span className="inline-flex items-center gap-1.5 text-xs px-2.5 py-1 rounded-full bg-white/5 border border-white/10 text-ink-muted">
                <Pill size={12} className="text-primary" />Medications
              </span>
              <div className="inline-flex items-center gap-2 text-xs text-ink-muted bg-white/5 border border-white/10 px-3 py-1.5 rounded-full">
                <User size={14} />
                Signed in as {auth?.fullName || "Anita Patient"}
              </div>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <LanguageSwitcher hideLabel />
            <button 
              onClick={handleLogout} 
              aria-label="Log out"
              className="inline-flex items-center gap-2 px-4 py-2 bg-transparent text-ink-muted border border-white/10 rounded-element text-sm font-medium hover:bg-white/5 hover:text-ink transition-colors"
            >
              <LogOut size={16} />Logout
            </button>
          </div>
        </div>

        <div className="max-w-4xl animate-fadeSlideUp" style={{animationDelay: '0.1s'}}>
          
          <div className="flex justify-between items-center mb-6">
            <h2 className="font-display text-2xl font-medium">Prescription History</h2>
          </div>

          {loading ? (
            <div className="flex flex-col gap-4">
              {[1, 2].map(i => (
                <div key={i} className="card-premium h-32 animate-pulse flex flex-col justify-center">
                  <div className="h-6 w-1/3 bg-white/10 rounded mb-4"></div>
                  <div className="h-4 w-full bg-white/10 rounded"></div>
                </div>
              ))}
            </div>
          ) : error ? (
            <div className="flex flex-col items-center justify-center p-12 text-center bg-alert/5 border border-alert/20 rounded-xl">
              <AlertTriangle size={32} className="text-alert mb-4" />
              <h3 className="font-display text-lg mb-2">Unable to load prescriptions</h3>
              <p className="text-sm text-ink-muted mb-6">{error}</p>
              <button className="px-4 py-2 border border-white/20 rounded-element text-sm font-medium hover:bg-white/5 transition-colors flex items-center gap-2" onClick={load}>
                <RefreshCw size={16} /> Retry
              </button>
            </div>
          ) : !prescriptions.length ? (
            <div className="flex flex-col items-center justify-center p-16 text-center border border-white/5 rounded-xl border-dashed">
              <ShieldCheck size={48} className="text-ink-muted/30 mb-4" />
              <h3 className="font-display text-lg mb-2">No Prescriptions Available</h3>
              <p className="text-sm text-ink-muted mb-6">Prescriptions will appear here after a consultation is completed.</p>
              <button className="px-4 py-2 border border-white/20 rounded-element text-sm font-medium hover:bg-white/5 transition-colors inline-flex items-center gap-2" onClick={load}>
                <RefreshCw size={14}/> Check again
              </button>
            </div>
          ) : (
            <div className="space-y-6">
              {prescriptions.map((prescription) => (
                <div key={prescription.id} className="card-premium">
                  <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-white/10 pb-5 mb-5">
                    <div>
                      <h3 className="font-medium text-lg mb-1">{prescription.doctorName}</h3>
                      <p className="text-sm text-ink-muted flex items-center gap-1.5 font-mono">
                        <CalendarDays size={14} /> Follow-up: {prescription.followUpDate || "Not scheduled"}
                      </p>
                    </div>
                    <div className="flex flex-wrap items-center gap-3">
                      {activeDelivery?.prescriptionId === prescription.id && (
                        <span className="text-sm text-primary flex items-center gap-1.5 font-semibold bg-primary/10 px-3 py-1.5 rounded-full">
                          <Truck size={16} /> Delivery in Progress
                        </span>
                      )}
                      <Link to={`/patient/prescriptions/${prescription.id}/print`} className="inline-flex items-center gap-2 px-4 py-2 bg-white/5 text-ink-muted hover:text-ink hover:bg-white/10 border border-white/10 rounded-element text-sm font-medium transition-colors">
                        <FileText size={16} /> Print
                      </Link>
                    </div>
                  </div>
                  
                  {prescription.notes && (
                    <div className="mb-6 p-4 bg-primary/5 rounded-xl border-l-4 border-primary">
                      <p className="text-sm text-ink italic leading-relaxed">"{prescription.notes}"</p>
                    </div>
                  )}

                  <h4 className="text-sm font-semibold text-ink-muted uppercase tracking-widest mb-4">Medications</h4>
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                    {(Array.isArray(prescription.medications) ? prescription.medications : []).map((medicine) => (
                      <div key={medicine.id} className="bg-white/5 border border-white/10 rounded-xl p-4 transition-colors hover:bg-white/10">
                        <p className="font-medium text-ink mb-2">{medicine.medicineName}</p>
                        <p className="text-sm text-ink-muted mb-1 font-mono">{medicine.dosage} <span className="opacity-50">|</span> {medicine.frequency}</p>
                        <p className="text-xs text-ink-muted uppercase tracking-wider mt-2 pt-2 border-t border-white/10">Duration: {medicine.durationDays} days</p>
                      </div>
                    ))}
                  </div>

                  {activeDelivery?.prescriptionId === prescription.id && (
                    <div className="mt-6 p-5 bg-white/5 rounded-xl border border-primary/50 relative overflow-hidden">
                      <div className="absolute inset-0 bg-primary/5 pointer-events-none"></div>
                      <h4 className="text-base font-semibold text-ink flex items-center gap-2 mb-4 relative z-10">
                        <Truck size={18} className="text-primary" />
                        Live Delivery Tracking 
                        <span className="text-[10px] text-amber-500 bg-amber-500/10 px-2 py-0.5 rounded border border-amber-500/20 ml-2">
                          (Simulated / Estimated)
                        </span>
                        <span className="text-[10px] bg-primary text-canvas px-2.5 py-1 rounded-full ml-auto uppercase tracking-wider font-bold">
                          {activeDelivery.status.replace(/_/g, ' ')}
                        </span>
                      </h4>
                      
                      <div className="relative w-full h-[300px] bg-surface rounded-xl overflow-hidden border border-white/10 z-10">
                        <MapContainer center={[activeDelivery.lat, activeDelivery.lng]} zoom={14} style={{ height: '100%', width: '100%' }}>
                          <TileLayer
                            attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
                            url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
                          />
                          <Marker position={[activeDelivery.lat, activeDelivery.lng]}>
                            <Popup>
                              ≡ƒÜÜ Out for Delivery
                            </Popup>
                          </Marker>
                          <Marker position={[40.7128, -74.0060]}>
                            <Popup>
                              ≡ƒÅá Destination
                            </Popup>
                          </Marker>
                        </MapContainer>
                      </div>
                      <p className="text-xs text-ink-muted mt-3 text-center font-mono relative z-10">
                        Driver Coordinates: {activeDelivery.lat?.toFixed(5)}, {activeDelivery.lng?.toFixed(5)}
                      </p>
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}

        </div>
      </main>
    </div>
  );
}

import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { useLanguage } from "../context/LanguageContext";
import { fetchPatientProfile, updatePatientProfile } from "../services/telecareService";
import { getApiErrorMessage } from "../utils/apiError";
import { supportedLanguages, translateDisplayText } from "../utils/i18n";
import { useToast } from "../components/ui/ToastProvider";
import PatientSidebar from "../components/PatientSidebar";
import { User, LogOut, FileText, UserCircle, Save, AlertTriangle, ShieldCheck } from "lucide-react";
import { buildLoginRedirect } from "../utils/authSession";
import LanguageSwitcher from "../components/LanguageSwitcher";
import DataAccessTransparencyPanel from "../components/patient/DataAccessTransparencyPanel";

export default function PatientProfilePage() {
  const { auth, logout } = useAuth();
  const navigate = useNavigate();
  const { language, t, translateUiText = (value) => translateDisplayText(language, value) } = useLanguage();
  const { pushToast } = useToast();
  const patientId = auth?.profileId;
  
  const [form, setForm] = useState(null);
  const [loadError, setLoadError] = useState("");
  const [saveError, setSaveError] = useState("");
  const [saving, setSaving] = useState(false);

  const buildFormFromProfile = (data) => ({
    fullName: data?.user?.fullName || "",
    email: data?.user?.email || "",
    phone: data?.user?.phone || "",
    preferredLanguage: data?.user?.preferredLanguage || "en",
    age: data?.age ?? "",
    gender: data?.gender || "",
    bloodGroup: data?.bloodGroup || "",
    allergies: data?.allergies || "",
    diseases: data?.diseases || "",
    emergencyContactName: data?.emergencyContactName || "",
    emergencyContactPhone: data?.emergencyContactPhone || "",
    medicalHistorySummary: data?.medicalHistorySummary || "",
    emailNotificationsEnabled: data?.user?.emailNotificationsEnabled ?? true,
    smsNotificationsEnabled: data?.user?.smsNotificationsEnabled ?? false,
    pushNotificationsEnabled: data?.user?.pushNotificationsEnabled ?? true
  });

  useEffect(() => {
    if (!patientId) {
      setForm(null);
      setLoadError("Unable to load profile.");
      return;
    }
    fetchPatientProfile(patientId)
      .then((data) => {
        setForm(buildFormFromProfile(data));
        setLoadError("");
      })
      .catch((err) => {
        setForm(null);
        setLoadError(getApiErrorMessage(err, "Unable to load profile."));
      });
  }, [patientId, language]);

  const handleSave = async () => {
    try {
      setSaving(true);
      setSaveError("");
      await updatePatientProfile(patientId, form);
      try {
        const refreshed = await fetchPatientProfile(patientId);
        setForm(buildFormFromProfile(refreshed));
        pushToast({ type: "success", title: "Profile Saved", message: "Your profile has been successfully updated." });
      } catch (refreshError) {
        const message = getApiErrorMessage(refreshError, "Unable to load profile.");
        setSaveError(message);
        pushToast({ type: "error", title: "Error", message });
      }
    } catch (err) {
      const message = getApiErrorMessage(err, "Unable to save profile.");
      setSaveError(message);
      pushToast({ type: "error", title: "Error", message });
    } finally {
      setSaving(false);
    }
  };

  const handleLogout = () => {
    logout();
    navigate(buildLoginRedirect(""), { replace: true });
  };

  const languageOptions = supportedLanguages;
  const genderOptions = ["Female", "Male", "Other"];

  return (
    <div className="min-h-screen bg-canvas text-ink font-sans flex flex-col lg:flex-row">
      <PatientSidebar />
      
      <main className="flex-1 p-6 lg:p-10 min-w-0" role="main">
        {/* Topbar */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4 animate-fadeSlideUp">
          <div>
            <h1 className="font-display text-3xl font-medium mb-2">Patient Profile</h1>
            <p className="text-ink-muted text-sm mb-3">Manage your personal information and clinical details.</p>
            <div className="flex gap-2 items-center mt-3">
              <span className="inline-flex items-center gap-1.5 text-xs px-2.5 py-1 rounded-full bg-white/5 border border-white/10 text-ink-muted">
                <UserCircle size={12} className="text-primary" />Profile
              </span>
              <div className="inline-flex items-center gap-2 text-xs text-ink-muted bg-white/5 border border-white/10 px-3 py-1.5 rounded-full">
                <User size={14} />
                Signed in as {auth?.fullName || "Anita Patient"}
              </div>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <LanguageSwitcher hideLabel />
            <button 
              onClick={handleLogout} 
              aria-label="Log out"
              className="inline-flex items-center gap-2 px-4 py-2 bg-transparent text-ink-muted border border-white/10 rounded-element text-sm font-medium hover:bg-white/5 hover:text-ink transition-colors"
            >
              <LogOut size={16} />Logout
            </button>
          </div>
        </div>

        <div className="max-w-5xl animate-fadeSlideUp" style={{animationDelay: '0.1s'}}>
          
          <div className="flex items-center gap-4 mb-6">
             <h3 className="font-display text-xl font-medium">Personal & Medical Info</h3>
             <div className="flex-1 h-px bg-white/10"></div>
          </div>

          {loadError ? (
            <div className="flex flex-col items-center justify-center p-12 text-center bg-alert/5 border border-alert/20 rounded-xl mt-8">
              <AlertTriangle size={32} className="text-alert mb-4" />
              <h3 className="font-display text-lg mb-2">Unable to load profile</h3>
              <p className="text-sm text-ink-muted">{loadError}</p>
            </div>
          ) : !form ? (
            <div className="card-premium !bg-surface mt-8">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {[1,2,3,4,5,6].map(i => <div key={i} className="card-premium h-16 animate-pulse bg-white/5"></div>)}
              </div>
            </div>
          ) : (
            <div className="card-premium !bg-surface mt-8">
              
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                
                {/* Identity */}
                <div className="flex flex-col gap-4">
                  <h4 className="text-sm font-semibold uppercase tracking-widest text-primary mb-2 flex items-center gap-2">
                    <UserCircle size={18} /> Identity & Contact
                  </h4>
                  
                  <div>
                    <label className="block text-xs font-semibold text-ink-muted uppercase tracking-widest mb-2">Full Name</label>
                    <input 
                      type="text" 
                      value={form.fullName} 
                      onChange={e => setForm({...form, fullName: e.target.value})}
                      className="w-full p-3 bg-white/5 border border-white/10 rounded-xl text-ink outline-none focus:border-primary/50 transition-colors" 
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-semibold text-ink-muted uppercase tracking-widest mb-2">Email</label>
                    <input 
                      type="email" 
                      value={form.email} 
                      onChange={e => setForm({...form, email: e.target.value})}
                      className="w-full p-3 bg-white/5 border border-white/10 rounded-xl text-ink outline-none focus:border-primary/50 transition-colors" 
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-semibold text-ink-muted uppercase tracking-widest mb-2">Phone</label>
                    <input 
                      type="text" 
                      value={form.phone} 
                      onChange={e => setForm({...form, phone: e.target.value})}
                      className="w-full p-3 bg-white/5 border border-white/10 rounded-xl text-ink outline-none focus:border-primary/50 transition-colors" 
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-semibold text-ink-muted uppercase tracking-widest mb-2">Preferred Language</label>
                    <select 
                      value={form.preferredLanguage} 
                      onChange={e => setForm({...form, preferredLanguage: e.target.value})}
                      className="w-full p-3 bg-white/5 border border-white/10 rounded-xl text-ink outline-none focus:border-primary/50 transition-colors"
                    >
                      {languageOptions.map(option => (
                        <option key={option.code} value={option.code} className="bg-canvas">{translateDisplayText(language, option.code)}</option>
                      ))}
                    </select>
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-xs font-semibold text-ink-muted uppercase tracking-widest mb-2">Age</label>
                      <input 
                        type="number" 
                        value={form.age} 
                        onChange={e => setForm({...form, age: Number(e.target.value)})}
                        className="w-full p-3 bg-white/5 border border-white/10 rounded-xl text-ink outline-none focus:border-primary/50 transition-colors" 
                      />
                    </div>
                    <div>
                      <label className="block text-xs font-semibold text-ink-muted uppercase tracking-widest mb-2">Gender</label>
                      <select 
                        value={form.gender} 
                        onChange={e => setForm({...form, gender: e.target.value})}
                        className="w-full p-3 bg-white/5 border border-white/10 rounded-xl text-ink outline-none focus:border-primary/50 transition-colors"
                      >
                        <option value="" className="bg-canvas">Not set</option>
                        {genderOptions.map(option => (
                          <option key={option} value={option} className="bg-canvas">{translateDisplayText(language, option)}</option>
                        ))}
                      </select>
                    </div>
                  </div>
                </div>

                {/* Clinical */}
                <div className="flex flex-col gap-4">
                  <h4 className="text-sm font-semibold uppercase tracking-widest text-primary mb-2 flex items-center gap-2">
                    <FileText size={18} /> Medical & Emergency
                  </h4>

                  <div>
                    <label className="block text-xs font-semibold text-ink-muted uppercase tracking-widest mb-2">Blood Group</label>
                    <input 
                      type="text" 
                      value={form.bloodGroup} 
                      onChange={e => setForm({...form, bloodGroup: e.target.value})}
                      className="w-full p-3 bg-white/5 border border-white/10 rounded-xl text-ink outline-none focus:border-primary/50 transition-colors" 
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-semibold text-ink-muted uppercase tracking-widest mb-2">Allergies</label>
                    <input 
                      type="text" 
                      value={form.allergies} 
                      onChange={e => setForm({...form, allergies: e.target.value})}
                      className="w-full p-3 bg-white/5 border border-white/10 rounded-xl text-ink outline-none focus:border-primary/50 transition-colors" 
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-semibold text-ink-muted uppercase tracking-widest mb-2">Pre-existing Diseases</label>
                    <input 
                      type="text" 
                      value={form.diseases} 
                      onChange={e => setForm({...form, diseases: e.target.value})}
                      className="w-full p-3 bg-white/5 border border-white/10 rounded-xl text-ink outline-none focus:border-primary/50 transition-colors" 
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-semibold text-ink-muted uppercase tracking-widest mb-2">Emergency Contact Name</label>
                    <input 
                      type="text" 
                      value={form.emergencyContactName} 
                      onChange={e => setForm({...form, emergencyContactName: e.target.value})}
                      className="w-full p-3 bg-white/5 border border-white/10 rounded-xl text-ink outline-none focus:border-primary/50 transition-colors" 
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-semibold text-ink-muted uppercase tracking-widest mb-2">Emergency Contact Phone</label>
                    <input 
                      type="text" 
                      value={form.emergencyContactPhone} 
                      onChange={e => setForm({...form, emergencyContactPhone: e.target.value})}
                      className="w-full p-3 bg-white/5 border border-white/10 rounded-xl text-ink outline-none focus:border-primary/50 transition-colors" 
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-semibold text-ink-muted uppercase tracking-widest mb-2">Medical History Summary</label>
                    <textarea 
                      value={form.medicalHistorySummary} 
                      onChange={e => setForm({...form, medicalHistorySummary: e.target.value})}
                      className="w-full min-h-[100px] p-3 bg-white/5 border border-white/10 rounded-xl text-ink outline-none focus:border-primary/50 transition-colors resize-y" 
                    />
                  </div>
                </div>

              </div>

              {/* Notification Preferences */}
              <div className="mt-8 pt-8 border-t border-white/10">
                <h4 className="text-sm font-semibold uppercase tracking-widest text-primary mb-4 flex items-center gap-2">
                  <ShieldCheck size={18} /> Notification Preferences
                </h4>
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
                  <label className="flex items-center gap-3 cursor-pointer">
                    <input 
                      type="checkbox" 
                      checked={form.emailNotificationsEnabled} 
                      onChange={e => setForm({...form, emailNotificationsEnabled: e.target.checked})}
                      className="w-5 h-5 accent-primary bg-white/5 border border-white/10 rounded" 
                    />
                    <span className="text-sm text-ink font-medium">Email Notifications</span>
                  </label>
                  <label className="flex items-center gap-3 cursor-pointer">
                    <input 
                      type="checkbox" 
                      checked={form.smsNotificationsEnabled} 
                      onChange={e => setForm({...form, smsNotificationsEnabled: e.target.checked})}
                      className="w-5 h-5 accent-primary bg-white/5 border border-white/10 rounded" 
                    />
                    <span className="text-sm text-ink font-medium">SMS Notifications</span>
                  </label>
                  <label className="flex items-center gap-3 cursor-pointer">
                    <input 
                      type="checkbox" 
                      checked={form.pushNotificationsEnabled} 
                      onChange={e => setForm({...form, pushNotificationsEnabled: e.target.checked})}
                      className="w-5 h-5 accent-primary bg-white/5 border border-white/10 rounded" 
                    />
                    <span className="text-sm text-ink font-medium">Push Notifications</span>
                  </label>
                </div>
              </div>

              <div className="mt-8 pt-6 border-t border-white/10 flex items-center justify-end gap-4">
                {saveError && <p className="text-sm font-medium text-alert animate-fadeIn">{saveError}</p>}
                <button 
                  className="btn-primary py-2.5 px-6 flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed" 
                  disabled={saving} 
                  onClick={handleSave}
                >
                  <Save size={18} className={saving ? "animate-pulse" : ""} /> {saving ? "Saving..." : "Save Profile"}
                </button>
              </div>

            </div>
          )}

          {/* Data Access Transparency Panel */}
          {patientId && (
            <DataAccessTransparencyPanel patientId={patientId} />
          )}

        </div>
      </main>
    </div>
  );
}

import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import Badge from "../components/Badge";
import LocalizedText from "../components/LocalizedText";
import AiReportSummaryCard from "../ai/components/AiReportSummaryCard";
import AiMoodInsightsPanel from "../ai/components/AiMoodInsightsPanel";
import { useAuth } from "../context/AuthContext";
import { useLanguage } from "../context/LanguageContext";
import { fetchMedicalRecords } from "../services/telecareService";
import { getApiErrorMessage } from "../utils/apiError";
import { translateDisplayText } from "../utils/i18n";
import PatientSidebar from "../components/PatientSidebar";
import { User, LogOut, FileArchive, RefreshCw, AlertTriangle, FileText, LayoutList, Stethoscope, Pill, AlertCircle } from "lucide-react";
import { buildLoginRedirect } from "../utils/authSession";
import LanguageSwitcher from "../components/LanguageSwitcher";

export default function PatientRecordsPage() {
  const { auth, logout } = useAuth();
  const navigate = useNavigate();
  const { language, t, translateUiText = (value) => translateDisplayText(language, value) } = useLanguage();
  const patientId = auth?.profileId;
  
  const [records, setRecords] = useState(null);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);

  const load = async () => {
    if (!patientId) {
      setRecords(null);
      setError("Unable to load medical records.");
      setLoading(false);
      return;
    }
    setRecords(null);
    setLoading(true);
    try {
      const data = await fetchMedicalRecords(patientId);
      setRecords(data);
      setError("");
    } catch (err) {
      setError(getApiErrorMessage(err, "Unable to load medical records."));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, [patientId]);

  const handleLogout = () => {
    logout();
    navigate(buildLoginRedirect(""), { replace: true });
  };

  const triageHistory = Array.isArray(records?.triageHistory) ? records.triageHistory : [];
  const consultations = Array.isArray(records?.consultations) ? records.consultations : [];
  const prescriptions = Array.isArray(records?.prescriptions) ? records.prescriptions : [];
  const alerts = Array.isArray(records?.alerts) ? records.alerts : [];
  
  const hasRecordContent = Boolean(
    records?.patientProfile?.medicalHistorySummary ||
    triageHistory.length ||
    consultations.length ||
    prescriptions.length ||
    alerts.length
  );

  return (
    <div className="min-h-screen bg-canvas text-ink font-sans flex flex-col lg:flex-row">
      <PatientSidebar />
      
      <main className="flex-1 p-6 lg:p-10 min-w-0" role="main">
        {/* Topbar */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4 animate-fadeSlideUp">
          <div>
            <h1 className="font-display text-3xl font-medium mb-2">Medical Records</h1>
            <p className="text-ink-muted text-sm mb-3">Comprehensive health history and structured insights.</p>
            <div className="flex gap-2 items-center mt-3">
              <span className="inline-flex items-center gap-1.5 text-xs px-2.5 py-1 rounded-full bg-white/5 border border-white/10 text-ink-muted">
                <FileArchive size={12} className="text-primary" />Health
              </span>
              <div className="inline-flex items-center gap-2 text-xs text-ink-muted bg-white/5 border border-white/10 px-3 py-1.5 rounded-full">
                <User size={14} />
                Signed in as {auth?.fullName || "Anita Patient"}
              </div>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <LanguageSwitcher hideLabel />
            <button 
              onClick={handleLogout} 
              aria-label="Log out"
              className="inline-flex items-center gap-2 px-4 py-2 bg-transparent text-ink-muted border border-white/10 rounded-element text-sm font-medium hover:bg-white/5 hover:text-ink transition-colors"
            >
              <LogOut size={16} />Logout
            </button>
          </div>
        </div>

        <div className="max-w-5xl animate-fadeSlideUp" style={{animationDelay: '0.1s'}}>
          
          {loading ? (
            <div className="flex flex-col gap-6 mt-8">
              {[1,2,3,4].map(i => <div key={i} className="card-premium h-40 animate-pulse bg-white/5"></div>)}
            </div>
          ) : error ? (
            <div className="flex flex-col items-center justify-center p-12 text-center bg-alert/5 border border-alert/20 rounded-xl mt-8">
              <AlertTriangle size={32} className="text-alert mb-4" />
              <h3 className="font-display text-lg mb-2">Unable to load records</h3>
              <p className="text-sm text-ink-muted mb-6">{error}</p>
              <button className="px-4 py-2 border border-white/20 rounded-element text-sm font-medium hover:bg-white/5 transition-colors flex items-center gap-2" onClick={load}><RefreshCw size={16} /> Retry</button>
            </div>
          ) : !hasRecordContent ? (
            <div className="flex flex-col items-center justify-center p-16 text-center border border-white/5 rounded-xl border-dashed min-h-[300px] mt-8">
              <FileArchive size={48} className="text-ink-muted/30 mb-4" />
              <h3 className="font-display text-lg mb-2">No Medical Records Yet</h3>
              <p className="text-sm text-ink-muted max-w-[300px] leading-relaxed mb-6">No structured medical records are available yet. They will appear here after triage, consultation, or prescription activity.</p>
              <button className="px-4 py-2 bg-white/5 border border-white/20 rounded-element text-sm font-medium hover:bg-white/10 transition-colors flex items-center gap-2" onClick={load}><RefreshCw size={16} /> Refresh</button>
            </div>
          ) : (
            <div className="space-y-12 mt-8">
              
              {/* Medical History Summary */}
              <div className="flex flex-col">
                <div className="flex items-center gap-4 mb-6">
                   <h2 className="font-display text-xl font-medium text-white">Clinical Summary</h2>
                   <div className="flex-1 h-px bg-white/10"></div>
                </div>

                <div className="card-premium !bg-surface">
                  <h3 className="text-sm font-semibold uppercase tracking-widest text-primary mb-4 flex items-center gap-2">
                    <FileText size={18} /> Patient Context
                  </h3>
                  {records.patientProfile?.medicalHistorySummary ? (
                    <LocalizedText as="p" className="text-[15px] leading-relaxed text-ink/90 bg-white/5 p-4 rounded-xl border border-white/10" value={records.patientProfile.medicalHistorySummary} />
                  ) : (
                    <p className="text-[15px] text-ink-muted italic bg-white/5 p-4 rounded-xl border border-white/10">No history summary recorded.</p>
                  )}
                </div>
              </div>

              {/* AI Panels */}
              <div className="flex flex-col">
                <div className="flex items-center gap-4 mb-6">
                   <h2 className="font-display text-xl font-medium text-white">AI Insights</h2>
                   <div className="flex-1 h-px bg-white/10"></div>
                </div>
                
                <div className="flex flex-col gap-6">
                  <AiReportSummaryCard patientId={patientId} />
                  <AiMoodInsightsPanel patientId={patientId} />
                </div>
              </div>

              {/* Timeline */}
              <div className="flex flex-col">
                <div className="flex items-center gap-4 mb-6">
                   <h2 className="font-display text-xl font-medium text-white">Structured Record Timeline</h2>
                   <div className="flex-1 h-px bg-white/10"></div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  
                  {/* Triage */}
                  <div className="card-premium !bg-surface flex flex-col">
                    <h3 className="text-sm font-semibold uppercase tracking-widest text-ink-muted mb-5 flex items-center gap-2">
                      <LayoutList size={18} className="text-primary" /> Triage History
                    </h3>
                    {triageHistory.length > 0 ? (
                      <div className="flex flex-wrap gap-2">
                        {triageHistory.map(item => (
                          <Badge key={item.id} value={item.level} />
                        ))}
                      </div>
                    ) : (
                      <p className="text-sm text-ink-muted italic">No triage history available.</p>
                    )}
                  </div>

                  {/* Consultations */}
                  <div className="card-premium !bg-surface flex flex-col justify-center items-center text-center p-8">
                    <div className="w-12 h-12 rounded-full bg-primary/10 flex items-center justify-center text-primary mb-4 border border-primary/20">
                      <Stethoscope size={24} />
                    </div>
                    <p className="text-3xl font-display font-medium text-ink mb-1">{consultations.length}</p>
                    <p className="text-sm text-ink-muted font-medium">Consultations Recorded</p>
                  </div>

                  {/* Prescriptions */}
                  <div className="card-premium !bg-surface flex flex-col justify-center items-center text-center p-8">
                    <div className="w-12 h-12 rounded-full bg-primary/10 flex items-center justify-center text-primary mb-4 border border-primary/20">
                      <Pill size={24} />
                    </div>
                    <p className="text-3xl font-display font-medium text-ink mb-1">{prescriptions.length}</p>
                    <p className="text-sm text-ink-muted font-medium">Prescription Records Available</p>
                  </div>

                  {/* Alerts */}
                  <div className="card-premium !bg-surface flex flex-col">
                    <h3 className="text-sm font-semibold uppercase tracking-widest text-ink-muted mb-5 flex items-center gap-2">
                      <AlertCircle size={18} className="text-alert" /> Active Alerts
                    </h3>
                    {alerts.length > 0 ? (
                      <div className="flex flex-col gap-4">
                        {alerts.map(alert => (
                          <div key={alert.id} className="p-3 bg-white/5 rounded-xl border border-white/10 flex flex-col gap-2 items-start">
                            <Badge value={alert.severity} />
                            <LocalizedText as="p" className="text-sm leading-relaxed text-ink/90" value={alert.message} />
                          </div>
                        ))}
                      </div>
                    ) : (
                      <p className="text-sm text-ink-muted italic">No active alerts.</p>
                    )}
                  </div>

                </div>
              </div>

            </div>
          )}
          
        </div>
      </main>
    </div>
  );
}

import { useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { useLanguage } from "../context/LanguageContext";
import { fetchAdherence, fetchPatientReminders, updateReminderStatus } from "../services/telecareService";
import { getApiErrorMessage } from "../utils/apiError";
import { useToast } from "../components/ui/ToastProvider";
import PatientSidebar from "../components/PatientSidebar";
import { User, LogOut, Bell, Search, AlertTriangle, RefreshCw, CheckCircle2, ShieldCheck, XCircle, Clock, TrendingUp, TrendingDown, Minus } from "lucide-react";
import { buildLoginRedirect } from "../utils/authSession";
import LanguageSwitcher from "../components/LanguageSwitcher";

export default function PatientRemindersPage() {
  const { auth, logout } = useAuth();
  const { language, t } = useLanguage();
  const { pushToast } = useToast();
  const navigate = useNavigate();
  const patientId = auth?.profileId;
  
  const [reminders, setReminders] = useState([]);
  const [adherence, setAdherence] = useState(null);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);
  const [updatingReminderId, setUpdatingReminderId] = useState(null);
  const [filter, setFilter] = useState("All");
  const [search, setSearch] = useState("");

  const parseScheduledDate = (value) => {
    if (!value) return null;
    const date = new Date(`${value}T00:00:00`);
    return Number.isNaN(date.getTime()) ? null : date;
  };

  const startOfToday = useMemo(() => {
    const now = new Date();
    return new Date(now.getFullYear(), now.getMonth(), now.getDate());
  }, []);

  const toEffectiveStatus = (item) => {
    if (!item) return "PENDING";
    if (item.status && item.status !== "PENDING") return item.status;
    const scheduled = parseScheduledDate(item.scheduledDate);
    if (!scheduled) return item.status || "PENDING";
    return scheduled < startOfToday ? "MISSED" : (item.status || "PENDING");
  };

  const dedupeReminders = (items) => {
    const seen = new Set();
    const result = [];
    items.forEach((item) => {
      const key = [
        item.medicineName || "",
        item.dosage || "",
        item.frequency || "",
        item.scheduledDate || "",
        item.status || ""
      ].join("|");
      if (!seen.has(key)) {
        seen.add(key);
        result.push(item);
      }
    });
    return result;
  };

  const load = async () => {
    if (!patientId) {
      setReminders([]);
      setAdherence(null);
      setError("Unable to load reminders.");
      setLoading(false);
      return;
    }
    setLoading(true);
    try {
      const [reminderData, adherenceData] = await Promise.all([
        fetchPatientReminders(patientId),
        fetchAdherence(patientId)
      ]);
      const normalized = Array.isArray(reminderData) ? reminderData : [];
      const deduped = dedupeReminders(normalized);
      const enriched = deduped.map((item) => ({
        ...item,
        effectiveStatus: toEffectiveStatus(item)
      }));
      setReminders(enriched);
      setAdherence(adherenceData);
      setError("");
    } catch (err) {
      setError(getApiErrorMessage(err, "Unable to load reminders."));
      setReminders([]);
      setAdherence(null);
    } finally {
      setLoading(false);
    }
  };

  const updateStatus = async (reminderId, status) => {
    setUpdatingReminderId(reminderId);
    setError("");
    try {
      await updateReminderStatus(reminderId, { status });
      pushToast({
        type: "success",
        title: "Reminders",
        message: status === "TAKEN" ? "Reminder marked as taken." : "Reminder marked as missed."
      });
      await load();
    } catch (err) {
      const message = getApiErrorMessage(err, "Unable to update reminder status.");
      setError(message);
      pushToast({ type: "error", title: "Error", message });
    } finally {
      setUpdatingReminderId(null);
    }
  };

  useEffect(() => {
    load();
  }, [patientId]);

  const filteredReminders = useMemo(() => {
    const query = search.trim().toLowerCase();
    return reminders.filter((item) => {
      const status = item.effectiveStatus || item.status || "PENDING";
      if (filter !== "All" && status !== filter.toUpperCase()) return false;
      if (!query) return true;
      const target = `${item.medicineName ?? ""} ${item.dosage ?? ""} ${item.frequency ?? ""}`.toLowerCase();
      return target.includes(query);
    });
  }, [filter, reminders, search]);

  const groupedReminders = useMemo(() => {
    const groups = {
      today: [],
      yesterday: [],
      week: [],
      older: []
    };
    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const yesterday = new Date(today);
    yesterday.setDate(today.getDate() - 1);
    const weekStart = new Date(today);
    weekStart.setDate(today.getDate() - 6);

    filteredReminders.forEach((item) => {
      const scheduled = parseScheduledDate(item.scheduledDate);
      if (!scheduled) {
        groups.older.push(item);
        return;
      }
      if (scheduled >= today && scheduled < new Date(today.getTime() + 24 * 60 * 60 * 1000)) {
        groups.today.push(item);
      } else if (scheduled >= yesterday && scheduled < today) {
        groups.yesterday.push(item);
      } else if (scheduled >= weekStart) {
        groups.week.push(item);
      } else {
        groups.older.push(item);
      }
    });
    return groups;
  }, [filteredReminders, startOfToday]);

  const adherencePercentage = Number(adherence?.adherencePercentage ?? 0);
  
  let trendIcon = <Minus size={24} className="text-ink-muted" />;
  let trendColorClass = "border-ink-muted bg-white/5";
  let trendText = "Steady adherence trend";
  
  if (adherencePercentage >= 80) {
    trendIcon = <TrendingUp size={24} className="text-primary" />;
    trendColorClass = "border-primary/50 bg-primary/10";
    trendText = "Great consistency on your regimen";
  } else if (adherencePercentage < 50 && adherencePercentage > 0) {
    trendIcon = <TrendingDown size={24} className="text-alert" />;
    trendColorClass = "border-alert/50 bg-alert/10";
    trendText = "Slight dip in adherence ΓÇö check in with your care team";
  } else if (adherencePercentage === 0) {
    trendText = "No data yet ΓÇö your trend will appear here as you log doses.";
  }

  const handleLogout = () => {
    logout();
    navigate(buildLoginRedirect(""), { replace: true });
  };

  return (
    <div className="min-h-screen bg-canvas text-ink font-sans flex flex-col lg:flex-row">
      <PatientSidebar />
      
      <main className="flex-1 p-6 lg:p-10 min-w-0" role="main">
        {/* Topbar */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4 animate-fadeSlideUp">
          <div>
            <h1 className="font-display text-3xl font-medium mb-2">Reminders</h1>
            <p className="text-ink-muted text-sm mb-3">Track your scheduled medications and adherence trends.</p>
            <div className="flex gap-2 items-center mt-3">
              <span className="inline-flex items-center gap-1.5 text-xs px-2.5 py-1 rounded-full bg-white/5 border border-white/10 text-ink-muted">
                <Bell size={12} className="text-primary" />Medications
              </span>
              <div className="inline-flex items-center gap-2 text-xs text-ink-muted bg-white/5 border border-white/10 px-3 py-1.5 rounded-full">
                <User size={14} />
                Signed in as {auth?.fullName || "Anita Patient"}
              </div>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <LanguageSwitcher hideLabel />
            <button 
              onClick={handleLogout} 
              aria-label="Log out"
              className="inline-flex items-center gap-2 px-4 py-2 bg-transparent text-ink-muted border border-white/10 rounded-element text-sm font-medium hover:bg-white/5 hover:text-ink transition-colors"
            >
              <LogOut size={16} />Logout
            </button>
          </div>
        </div>

        <div className="max-w-4xl animate-fadeSlideUp" style={{animationDelay: '0.1s'}}>
          
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center flex-wrap gap-4 mb-6">
            <div>
              <h2 className="font-display text-2xl font-medium mb-3">Overview</h2>
              <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
                {['All', 'Pending', 'Taken', 'Missed'].map(f => (
                  <button 
                    key={f} 
                    className={`px-4 py-1.5 rounded-full text-xs font-medium transition-colors border border-white/10 whitespace-nowrap ${filter === f ? 'bg-primary text-canvas border-primary' : 'bg-transparent text-ink-muted hover:text-ink hover:bg-white/5'}`}
                    onClick={() => setFilter(f)}
                  >
                    {f}
                  </button>
                ))}
              </div>
            </div>
            
            <div className="relative w-full md:w-auto md:min-w-[280px]">
              <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-ink-muted" />
              <input
                type="text"
                placeholder="Search medication..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="w-full bg-white/5 border border-white/10 rounded-full py-2.5 pl-10 pr-4 text-ink focus:outline-none focus:ring-2 focus:ring-primary/50 placeholder-ink-muted/50 text-sm transition-all"
              />
            </div>
          </div>

          {/* Adherence Insight Card */}
          <div className="card-premium flex items-center gap-5 mb-8">
            <div className={`w-14 h-14 rounded-full flex items-center justify-center shrink-0 border ${trendColorClass}`}>
              {trendIcon}
            </div>
            <div>
              <h3 className="font-medium text-base mb-1">Adherence Insight</h3>
              <p className="text-sm text-ink-muted leading-relaxed">
                {trendText} <span className="opacity-60 block mt-0.5 font-mono text-xs">(~{adherencePercentage}% of recent doses logged)</span>
              </p>
            </div>
          </div>

          {loading && !reminders.length ? (
            <div className="flex flex-col gap-4">
              {[1, 2, 3].map(i => (
                <div key={i} className="card-premium h-24 animate-pulse flex flex-col justify-center">
                  <div className="h-5 w-2/5 bg-white/10 rounded mb-3"></div>
                  <div className="h-4 w-3/5 bg-white/10 rounded"></div>
                </div>
              ))}
            </div>
          ) : error ? (
            <div className="flex flex-col items-center justify-center p-12 text-center bg-alert/5 border border-alert/20 rounded-xl">
              <AlertTriangle size={32} className="text-alert mb-4" />
              <h3 className="font-display text-lg mb-2">Unable to load reminders</h3>
              <p className="text-sm text-ink-muted mb-6">{error}</p>
              <button className="px-4 py-2 border border-white/20 rounded-element text-sm font-medium hover:bg-white/5 transition-colors flex items-center gap-2" onClick={() => load()}>
                <RefreshCw size={16} /> Retry
              </button>
            </div>
          ) : !loading && !error && !reminders.length ? (
            <div className="flex flex-col items-center justify-center p-16 text-center border border-white/5 rounded-xl border-dashed">
              <ShieldCheck size={48} className="text-ink-muted/30 mb-4" />
              <h3 className="font-display text-lg mb-2">No active reminders</h3>
              <p className="text-sm text-ink-muted max-w-md">Reminders will appear here automatically when a prescription is active.</p>
            </div>
          ) : !loading && !error && reminders.length && !filteredReminders.length ? (
            <div className="flex flex-col items-center justify-center p-16 text-center border border-white/5 rounded-xl border-dashed">
              <Search size={48} className="text-ink-muted/30 mb-4" />
              <h3 className="font-display text-lg mb-2">No reminders match</h3>
              <p className="text-sm text-ink-muted">Try a different filter or clear your search input.</p>
            </div>
          ) : (
            <div className="space-y-10">
              {[
                { label: "Today", items: groupedReminders.today },
                { label: "Yesterday", items: groupedReminders.yesterday },
                { label: "Earlier this week", items: groupedReminders.week },
                { label: "Older", items: groupedReminders.older }
              ].map((group) => (
                group.items.length > 0 && (
                  <div key={group.label} className="animate-fadeSlideUp">
                    <div className="flex items-center gap-4 mb-4">
                       <h3 className="text-sm font-semibold tracking-widest uppercase text-ink-muted/80">{group.label}</h3>
                       <div className="flex-1 h-px bg-white/10"></div>
                    </div>
                    <div className="flex flex-col gap-4">
                      {group.items.map((item) => {
                        const status = item.effectiveStatus || item.status || "PENDING";
                        const actionable = status === "PENDING";
                        
                        let statusBadge = null;
                        if (status === 'TAKEN') statusBadge = <span className="inline-flex items-center gap-1.5 px-3 py-1 bg-primary/10 text-primary rounded-full text-xs font-semibold tracking-wider uppercase border border-primary/20"><CheckCircle2 size={14}/> Taken</span>;
                        else if (status === 'MISSED') statusBadge = <span className="inline-flex items-center gap-1.5 px-3 py-1 bg-alert/10 text-alert rounded-full text-xs font-semibold tracking-wider uppercase border border-alert/20"><XCircle size={14}/> Missed</span>;
                        else statusBadge = <span className="inline-flex items-center gap-1.5 px-3 py-1 bg-white/5 text-ink-muted rounded-full text-xs font-semibold tracking-wider uppercase border border-white/10"><Clock size={14}/> Pending</span>;

                        return (
                          <div key={`${item.id}-${item.scheduledDate}`} className="card-premium flex flex-col sm:flex-row sm:items-center justify-between gap-5 hover:border-white/20 transition-colors">
                            <div>
                              <h4 className="text-base font-medium mb-1.5">{item.medicineName || "Medication"}</h4>
                              <p className="text-sm text-ink-muted font-mono flex flex-wrap items-center gap-1.5">
                                <span>{item.dosage || "Dose not set"}</span>
                                <span className="opacity-40">ΓÇó</span>
                                <span>{item.frequency || "Frequency not set"}</span>
                                <span className="opacity-40">ΓÇó</span>
                                <span>{item.scheduledDate}</span>
                              </p>
                            </div>
                            <div className="flex items-center gap-4 flex-wrap">
                              {statusBadge}
                              {actionable && (
                                <div className="flex gap-2">
                                  <button
                                    className="px-4 py-2 bg-primary/10 hover:bg-primary/20 text-primary border border-primary/20 rounded-element text-sm font-medium transition-colors disabled:opacity-50"
                                    disabled={updatingReminderId === item.id}
                                    onClick={() => updateStatus(item.id, "TAKEN")}
                                  >
                                    Mark Taken
                                  </button>
                                  <button
                                    className="px-4 py-2 bg-transparent hover:bg-white/5 text-ink border border-white/20 rounded-element text-sm font-medium transition-colors disabled:opacity-50"
                                    disabled={updatingReminderId === item.id}
                                    onClick={() => updateStatus(item.id, "MISSED")}
                                  >
                                    Missed
                                  </button>
                                </div>
                              )}
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                )
              ))}
            </div>
          )}

        </div>
      </main>
    </div>
  );
}

import LanguageSwitcher from "../components/LanguageSwitcher";
import { useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { useLanguage } from "../context/LanguageContext";
import { fetchPatientTimeline } from "../services/telecareService";
import { getApiErrorMessage } from "../utils/apiError";
import PatientSidebar from "../components/PatientSidebar";
import { User, LogOut, Activity, Bell, CalendarDays, FileText, HeartPulse, MessageSquareText, Pill, AlertTriangle, RefreshCw, Layers } from "lucide-react";
import { buildLoginRedirect } from "../utils/authSession";
import {
  deriveActor,
  deriveStatus,
  formatTimelineDate,
  formatRelativeTimelineDate,
  groupTimelineEvents,
  needsAction,
  normalizeTimelineDate
} from "../utils/timelineUtils";

export default function PatientTimelinePage() {
  const { auth, logout } = useAuth();
  const { language, t } = useLanguage();
  const navigate = useNavigate();
  const patientId = auth?.profileId;
  
  const [timeline, setTimeline] = useState([]);
  const [filter, setFilter] = useState("All");
  const [viewMode, setViewMode] = useState(() => {
    if (typeof window === "undefined") return "comfortable";
    try {
      const stored = localStorage.getItem("telecareplus-timeline-view");
      return stored === "compact" || stored === "comfortable" ? stored : "comfortable";
    } catch {
      return "comfortable";
    }
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const load = async () => {
    if (!patientId) {
      setTimeline([]);
      setError("Unable to load timeline.");
      setLoading(false);
      return;
    }
    setLoading(true);
    try {
      const data = await fetchPatientTimeline(patientId);
      setTimeline(Array.isArray(data) ? data : []);
      setError("");
    } catch (err) {
      setError(getApiErrorMessage(err, "Unable to load timeline."));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, [patientId]);

  const processedTimeline = useMemo(() => {
    const grouped = groupTimelineEvents(timeline);
    return grouped
      .map((item) => {
        const { date, isValid, isSuspiciousFuture } = normalizeTimelineDate(item?.occurredAt);
        const status = deriveStatus(item);
        const actor = deriveActor(item);
        const actionNeeded = needsAction(item, status);
        return {
          ...item,
          displayDate: formatTimelineDate(date),
          relativeDate: formatRelativeTimelineDate(date),
          hasValidDate: isValid,
          suspiciousDate: isSuspiciousFuture,
          status,
          actor,
          actionNeeded
        };
      })
      .sort((a, b) => {
        const aDate = normalizeTimelineDate(a?.occurredAt).date;
        const bDate = normalizeTimelineDate(b?.occurredAt).date;
        if (!aDate && !bDate) return 0;
        if (!aDate) return 1;
        if (!bDate) return -1;
        return bDate.getTime() - aDate.getTime();
      });
  }, [timeline]);

  const filterOptions = [
    { label: "All", value: "All" },
    { label: "Appointments", value: "APPOINTMENT" },
    { label: "Triage", value: "TRIAGE" },
    { label: "Prescriptions", value: "PRESCRIPTION" },
    { label: "Alerts", value: "ALERT" }
  ];

  const filteredTimeline = useMemo(() => {
    if (filter === "All") return processedTimeline;
    return processedTimeline.filter((item) => item.type === filter);
  }, [filter, processedTimeline]);

  const groupedByDate = useMemo(() => {
    const groups = { today: [], yesterday: [], week: [], older: [] };
    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const yesterday = new Date(today); yesterday.setDate(today.getDate() - 1);
    const weekStart = new Date(today); weekStart.setDate(today.getDate() - 6);

    filteredTimeline.forEach((item) => {
      const date = normalizeTimelineDate(item?.occurredAt).date;
      if (!date) {
        groups.older.push(item);
        return;
      }
      const dateOnly = new Date(date.getFullYear(), date.getMonth(), date.getDate());
      if (dateOnly.getTime() === today.getTime()) {
        groups.today.push(item);
      } else if (dateOnly.getTime() === yesterday.getTime()) {
        groups.yesterday.push(item);
      } else if (dateOnly >= weekStart) {
        groups.week.push(item);
      } else {
        groups.older.push(item);
      }
    });

    return groups;
  }, [filteredTimeline]);

  const renderTypeIcon = (type) => {
    const props = { size: 18, className: "text-ink-muted group-hover:text-primary transition-colors" };
    switch (type) {
      case "APPOINTMENT": return <CalendarDays {...props} />;
      case "TRIAGE": return <HeartPulse {...props} />;
      case "PRESCRIPTION": return <Pill {...props} />;
      case "HEALTH": return <Activity {...props} />;
      case "ALERT": return <Bell {...props} />;
      case "CONSULTATION": return <MessageSquareText {...props} />;
      default: return <FileText {...props} />;
    }
  };

  const handleLogout = () => {
    logout();
    navigate(buildLoginRedirect(""), { replace: true });
  };

  return (
    <div className="min-h-screen bg-canvas text-ink font-sans flex flex-col lg:flex-row">
      <PatientSidebar />
      
      <main className="flex-1 p-6 lg:p-10 min-w-0" role="main">
        {/* Topbar */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4 animate-fadeSlideUp">
          <div>
            <h1 className="font-display text-3xl font-medium mb-2">Unified Timeline</h1>
            <p className="text-ink-muted text-sm mb-3">Your complete medical history and continuity of care.</p>
            <div className="flex gap-2 items-center mt-3">
              <span className="inline-flex items-center gap-1.5 text-xs px-2.5 py-1 rounded-full bg-white/5 border border-white/10 text-ink-muted">
                <Activity size={12} className="text-primary" />Health
              </span>
              <div className="inline-flex items-center gap-2 text-xs text-ink-muted bg-white/5 border border-white/10 px-3 py-1.5 rounded-full">
                <User size={14} />
                Signed in as {auth?.fullName || "Anita Patient"}
              </div>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <LanguageSwitcher hideLabel />
            <button 
              onClick={handleLogout} 
              aria-label="Log out"
              className="inline-flex items-center gap-2 px-4 py-2 bg-transparent text-ink-muted border border-white/10 rounded-element text-sm font-medium hover:bg-white/5 hover:text-ink transition-colors"
            >
              <LogOut size={16} />Logout
            </button>
          </div>
        </div>

        <div className="max-w-5xl animate-fadeSlideUp" style={{animationDelay: '0.1s'}}>
          
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-8">
            <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
              {filterOptions.map(f => (
                <button 
                  key={f.value} 
                  className={`px-4 py-1.5 rounded-full text-xs font-medium transition-colors border whitespace-nowrap ${filter === f.value ? 'bg-primary text-canvas border-primary' : 'bg-transparent text-ink-muted border-white/10 hover:text-ink hover:bg-white/5'}`}
                  onClick={() => setFilter(f.value)}
                >
                  {f.label}
                </button>
              ))}
            </div>
            
            <div className="flex gap-1 bg-white/5 border border-white/10 p-1 rounded-full shrink-0">
              <button 
                className={`px-4 py-1.5 rounded-full text-xs font-medium transition-colors ${viewMode === 'comfortable' ? 'bg-primary text-canvas' : 'bg-transparent text-ink-muted hover:text-ink'}`}
                onClick={() => { setViewMode("comfortable"); localStorage.setItem("telecareplus-timeline-view", "comfortable"); }}
              >
                Comfortable
              </button>
              <button 
                className={`px-4 py-1.5 rounded-full text-xs font-medium transition-colors ${viewMode === 'compact' ? 'bg-primary text-canvas' : 'bg-transparent text-ink-muted hover:text-ink'}`}
                onClick={() => { setViewMode("compact"); localStorage.setItem("telecareplus-timeline-view", "compact"); }}
              >
                Compact
              </button>
            </div>
          </div>

          {loading ? (
            <div className="flex flex-col gap-4 mt-8">
              {[1, 2, 3].map(i => (
                <div key={i} className="card-premium h-24 animate-pulse bg-white/5"></div>
              ))}
            </div>
          ) : error ? (
            <div className="flex flex-col items-center justify-center p-12 text-center bg-alert/5 border border-alert/20 rounded-xl mt-8">
              <AlertTriangle size={32} className="text-alert mb-4" />
              <h3 className="font-display text-lg mb-2">Unable to load timeline</h3>
              <p className="text-sm text-ink-muted mb-6">{error}</p>
              <button className="px-4 py-2 border border-white/20 rounded-element text-sm font-medium hover:bg-white/5 transition-colors flex items-center gap-2" onClick={load}><RefreshCw size={16} /> Retry</button>
            </div>
          ) : !loading && !error && !timeline.length ? (
            <div className="flex flex-col items-center justify-center p-16 text-center border border-white/5 rounded-xl border-dashed min-h-[300px] mt-8">
              <Layers size={48} className="text-ink-muted/30 mb-4" />
              <h3 className="font-display text-lg mb-2">No Timeline Events</h3>
              <p className="text-sm text-ink-muted max-w-[280px]">No recent continuity events were found.</p>
            </div>
          ) : !loading && !error && timeline.length && !filteredTimeline.length ? (
            <div className="flex flex-col items-center justify-center p-16 text-center border border-white/5 rounded-xl border-dashed min-h-[300px] mt-8">
              <Layers size={48} className="text-ink-muted/30 mb-4" />
              <h3 className="font-display text-lg mb-2">No matching events</h3>
              <p className="text-sm text-ink-muted max-w-[280px]">No timeline events match your filter.</p>
            </div>
          ) : (
            <div className="flex flex-col gap-10 mt-8">
              {[
                { key: "today", label: "Today", items: groupedByDate.today },
                { key: "yesterday", label: "Yesterday", items: groupedByDate.yesterday },
                { key: "week", label: "Earlier this week", items: groupedByDate.week },
                { key: "older", label: "Older", items: groupedByDate.older }
              ].map((group) => (
                group.items.length > 0 && (
                  <div key={group.key} className="flex flex-col">
                    <div className="flex items-center gap-4 mb-6">
                       <h3 className="font-display text-xl font-medium">{group.label}</h3>
                       <div className="flex-1 h-px bg-white/10"></div>
                    </div>
                    <div className="flex flex-col gap-4">
                      {group.items.map((item, index) => (
                        <div key={`${item.type}-${item.occurredAt}-${index}`} className={`card-premium group !bg-surface hover:border-white/20 transition-colors ${viewMode === 'compact' ? '!p-4' : '!p-6'} ${item.actionNeeded ? 'border-alert/50 shadow-[0_0_15px_rgba(239,68,68,0.15)]' : ''}`}>
                          <div className="flex gap-4 sm:gap-6 items-start">
                            
                            <div className="w-12 h-12 rounded-full bg-white/5 border border-white/10 flex items-center justify-center shrink-0 group-hover:border-primary/30 transition-colors">
                              {renderTypeIcon(item.type)}
                            </div>
                            
                            <div className="flex-1 min-w-0">
                              <div className="flex flex-col sm:flex-row sm:items-start justify-between gap-3 sm:gap-4 mb-2">
                                <div>
                                  <div className="flex items-center gap-2 flex-wrap mb-1">
                                    <h4 className="text-base font-semibold text-ink">{item.title}</h4>
                                    {item.repeatCount > 1 && (
                                      <span className="text-[10px] font-bold uppercase tracking-widest bg-white/5 border border-white/10 px-2 py-0.5 rounded text-ink-muted">Repeated x{item.repeatCount}</span>
                                    )}
                                  </div>
                                  <p className="text-sm text-ink-muted">
                                    <strong className="text-ink/90 font-medium">{item.relativeDate}</strong> <span className="opacity-50 mx-1">ΓÇó</span> {item.displayDate}
                                  </p>
                                </div>
                                <div className="flex flex-wrap gap-2 shrink-0">
                                  <span className="text-xs font-semibold px-3 py-1 bg-white/5 border border-white/10 text-ink-muted rounded-full">{item.type}</span>
                                  {item.status && (
                                    <span className="text-xs font-semibold px-3 py-1 bg-primary/10 border border-primary/20 text-primary rounded-full">{item.status}</span>
                                  )}
                                  {item.actionNeeded && (
                                    <span className="text-xs font-semibold px-3 py-1 bg-alert/10 border border-alert/20 text-alert rounded-full">Needs Action</span>
                                  )}
                                </div>
                              </div>
                              
                              <div className="mt-3">
                                <span className="inline-block text-xs font-medium bg-white/5 border border-white/10 px-2.5 py-1 rounded text-ink/80 mb-2">
                                  Source: {item.actor}
                                </span>
                                {item.details && <p className="text-sm leading-relaxed text-ink-muted">{item.details}</p>}
                              </div>
                            </div>
                            
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )
              ))}
            </div>
          )}

        </div>
      </main>
    </div>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useLocalizedText } from "../components/LocalizedText";
import { useAccessibility } from "../context/AccessibilityContext";
import { useAuth } from "../context/AuthContext";
import { useLanguage } from "../context/LanguageContext";
import { fetchAdaptiveTriage, fetchCopilotRecommendations } from "../services/telecareService";
import { getApiErrorMessage } from "../utils/apiError";
import { translateDisplayText } from "../utils/i18n";
import PatientSidebar from "../components/PatientSidebar";
import { User, LogOut, Mic, MicOff, Volume2, PlayCircle, StopCircle, AlertTriangle, ShieldCheck, MessageSquare } from "lucide-react";
import { buildLoginRedirect } from "../utils/authSession";
import LanguageSwitcher from "../components/LanguageSwitcher";

const SUPPORT_COPY_BASE = {
  browserReadiness: "Browser voice readiness",
  speechPlayback: "Speech playback",
  voiceCapture: "Voice capture",
  enableMicrophone: "Enable microphone",
  enablingMicrophone: "Enabling microphone...",
  microphoneReady: "Microphone access is ready. You can start listening now.",
  microphoneUnavailable: "This browser cannot request microphone access from the page.",
  microphoneBlockedGuidance: "Open your browser site settings for this page and allow microphone access, then try again.",
  ready: "Ready",
  limited: "Limited",
  permissionRequired: "Permission required",
  fallbackTitle: "Fallback guidance",
  fallbackBody: "If listening is unavailable, use the Accessibility toolbar to read the page aloud and continue with keyboard shortcuts.",
  activeLocale: "Active voice locale",
  loadingGuidance: "Loading voice guidance...",
  permissionDenied: "Microphone permission was denied. You can still use the Accessibility tools to read the page aloud.",
  permissionRequiredNotice: "Voice capture needs microphone permission from the browser before it can start.",
  localeVoiceFallback: "A matching voice pack for the selected language was not found, so the browser may use a fallback voice.",
  noSpeechDetected: "No speech was detected. Try again and speak clearly after listening starts.",
  recognitionUnavailable: "Voice capture is not available in this browser right now.",
  recognitionFailed: "Voice capture could not start or continue. Please try again.",
  recognitionNetworkFailed: "Voice capture is unavailable because the browser could not reach its speech service.",
  guidanceUnavailable: "Voice guidance is not available yet. Load patient guidance first, then try again."
};

const RECOGNITION_LOCALE = {
  en: "en-US",
  hi: "hi-IN",
  ml: "ml-IN",
  te: "te-IN",
  pa: "pa-IN",
  ta: "ta-IN"
};

function detectSpeechPlaybackSupport() {
  return typeof window !== "undefined"
    && (
      Boolean(window.speechSynthesis)
      || "speechSynthesis" in window
      || "SpeechSynthesisUtterance" in window
      || typeof window.SpeechSynthesisUtterance === "function"
    );
}

function detectVoiceRecognitionSupport() {
  return typeof window !== "undefined"
    && ("SpeechRecognition" in window || "webkitSpeechRecognition" in window);
}

function getLocalizedSupportCopy(translateUiText) {
  return Object.fromEntries(
    Object.entries(SUPPORT_COPY_BASE).map(([key, value]) => [key, translateUiText(value)])
  );
}

function getRecognitionErrorMessage(errorCode, text) {
  switch (errorCode) {
    case "not-allowed":
    case "service-not-allowed":
      return text.permissionDenied;
    case "no-speech":
      return text.noSpeechDetected;
    case "network":
      return text.recognitionNetworkFailed;
    default:
      return text.recognitionFailed;
  }
}

async function requestMicrophoneAccess() {
  if (typeof navigator === "undefined" || !navigator.mediaDevices?.getUserMedia) {
    return false;
  }
  try {
    const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    stream.getTracks().forEach((track) => track.stop());
    return true;
  } catch {
    return false;
  }
}

export default function PatientVoiceAssistPage() {
  const { auth, logout } = useAuth();
  const navigate = useNavigate();
  const { language, t, translateUiText = (value) => translateDisplayText(language, value) } = useLanguage();
  const { speak, stopReading } = useAccessibility();
  const supportText = useMemo(() => getLocalizedSupportCopy(translateUiText), [translateUiText, language]);
  const patientId = auth?.profileId;
  
  const [copilot, setCopilot] = useState(null);
  const [adaptive, setAdaptive] = useState(null);
  const [transcript, setTranscript] = useState("");
  const [listening, setListening] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [microphonePermission, setMicrophonePermission] = useState("unknown");
  const [requestingPermission, setRequestingPermission] = useState(false);
  const [speechSupported, setSpeechSupported] = useState(detectSpeechPlaybackSupport);
  const [recognitionSupported, setRecognitionSupported] = useState(detectVoiceRecognitionSupport);
  const [voicesReady, setVoicesReady] = useState(() => {
    if (typeof window === "undefined" || !window.speechSynthesis) return false;
    return (window.speechSynthesis.getVoices?.() || []).length > 0;
  });
  const recognitionRef = useRef(null);

  const playbackReady = speechSupported || detectSpeechPlaybackSupport();
  const recognitionReady = (recognitionSupported || detectVoiceRecognitionSupport()) && microphonePermission !== "denied";

  const load = () => {
    if (!patientId) return;
    setLoading(true);
    Promise.allSettled([fetchCopilotRecommendations(patientId), fetchAdaptiveTriage(patientId)])
      .then(([copilotResult, adaptiveResult]) => {
        const nextCopilot = copilotResult.status === "fulfilled" ? copilotResult.value : null;
        const nextAdaptive = adaptiveResult.status === "fulfilled" ? adaptiveResult.value : null;
        setCopilot(nextCopilot);
        setAdaptive(nextAdaptive);
        if (!nextCopilot && !nextAdaptive) {
          setError(getApiErrorMessage(copilotResult.status === "rejected" ? copilotResult.reason : adaptiveResult.reason, t("unableLoadVoiceSupport")));
        } else {
          setError("");
        }
      })
      .finally(() => setLoading(false));
  };

  useEffect(() => {
    load();
  }, [patientId, t]);

  useEffect(() => {
    if (typeof window === "undefined") return undefined;
    let supportRefreshTimer = null;
    const refreshVoiceSupport = () => {
      setSpeechSupported(detectSpeechPlaybackSupport());
      setRecognitionSupported(detectVoiceRecognitionSupport());
      setVoicesReady((window.speechSynthesis?.getVoices?.() || []).length > 0);
    };
    const handleVoicesChanged = () => refreshVoiceSupport();
    const primeVoiceSupport = () => {
      try {
        window.speechSynthesis?.resume?.();
        window.speechSynthesis?.getVoices?.();
      } catch { /* ignore */ }
      refreshVoiceSupport();
    };
    refreshVoiceSupport();
    supportRefreshTimer = window.setInterval(() => {
      refreshVoiceSupport();
      if (detectSpeechPlaybackSupport()) {
        window.clearInterval(supportRefreshTimer);
        supportRefreshTimer = null;
      }
    }, 1200);

    window.speechSynthesis?.addEventListener?.("voiceschanged", handleVoicesChanged);
    window.addEventListener("pageshow", primeVoiceSupport);
    window.addEventListener("focus", primeVoiceSupport);
    window.addEventListener("pointerdown", primeVoiceSupport, true);
    window.addEventListener("keydown", primeVoiceSupport, true);

    return () => {
      if (supportRefreshTimer) window.clearInterval(supportRefreshTimer);
      window.speechSynthesis?.removeEventListener?.("voiceschanged", handleVoicesChanged);
      window.removeEventListener("pageshow", primeVoiceSupport);
      window.removeEventListener("focus", primeVoiceSupport);
      window.removeEventListener("pointerdown", primeVoiceSupport, true);
      window.removeEventListener("keydown", primeVoiceSupport, true);
    };
  }, []);

  useEffect(() => {
    if (typeof navigator === "undefined" || !navigator.permissions?.query) {
      setMicrophonePermission("unknown");
      return undefined;
    }
    let permissionStatus;
    navigator.permissions.query({ name: "microphone" })
      .then((status) => {
        permissionStatus = status;
        setMicrophonePermission(status.state || "unknown");
        status.onchange = () => setMicrophonePermission(status.state || "unknown");
      })
      .catch(() => setMicrophonePermission("unknown"));
    return () => { if (permissionStatus) permissionStatus.onchange = null; };
  }, []);

  useEffect(() => {
    if (!recognitionSupported) {
      recognitionRef.current = null;
      return undefined;
    }
    const Recognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    const recognition = new Recognition();
    recognition.lang = RECOGNITION_LOCALE[language] ?? RECOGNITION_LOCALE.en;
    recognition.interimResults = false;
    recognition.maxAlternatives = 1;
    recognition.onstart = () => { setListening(true); setError(""); };
    recognition.onresult = (event) => {
      const text = event.results?.[0]?.[0]?.transcript || "";
      setTranscript(text);
      setListening(false);
      setError("");
    };
    recognition.onerror = (event) => {
      setListening(false);
      if (event?.error === "aborted") return;
      setError(getRecognitionErrorMessage(event?.error, supportText));
    };
    recognition.onend = () => setListening(false);
    recognitionRef.current = recognition;

    return () => {
      recognition.onstart = null;
      recognition.onresult = null;
      recognition.onerror = null;
      recognition.onend = null;
      try { recognition.abort(); } catch { /* ignore */ }
      if (recognitionRef.current === recognition) recognitionRef.current = null;
    };
  }, [language, recognitionSupported, supportText]);

  useEffect(() => {
    if (typeof document === "undefined") return undefined;
    const handleVisibilityChange = () => {
      if (document.visibilityState === "visible") return;
      try { recognitionRef.current?.stop(); } catch { /* ignore */ }
      finally { setListening(false); }
    };
    document.addEventListener("visibilitychange", handleVisibilityChange);
    return () => document.removeEventListener("visibilitychange", handleVisibilityChange);
  }, []);

  useEffect(() => () => stopReading(), [stopReading]);
  useEffect(() => { stopReading(); }, [language, stopReading]);

  const guidanceSource = useMemo(() => {
    const lines = [];
    if (copilot?.patientActions?.length) lines.push(...copilot.patientActions.slice(0, 3));
    if (adaptive?.questions?.length) {
      lines.push(t("adaptiveTriage"));
      lines.push(...adaptive.questions.slice(0, 3));
    }
    return lines.join(". ");
  }, [adaptive, copilot, t]);
  
  const localizedGuidanceText = useLocalizedText(guidanceSource, { minLength: 8 });

  const startListening = async () => {
    if (microphonePermission === "denied") { setError(supportText.permissionDenied); return; }
    if (!recognitionRef.current) { setError(supportText.recognitionUnavailable); return; }
    if (listening) return;
    if (microphonePermission === "prompt") {
      const granted = await requestMicrophoneAccess();
      if (!granted) {
        setMicrophonePermission("denied");
        setError(supportText.permissionDenied);
        return;
      }
      setMicrophonePermission("granted");
    }
    setError("");
    try { recognitionRef.current.start(); } 
    catch {
      setListening(false);
      setError(microphonePermission === "prompt" ? supportText.permissionRequiredNotice : supportText.recognitionFailed);
    }
  };

  const enableMicrophone = async () => {
    if (!recognitionSupported) { setError(supportText.recognitionUnavailable); return; }
    if (typeof navigator === "undefined" || !navigator.mediaDevices?.getUserMedia) { setError(supportText.microphoneUnavailable); return; }
    if (requestingPermission) return;
    setRequestingPermission(true);
    setError("");
    try {
      const granted = await requestMicrophoneAccess();
      if (granted) {
        setMicrophonePermission("granted");
        setError("");
        return;
      }
      setMicrophonePermission("denied");
      setError(supportText.permissionDenied);
    } finally {
      setRequestingPermission(false);
    }
  };

  const stopListening = () => {
    try { recognitionRef.current?.stop(); } catch { /* ignore */ }
    finally { setListening(false); }
  };

  const speakGuidance = () => {
    const voiceText = localizedGuidanceText || guidanceSource;
    if (!playbackReady) { setError(t("browserVoiceUnsupported")); return; }
    if (!voiceText) { setError(supportText.guidanceUnavailable); return; }
    setError("");
    speak(voiceText, language);
  };

  const speakLowLiteracySummary = () => {
    if (!playbackReady) { setError(t("browserVoiceUnsupported")); return; }
    setError("");
    speak([t("voiceAssistHub"), t("startListening"), t("stopListening"), t("speakGuidance"), t("capturedTranscript"), t("spokenGuidance")].join(". "), language);
  };

  const handleLogout = () => {
    logout();
    navigate(buildLoginRedirect(""), { replace: true });
  };

  const supported = recognitionSupported || speechSupported || detectVoiceRecognitionSupport() || detectSpeechPlaybackSupport();

  return (
    <div className="min-h-screen bg-canvas text-ink font-sans flex flex-col lg:flex-row">
      <PatientSidebar />
      
      <main className="flex-1 p-6 lg:p-10 min-w-0" role="main">
        {/* Topbar */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4 animate-fadeSlideUp">
          <div>
            <h1 className="font-display text-3xl font-medium mb-2">Voice Assist</h1>
            <p className="text-ink-muted text-sm mb-3">Hands-free voice capture and audible medical guidance.</p>
            <div className="flex gap-2 items-center mt-3">
              <span className="inline-flex items-center gap-1.5 text-xs px-2.5 py-1 rounded-full bg-white/5 border border-white/10 text-ink-muted">
                <Volume2 size={12} className="text-primary" />Accessibility
              </span>
              <div className="inline-flex items-center gap-2 text-xs text-ink-muted bg-white/5 border border-white/10 px-3 py-1.5 rounded-full">
                <User size={14} />
                Signed in as {auth?.fullName || "Anita Patient"}
              </div>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <LanguageSwitcher hideLabel />
            <button 
              onClick={handleLogout} 
              aria-label="Log out"
              className="inline-flex items-center gap-2 px-4 py-2 bg-transparent text-ink-muted border border-white/10 rounded-element text-sm font-medium hover:bg-white/5 hover:text-ink transition-colors"
            >
              <LogOut size={16} />Logout
            </button>
          </div>
        </div>

        <div className="max-w-5xl animate-fadeSlideUp" style={{animationDelay: '0.1s'}}>
          
          <div className="space-y-10">
            
            {/* Status & Controls Panel */}
            <div>
              <div className="flex items-center gap-4 mb-6">
                 <h3 className="font-display text-xl font-medium">System Status</h3>
                 <div className="flex-1 h-px bg-white/10"></div>
              </div>
              
              <div className="card-premium">
                <p className="text-sm text-ink-muted mb-6 leading-relaxed">
                  {translateUiText("Voice capture needs microphone permission from the browser before it can start. You can also use the Accessibility tools to read the page aloud.")}
                </p>
                
                {!supported && (
                  <div className="mb-6 p-4 bg-alert/10 border border-alert/20 rounded-xl flex items-start gap-4">
                    <AlertTriangle size={24} className="text-alert shrink-0 mt-0.5" />
                    <div>
                      <p className="font-medium text-alert mb-1">Browser Unsupported</p>
                      <p className="text-sm text-alert/80 leading-relaxed">Your browser does not support Voice Assist features.</p>
                    </div>
                  </div>
                )}
                
                {error && (
                  <div className="mb-6 p-4 bg-alert/10 border border-alert/20 rounded-xl flex items-start gap-4">
                    <AlertTriangle size={24} className="text-alert shrink-0 mt-0.5" />
                    <div>
                      <p className="font-medium text-alert mb-1">Voice Support Issue</p>
                      <p className="text-sm text-alert/80 leading-relaxed">{error}</p>
                    </div>
                  </div>
                )}

                <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-8">
                  <div className="p-4 bg-white/5 border border-white/10 rounded-xl">
                    <p className="text-[10px] font-bold text-ink-muted uppercase tracking-widest mb-2">{supportText.speechPlayback}</p>
                    <p className={`text-base font-semibold ${playbackReady ? 'text-primary' : 'text-alert'}`}>
                      {playbackReady ? supportText.ready : supportText.limited}
                    </p>
                  </div>
                  <div className="p-4 bg-white/5 border border-white/10 rounded-xl">
                    <p className="text-[10px] font-bold text-ink-muted uppercase tracking-widest mb-2">{supportText.voiceCapture}</p>
                    <p className={`text-base font-semibold ${recognitionReady ? 'text-primary' : (microphonePermission === 'prompt' ? 'text-amber-500' : 'text-alert')}`}>
                      {!recognitionSupported ? supportText.limited : microphonePermission === "denied" ? supportText.limited : microphonePermission === "prompt" ? supportText.permissionRequired : supportText.ready}
                    </p>
                  </div>
                  <div className="p-4 bg-white/5 border border-white/10 rounded-xl">
                    <p className="text-[10px] font-bold text-ink-muted uppercase tracking-widest mb-2">{supportText.activeLocale}</p>
                    <p className="text-base font-semibold text-ink">
                      {RECOGNITION_LOCALE[language] ?? RECOGNITION_LOCALE.en}
                    </p>
                  </div>
                </div>

                <div className="flex flex-wrap gap-3">
                  {recognitionSupported && microphonePermission !== "granted" && (
                    <button className="px-5 py-2.5 bg-white/5 hover:bg-white/10 border border-white/20 text-ink rounded-element text-sm font-medium transition-colors disabled:opacity-50" disabled={requestingPermission} onClick={enableMicrophone}>
                      {requestingPermission ? supportText.enablingMicrophone : supportText.enableMicrophone}
                    </button>
                  )}
                  <button className="btn-primary py-2.5 px-5 flex items-center gap-2" disabled={!recognitionReady || listening} onClick={startListening}>
                    <Mic size={18} className={listening ? "animate-pulse" : ""} /> {listening ? t("listening") : t("startListening")}
                  </button>
                  <button className="px-5 py-2.5 bg-alert/10 hover:bg-alert/20 border border-alert/20 text-alert rounded-element text-sm font-medium transition-colors disabled:opacity-50 flex items-center gap-2" disabled={!recognitionReady || !listening} onClick={stopListening}>
                    <MicOff size={18} /> {t("stopListening")}
                  </button>
                  <button className="px-5 py-2.5 bg-white/5 hover:bg-white/10 border border-white/20 text-ink rounded-element text-sm font-medium transition-colors disabled:opacity-50 flex items-center gap-2" disabled={!playbackReady || loading} onClick={speakGuidance}>
                    <PlayCircle size={18} /> {t("speakGuidance")}
                  </button>
                  <button className="px-5 py-2.5 bg-white/5 hover:bg-white/10 border border-white/20 text-ink rounded-element text-sm font-medium transition-colors disabled:opacity-50 flex items-center gap-2" onClick={stopReading}>
                    <StopCircle size={18} /> Stop Reading
                  </button>
                </div>

              </div>
            </div>

            {/* Workspace Panels */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 items-start">
              
              {/* Transcript */}
              <div className="flex flex-col">
                <div className="flex items-center gap-4 mb-6">
                   <h3 className="font-display text-xl font-medium">Captured Transcript</h3>
                   <div className="flex-1 h-px bg-white/10"></div>
                </div>
                
                {!listening && !transcript ? (
                  <div className="flex flex-col items-center justify-center p-12 text-center border border-white/5 rounded-xl border-dashed min-h-[240px]">
                    <MessageSquare size={40} className="text-ink-muted/30 mb-4" />
                    <h3 className="font-display text-lg mb-2">No Transcript Yet</h3>
                    <p className="text-sm text-ink-muted max-w-[250px]">Click &quot;Start Listening&quot; to capture your speech and translate it into text.</p>
                  </div>
                ) : (
                  <div className="card-premium min-h-[240px] !bg-surface">
                    {listening ? (
                      <div className="flex items-center gap-3 text-primary">
                        <div className="w-3 h-3 rounded-full bg-primary animate-pulse"></div>
                        <span className="font-semibold tracking-wide">Listening...</span>
                      </div>
                    ) : (
                      <p className="text-base leading-relaxed text-ink">{transcript}</p>
                    )}
                  </div>
                )}
              </div>

              {/* Guidance */}
              <div className="flex flex-col">
                <div className="flex items-center gap-4 mb-6">
                   <h3 className="font-display text-xl font-medium">Audible Guidance</h3>
                   <div className="flex-1 h-px bg-white/10"></div>
                </div>
                
                {loading ? (
                   <div className="card-premium min-h-[240px] flex flex-col gap-4">
                      <div className="h-5 w-4/5 bg-white/10 rounded animate-pulse"></div>
                      <div className="h-5 w-3/5 bg-white/10 rounded animate-pulse"></div>
                   </div>
                ) : (!copilot?.patientActions?.length && !adaptive?.questions?.length) ? (
                  <div className="flex flex-col items-center justify-center p-12 text-center border border-white/5 rounded-xl border-dashed min-h-[240px]">
                    <ShieldCheck size={40} className="text-ink-muted/30 mb-4" />
                    <h3 className="font-display text-lg mb-2">No Active Guidance</h3>
                    <p className="text-sm text-ink-muted max-w-[250px]">You have no pending triage questions or required patient actions at this time.</p>
                  </div>
                ) : (
                  <div className="flex flex-col gap-4">
                    {(copilot?.patientActions || []).map((item, idx) => (
                      <div key={idx} className="card-premium !p-5 hover:border-white/20 transition-colors !bg-surface">
                        <p className="text-sm leading-relaxed text-ink-muted">{item}</p>
                      </div>
                    ))}
                    {(adaptive?.questions || []).slice(0, 3).map((item, idx) => (
                      <div key={`adaptive-${idx}`} className="card-premium !p-5 hover:border-white/20 transition-colors border-l-4 border-l-primary !bg-surface">
                        <h4 className="text-[10px] font-bold text-primary uppercase tracking-widest mb-2">Triage Question</h4>
                        <p className="text-sm leading-relaxed text-ink-muted">{item}</p>
                      </div>
                    ))}
                  </div>
                )}
              </div>

            </div>

          </div>
        </div>
      </main>
    </div>
  );
}

import { useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { useLanguage } from "../context/LanguageContext";
import { createTriage, fetchTriageHistory } from "../services/telecareService";
import { getApiErrorMessage } from "../utils/apiError";
import { emitTriageUpdated } from "../utils/appEvents";
import { buildLoginRedirect } from "../utils/authSession";
import { logAsyncFailure, runWithRequestTimeout } from "../utils/requestLifecycle";
import {
  Stethoscope,
  User,
  LogOut,
  CheckCircle2,
  ShieldAlert,
  AlertTriangle,
  Zap,
  BrainCircuit,
  HelpCircle,
  History,
  Sparkles,
  Activity,
  Check,
  Circle,
  Stethoscope as RoutineIcon
} from "lucide-react";
import PatientSidebar from "../components/PatientSidebar";
import LanguageSwitcher from "../components/LanguageSwitcher";
import HumanBodyModel from "../components/triage/HumanBodyModel";
import SymptomTrendsPanel from "../components/patient/SymptomTrendsPanel";

export default function TriagePage() {
  const { auth, logout } = useAuth();
  const navigate = useNavigate();
  const { language, t } = useLanguage() || { language: "en", t: (k) => k };
  const patientId = auth?.profileId;

  const [form, setForm] = useState({
    patientId,
    symptoms: "I've had a severe headache and nausea since yesterday morning.",
    symptomDurationDays: 1,
    chestPain: true,
    severeBreathlessness: false,
    fainting: false,
    temperature: 99.4,
    persistentHighFever: false
  });
  
  const [history, setHistory] = useState([]);
  const [filter, setFilter] = useState("All");
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState("");
  const [fieldErrors, setFieldErrors] = useState({ symptoms: "" });

  useEffect(() => {
    setForm((current) => ({ ...current, patientId }));
  }, [patientId]);

  const loadHistory = async ({ suppressError = false, signal } = {}) => {
    if (!patientId) {
      setLoading(false);
      return;
    }
    setLoading(true);
    try {
      const data = await runWithRequestTimeout(
        (requestSignal) => fetchTriageHistory(patientId, { signal: requestSignal }),
        { signal }
      );
      setHistory(data);
    } catch (err) {
      logAsyncFailure("triage:history", err, { patientId });
      setHistory([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    const controller = new AbortController();
    loadHistory({ signal: controller.signal });
    return () => controller.abort();
  }, [patientId]);

  const handleLogout = () => {
    logout();
    navigate(buildLoginRedirect(""), { replace: true });
  };

  const navigator = useMemo(() => {
    if (!form.symptoms.trim() && !form.chestPain && !form.severeBreathlessness && !form.fainting && !form.persistentHighFever) {
      return null;
    }
    const flags = [];
    if (form.chestPain || form.severeBreathlessness || form.fainting) {
      flags.push("Emergency indicators detected. Seek urgent medical review.");
    }
    if (Number(form.temperature) && Number(form.temperature) >= 101) {
      flags.push("High temperature reported. Monitor closely and hydrate.");
    }
    if (form.persistentHighFever) {
      flags.push("Persistent fever noted. Escalate if symptoms worsen.");
    }
    if (Number(form.symptomDurationDays) >= 7) {
      flags.push("Symptoms lasting more than a week. Schedule follow-up.");
    }
    const questions = [
      "When did the symptoms start and what changed recently?",
      "Is the discomfort getting worse, better, or staying the same?",
      "Any medications already taken or missed?",
      "Any recent exposure to illness or travel?"
    ];
    return {
      summary: "Use this guided checklist to prepare your triage details.",
      flags,
      questions,
      disclaimer: "This guidance supports triage and does not replace a clinician."
    };
  }, [form]);

  const parseTriageLevel = (rawLevel) => {
    const levelStr = String(rawLevel).toUpperCase();
    if (levelStr.includes("EMERGENCY")) return { label: "EMERGENCY", type: "emergency" };
    if (levelStr.includes("URGENT")) return { label: "URGENT", type: "urgent" };
    return { label: "ROUTINE", type: "routine" };
  };

  const sortedHistory = useMemo(() => {
    return [...history].sort((a, b) => new Date(b.assessedAt) - new Date(a.assessedAt));
  }, [history]);

  const filteredHistory = useMemo(() => {
    if (filter === "All") return sortedHistory;
    return sortedHistory.filter(item => {
      const lvl = parseTriageLevel(item.level);
      return lvl.label.toLowerCase() === filter.toLowerCase();
    });
  }, [sortedHistory, filter]);

  const groupedHistory = useMemo(() => {
    const today = [];
    const yesterday = [];
    const earlier = [];
    
    const now = new Date();
    const startOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const startOfYesterday = new Date(startOfToday);
    startOfYesterday.setDate(startOfYesterday.getDate() - 1);
    
    filteredHistory.forEach(item => {
      const date = new Date(item.assessedAt);
      if (date >= startOfToday) {
        today.push(item);
      } else if (date >= startOfYesterday && date < startOfToday) {
        yesterday.push(item);
      } else {
        earlier.push(item);
      }
    });
    return { today, yesterday, earlier };
  }, [filteredHistory]);

  const formatTime = (isoString) => {
    return new Date(isoString).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' }).toLowerCase();
  };

  return (
    <div className="min-h-screen bg-canvas text-ink font-sans flex flex-col lg:flex-row">
      <PatientSidebar />

      <main className="flex-1 p-6 lg:p-10 min-w-0" role="main">
        {/* Topbar */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4 animate-fadeSlideUp">
          <div>
            <h1 className="font-display text-3xl font-medium mb-2">Smart symptom triage</h1>
            <p className="text-ink-muted text-sm mb-3">Evaluate your symptoms and receive clinical guidance instantly.</p>
            <div className="flex gap-2 items-center mt-3">
              <span className="inline-flex items-center gap-1.5 text-xs px-2.5 py-1 rounded-full bg-white/5 border border-white/10 text-ink-muted">
                <Stethoscope size={12} className="text-primary" />Care
              </span>
              <div className="inline-flex items-center gap-2 text-xs text-ink-muted bg-white/5 border border-white/10 px-3 py-1.5 rounded-full">
                <User size={14} />
                Signed in as {auth?.fullName || "Anita Patient"}
              </div>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <LanguageSwitcher hideLabel />
            <button 
              onClick={handleLogout} 
              aria-label="Log out"
              className="inline-flex items-center gap-2 px-4 py-2 bg-transparent text-ink-muted border border-white/10 rounded-element text-sm font-medium hover:bg-white/5 hover:text-ink transition-colors"
            >
              <LogOut size={16} />Logout
            </button>
          </div>
        </div>

        <div className="grid grid-cols-1 xl:grid-cols-[1.5fr_1fr] gap-6 mb-8">
          {/* LEFT COLUMN: THE FORM */}
          <div className="card-premium animate-fadeSlideUp" style={{animationDelay: '0.1s'}}>
            <h2 className="font-display text-xl font-medium mb-6 flex items-center gap-2">
              <Activity size={20} className="text-primary"/>Clinical Intake
            </h2>
            
            <div className="mb-6 bg-white/5 p-4 rounded-xl border border-white/10">
              <HumanBodyModel onPartClick={(part) => {
                setForm(prev => ({ 
                  ...prev, 
                  symptoms: prev.symptoms ? `${prev.symptoms} Pain in ${part}.` : `Pain in ${part}.` 
                }));
                if (fieldErrors.symptoms) setFieldErrors({ symptoms: "" });
              }} />
            </div>

            <div className="mb-6">
              <label className="block text-sm font-medium text-ink-muted mb-2" htmlFor="symptoms">Describe your primary symptoms</label>
              <textarea 
                id="symptoms"
                className="w-full bg-white/5 border border-white/10 rounded-element p-3 text-ink focus:outline-none focus:ring-2 focus:ring-primary/50 placeholder-ink-muted/50"
                rows="3" 
                placeholder="e.g., I've had a severe headache and nausea since yesterday morning."
                value={form.symptoms}
                onChange={(e) => {
                  setForm({ ...form, symptoms: e.target.value });
                  if (fieldErrors.symptoms) setFieldErrors({ symptoms: "" });
                }}
                aria-invalid={!!fieldErrors.symptoms}
              />
              {fieldErrors.symptoms && <p className="text-sm text-alert mt-1">{fieldErrors.symptoms}</p>}
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-6">
              <div>
                <label className="block text-sm font-medium text-ink-muted mb-2" htmlFor="duration">Duration (Days)</label>
                <input 
                  id="duration" 
                  type="number" 
                  className="w-full bg-white/5 border border-white/10 rounded-element p-3 text-ink font-mono focus:outline-none focus:ring-2 focus:ring-primary/50" 
                  min="1" 
                  value={form.symptomDurationDays} 
                  onChange={(e) => setForm({ ...form, symptomDurationDays: e.target.value })} 
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-ink-muted mb-2" htmlFor="temp">Temperature (┬░F)</label>
                <input 
                  id="temp" 
                  type="number" 
                  className="w-full bg-white/5 border border-white/10 rounded-element p-3 text-ink font-mono focus:outline-none focus:ring-2 focus:ring-primary/50" 
                  value={form.temperature} 
                  onChange={(e) => setForm({ ...form, temperature: e.target.value })} 
                />
              </div>
            </div>

            <h3 className="text-sm font-medium text-ink-muted mb-3">Select any severe symptoms that apply</h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 mb-6">
              {[
                { id: 'chestPain', label: 'Chest pain' },
                { id: 'severeBreathlessness', label: 'Severe breathlessness' },
                { id: 'fainting', label: 'Fainting / dizziness' },
                { id: 'persistentHighFever', label: 'Persistent high fever' }
              ].map(symptom => (
                <label key={symptom.id} className="flex items-center gap-3 cursor-pointer group">
                  <div className={`w-5 h-5 rounded border flex items-center justify-center transition-colors ${form[symptom.id] ? 'bg-primary border-primary text-canvas' : 'border-white/20 group-hover:border-white/40'}`}>
                    {form[symptom.id] && <Check size={12} strokeWidth={3} />}
                  </div>
                  <input type="checkbox" className="sr-only" checked={form[symptom.id]} onChange={(e) => setForm({ ...form, [symptom.id]: e.target.checked })} />
                  <span className="text-sm">{symptom.label}</span>
                </label>
              ))}
            </div>

            {error && (
              <div className="flex gap-2 p-4 bg-alert/10 border border-alert/30 rounded-element text-alert text-sm mb-6">
                <ShieldAlert size={18} className="shrink-0" />
                <span>{error}</span>
              </div>
            )}

            {result && (
              <div className="p-5 bg-primary/10 border border-primary/30 rounded-xl mb-6">
                <div className="flex items-center gap-2 mb-2">
                  <CheckCircle2 className="text-primary" size={18} />
                  <span className="font-medium text-ink">Triage Complete</span>
                </div>
                <p className="text-sm text-ink-muted leading-relaxed">{result.recommendation}</p>
              </div>
            )}

            <button 
              className="btn-primary w-full sm:w-auto inline-flex items-center justify-center gap-2 py-3 px-6 text-base"
              disabled={submitting}
              onClick={async () => {
                if (!form.symptoms.trim()) {
                  setFieldErrors({ symptoms: "Symptoms are required to run triage." });
                  return;
                }
                setSubmitting(true);
                setError("");
                try {
                  const data = await createTriage({
                    ...form,
                    symptoms: form.symptoms.trim(),
                    symptomDurationDays: Number(form.symptomDurationDays),
                    oxygenLevel: 98,
                    temperature: Number(form.temperature)
                  });
                  setResult(data);
                  setHistory((current) => [data, ...current.filter((item) => item.id !== data.id)]);
                  emitTriageUpdated();
                } catch (err) {
                  setError(getApiErrorMessage(err, "Triage submission failed."));
                } finally {
                  setSubmitting(false);
                }
              }}
            >
              <Sparkles size={18} /> {submitting ? "Evaluating..." : "Evaluate triage"}
            </button>
          </div>

          {/* RIGHT COLUMN: AI NAVIGATOR */}
          <div className="card-premium ai-content animate-fadeSlideUp" style={{animationDelay: '0.2s'}}>
            <h2 className="font-display text-xl font-medium mb-6 flex items-center gap-2">
              <BrainCircuit size={20} className="text-live"/>AI symptom navigator
            </h2>
            {navigator ? (
              <div>
                <p className="text-sm text-ink leading-relaxed mb-6">{navigator.summary}</p>
                
                {navigator.flags.length > 0 && (
                  <div className="flex flex-col gap-3 mb-6">
                    {navigator.flags.map((flag, idx) => (
                      <div key={idx} className="flex gap-2 items-start text-sm text-alert bg-alert/5 p-3 rounded-element border border-alert/20">
                        <AlertTriangle size={16} className="shrink-0 mt-0.5" /> 
                        <span>{flag}</span>
                      </div>
                    ))}
                  </div>
                )}

                <p className="text-sm font-medium mb-3">Consider discussing:</p>
                <ul className="flex flex-col gap-2 pl-2">
                  {navigator.questions.map((q, idx) => (
                    <li key={idx} className="flex gap-2 items-start text-sm text-ink-muted">
                      <Circle size={8} className="shrink-0 mt-1.5 text-primary fill-primary" />
                      <span>{q}</span>
                    </li>
                  ))}
                </ul>

                <p className="text-xs text-ink-muted mt-8 italic border-t border-white/10 pt-4">{navigator.disclaimer}</p>
              </div>
            ) : (
              <div className="flex flex-col items-center justify-center text-center py-12 px-4 opacity-70">
                <div className="w-16 h-16 rounded-full bg-white/5 border border-white/10 flex items-center justify-center text-ink-muted mb-4">
                  <HelpCircle size={28} />
                </div>
                <p className="text-sm text-ink-muted leading-relaxed">
                  Enter your symptoms and select<br/>'Evaluate triage' to receive a guided<br/>assessment and risk profile here.
                </p>
              </div>
            )}
          </div>
        </div>

        {/* SYMPTOM TRENDS SECTION */}
        {patientId && (
          <SymptomTrendsPanel patientId={patientId} />
        )}

        {/* HISTORY SECTION */}
        <div className="card-premium animate-fadeSlideUp" style={{animationDelay: '0.2s'}} role="region" aria-label="Triage History">
          
          <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-6 gap-4 border-b border-white/10 pb-6">
            <h2 className="font-display text-xl font-medium flex items-center gap-2"><History size={20}/> Triage history</h2>
            <div className="flex bg-white/5 rounded-full p-1 border border-white/10">
              {['All', 'Routine', 'Urgent', 'Emergency'].map(f => (
                <button 
                  key={f}
                  className={`px-4 py-1.5 rounded-full text-xs font-medium transition-colors ${filter === f ? 'bg-primary text-canvas shadow' : 'text-ink-muted hover:text-ink'}`}
                  onClick={() => setFilter(f)}
                >
                  {f}
                </button>
              ))}
            </div>
          </div>

          {loading ? (
            <div className="flex flex-col gap-4">
              {[1,2,3].map(i => (
                <div key={i} className="flex gap-4 p-4 border border-white/5 rounded-xl bg-white/5 animate-pulse">
                   <div className="w-12 h-12 rounded-xl bg-white/10"></div>
                   <div className="flex-1">
                     <div className="h-5 w-1/3 bg-white/10 rounded mb-2"></div>
                     <div className="h-4 w-2/3 bg-white/10 rounded"></div>
                   </div>
                </div>
              ))}
            </div>
          ) : filteredHistory.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-16 px-4 text-center">
              <History size={40} className="text-ink-muted/30 mb-4" />
              <h3 className="font-display text-lg mb-2">No history found</h3>
              <p className="text-sm text-ink-muted">You haven't completed any triage assessments in this category.</p>
            </div>
          ) : (
            <div className="flex flex-col gap-8">
              {[
                { label: 'TODAY', items: groupedHistory.today },
                { label: 'YESTERDAY', items: groupedHistory.yesterday },
                { label: 'EARLIER THIS WEEK', items: groupedHistory.earlier }
              ].map(group => group.items.length > 0 && (
                <div key={group.label}>
                  <div className="text-xs font-semibold text-ink-muted tracking-widest uppercase mb-4 pl-2">{group.label}</div>
                  <div className="flex flex-col gap-3">
                    {group.items.map(item => {
                      const lvl = parseTriageLevel(item.level);
                      const isEmergency = lvl.type === 'emergency';
                      const isUrgent = lvl.type === 'urgent';
                      
                      let Icon = RoutineIcon;
                      if (isEmergency) Icon = AlertTriangle;
                      if (isUrgent) Icon = Zap;

                      const iconBgClass = isEmergency ? 'bg-alert/10 text-alert border-alert/20' : isUrgent ? 'bg-[#C9A24B]/10 text-[#C9A24B] border-[#C9A24B]/20' : 'bg-primary/10 text-primary border-primary/20';
                      const badgeClass = isEmergency ? 'bg-alert text-canvas' : isUrgent ? 'bg-[#C9A24B] text-canvas' : 'bg-primary text-canvas';
                      const stripClass = isEmergency ? 'border-alert/30 bg-alert/5' : 'border-white/5 bg-white/5 hover:bg-white/10 transition-colors';

                      return (
                        <div key={item.id} className={`flex flex-col sm:flex-row gap-4 p-4 rounded-xl border ${stripClass}`}>
                          <div className={`w-12 h-12 rounded-xl flex items-center justify-center border shrink-0 ${iconBgClass}`}>
                            <Icon size={20} />
                          </div>
                          <div className="flex-1 min-w-0">
                            <div className="flex flex-wrap items-center gap-3 mb-1">
                              <span className="font-medium truncate">{item.symptoms}</span>
                              <span className={`text-[10px] uppercase tracking-wider font-bold px-2 py-0.5 rounded-full ${badgeClass}`}>{lvl.label}</span>
                            </div>
                            <div className="text-sm text-ink-muted leading-relaxed">{item.recommendation}</div>
                          </div>
                          <div className="text-xs font-mono text-ink-muted whitespace-nowrap pt-1">
                            {formatTime(item.assessedAt)}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </main>
    </div>
  );
}

import axios from "axios";
import { trackApiFailure, trackAuthEvent, trackTelemetry } from "./telemetry";
import { safeJsonParse } from "../utils/safeJson";
import { normalizeAuth } from "../utils/normalizeAuth";
import { AUTH_CHANGED_EVENT, AUTH_STORAGE_KEY, clearAuthStorageArtifacts } from "../utils/authSession";

export const API_BASE_URL = (import.meta.env.VITE_API_BASE_URL || "http://localhost:8080/api").replace(/\/+$/, "");
const API_CACHE_PREFIX = "telecareplus-api-cache-v14";
const API_CACHE_TTL_MS = 1000 * 60 * 60 * 12;
const OFFLINE_QUEUE_STORAGE_KEY = "telecareplus-offline-write-queue-v1";
const OFFLINE_QUEUE_EVENT = "telecareplus-offline-queue-updated";
const AUTH_REDIRECT_GUARD_KEY = "telecareplus-auth-redirecting";
const AUTH_REDIRECT_GUARD_TTL_MS = 3000;
const MUTATION_METHODS = new Set(["post", "put", "patch", "delete"]);
const OFFLINE_QUEUEABLE_PATH_PATTERNS = [
  /\/triage$/i,
  /\/health-records$/i,
  /\/reminders\/\d+\/status$/i,
  /\/future-care\/observations$/i
];

function getStoredLanguage() {
  if (typeof window === "undefined") {
    return "en";
  }

  try {
    const queryLanguage = new URL(window.location.href).searchParams.get("lang");
    if (queryLanguage) {
      return queryLanguage;
    }
  } catch {
    // Ignore malformed URL state.
  }

  try {
    return localStorage.getItem("telecareplus-language")
      || sessionStorage.getItem("telecareplus-language")
      || document.documentElement?.lang
      || "en";
  } catch {
    return document.documentElement?.lang || "en";
  }
}

const api = axios.create({
  baseURL: API_BASE_URL,
  timeout: 15000
});

let queueReplayPromise = null;
let offlineReplayIntervalId = null;

function getStoredAuthObject() {
  try {
    const auth = localStorage.getItem(AUTH_STORAGE_KEY);
    if (!auth) {
      return null;
    }
    const parsed = safeJsonParse(auth);
    if (!parsed) {
      localStorage.removeItem(AUTH_STORAGE_KEY);
      return null;
    }
    // normalize stored shape so callers always get canonical shape
    const normalized = normalizeAuth(parsed);
    if (!normalized) {
      // corrupted or expired
      localStorage.removeItem(AUTH_STORAGE_KEY);
      return null;
    }
    return normalized;
  } catch {
    localStorage.removeItem(AUTH_STORAGE_KEY);
    return null;
  }
}

export function getStoredAuthToken() {
  return getStoredAuthObject()?.token || null;
}

function clearStoredAuthState() {
  if (typeof localStorage === "undefined") {
    return;
  }

  try {
    clearAuthStorageArtifacts();
  } catch {
    // Ignore storage cleanup issues.
  }

  if (typeof window !== "undefined") {
    window.dispatchEvent(new CustomEvent(AUTH_CHANGED_EVENT, { detail: null }));
  }
}

function sanitizeRequestPath(url = "") {
  return String(url || "")
    .split("?")[0]
    .replace(/[0-9a-f]{8}-[0-9a-f-]{27,}/gi, ":id")
    .replace(/\/\d+(?=\/|$)/g, "/:id");
}

function shouldSkipAuthRedirect() {
  if (typeof window === "undefined") {
    return true;
  }

  try {
    const last = Number(sessionStorage.getItem(AUTH_REDIRECT_GUARD_KEY));
    if (Number.isFinite(last) && Date.now() - last < AUTH_REDIRECT_GUARD_TTL_MS) {
      return true;
    }
  } catch {
    return false;
  }

  return false;
}

function markAuthRedirect() {
  if (typeof window === "undefined") {
    return;
  }

  try {
    sessionStorage.setItem(AUTH_REDIRECT_GUARD_KEY, String(Date.now()));
  } catch {
    // Ignore guard persistence failures.
  }
}

function buildCacheKey(config) {
  const auth = getStoredAuthObject();
  const scope = auth?.role && (auth?.profileId || auth?.userId)
    ? `${auth.role}:${auth.profileId ?? auth.userId}`
    : "public";
  const target = `${config.baseURL || API_BASE_URL}${config.url || ""}`;
  return `${API_CACHE_PREFIX}:${scope}:${target}`;
}

function writeCachedResponse(config, data) {
  if (typeof localStorage === "undefined") {
    return;
  }

  try {
    localStorage.setItem(buildCacheKey(config), JSON.stringify({
      cachedAt: Date.now(),
      data
    }));
  } catch {
    // Ignore storage pressure; online flow still works.
  }
}

function readCachedResponse(config) {
  if (typeof localStorage === "undefined") {
    return null;
  }

  try {
    const raw = localStorage.getItem(buildCacheKey(config));
    if (!raw) {
      return null;
    }

    const parsed = safeJsonParse(raw);
    if (!parsed?.cachedAt || Date.now() - parsed.cachedAt > API_CACHE_TTL_MS) {
      localStorage.removeItem(buildCacheKey(config));
      return null;
    }

    return parsed.data;
  } catch {
    localStorage.removeItem(buildCacheKey(config));
    return null;
  }
}

function emitOfflineQueueEvent(queue) {
  if (typeof window === "undefined") {
    return;
  }

  window.dispatchEvent(new CustomEvent(OFFLINE_QUEUE_EVENT, {
    detail: {
      size: queue.length,
      items: queue
    }
  }));
}

function readOfflineQueue() {
  if (typeof localStorage === "undefined") {
    return [];
  }

  try {
    const parsed = safeJsonParse(localStorage.getItem(OFFLINE_QUEUE_STORAGE_KEY), []);
    if (!Array.isArray(parsed)) {
      localStorage.removeItem(OFFLINE_QUEUE_STORAGE_KEY);
      return [];
    }
    return parsed;
  } catch {
    localStorage.removeItem(OFFLINE_QUEUE_STORAGE_KEY);
    return [];
  }
}

function writeOfflineQueue(queue) {
  if (typeof localStorage === "undefined") {
    return;
  }

  localStorage.setItem(OFFLINE_QUEUE_STORAGE_KEY, JSON.stringify(queue));
  emitOfflineQueueEvent(queue);
}

function serializeRequestData(data) {
  if (data === undefined || data === null) {
    return null;
  }

  if (typeof data === "string") {
    return data;
  }

  try {
    return JSON.stringify(data);
  } catch {
    return null;
  }
}

function canQueueOffline(config) {
  if (config?.skipOfflineQueue) {
    return false;
  }

  const method = String(config?.method || "get").toLowerCase();
  if (!MUTATION_METHODS.has(method)) {
    return false;
  }

  const target = `${config?.baseURL || API_BASE_URL}${config?.url || ""}`;
  return OFFLINE_QUEUEABLE_PATH_PATTERNS.some((pattern) => pattern.test(target));
}

function queueOfflineWrite(config) {
  const queue = readOfflineQueue();
  const item = {
    id: `offline-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    baseURL: config?.baseURL || API_BASE_URL,
    url: config?.url || "",
    method: String(config?.method || "post").toLowerCase(),
    params: config?.params || null,
    data: serializeRequestData(config?.data),
    queuedAt: new Date().toISOString()
  };

  queue.push(item);
  writeOfflineQueue(queue);
  trackTelemetry("network:queued-write", {
    endpoint: sanitizeRequestPath(item.url),
    method: item.method
  }, {
    level: "warn",
    fingerprint: `offline-queue:${item.method}:${sanitizeRequestPath(item.url)}`
  });
  return item;
}

function createQueuedError(item) {
  const error = new Error("Stored locally as a pending change. It has not reached the server yet and will retry when your connection returns.");
  error.offlineQueued = true;
  error.pendingLocalSave = true;
  error.queuedRequestId = item.id;
  error.response = {
    data: {
      message: "Stored locally as a pending change. It has not reached the server yet and will retry when your connection returns."
    },
    status: 202,
    statusText: "Accepted"
  };
  return error;
}

async function replayOfflineQueue() {
  if (typeof window === "undefined" || !navigator.onLine) {
    return [];
  }

  if (queueReplayPromise) {
    return queueReplayPromise;
  }

  queueReplayPromise = (async () => {
    const queue = readOfflineQueue();
    if (!queue.length) {
      return [];
    }

    const remaining = [];
    const processed = [];

    for (const item of queue) {
      try {
        await api.request({
          baseURL: item.baseURL,
          url: item.url,
          method: item.method,
          params: item.params || undefined,
          data: item.data,
          skipOfflineQueue: true,
          headers: {
            "Content-Type": "application/json",
            "X-TeleCare-Offline-Replay": "1"
          }
        });
        processed.push(item);
      } catch (error) {
        if (error?.response && error.response.status >= 400 && error.response.status < 500) {
          processed.push(item);
          continue;
        }
        remaining.push(item);
      }
    }

    writeOfflineQueue(remaining);
    return processed;
  })();

  try {
    return await queueReplayPromise;
  } finally {
    queueReplayPromise = null;
  }
}

if (typeof window !== "undefined") {
  window.addEventListener("online", () => {
    replayOfflineQueue().catch(() => {});
  });
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible" && navigator.onLine) {
      replayOfflineQueue().catch(() => {});
    }
  });
  setTimeout(() => {
    replayOfflineQueue().catch(() => {});
  }, 1000);
  if (!offlineReplayIntervalId) {
    window.setInterval(() => {
      if (navigator.onLine && readOfflineQueue().length) {
        replayOfflineQueue().catch(() => {});
      }
    }, 30000);
    offlineReplayIntervalId = true; // just to prevent multiple intervals
  }
}

export function getOfflineQueueSnapshot() {
  return readOfflineQueue();
}

export function subscribeToOfflineQueue(listener) {
  if (typeof window === "undefined") {
    return () => {};
  }

  const handler = (event) => listener(event.detail);
  window.addEventListener(OFFLINE_QUEUE_EVENT, handler);
  listener({
    size: readOfflineQueue().length,
    items: readOfflineQueue()
  });
  return () => window.removeEventListener(OFFLINE_QUEUE_EVENT, handler);
}

export async function flushOfflineQueue() {
  return replayOfflineQueue();
}

api.interceptors.request.use((config) => {
  const metadata = {
    ...(config.metadata || {}),
    startedAt: Date.now()
  };
  const targetUrl = String(config.url || "");
  const isAuthRequest = Boolean(metadata.isAuthRequest) || targetUrl.includes("/auth/");
  const token = isAuthRequest ? null : getStoredAuthToken();
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  config.metadata = metadata;
  console.log("[BOOTSTRAP]", {
    step: "api-request",
    method: String(config.method || "get").toUpperCase(),
    url: config.url,
    authenticated: Boolean(token),
    authRequest: isAuthRequest
  });
  if (typeof window !== "undefined" && window.__TELECARE_LOCAL_RUNTIME__) {
    try {
      console.log("[TeleCare+] api.request", { method: config.method, url: config.url, headers: { ...(config.headers || {}) } });
    } catch (err) {
      // ignore
    }
  }
  return config;
});

api.interceptors.response.use(
  (response) => {
    console.log("[BOOTSTRAP]", {
      step: "api-response",
      method: String(response.config?.method || "get").toUpperCase(),
      url: response.config?.url,
      status: response.status
    });
    if (typeof window !== "undefined" && window.__TELECARE_LOCAL_RUNTIME__) {
      try {
        console.log("[TeleCare+] api.response", { method: response.config?.method, url: response.config?.url, status: response.status });
      } catch (err) {
        // ignore
      }
    }
    if ((response.config?.method || "get").toLowerCase() === "get" && response?.data !== undefined) {
      writeCachedResponse(response.config, response.data);
    }
    return response;
  },
  (error) => {
    console.log("[BOOTSTRAP]", {
      step: "api-error",
      method: String(error?.config?.method || "get").toUpperCase(),
      url: error?.config?.url,
      status: error?.response?.status ?? null,
      message: error?.message ?? "Unknown API error"
    });
    if (typeof window !== "undefined" && window.__TELECARE_LOCAL_RUNTIME__) {
      try {
        console.log("[TeleCare+] api.error", { message: error?.message, url: error?.config?.url, status: error?.response?.status });
      } catch (err) {
        // ignore
      }
    }
    const config = error?.config;
    // Don't trigger auth cleanup for cancelled/aborted requests
    try {
      if (error?.code === "ERR_CANCELED" || error?.message?.toLowerCase().includes("canceled") || error?.message?.toLowerCase().includes("aborted")) {
        return Promise.reject(error);
      }
    } catch {
      // ignore
    }
    if (error?.response?.status === 401 && config && !String(config.url || "").includes("/auth/") && !(config.metadata && config.metadata.isAuthRequest)) {
      // if a login/register/verify request triggered this, skip cleanup here
      clearStoredAuthState();
      trackAuthEvent("expired-session", {
        endpoint: sanitizeRequestPath(config?.url || ""),
        status: 401
      });

      if (typeof window !== "undefined" && !shouldSkipAuthRedirect()) {
        const pathname = window.location.pathname || "";
        if (!pathname.endsWith("/login")) {
          const language = getStoredLanguage();
          const languageSearch = language && language !== "en" ? `?lang=${language}` : "";
          try {
            sessionStorage.setItem("telecareplus-auth-expired", "1");
          } catch {
            // Ignore session storage errors.
          }
          markAuthRedirect();
          window.location.replace(`/login${languageSearch}`);
        }
      }
    }

    if (config && (config.method || "get").toLowerCase() === "get" && !error.response) {
      const cachedData = readCachedResponse(config);
      if (cachedData !== null) {
        return Promise.resolve({
          data: cachedData,
          status: 200,
          statusText: "OK",
          headers: { "x-telecare-cache": "1" },
          config,
          request: error.request
        });
      }
    }

    if (config && canQueueOffline(config) && (!navigator.onLine || !error.response)) {
      const queuedItem = queueOfflineWrite(config);
      return Promise.reject(createQueuedError(queuedItem));
    }

    trackApiFailure({
      endpoint: sanitizeRequestPath(config?.url || ""),
      method: String(config?.method || "get").toUpperCase(),
      status: error?.response?.status ?? null,
      durationMs: config?.metadata?.startedAt ? Date.now() - config.metadata.startedAt : null,
      offline: typeof navigator !== "undefined" ? !navigator.onLine : false,
      queued: false
    });

    return Promise.reject(error);
  }
);

export default api;
